#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   0x8000
#define ADS1115_CFG_MUX_AIN0   0x4000
#define ADS1115_CFG_PGA_4_096  0x0200
#define ADS1115_CFG_MODE_SS   0x0100
#define ADS1115_CFG_DR_128    0x0080
#define ADS1115_CFG_CQUE_NONE 0x0003

#define MLX91219_SENSITIVITY  0.040f   /* V/A */
#define MLX91219_MID_SUPPLY   3.3f     /* V */
#define MLX91219_ZERO_CURRENT 0.0f    /* A */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit value to an ADS1115 register (MSB first on the bus). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    return i2cWriteI2CBlockData(handle, reg, buf + 1, 2);
}

/* Read a 16-bit value from an ADS1115 register (MSB first on the bus). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteI2CBlockData(handle, reg, (char *)buf, 0) < 0)
        return -1;
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2)
        return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Trigger a single-shot conversion on AIN0 and read the result. */
static int read_current(int handle, float *current) {
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096 | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }

    /* Wait for conversion to complete (~8ms at 128 SPS). */
    gpioDelay(10000);

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &raw) < 0) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion register\n");
        return -1;
    }

    /* Convert 16-bit signed two's-complement to signed 16-bit. */
    int16_t signed_raw = (int16_t)raw;
    *current = (float)signed_raw * MLX91219_SENSITIVITY / 1000.0f;
    *current += MLX91219_ZERO_CURRENT;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Sensor via ADS1115\n");
    printf("I2C bus %d, ADS1115 addr 0x%02X\n", I2C_BUS, ADS1115_ADDR);
    printf("Sampling every 500ms. Press Ctrl+C to exit.\n\n");

    while (running) {
        float current;
        if (read_current(i2c_handle, &current) == 0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Warning: current read failed, continuing...\n");
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

