#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define HEAT_SENSOR_GPIO  0
#define BUZZER_GPIO       27
#define I2C_BUS           1
#define ADS1115_ADDR      0x48
#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CONFIG 0x01

#define TEMP_THRESHOLD 60.0f
#define TEMP_MIN       20.0f
#define TEMP_MAX       80.0f
#define ADC_VREF       3.3f
#define ADC_MAX         32767.0f
#define ADC_GAIN_4_096V 0x0200
#define ADC_SINGLE_SHOT 0x0100
#define ADC_128_SPS     0x0080
#define ADC_AIN0        0x4000

#define DEBOUNCE_US     50000
#define POLL_US         100000
#define BUZZER_ON_US    2000000

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_flame_tick = 0;
static volatile int flame_active = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ads1115_write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

static int ads1115_read_conversion(int handle, int16_t *raw) {
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *raw = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float adc_to_temperature(int16_t raw) {
    float voltage = (float)raw / ADC_MAX * ADC_VREF;
    return TEMP_MIN + (TEMP_MAX - TEMP_MIN) * voltage;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_flame_tick > DEBOUNCE_US) {
        last_flame_tick = tick;
        flame_active = 1;
    }
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
