#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_FAN_PIN 18
#define DEFAULT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.1
#define LOG_FILE "current_log.txt"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static double current_threshold = DEFAULT_THRESHOLD;
static double sensor_sensitivity = DEFAULT_SENSITIVITY;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) - sensor absent or wiring fault\n", adc_value);
    }
    return adc_value;
}

static double adc_to_current(int adc_value) {
    double voltage = (adc_value / 1023.0) * 3.3;
    return voltage / sensor_sensitivity;
}

static void log_data(double current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, Current: %.2f A\n", timestamp, current);
    } else {
        fprintf(fp, "Timestamp Error, Current: %.2f A\n", current);
    }

    fclose(fp);
}

static void control_fan(double current) {
    int val = (current > current_threshold) ? 1 : 0;
    if (gpiod_line_set_value(fan_line, val) < 0) {
        fprintf(stderr, "Error setting fan GPIO: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fan_line = gpiod_chip_get_line(chip, DEFAULT_FAN_PIN);
    if (!fan_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DEFAULT_FAN_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Fan control system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            sleep(1);
            continue;
        }

        double current = adc_to_current(adc_value);
        log_data(current);
        control_fan(current);

        printf("Current: %.2f A\n", current);

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

