#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000  // AIN0 single-ended, +/-4.096V, 128 SPS
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_OS_ONE 0x0001
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_DEFAULT 0x8000 | 0x0080 | 0x0100 | 0x0200 | 0x0080 | 0x0003

// Calibration parameters (example values, replace with actual calibration data)
#define CO_MIN_PPM 0.0
#define CO_MAX_PPM 100.0
#define CO_MIN_RAW 0
#define CO_MAX_RAW 65535
#define CO_SLOPE 0.1
#define CO_INTERCEPT 50.0

// Global variables
