int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_ppm(int16_t raw_value);
void log_data(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit ADC value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];
    char reg;
    char buf[2];
    int16_t config_val;
    int16_t raw;
    int status;

