#define REF_PRESSURE 20.0e-6f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mic_data(int handle, int *raw_out) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, MIC_REG, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    *raw_out = (buf[0] << 8) | buf[1];
    return 0;
}

static float convert_to_dB(int raw) {
    float voltage = (float)raw * 3.3f / 32768.0f;
    float pressure = voltage * 1.0f / MIC_SENSITIVITY;
    return 20.0f * log10f(pressure / REF_PRESSURE) + MIC_SENSITIVITY;
}

static void log_data(float avg_dB) {
    FILE *fp = fopen("audio_log.txt", "a");
    if (!fp) {
        perror("fopen audio_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f dB\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, avg_dB);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handles[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        handles[i] = i2cOpen(I2C_BUS, (i == 0) ? MIC1_ADDR : MIC2_ADDR, 0);
        if (handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                    (i == 0) ? MIC1_ADDR : MIC2_ADDR, handles[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        for (int i = 0; i < NUM_SENSORS; i++) {
            i2cClose(handles[i]);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Acoustic leak detection started. Press Ctrl+C to exit.\n");

    while (running) {
        float sum = 0.0f;
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int raw;
            if (read_mic_data(handles[i], &raw) == 0) {
                sum += convert_to_dB(raw);
                valid++;
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
                sum += ERROR_VALUE;
            }
        }
        if (valid > 0) {
            float avg = sum / valid;
            log_data(avg);
        } else {
            fprintf(stderr, "No valid sensor readings, skipping log entry\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(handles[i]);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

