#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0          // Mode 0, active low CS
#define LED_GPIO 27
#define THRESHOLD 0.7f      // 70% of normalized scale
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define WINDOW_DURATION_US 100000 // 100 ms
#define NUM_SAMPLES (WINDOW_DURATION_US / SAMPLE_INTERVAL_US)
#define ADC_RESOLUTION 1024.0f // MCP3008 is 10-bit

// Global variables
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_rms(int *samples, int num_samples);
void log_data(float mic1_rms, float mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    char tx_buffer[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Function to calculate the RMS value of a set of samples
float calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double sample = (double)samples[i];
        sum_of_squares += sample * sample;
    }
    return (float)sqrt(sum_of_squares / num_samples);
}

// Function to log data to a CSV file
void log_data(float mic1_rms, float mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output and ensure it's off
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
        fflush(log_file);
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];
        int mic1_sum = 0;
        int mic2_sum = 0;
        int mic1_count = 0;
        int mic2_count = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_value = read_mcp3008(0);
            int mic2_value = read_mcp3008(1);

            if (mic1_value < 0 || mic2_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC values\n");
                break;
            }

            mic1_samples[mic1_count] = mic1_value;
            mic2_samples[mic2_count] = mic2_value;

            mic1_sum += mic1_value;
            mic2_sum += mic2_value;

            mic1_count++;
            mic2_count++;

            gpioDelay(SAMPLE_INTERVAL_US); // 1 ms delay
        }

        if (mic1_count == NUM_SAMPLES && mic2_count == NUM_SAMPLES) {
            float mic1_rms = calculate_rms(mic1_samples, mic1_count);
            float mic2_rms = calculate_rms(mic2_samples, mic2_count);

            log_data(mic1_rms, mic2_rms);

            if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
                gpioDelay(500000);      // 500 ms delay
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Warning: Incomplete sampling window, skipping threshold check\n");
        }
    }

    // Cleanup and exit
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

