#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// ADS1115 Config Word
#define ADS1115_CONFIG 0x8000 | 0x4000 | 0x0200 | 0x0100 | 0x0080 | 0x0003

// MLX91204 Transfer Function (ratiometric, 5V supply)
#define MLX91204_V_MIN 0.5
#define MLX91204_V_MAX 4.5
#define MLX91204_I_MIN 0.0
#define MLX91204_I_MAX 100.0
#define MLX91204_V_PER_A 5.0

// Global Variables
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

// Function Prototypes
int initialize_i2c(void);
int read_ads1115_raw(int16_t *raw_value);
double convert_to_current(int16_t raw_value);
void add_to_buffer(double current);
double calculate_average(void);
void signal_handler(int signal);
void cleanup(void);

// Signal Handler
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

// Initialize I2C
int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115_raw(int16_t *raw_value) {
    char config[3];
    char read_buf[2];
    int result;

    // Write config to start single conversion on A0
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG | (ADS1115_CONFIG_OS_SINGLE << 15));
    config[2] = (ADS1115_CONFIG_MUX_A0 << 12) | (ADS1115_CONFIG_PGA_4_096V << 9) | (ADS1115_CONFIG_MODE_SINGLE << 5) | (ADS1115_CONFIG_DR_128SPS << 0);

    result = i2cWriteDevice(i2c_handle, config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (approx 8ms for 128 SPS)
    gpioDelay(10000);

    // Read conversion result
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw ADC value to current (A)
double convert_to_current(int16_t raw_value) {
    double voltage = (raw_value * 4.096) / 32768.0;
    return (voltage / MLX91204_V_PER_A) * MLX91204_I_MAX;
}

// Add current reading to circular buffer
void add_to_buffer(double current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Calculate average current from buffer
double calculate_average(void) {
    if (buffer_count == 0) {
        return 0.0;
    }
    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / buffer_count;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
