static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int tcs34725_init(int handle) {
    uint8_t id = 0;
    if (i2c_read_byte(handle, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "ID mismatch: got 0x%02X, expected 0x%02X\n", id, TCS34725_ID_VALUE);
        return -1;
    }
    if (i2c_write_byte(handle, TCS34725_ATIME, TCS34725_ATIME_2_4MS) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_CONTROL, TCS34725_GAIN_4X) < 0) return -1;
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON_AEN) < 0) return -1;
    return 0;
}

static int read_color_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word(handle, TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_RDATA, red) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(handle, TCS34725_BDATA, blue) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cWriteByteData(g_i2c_handle, TCS34725_ENABLE, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %d\n", TCS34725_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcs34725_init(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,clear,red,green,blue\n");
        fflush(g_log_file);
    }

    int consecutive_failures = 0;

    while (g_running) {
        uint16_t clear, red, green, blue;
        int rc = read_color_data(g_i2c_handle, &clear, &red, &green, &blue);
        if (rc == 0) {
            log_data(g_log_file, clear, red, green, blue);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive I2C failures, exiting\n");
                break;
            }
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

