#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VOLTAGE_REF 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define OVERCURRENT_THRESHOLD 10.0
#define MOTOR_SHUTDOWN_PIN 17
#define GPIO_CHIP "gpiochip0"
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n", attempt + 1, MAX_RETRIES, strerror(errno));
        usleep(10000);
    }
    return -1;
}

static float adc_to_current(int adc_value) {
    float voltage = (float)adc_value * VOLTAGE_REF / 1023.0;
    return (voltage - OFFSET) / SENSITIVITY;
}

static void log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return;
        }
        fseek(log_fp, 0, SEEK_END);
        if (ftell(log_fp) == 0) {
            fprintf(log_fp, "timestamp,current_in_Amperes\n");
        }
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, current);
    fflush(log_fp);
}

static void cleanup(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get motor shutdown line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 1) < 0) {
        perror("Failed to request motor shutdown line as output");
        gpiod_line_release(shutdown_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float current = adc_to_current(adc_value);

        log_data(current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Shutting down motor.\n");
            if (gpiod_line_set_value(shutdown_line, 0) < 0) {
                perror("Failed to set motor shutdown line LOW");
            }
            log_data(current);
            sleep(1);
            if (gpiod_line_set_value(shutdown_line, 1) < 0) {
                perror("Failed to set motor shutdown line HIGH");
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

