    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return;
        }
        fseek(log_fp, 0, SEEK_END);
        if (ftell(log_fp) == 0) {
            fprintf(log_fp, "timestamp,current_in_Amperes\n");
        }
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, current);
    fflush(log_fp);
}

static void cleanup(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        perror("Failed to get motor shutdown line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 1) < 0) {
        perror("Failed to request motor shutdown line as output");
        gpiod_line_release(shutdown_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(1);
            continue;
        }

        float current = adc_to_current(adc_value);

        log_data(current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Shutting down motor.\n");
            if (gpiod_line_set_value(shutdown_line, 0) < 0) {
                perror("Failed to set motor shutdown line LOW");
            }
            log_data(current);
            sleep(1);
            if (gpiod_line_set_value(shutdown_line, 1) < 0) {
                perror("Failed to set motor shutdown line HIGH");
            }
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

