#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* ADS1115 config bits */
#define ADS1115_OS_BEGIN       (1 << 15)
#define ADS1115_MUX_AIN0_GND   (0x04 << 12)  /* AIN0 single-ended */
#define ADS1115_MUX_AIN1_GND   (0x05 << 12)  /* AIN1 single-ended */
#define ADS1115_PGA_2_3        (0x01 << 9)   /* FSR ±6.144V */
#define ADS1115_MODE_SINGLE    (0x01 << 8)
#define ADS1115_DR_128SPS      (0x04 << 5)
#define ADS1115_CQUE_NONE      (0x03 << 0)

/* GPIO pin for warning LED */
#define LED_PIN 17

/* Pressure threshold (kPa) */
#define PRESSURE_THRESHOLD 105.0

/* Conversion constants */
#define VREF 5.0
#define VOUT_MIN 0.0
#define VOUT_MAX 5.0
#define P_MIN 0.0
#define P_MAX 400.0
#define T_MIN 0.0
#define T_MAX 100.0

/* ADS1115 config word */
#define ADS1115_CONFIG 0x8000 | ADS1115_OS_BEGIN | ADS1115_MUX_AIN0_GND | ADS1115_PGA_2_3 | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS | ADS1115_CQUE_NONE

/* I2C retry parameters */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to an ADS1115 register */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from an ADS1115 register */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Read a 16-bit ADC value from the ADS1115 */
static int read_ads1115(int handle, uint16_t *raw) {
    uint16_t config = ADS1115_CONFIG;
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
            retries--;
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        /* Wait for conversion to complete (~8ms at 128 SPS) */
        gpioDelay(10000);

        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0) {
            fprintf(stderr, "Error reading ADS1115 config: %s\n", strerror(errno));
            retries--;
            gpioDelay(I2C_RETRY_DELAY_US);
            continue;
        }

        if (cfg & ADS1115_OS_BEGIN) {
            if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, raw) < 0) {
                fprintf(stderr, "Error reading ADS1115 conversion: %s\n", strerror(errno));
                retries--;
                gpioDelay(I2C_RETRY_DELAY_US);
                continue;
            }
            return 0;
        }

        /* Conversion not complete yet */
        retries--;
        gpioDelay(I2C_RETRY_DELAY_US);
    }

    fprintf(stderr, "Failed to read ADS1115 after %d retries\n", I2C_RETRIES);
    return -1;
}

/* Convert raw ADC value to pressure (kPa) */
static float raw_to_pressure(uint16_t raw) {
    float voltage = (raw / 32767.0f) * VREF;
    return (voltage / VOUT_MAX) * (P_MAX - P_MIN) + P_MIN;
}

/* Convert raw ADC value to temperature (°C) */
static float raw_to_temperature(uint16_t raw) {
    float voltage = (raw / 32767.0f) * VREF;
    return (voltage / VOUT_MAX) * (T_MAX - T_MIN) + T_MIN;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address */
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90834 Pressure Sensor Interface (ADS1115 ADC)\n");
    printf("Press Ctrl+C to exit.\n\n");

    while (!terminate) {
        uint16_t raw_pressure = 0;
        uint16_t raw_temperature = 0;

        if (read_ads1115(i2c_handle, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading pressure data, retrying in 1 second...\n");
            gpioDelay(1000000);
            continue;
        }

        if (read_ads1115(i2c_handle, &raw_temperature) < 0) {
            fprintf(stderr, "Error reading temperature data, retrying in 1 second...\n");
            gpioDelay(1000000);
            continue;
        }

        float pressure = raw_to_pressure(raw_pressure);
        float temperature = raw_to_temperature(raw_temperature);

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            printf("WARNING: Pressure exceeds threshold (%.2f kPa > %.2f kPa)!\n", pressure, PRESSURE_THRESHOLD);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

