#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3f       /* MCP3008 reference voltage */
#define SENSITIVITY    0.066f     /* MLX91209: 66 mV/A */
#define OVERCURRENT_THRESHOLD 10.0f /* Amps */
#define MOTOR_SHUTDOWN_PIN 27
#define SAMPLE_INTERVAL_US 100000 /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       Start bit
     *   Byte 1: (0x08 | channel) << 4      Single-ended + channel
     *   Byte 2: 0x00                       Don't-care (clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in upper nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to current (A)                                  */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    float voltage = (float)adc_value * VREF / (float)ADC_MAX_VALUE;
    return (voltage - 0.5f) / SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log current reading with timestamp                                   */
/* ------------------------------------------------------------------ */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Motor shutdown safety monitor                                     */
/* ------------------------------------------------------------------ */
static void check_overcurrent(float current)
{
    if (current > OVERCURRENT_THRESHOLD) {
        fprintf(stderr, "OVERCURRENT DETECTED! Current: %.2f A\n", current);
        if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set motor shutdown pin HIGH\n");
        }
        log_current(current);
        running = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (MOTOR_SHUTDOWN_PIN >= 0) {
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin as output, initially LOW */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize GPIO %d LOW\n", MOTOR_SHUTDOWN_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);
        check_overcurrent(current);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

