#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)
#define ADC_VREF 4.096
#define ADC_MAX_VALUE 32767.0
#define SENSOR_OFFSET 0.5
#define SENSOR_SENSITIVITY 0.1
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_adc(int *raw_value);
float convert_to_pressure(int raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        return -1;
    }

    // Configure ADS1115: Start single conversion, AIN0 vs GND, +/-4.096V, single-shot, 128 SPS, no comparator
    uint16_t config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | 
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | 
                      ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, add margin)
    gpioDelay(10000); // 10ms

    return 0;
}

// Read raw ADC value from ADS1115
int read_adc(int *raw_value) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Point to conversion register
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error setting conversion register pointer: %s\n", strerror(errno));
        return -1;
    }

    // Read 2 bytes of conversion data
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading conversion data: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Convert raw ADC value to pressure (kPa)
float convert_to_pressure(int raw_value) {
    float voltage = (raw_value / ADC_MAX_VALUE) * ADC_VREF;
    float pressure = (voltage - SENSOR_OFFSET) / SENSOR_SENSITIVITY;
    return pressure;
}

// Log pressure reading to file with timestamp
int log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int raw_value;
        if (read_adc(&raw_value) == 0) {
            float pressure = convert_to_pressure(raw_value);
            if (pressure >= 0.0 && pressure <= 100.0) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure reading.\n");
                }
            } else {
                fprintf(stderr, "Invalid pressure reading: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading ADC value.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    return 0;
}

