#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity threshold exceeded. Current humidity: %.2f%%"

#define VREF 5.0
#define ADC_RESOLUTION 4095.0
#define ADC_MAX 4095.0
#define ADC_MIN 0.0
#define ADC_VOUT_MIN 0.0
#define ADC_VOUT_MAX 5.0

#define T0 25.0
#define R0 10.0
#define BETA 3950.0
#define R0_T 25.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x0F) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

float calculate_humidity(int adc_value) {
    float vout = (float)adc_value / ADC_RESOLUTION * VREF;
    if (vout < ADC_VOUT_MIN) vout = ADC_VOUT_MIN;
    if (vout > ADC_VOUT_MAX) vout = ADC_VOUT_MAX;

    float rh = (vout - ADC_VOUT_MIN) / (ADC_VOUT_MAX - ADC_VOUT_MIN) * 100.0;
    if (rh < 0.0) rh = 0.0;
    if (rh > 100.0) rh = 100.0;

    return rh;
}

float calculate_temperature(int adc_value) {
    float vout = (float)adc_value / ADC_RESOLUTION * VREF;
    if (vout < ADC_VOUT_MIN) vout = ADC_VOUT_MIN;
    if (vout > ADC_VOUT_MAX) vout = ADC_VOUT_MAX;

    float t = (vout - ADC_VOUT_MIN) / (ADC_VOUT_MAX - ADC_VOUT_MIN) * 100.0;
    float r = R0 / (R0_T - t);
    float beta = BETA;
    float log_r = logf(r);
    float temp = (beta * t) / (logf(beta) - logf(t + 273.15));
    return temp;
}

void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: %s\\n\\nEmail Body: %s\" | ssmtp %s",
             EMAIL_SUBJECT, EMAIL_BODY, EMAIL_RECIPIENT);

    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to send email alert (system returned %d)\n", result);
    }
}

void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_hum = read_mcp3208(MCP3208_CHANNEL);
        int adc_temp = read_mcp3208(MCP3208_CHANNEL);

        if (adc_hum < 0 || adc_temp < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(1000000);
            continue;
        }

        float humidity = calculate_humidity(adc_hum);
        float temperature = calculate_temperature(adc_temp);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

