#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_PIN 8
#define VREF 3.3f
#define ADC_RESOLUTION 4095.0f
#define TMP36_MIN_TEMP -40.0f
#define TMP36_MAX_TEMP 125.0f
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *chip = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3208_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3208(uint16_t *adc_value) {
    if (spi_fd < 0) {
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS line: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_temperature(uint16_t adc_value) {
    float voltage = (float)adc_value * VREF / ADC_RESOLUTION;
    float temp = (voltage - 0.5f) / 0.01f;
    return temp;
}

static int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }

        fseek(log_fp, 0, SEEK_END);
        long file_size = ftell(log_fp);
        if (file_size == 0) {
            fprintf(log_fp, "timestamp,temperature_celsius\n");
        }
    }

    if (fprintf(log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t adc_value = 0;

        if (read_mcp3208(&adc_value) < 0) {
            fprintf(stderr, "SPI read failed, retrying...\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (adc_value > ADC_RESOLUTION) {
            fprintf(stderr, "ADC value out of range: %u\n", adc_value);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float temperature = adc_to_temperature(adc_value);

        if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Failed to log temperature\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

