#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define SAMPLE_RATE 100
#define IMPACT_THRESHOLD 2.0
#define VREF 3.3
#define ADC_MAX 1023.0
#define ADXL335_SENSITIVITY 0.3
#define ADXL335_ZERO_G_VOLTAGE 1.65

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (gpioWrite(SPI_CHANNEL, 0) < 0) {
        fprintf(stderr, "Failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (gpioWrite(SPI_CHANNEL, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double adc_to_voltage(int adc_value) {
    return (double)adc_value / ADC_MAX * VREF;
}

static double voltage_to_g(double voltage) {
    if (voltage <= ADXL335_ZERO_G_VOLTAGE) {
        return 0.0;
    }
    return (voltage - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
}

static void log_data(int x, int y, int z, double x_g, double y_g, double z_g, int impact) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.4f,%.4f,%.4f,%s\n",
            timestamp, x, y, z, x_g, y_g, z_g, impact ? "IMPACT DETECTED" : "");
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(SPI_CHANNEL, PI_OUTPUT);
    gpioWrite(SPI_CHANNEL, 1);

    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open impact_log.txt\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    printf("Starting impact detection. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int x = read_mcp3008(0);
