#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define SAMPLE_RATE 100
#define IMPACT_THRESHOLD 2.0
#define VREF 3.3
#define ADC_MAX 1023.0
#define ADXL335_SENSITIVITY 0.3
#define ADXL335_ZERO_G_VOLTAGE 1.65

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (gpioWrite(SPI_CHANNEL, 0) < 0) {
        fprintf(stderr, "Failed to assert CS\n");
        return -1;
    }

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (gpioWrite(SPI_CHANNEL, 1) < 0) {
        fprintf(stderr, "Failed to deassert CS\n");
        return -1;
    }

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double adc_to_voltage(int adc_value) {
    return (double)adc_value / ADC_MAX * VREF;
}

