/*
 * Raspberry Pi Zero W - Si1172-A30-GMR Optical Heart Rate Sensor Logger
 *
 * Reads raw photoplethysmography (PPG) samples from the Si1172 via I2C
 * (bus 1, address 0x49) and logs them to biometric_log.csv.
 *
 * NOTE: The Si1172 is a proprietary sensor requiring a custom algorithm
 * to convert raw PPG samples into HR and SpO2. This program logs raw
 * 16-bit IR and RED ADC values as proxy values for HR and SpO2.
 *
 * Build: gcc -O2 -Wall -o hr_logger hr_logger.c -lpigpio -lrt
 * Run:   sudo ./hr_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1172_ADDR    0x49

/* Si1172 command register (0xC0) - write a command to trigger a measurement */
#define SI1172_CMD_REG  0xC0
#define SI1172_CMD_MEAS  0x01  /* Start a measurement / read FIFO */

/* Si1172 FIFO data registers (0xC1-0xC4) - 16-bit little-endian */
#define SI1172_FIFO_DATA_REG  0xC1
#define SI1172_FIFO_IR_REG    0xC2
#define SI1172_FIFO_RED_REG   0xC3

/* Error flags */
#define ERR_OK              0
#define ERR_I2C_OPEN        1
#define ERR_SENSOR_ABSENT   2

/* Globals for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the Si1172 command register              */
/* ------------------------------------------------------------------ */
static int si1172_write_cmd(int handle, uint8_t cmd)
{
    char buf[2];
    buf[0] = (char)cmd;
    buf[1] = 0x00;  /* dummy byte to clock out the command */

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (cmd 0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from a Si1172 FIFO register     */
/* ------------------------------------------------------------------ */
static int si1172_read_fifo(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data_buf[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (reg 0x%02X) failed\n", reg);
        return -1;
    }

    *out = (uint16_t)((uint8_t)data_buf[0] | ((uint8_t)data_buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single raw PPG sample from the Si1172 FIFO                 */
/* ------------------------------------------------------------------ */
static int si1172_read_ppg_sample(int handle, uint16_t *ir, uint16_t *red)
{
    if (si1172_read_fifo(handle, SI1172_FIFO_IR_REG, ir) != 0)
        return -1;
    if (si1172_read_fifo(handle, SI1172_FIFO_RED_REG, red) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                   */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t ir, uint16_t red, int error_flag)
{
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%d\n", (long)now, ir, red, error_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1172 default 7-bit address */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI1172_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv for appending\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,HR_bpm,SpO2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Si1172 HR logger started. Logging to biometric_log.csv (Ctrl+C to stop).\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int      err = ERR_OK;

        /* Trigger a measurement by writing the command */
        if (si1172_write_cmd(g_i2c_handle, SI1172_CMD_MEAS) != 0) {
            err = ERR_I2C_OPEN;
            break;
        }

        /* Wait for the measurement to complete (poll the command register) */
        for (int i = 0; i < 20; i++) {
            if (si1172_read_fifo(g_i2c_handle, SI1172_CMD_REG, NULL) != 0) {
                err = ERR_I2C_OPEN;
                break;
            }
            if (i == 19) {
                fprintf(stderr, "[WARN] Measurement timeout - sensor may be absent or unresponsive\n");
                err = ERR_SENSOR_ABSENT;
                break;
            }
            gpioDelay(10000);  /* 10 ms */
        }

        if (err == ERR_SENSOR_ABSENT) {
            fprintf(stderr, "[ERROR] Sensor absent or unresponsive - logging error row\n");
            log_data(g_log_file, 0, 0, ERR_SENSOR_ABSENT);
            break;
        }

        if (err != ERR_OK) {
            fprintf(stderr, "[ERROR] I2C communication failure - logging error row\n");
            log_data(g_log_file, 0, 0, err);
            break;
        }

        /* Read a single PPG sample */
        if (si1172_read_ppg_sample(g_i2c_handle, &ir, &red) != 0) {
            err = ERR_I2C_OPEN;
            break;
        }

        /* Log the raw data */
        log_data(g_log_file, ir, red, ERR_OK);

        /* Sleep 1 second before the next sample */
        gpioDelay(1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

