#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ICP10125_ADDR 0x67
#define MEASURE_CMD 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_data(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t raw_pressure, raw_temperature;

    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) {
        return -1;
    }

    usleep(10000);

    if (i2c_read_data(fd, data, 6) < 0) {
        return -1;
    }

    raw_pressure = (int32_t)((data[0] << 8) | data[1]);
    raw_temperature = (int32_t)((data[2] << 8) | data[3]);

    *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
    *pressure = 45000.0f * (float)raw_pressure / 65535.0f + 45000.0f;

    return 0;
}

void log_data(FILE *fp, float temperature, float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, pressure);
    fflush(fp);
}

void display_data(float temperature, float pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

int main() {
    float temperature, pressure;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Pressure(Pa)\n");
    }

    while (running) {
        if (read_sensor_data(i2c_fd, &temperature, &pressure) == 0) {
            log_data(log_file, temperature, pressure);
            display_data(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to reopen I2C bus");
                running = 0;
            } else {
                if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
                    perror("Failed to set I2C slave address");
                    close(i2c_fd);
                    i2c_fd = -1;
                }
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("\nExiting gracefully...\n");
    return 0;
}

