#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BUFFER_SIZE 1024
#define GAIN 1.0

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void process_audio(int *audio1, int *audio2, int *output) {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val1 = audio1[i];
        int val2 = audio2[i];
        int diff = val1 - val2;
        output[i] = (diff * GAIN) + 32768;
    }
}

int main(int argc, char *argv[]) {
    int gain = 1.0;

    if (argc > 1) {
        gain = (float)atof(argv[1]);
        if (gain < 0.1 || gain > 1000.0) {
            fprintf(stderr, "Invalid gain value: %s. Using default 1.0.\n", argv[1]);
            gain = 1.0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int *audio1 = (int *)malloc(BUFFER_SIZE * NUM_CHANNELS * sizeof(int));
    int *audio2 = (int *)malloc(BUFFER_SIZE * NUM_CHANNELS * sizeof(int));
    int *output = (int *)malloc(BUFFER_SIZE * NUM_CHANNELS * sizeof(int));

    if (!audio1 || !audio2 || !output) {
        fprintf(stderr, "Memory allocation failed\n");
        free(audio1); free(audio2); free(output);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        for (int ch = 0; ch < NUM_CHANNELS; ch++) {
            audio1[i * NUM_CHANNELS + ch] = read_adc(ADC_CHANNEL);
            audio2[i * NUM_CHANNELS + ch] = read_adc(ADC_CHANNEL);
            output[i * NUM_CHANNELS + ch] = 0;
        }
    }

    while (!terminate) {
        for (int i = 0; i < BUFFER_SIZE; i++) {
            process_audio(audio1, audio2, output);
            printf("%d", output[i]);
            if (i < BUFFER_SIZE - 1) {
                printf(",");
            }
        }
        printf("\n");
        fflush(stdout);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    free(audio1); free(audio2); free(output);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

