#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define BUZZER_PIN 18
#define FLAME_THRESHOLD 1.0
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open SPI device");
        return -1;
    }
    unsigned int speed = SPI_SPEED;
    unsigned char mode = 0;
    unsigned char bits = 8;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static float read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: %s not found, using default 25.0°C\n", TEMP_FILE);
        return 25.0f;
    }
    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: failed to read temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return 25.0f;
    }
    fclose(fp);
    return temp;
}

static void log_data(int raw, float voltage, float flame, float temp) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,%d,%.4f,%.4f,%.2f,%d\n", ts, raw, voltage, flame, temp, flame);
    fflush(log_fp);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return 1;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    while (running) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw = read_mcp3008(spi_fd, 0);
            if (raw >= 0) break;
            usleep(10000);
        }
        if (raw < 0) {
            fprintf(stderr, "SPI read failed after %d attempts\n", MAX_RETRIES);
            log_data(-1, -1.0f, 0, 0);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (float)raw / 1023.0f * 3.3f;
        float temp = read_temperature();
        float flame = (voltage + (temp - 25.0f) * 0.001f) > FLAME_THRESHOLD;
        gpiod_line_set_value(buzzer_line, flame ? 1 : 0);

        log_data(raw, voltage, flame, temp);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

