#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define LED_PIN        17
#define WATER_LEVEL_THRESHOLD_HIGH  75.0f
#define WATER_LEVEL_THRESHOLD_LOW   70.0f
#define SAMPLE_INTERVAL_US 5000000
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_json_file = NULL;
static int g_led_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void log_water_level(float percentage) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (g_json_file) {
        fprintf(g_json_file, "  {\"timestamp\": \"%s\", \"water_level\": %.2f}\n",
                ts, percentage);
        fflush(g_json_file);
    } else {
        fprintf(stderr, "JSON file not open; logging to console: %s\n", ts);
        printf("%s - Water Level: %.2f%%\n", ts, percentage);
    }
}

static void control_led(float percentage) {
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && !g_led_state) {
        if (gpioWrite(LED_PIN, 1) == 0) {
            g_led_state = 1;
            printf("LED ON (water level %.2f%% > %.1f%%)\n",
                   percentage, WATER_LEVEL_THRESHOLD_HIGH);
        } else {
            fprintf(stderr, "Failed to set LED pin %d HIGH\n", LED_PIN);
        }
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && g_led_state) {
        if (gpioWrite(LED_PIN, 0) == 0) {
            g_led_state = 0;
            printf("LED OFF (water level %.2f%% < %.1f%%)\n",
                   percentage, WATER_LEVEL_THRESHOLD_LOW);
        } else {
            fprintf(stderr, "Failed to set LED pin %d LOW\n", LED_PIN);
        }
    }
}

static void cleanup(void) {
    if (g_led_state) {
        gpioWrite(LED_PIN, 0);
        g_led_state = 0;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_json_file) {
        fclose(g_json_file);
        g_json_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(g_spi_handle));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        cleanup();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    g_json_file = fopen("water_levels.json", "a+");
    if (!g_json_file) {
        perror("fopen water_levels.json");
        cleanup();
        return 1;
    }

    fseek(g_json_file, 0, SEEK_END);
    long pos = ftell(g_json_file);
    if (pos == 0) {
        fprintf(g_json_file, "[]\n");
        fflush(g_json_file);
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);
        log_water_level(percentage);
        control_led(percentage);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

