    if (raw_value < config.min_raw) raw_value = config.min_raw;
    if (raw_value > config.max_raw) raw_value = config.max_raw;
    return (int)(((float)(raw_value - config.min_raw) / (config.max_raw - config.min_raw)) * 100.0f);
}

static int log_data(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            moisture_level, config.moisture_threshold);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

static int send_email_alert(int moisture_level) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Plant moisture level is below threshold: %d%%\" | msmtp -t %s -a %s",
             moisture_level, config.recipient_email, config.msmtp_config);

    FILE *fp = popen(command, "w");
    if (!fp) {
        perror("Error opening pipe for msmtp");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("Error closing pipe");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

static int setup(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(config.spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:i:t:l:e:c:")) != -1) {
        switch (opt) {
            case 'c': config.spi_channel = atoi(optarg); break;
            case 'a': config.adc_channel = atoi(optarg); break;
            case 'm': config.min_raw = atoi(optarg); break;
            case 'i': config.max_raw = atoi(optarg); break;
            case 't': config.moisture_threshold = atoi(optarg); break;
            case 'l': config.logging_interval = atoi(optarg); break;
            case 'e': strncpy(config.recipient_email, optarg, sizeof(config.recipient_email) - 1); config.recipient_email[sizeof(config.recipient_email) - 1] = '\0'; break;
            case 'c': strncpy(config.msmtp_config, optarg, sizeof(config.msmtp_config) - 1); config.msmtp_config[sizeof(config.msmtp_config) - 1] = '\0'; break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-i max_raw] [-t moisture_threshold] [-l logging_interval] [-e recipient_email] [-c msmtp_config]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (setup() != 0) {
        return 1;
    }

    printf("Plant monitoring started. Logging every %d seconds.\n", config.logging_interval);

    while (!terminate) {
        int raw_value = read_mcp3008(config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            int moisture_level = calibrate_moisture(raw_value);
            printf("Raw: %d, Moisture: %d%%\n", raw_value, moisture_level);

            if (log_data(moisture_level) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }

            if (moisture_level < config.moisture_threshold) {
                printf("Moisture level below threshold (%d%%). Sending email alert...\n", config.moisture_threshold);
                if (send_email_alert(moisture_level) != 0) {
                    fprintf(stderr, "Error: Failed to send email alert\n");
                }
            }
        }

        for (int i = 0; i < config.logging_interval && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Plant monitoring stopped.\n");
    return 0;
}

