#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define LOG_FILE    "soil_moisture.log"
#define SAMPLE_US   1000000  /* 1 second */
#define ADC_MAX     1023

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel 0               */
/* Returns 0-1023 on success, -1 on error.                            */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle)
{
    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | ch) << 4           (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    char tx[3] = { 0x01, (char)((0x08 | 0x00) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

/* ------------------------------------------------------------------ */
/* Convert 10-bit ADC value to moisture percentage (0-100)             */
/* ------------------------------------------------------------------ */
static float calculate_moisture(int adc_value)
{
    float pct = ((float)adc_value / (float)ADC_MAX) * 100.0f;
    if (pct < 0.0f)   pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

/* ------------------------------------------------------------------ */
/* Log one sample with ISO-8601 timestamp                               */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int adc_value, float moisture_pct)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s, ADC: %d, Moisture: %.2f%%\n", ts, adc_value, moisture_pct);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int sample_interval_us = SAMPLE_US;

    if (argc > 1) {
        sample_interval_us = (int)atoi(argv[1]);
        if (sample_interval_us < 10000 || sample_interval_us > 1000000) {
            fprintf(stderr, "Invalid sample interval '%s'. Using default 1s.\n", argv[1]);
            sample_interval_us = SAMPLE_US;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);  /* mode 0 */
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitor started. Logging to %s every %d us.\n",
           LOG_FILE, sample_interval_us);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle);
        if (adc < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            gpioDelay(sample_interval_us);
            continue;
        }

        float moisture = calculate_moisture(adc);
        log_data(g_log_file, adc, moisture);

        gpioDelay(sample_interval_us);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

