#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_FLAGS 0          // Mode 0, active-low CS
#define ADC_CHANNEL 0       // MCP3008 channel 0
#define ADC_MAX_VALUE 1023  // 10-bit ADC
#define VREF 3.3            // Reference voltage
#define MIN_VOLTAGE 0.5     // 0.5V -> 10 kPa
#define MAX_VOLTAGE 4.5     // 4.5V -> 150 kPa
#define MIN_PRESSURE 10.0   // 10 kPa
#define MAX_PRESSURE 150.0  // 150 kPa
#define SAMPLE_INTERVAL 1   // seconds
#define MAX_CONSECUTIVE_ERRORS 10

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel (3 bits)
    // tx[0] = 0x01 (start)
    // tx[1] = (0x08 | channel) << 4 (single-ended + channel)
    // tx[2] = 0x00 (don't care)
    char tx_buffer[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    // rx[1] contains the two most significant bits (masked with 0x03)
    // rx[2] contains the eight least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

// Convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage %.3fV out of range [%.1f, %.1f]\n",
                voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0; // Indicate invalid reading
    }

    // Map voltage to pressure
    float pressure = MIN_PRESSURE + ((voltage - MIN_VOLTAGE) /
                                    (MAX_VOLTAGE - MIN_VOLTAGE)) *
                     (MAX_PRESSURE - MIN_PRESSURE);

    return pressure;
}

