    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGTERM handler\n");
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("SPI0 CE0, MCP3008 CH0, 1 Hz sampling\n");
    printf("Press Ctrl+C to exit\n\n");

    int consecutive_errors = 0;

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: Failed to read ADC value (consecutive: %d)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Fatal: Max consecutive errors reached. Exiting.\n");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        consecutive_errors = 0;

        // Convert ADC value to voltage
        float voltage = (float)adc_value * VREF / (float)(ADC_MAX_VALUE + 1);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log data
        log_data(pressure);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

