#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_SEC 5

#define MCP3008_CHANNEL 0

static int spi_handle = -1;
static volatile sig_atomic_t running = 1;
static int pump_state = 0;
static int moisture_level = 0;
static int timer_id = -1;
static struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed: expected 3 bytes, got %d\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture level: %d)\n", moisture_level);
        } else {
