#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_ENABLE_1 0x01
#define REG_FIFO_WR_PTR 0x02
#define REG_OVF_COUNTER 0x03
#define REG_FIFO_RD_PTR 0x04
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x0F
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PART_ID 0xFF
#define EXPECTED_PART_ID 0x15

#define SAMPLE_INTERVAL_US 1000000
#define SAMPLE_PERIOD_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    return (rc == (int)len) ? 0 : -1;
}

static int max30102_init(int handle) {
    uint8_t part_id = 0;
    if (i2c_read_reg8(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X). Sensor not present?\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(handle, REG_MODE_CONFIG, 0x40) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg8(handle, REG_INTR_ENABLE_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, REG_FIFO_WR_PTR, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, REG_OVF_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_reg8(handle, REG_FIFO_RD_PTR, 0x00) < 0) return -1;

    if (i2c_write_reg8(handle, REG_FIFO_CONFIG, 0x04) < 0) return -1;
    if (i2c_write_reg8(handle, REG_MODE_CONFIG, 0x03) < 0) return -1;

    if (i2c_write_reg8(handle, REG_SPO2_CONFIG, 0x27) < 0) return -1;
    if (i2c_write_reg8(handle, REG_LED1_PA, 0x24) < 0) return -1;
    if (i2c_write_reg8(handle, REG_LED2_PA, 0x24) < 0) return -1;

    return 0;
}

static int max30102_read_fifo(int handle, uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(handle, REG_FIFO_DATA, buf, 6) < 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir  = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static float calculate_spo2(uint32_t red, uint32_t ir) {
    if (ir == 0) return 0.0f;
    float ratio = (float)red / (float)ir;
    float spo2 = 110.0f - 21.0f * ratio;
    if (spo2 < 0.0f) spo2 = 0.0f;
    if (spo2 > 100.0f) spo2 = 100.0f;
    return spo2;
}

static int detect_peak(int handle, uint32_t *ir, int *peak_idx, int *peak_val) {
    static uint32_t prev = 0;
    uint32_t cur = *ir;
    if (cur == prev) return 0;
    prev = cur;
    if (cur > *peak_val) {
        *peak_idx = *peak_val;
        *peak_val = cur;
        return 1;
    }
    return 0;
}

static void log_event(float spo2, int heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening health_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %d BPM\n", ts, spo2, heart_rate);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MAX30102_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (max30102_init(i2c_handle) < 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MAX30102 initialized. Monitoring SpO2 and heart rate...\n");

    while (!terminate) {
        uint32_t red = 0, ir = 0;
        if (max30102_read_fifo(i2c_handle, &red, &ir) < 0) {
            fprintf(stderr, "Error reading FIFO data\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float spo2 = calculate_spo2(red, ir);
        int heart_rate = 0;
        uint32_t ir_peak = 0, ir_peak_idx = 0;

        if (detect_peak(&ir, &ir_peak, &ir_peak_idx, &heart_rate) > 0) {
            heart_rate = (int)(ir_peak_idx * 5);
        }

        if (spo2 < 95.0f || heart_rate > 100) {
            log_event(spo2, heart_rate);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

