#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUZZER_GPIO 24
#define GAS_THRESHOLD 500
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static void control_buzzer(int gas_value) {
    if (gas_value < GAS_THRESHOLD) {
        if (gpioWrite(BUZZER_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to turn buzzer OFF\n");
        }
    } else {
        if (gpioWrite(BUZZER_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to turn buzzer ON\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize buzzer state\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        spiClose(spi_handle);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MQ-2 Gas Sensor Monitoring (MCP3008 CH0, Buzzer GPIO24)\n");
    printf("Threshold: %d, Sampling: %d ms\n", GAS_THRESHOLD, SAMPLE_INTERVAL_US / 1000);

    while (running) {
        int gas_value = read_mcp3008(0);
        if (gas_value < 0) {
            fprintf(stderr, "Error reading gas sensor, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        control_buzzer(gas_value);
        printf("Gas Value: %d, Buzzer: %s\n", gas_value, (gas_value < GAS_THRESHOLD) ? "OFF" : "ON");
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

