#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01

#define RELAY_PIN      17
#define REED_SENSOR_PIN 27

#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLE_COUNT   10
#define SAMPLE_DELAY_MS 50
#define POLL_DELAY_MS  200
#define RELAY_HOLD_MS  3000
#define THRESHOLD_PCT  80.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = 0x8000 | 0x4000 | 0x0000 | 0x0080 | 0x0003;
    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "ADS1115 config write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, uint16_t *out) {
    uint16_t cfg = 0x8000 | 0x4000 | 0x0000 | 0x0080 | 0x0003;
    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    usleep(10000);
    uint16_t conv;
    if (i2c_read16(fd, ADS1115_REG_CONV, &conv) < 0) return -1;
    *out = conv;
    return 0;
}

static float calculate_threshold(uint16_t *samples, int count) {
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += samples[i];
    return (float)sum / count * 32767.0f;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    struct gpiod_line *reed = gpiod_chip_get_line(chip, REED_SENSOR_PIN);
    if (!relay || !reed) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(relay, "door_lock", 0) < 0 ||
        gpiod_line_request_input(reed, "door_lock", 1) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        close(i2c_fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    uint16_t samples[SAMPLE_COUNT];
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        if (read_adc(i2c_fd, &samples[i]) < 0) {
            fprintf(stderr, "ADS1115 read failed at sample %d\n", i);
            close(i2c_fd);
            gpiod_line_release(relay);
            gpiod_line_release(reed);
            gpiod_chip_close(chip);
            return 1;
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    float threshold = calculate_threshold(samples, SAMPLE_COUNT);
    printf("Threshold: %.2f\n", threshold);

    int relay_state = 0;
    while (running) {
        uint16_t adc;
        if (read_adc(i2c_fd, &adc) < 0) {
            fprintf(stderr, "ADC read failed\n");
            log_event("ADC read error");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        float dist = (float)adc / 32767.0f * 100.0f;
        printf("Distance: %.2f mm\n", dist);

        if (dist < threshold) {
            if (relay_state == 0) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    perror("gpiod_line_set_value");
                } else {
                    relay_state = 1;
                    log_event("Door lock released");
                    printf("Door lock released\n");
                }
            }
            usleep(RELAY_HOLD_MS * 1000);
            if (gpiod_line_set_value(relay, 0) < 0) {
                perror("gpiod_line_set_value");
            } else {
                relay_state = 0;
                int reed = gpiod_line_get_value(reed);
                if (reed < 0) {
                    perror("gpiod_line_get_value");
                } else {
                    log_event(reed == 0 ? "Door opened" : "Door not opened");
                    printf("Door %s\n", reed == 0 ? "opened" : "not opened");
                }
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exiting cleanly\n");
    return 0;
}

