    if (gpiod_line_request_output(relay, "door_lock", 0) < 0 ||
        gpiod_line_request_input(reed, "door_lock", 1) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ads1115_init(i2c_fd) < 0) {
        close(i2c_fd);
        gpiod_line_release(relay);
        gpiod_line_release(reed);
        gpiod_chip_close(chip);
        return 1;
    }

    uint16_t samples[SAMPLE_COUNT];
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        if (read_adc(i2c_fd, &samples[i]) < 0) {
            fprintf(stderr, "ADS1115 read failed at sample %d\n", i);
            close(i2c_fd);
            gpiod_line_release(relay);
            gpiod_line_release(reed);
            gpiod_chip_close(chip);
            return 1;
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    float threshold = calculate_threshold(samples, SAMPLE_COUNT);
    printf("Threshold: %.2f\n", threshold);

    int relay_state = 0;
    while (running) {
        uint16_t adc;
        if (read_adc(i2c_fd, &adc) < 0) {
            fprintf(stderr, "ADC read failed\n");
            log_event("ADC read error");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        float dist = (float)adc / 32767.0f * 100.0f;
        printf("Distance: %.2f mm\n", dist);

        if (dist < threshold) {
            if (relay_state == 0) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    perror("gpiod_line_set_value");
                } else {
                    relay_state = 1;
                    log_event("Door lock released");
                    printf("Door lock released\n");
                }
            }
            usleep(RELAY_HOLD_MS * 1000);
            if (gpiod_line_set_value(relay, 0) < 0) {
                perror("gpiod_line_set_value");
            } else {
                relay_state = 0;
                int reed = gpiod_line_get_value(reed);
                if (reed < 0) {
                    perror("gpiod_line_get_value");
                } else {
                    log_event(reed == 0 ? "Door opened" : "Door not opened");
                    printf("Door %s\n", reed == 0 ? "opened" : "not opened");
                }
            }
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    gpiod_line_set_value(relay, 0);
    gpiod_line_release(relay);
    gpiod_line_release(reed);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Exiting cleanly\n");
    return 0;
}

