#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define LOG_FILE "soil_moisture_log.csv"
#define NUM_SENSORS 3
#define SAMPLE_INTERVAL_SEC 5
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_lines[NUM_SENSORS] = {NULL};
static const int cs_pins[NUM_SENSORS] = {CS0_PIN, CS1_PIN, CS2_PIN};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int chip_index, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d for chip %d\n", channel, chip_index);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_lines[chip_index], 0) < 0) {
        fprintf(stderr, "Error activating CS line for chip %d: %s\n", chip_index, strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer for chip %d: %s\n", chip_index, strerror(errno));
        gpiod_line_set_value(cs_lines[chip_index], 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_lines[chip_index], 1) < 0) {
        fprintf(stderr, "Error deactivating CS line for chip %d: %s\n", chip_index, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(const char *filename, int sensor1, int sensor2, int sensor3) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (cs_lines[i]) {
            gpiod_line_set_value(cs_lines[i], 1);
            gpiod_line_release(cs_lines[i]);
            cs_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(chip, cs_pins[i]);
        if (!cs_lines[i]) {
            fprintf(stderr, "Error getting CS line %d: %s\n", cs_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(cs_lines[i], "mcp3008", 1) < 0) {
            fprintf(stderr, "Error requesting CS line %d as output: %s\n", cs_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int write_header = (fp == NULL);
    if (fp) {
        fclose(fp);
    }

    if (write_header) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Error creating log file: %s\n", strerror(errno));
            cleanup();
            return 1;
        }
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
        fclose(fp);
    }

    printf("Soil moisture logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        int sensor_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i, 0);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }

        if (log_data(LOG_FILE, sensor_values[0], sensor_values[1], sensor_values[2]) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

