#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel, int *out_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            *out_value = ((rx[1] & 0x03) << 8) | rx[2];
            return 0;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n",
                attempt + 1, MAX_RETRIES, ret);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(10000);
        }
    }
    return -1;
}

static float adc_to_moisture(int adc_value) {
    const float dry = 200.0f;
    const float wet = 800.0f;
    if (adc_value < dry) adc_value = dry;
    if (adc_value > wet) adc_value = wet;
    return (float)(adc_value - dry) / (wet - dry) * 100.0f;
}

static void log_event(const char *event, int moisture) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - %s, Moisture: %.2f%%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event, moisture);
    } else {
        fprintf(fp, "[timestamp error] - %s, Moisture: %.2f%%\n", event, moisture);
    }
    fclose(fp);
}

static void control_pump(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", gpio);
        return;
    }
    log_event(state ? "Pump ON" : "Pump OFF", -1);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = 30;
    int duration = 10;
    int sleep_interval = 60;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration <= 0) {
        fprintf(stderr, "Duration must be positive\n");
        return EXIT_FAILURE;
    }
    if (sleep_interval <= 0) {
        fprintf(stderr, "Sleep interval must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started", -1);

    while (running) {
        int adc_value = -1;
        if (read_mcp3008(MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            log_event("ADC read error", -1);
            sleep(sleep_interval);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        log_event("Moisture reading", moisture);

        if (moisture < threshold) {
            log_event("Moisture below threshold", moisture);
            control_pump(PUMP_GPIO, 1);
            sleep(duration);
            control_pump(PUMP_GPIO, 0);
        }

        sleep(sleep_interval);
    }

    log_event("System shutting down", -1);
    cleanup();
    return EXIT_SUCCESS;
}

