#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define CTRL_BYTE      0x00   /* single-ended, channel 0, analog output off */
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Write control byte to select channel 0, single-ended, analog off */
    if (write(fd, &CTRL_BYTE, 1) != 1) {
        fprintf(stderr, "write(control byte) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Dummy read: PCF8591 returns the result of the previous conversion */
    uint8_t dummy;
    if (read(fd, &dummy, 1) != 1) {
        fprintf(stderr, "dummy read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        uint8_t sample;
        if (read(fd, &sample, 1) != 1) {
            fprintf(stderr, "read(sample) failed: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("AIN0: %u\n", sample);
        fflush(stdout);
        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

