#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* ---------------- Configuration ---------------- */
#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_CONV   0x00
#define ADS1115_CONFIG 0x01

#define GPIO_SHUTDOWN  27
#define BUFFER_SIZE    10
#define THRESHOLD_G    500.0f
#define SAMPLE_HZ      1
#define SAMPLE_US      (1000000 / SAMPLE_HZ)
#define ADC_VREF       3.3f
#define ADC_MAX        32767.0f
#define ADC_VMAX       (ADC_VREF * ADC_MAX)
#define SS49E_V0       2.5f   /* Zero-field output (V) */
#define SS49E_SENS     0.0014f /* 1.4 mV/Gauss */
#define SAMPLE_PERIOD_US SAMPLE_US

/* ---------------- Globals ---------------- */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ---------------- Circular buffer ---------------- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer field_buffer;

/* ---------------- Prototypes ---------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_adc(float *voltage);
static float convert_to_gauss(float voltage);
static void buffer_add(float gauss);
static float buffer_average(void);
static void shutdown_motor(void);
static void cleanup(void);

/* ---------------- Signal handler ---------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---------------- I2C / ADS1115 ---------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed: %d", i2c_handle);
        return -1;
    }

    /* Config: single-shot, AIN0 single-ended, 4.096 V ref, 128 SPS */
    uint16_t config = 0x8483; /* OS=1, MUX=100, PGA=001, MODE=1, DR=100 */
    char buf[3];
    buf[0] = ADS1115_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        syslog(LOG_ERR, "ADS1115 config write failed");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Wait for conversion (128 SPS -> ~8 ms; use 10 ms for safety) */
    gpioDelay(10000);
    return 0;
}

static int read_adc(float *voltage)
{
    char reg = ADS1115_CONV;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "ADS1115 conv reg write failed");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "ADS1115 conv read failed");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | (data[1] & 0xFF));
    *voltage = (raw / ADC_MAX) * ADC_VREF;
    return 0;
}

/* ---------------- SS49E transfer function ---------------- */
static float convert_to_gauss(float voltage)
{
    if (voltage < 0.0f) voltage = 0.0f;
    if (voltage > ADC_VMAX) voltage = ADC_VMAX;
    return (voltage - SS49E_V0) / SS49E_SENS;
}

/* ---------------- Circular buffer ---------------- */
static void buffer_add(float gauss)
{
    field_buffer.buffer[field_buffer.head] = gauss;
    field_buffer.head = (field_buffer.head + 1) % BUFFER_SIZE;
    if (field_buffer.count < BUFFER_SIZE)
        field_buffer.count++;
}

static float buffer_average(void)
{
    if (field_buffer.count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < field_buffer.count; i++)
        sum += field_buffer.buffer[i];
    return sum / (float)field_buffer.count;
}

/* ---------------- Motor shutdown ---------------- */
static void shutdown_motor(void)
{
    if (gpioWrite(GPIO_SHUTDOWN, 1) < 0)
        syslog(LOG_ERR, "gpioWrite HIGH failed on GPIO %d", GPIO_SHUTDOWN);
    syslog(LOG_INFO, "Motor shutdown triggered (rolling avg %.1f G > %.1f G)",
           buffer_average(), THRESHOLD_G);
}

/* ---------------- Cleanup ---------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    closelog();
}

/* ---------------- Main ---------------- */
int main(void)
{
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);

