#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x00 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)
#define ADS1115_CONFIG_DEFAULT (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_ON_US 50000
#define BLINK_OFF_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle, uint16_t config) {
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, config_buf, 3) < 0) {
        return -1;
    }

    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) {
        return -1;
    }

    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }

    return (int16_t)((data_buf[0] << 8) | data_buf[1]);
}

static double convert_to_gauss(int16_t adc_value) {
    double voltage = (adc_value * 4.096) / 32768.0;
    return voltage / 0.001;
}

static void blink_led(int gpio, int duration_us) {
    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "Failed to set LED high\n");
        return;
    }
    gpioDelay(BLINK_ON_US);
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "Failed to set LED low\n");
        return;
    }
    gpioDelay(BLINK_OFF_US);
    if (duration_us > BLINK_DURATION_US) {
        gpioDelay(duration_us - BLINK_DURATION_US);
    }
}

int main(int argc, char *argv[]) {
    double threshold = 100.0;

    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold value. Using default 100.0 Gauss.\n");
            threshold = 100.0;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E Hall sensor via ADS1115 (I2C 0x%02X). Threshold: %.2f Gauss. Press Ctrl+C to exit.\n", ADS1115_ADDR, threshold);

    while (running) {
        int16_t adc_value = read_ads1115(i2c_handle, ADS1115_CONFIG_DEFAULT);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from ADS1115\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = convert_to_gauss(adc_value);

        if (gauss > threshold) {
            printf("Magnetic field exceeds threshold: %.2f Gauss\n", gauss);
            blink_led(LED_GPIO, BLINK_DURATION_US);
        } else {
            printf("Magnetic field: %.2f Gauss\n", gauss);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

