#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD 30
#define MOISTURE_HYSTERESIS 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_TOPIC "pump_control"
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_KEEPALIVE 60
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Relay %s", pump_state ? "activated" : "deactivated");
    return 0;
}

static int publish_moisture(int moisture) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", moisture);
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

static int publish_pump(int state) {
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", state);
    int rc = mosquitto_publish(mosq, NULL, MQTT_PUMP_TOPIC, (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        syslog(LOG_ERR, "MQTT disconnect failed: %s", mosquitto_strerror(rc));
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message received");
        return;
    }
    char payload[32];
    memcpy(payload, message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';
    syslog(LOG_INFO, "Received MQTT message: %s", payload);
    if (strcmp(payload, "pump_on") == 0) {
        control_relay(1);
    } else if (strcmp(payload, "pump_off") == 0) {
        control_relay(0);
    }
}

static void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");
    if (pump_state) {
        control_relay(0);
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitor");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "pigpio initialized");

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    syslog(LOG_INFO, "SPI initialized (channel %d, %d Hz)", SPI_CHANNEL, SPI_SPEED);

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (control_relay(0) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return EXIT_FAILURE;
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Monitoring soil moisture every %d s", SAMPLE_INTERVAL);

    while (running) {
        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else if (moisture < 0 || moisture > 1023) {
            syslog(LOG_WARNING, "Sensor out of range: %d", moisture);
        } else {
            syslog(LOG_INFO, "Moisture level: %d%%", moisture);
            if (moisture < MOISTURE_THRESHOLD && !pump_state) {
                if (control_relay(1) == 0) {
                    publish_pump(1);
                }
            } else if (moisture > MOISTURE_HYSTERESIS && pump_state) {
                if (control_relay(0) == 0) {
                    publish_pump(0);
                }
            } else {
                publish_moisture(moisture);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

