#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5
#define BH1750_MEASURE_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    if (i2c_write_byte(fd, 0x10) < 0) return -1;
    usleep(1000);
    if (i2c_write_byte(fd, 0x20) < 0) return -1;
    usleep(BH1750_MEASURE_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int read_max9814(int fd, float *db) {
    uint8_t tx[3] = {0x01, (uint8_t)((MCP3008_CHANNEL & 0x07) << 4), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    *db = 0.5f * (float)adc - 0.5f;
    return 0;
}

static void log_data(FILE *fp, float sound_db, float light_lux, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound_db, light_lux, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) { perror("ioctl i2c"); close(i2c_fd); return 1; }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open spi"); close(i2c_fd); return 1; }
    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) { perror("ioctl spi mode"); close(spi_fd); close(i2c_fd); return 1; }
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) { perror("ioctl spi bits"); close(spi_fd); close(i2c_fd); return 1; }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) { perror("ioctl spi speed"); close(spi_fd); close(i2c_fd); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("fopen log"); close(spi_fd); close(i2c_fd); return 1; }
    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
        fflush(log_fp);
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        float sound_db = -1.0f, light_lux = -1.0f;
        int err = 0;

        if (read_bh1750(i2c_fd, &light_lux) < 0) {
            fprintf(stderr, "BH1750 read error\n");
            err = 1;
        }
        if (read_max9814(i2c_fd, &sound_db) < 0) {
            fprintf(stderr, "MAX9814 read error\n");
            err = 1;
        }

        log_data(log_fp, sound_db, light_lux, err ? 1 : 0);
        printf("Sound: %.2f dB, Light: %.2f lux, Error: %d\n", sound_db, light_lux, err);

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

