#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define LOG_INTERVAL 60
#define MAX_RETRIES 3
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write pump GPIO %d\n", PUMP_GPIO);
    }
}

static void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture_percentage);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize pump GPIO %d to OFF\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                gpioDelay(100000);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            log_data(-1.0);
            sleep(LOG_INTERVAL);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);

        if (moisture_percentage < 0) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            log_data(-1.0);
            sleep(LOG_INTERVAL);
            continue;
        }

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            control_pump(1);
        } else {
            control_pump(0);
        }

        log_data(moisture_percentage);
        sleep(LOG_INTERVAL);
    }

    printf("\nShutting down...\n");
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
