            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        float distance = adc_to_distance(adc_value);

        if (distance < PROXIMITY_THRESHOLD && last_state == 0) {
            debounce_count++;
            if (debounce_count >= 5) {
                debounce_count = 0;
                printf("Proximity detected! Opening door.\n");
                log_event("Proximity detected, door opened");

                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    perror("Failed to set relay high");
                } else {
                    last_state = 1;
                }
            }
        } else if (distance >= PROXIMITY_THRESHOLD && last_state == 1) {
            debounce_count = 0;
            printf("Distance normal. Closing door.\n");
            log_event("Distance normal, door closed");

            if (gpiod_line_set_value(relay_line, 0) < 0) {
                perror("Failed to set relay low");
            } else {
                last_state = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

