#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define ADC_MAX 1023
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile int keep_running = 1;

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

float calculate_valve_position(int avg_adc) {
    if (avg_adc <= 0) return 100.0f;
    if (avg_adc >= ADC_MAX) return 0.0f;
    return 100.0f - ((float)avg_adc / ADC_MAX) * 100.0f;
}

int set_valve_position(float position) {
    if (position < 0.0f) position = 0.0f;
    if (position > 100.0f) position = 100.0f;
    int duty = (int)(position * (PWM_RANGE / 100.0f));
    if (gpioPWM(VALVE_GPIO, duty) != 0) return -1;
    return 0;
}

int log_data(int s0, int s1, int s2, int avg, float valve_pos) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s, Sensor0: %d, Sensor1: %d, Sensor2: %d, Avg: %d, Valve: %.2f%%\n",
                ts, s0, s1, s2, avg, valve_pos) < 0) return -1;
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen("irrigation.log", "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("Irrigation control started. Press Ctrl+C to stop.\n");
    while (keep_running) {
        int sum = 0;
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_mcp3008(i * 3);
            if (v < 0) {
                fprintf(stderr, "Sensor %d read failed\n", i);
                continue;
            }
            sum += v;
            valid++;
        }
        if (valid == 0) {
            fprintf(stderr, "No valid sensor readings\n");
            sleep(LOG_INTERVAL);
            continue;
        }
        int avg = sum / valid;
        float pos = calculate_valve_position(avg);
        if (set_valve_position(pos) != 0) {
            fprintf(stderr, "PWM set failed\n");
        }
        if (log_data(avg, avg, avg, avg, pos) != 0) {
            fprintf(stderr, "Log write failed\n");
        }
        sleep(LOG_INTERVAL);
    }
    set_valve_position(0.0f);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Irrigation control stopped.\n");
    return 0;
}

