#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0 (GPIO8)
#define SPI_SPEED 1000000   // 1 MHz
#define SPI_MODE 0          // SPI Mode 0 (CPOL=0, CPHA=0)
#define MCP3008_CHANNEL 0   // YL-69 connected to CH0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5   // seconds
#define MAX_RETRIES 5
#define MAX_SPI_RETRIES 5

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void log_data(float moisture_level);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC (single-ended mode)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format (3 bytes):
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    // rx_buffer[1] contains the two most significant bits in its lower 2 bits
    // rx_buffer[2] contains the 8 least significant bits
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Convert ADC value to moisture percentage (0-100%)
float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1.0;
    }

    // YL-69: Higher ADC value = drier soil
    // Map 0-1023 to 0-100%
    float moisture_level = 100.0 - ((float)adc_value / 1023.0) * 100.0;

    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;

    return moisture_level;
}

// Log data to file with timestamp
void log_data(float moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_level);
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry mechanism with exponential backoff
        while (retries < MAX_SPI_RETRIES && adc_value < 0) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value < 0) {
                retries++;
                fprintf(stderr, "SPI read failed, retry %d/%d\n", retries, MAX_SPI_RETRIES);
                gpioDelay(100 * (1 << retries)); // 100ms, 200ms, 400ms, 800ms
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries. Skipping sample.\n", MAX_SPI_RETRIES);
            gpioDelay(SAMPLE_INTERVAL * 1000);
            continue;
        }

        // Convert to moisture level
        float moisture_level = convert_to_moisture(adc_value);

        if (moisture_level < 0) {
            fprintf(stderr, "Failed to convert ADC value to moisture level.\n");
            gpioDelay(SAMPLE_INTERVAL * 1000);
            continue;
        }

        // Log data
        log_data(moisture_level);

        printf("Moisture level: %.2f%%\n", moisture_level);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    // Cleanup
    cleanup();
    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

