#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_CYCLE_MAX 1000000
#define CONFIG_FILE "theremin_config.txt"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 10000

volatile sig_atomic_t program_running = 1;
FILE *config_file = NULL;
struct gpiod_chip *chip = NULL;
struct gpiod_line *trigger_line = NULL;
struct gpiod_line *echo_line = NULL;
int spi_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

void cleanup() {
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    if (config_file) fclose(config_file);
}

int load_config() {
    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) return -1;
    int trig_freq = 500, echo_freq = 500, volume = 100;
    if (fscanf(config_file, "%d %d %d", &trig_freq, &echo_freq, &volume) != 3) {
        fclose(config_file);
        config_file = NULL;
        return -1;
    }
    printf("Config loaded: Trig=%d Hz, Echo=%d Hz, Volume=%d%%\n", trig_freq, echo_freq, volume);
    return 0;
}

int save_config() {
    if (!config_file) return -1;
    fprintf(config_file, "%d %d %d\n", TRIGGER_FREQ, ECHO_FREQ, VOLUME);
    fflush(config_file);
    return 0;
}

int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) return -1;
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger_line || !echo_line) return -1;
    if (gpiod_line_request_output(trigger_line, "theremin", 0) < 0) return -1;
    if (gpiod_line_request_input(echo_line, "theremin") < 0) return -1;
    return 0;
}

int init_pwm() {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, "0", 1) < 0) { close(fd); return -1; }
    close(fd);
    usleep(100000);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, &PWM_PERIOD_NS, 8) < 0) { close(fd); return -1; }
    close(fd);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, &VOLUME, 4) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_DUTY_CYCLE_MAX) duty_cycle = PWM_DUTY_CYCLE_MAX;
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return;
    if (write(fd, &duty_cycle, 4) < 0) { close(fd); }
    close(fd);
}

