#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define AQI_THRESHOLD 100
#define AQI_MAX 500
#define LOG_FILE "air_quality.log"
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_aqi(int adc_value);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);
int initialize_spi();
int initialize_gpio();
int initialize_logging();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message for MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate AQI from ADC value
int calculate_aqi(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    // Linear mapping: 0-500 AQI corresponds to 0-1023 ADC value
    int aqi = (int)(((float)adc_value / 1023.0) * AQI_MAX);
    return aqi;
}

// Function to control the ventilation fan
void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

// Function to log data to file
void log_data(int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, AQI: %d\n", timestamp, aqi);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", FAN_GPIO);
        return -1;
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is initially off
    return 0;
}

// Function to initialize logging
int initialize_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        // Retry loop for SPI read
        while (retries < MAX_RETRIES && adc_value < 0) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error: SPI read failed, retrying...\n");
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(RETRY_DELAY_MS * 1000); // Wait 1 second before retrying
                }
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: SPI read failed after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
            spiClose(spi_handle);
            if (initialize_spi() != 0) {
                fprintf(stderr, "Error: SPI re-initialization failed. Exiting.\n");
                break;
            }
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Calculate AQI
        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "Error: AQI calculation failed.\n");
            continue;
        }

        // Control fan
        control_fan(aqi);

        // Log data
        log_data(aqi);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

