#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define PPM_THRESHOLD_HIGH 50.0
#define PPM_THRESHOLD_LOW 20.0
#define ADC_MAX_VALUE 1023.0
#define ADC_MIN_VALUE 0.0
#define ADC_ZERO_ERROR 0
#define ADC_MAX_ERROR 1023
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((channel << 4) | 0x80), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_ppm(int adc_value) {
    if (adc_value < ADC_MIN_VALUE) adc_value = ADC_MIN_VALUE;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;
    return (adc_value * (ADC_MAX_VALUE - ADC_MIN_VALUE) / ADC_MAX_VALUE) - (ADC_MIN_VALUE * (ADC_MAX_VALUE - ADC_MIN_VALUE) / ADC_MAX_VALUE);
}

static void log_data(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s, PPM: %.2f\n", timestamp, ppm);
    fclose(fp);
}

static void check_ppm(float ppm) {
    if (ppm > PPM_THRESHOLD_HIGH) {
        printf("Alcohol detected! Limit exceeded.\n");
        log_data(ppm);
    } else if (ppm < PPM_THRESHOLD_LOW) {
        printf("Sobriety confirmed.\n");
        log_data(ppm);
    } else {
        printf("Alcohol level within acceptable range.\n");
        log_data(ppm);
    }
}

static void cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        fprintf(stderr, "Error getting GPIO8: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mq3_cs", 1) < 0) {
        fprintf(stderr, "Error requesting CS line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MQ-3 Alcohol Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = -1;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "SPI read failed (attempt %d/%d). Retrying...\n", retries, MAX_RETRIES);
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (success) {
            float ppm = adc_to_ppm(adc_value);
            log_data(ppm);
            check_ppm(ppm);
        } else {
            fprintf(stderr, "Failed to read ADC after %d retries. Sensor may be absent or SPI bus error.\n", MAX_RETRIES);
            log_data(-1.0);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

