#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1 pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC channels for potentiometers
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM range
#define PWM_RANGE 255

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float map_speed(int pot_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void motion_profile(int motor1_speed, int motor2_speed);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    // Stop motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    // Close SPI
    spiClose(SPI_CHANNEL);
    // Terminate pigpio
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x80) | channel << 4
    // Byte 2: Don't care (0x00)
    unsigned char tx_buffer[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx_buffer[3] = {0};

    int result = spiXfer(SPI_CHANNEL, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map potentiometer value to speed factor
float map_speed(int pot_value) {
    // Logarithmic mapping for finer control at low speeds
    float speed_factor = log10((float)pot_value + 1.0) / log10(1023.0 + 1.0);
    if (speed_factor < 0.0) speed_factor = 0.0;
    if (speed_factor > 1.0) speed_factor = 1.0;
    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    gpioPWM(motor, speed);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    gpioWrite(motor, direction);
}

// Function to execute the motion profile
void motion_profile(int motor1_speed, int motor2_speed) {
    // Accelerate Motor 1 forward
    for (int i = 0; i <= 255 && program_running; i++) {
        set_motor_speed(1, i);
        set_motor_direction(1, 1);
        set_motor_direction(2, -1);
        gpioDelay(10000); // 10ms delay
    }

    // Hold speed for 2 seconds
    set_motor_speed(1, motor1_speed);
    set_motor_direction(1, 1);
    set_motor_direction(2, -1);
    gpioDelay(2000000); // 2 seconds

    // Decelerate Motor 1
    for (int i = motor1_speed; i >= 0 && program_running; i--) {
        set_motor_speed(1, i);
        gpioDelay(10000); // 10ms delay
    }

    // Reverse direction of Motor 1
    set_motor_direction(1, -1);
    set_motor_direction(2, 1);

    // Accelerate Motor 2 backward
    for (int i = 0; i <= 255 && program_running; i++) {
        set_motor_speed(2, i);
        set_motor_direction(1, -1);
        set_motor_direction(2, 1);
        gpioDelay(10000); // 10ms delay
    }

    // Hold speed for 2 seconds
    set_motor_speed(2, motor2_speed);
    set_motor_direction(1, -1);
    set_motor_direction(2, 1);
    gpioDelay(2000000); // 2 seconds

    // Decelerate Motor 2
    for (int i = motor2_speed; i >= 0 && program_running; i--) {
        set_motor_speed(2, i);
        gpioDelay(10000); // 10ms delay
    }

    // Reverse direction of Motor 2
    set_motor_direction(1, 1);
    set_motor_direction(2, -1);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Open SPI channel
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

