        // Set motor speeds
        set_motor_speed(1, (int)speed_factor1);
        set_motor_speed(2, (int)speed_factor2);

        // Execute motion profile
        motion_profile((int)speed_factor1, (int)speed_factor2);

        // Delay to avoid excessive CPU usage
        gpioDelay(500000); // 500ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

