#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int calibrate_noise_level(int *ambient_level) {
    int sum = 0;
    int valid_samples = 0;

    printf("Calibrating for %d seconds...\n", CALIBRATION_TIME);
    for (int i = 0; i < CALIBRATION_TIME * 1000 && running; i++) {
        int val = read_mcp3008(0);
        if (val >= 0) {
            sum += val;
            valid_samples++;
        }
        gpioDelay(1000);
    }

    if (!running) return -1;

    if (valid_samples == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1;
    }

    *ambient_level = sum / valid_samples;
    printf("Calibration complete. Ambient level: %d\n", *ambient_level);
    return 0;
}

int is_noise_excessive(int ambient_level, int current_level) {
    return current_level > ambient_level * 1.1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int ambient_level = 0;
    if (calibrate_noise_level(&ambient_level) != 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    int led_state = 0;
    uint32_t led_activation_time = 0;

    printf("Monitoring sound levels... Press Ctrl+C to exit.\n");

    while (running) {
        int current_level = read_mcp3008(0);
        if (current_level < 0) {
            fprintf(stderr, "Error reading ADC\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (is_noise_excessive(ambient_level, current_level)) {
            if (!led_state) {
                if (gpioWrite(LED_PIN, 1) == 0) {
                    led_state = 1;
                    led_activation_time = gpioTick();
                } else {
                    fprintf(stderr, "Failed to turn on LED\n");
                }
            } else {
                uint32_t now = gpioTick();
                if (now - led_activation_time >= DEBOUNCE_DELAY_US) {
                    if (gpioWrite(LED_PIN, 0) == 0) {
                        led_state = 0;
                    } else {
                        fprintf(stderr, "Failed to turn off LED\n");
                    }
                }
            }
        } else {
            if (led_state) {
                if (gpioWrite(LED_PIN, 0) == 0) {
                    led_state = 0;
                } else {
                    fprintf(stderr, "Failed to turn off LED\n");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

