#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel 0
#define LOG_FILE "airflow_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Sensor calibration (AWM720P: 0.5V at 0 SLPM, 4.5V at 200 SLPM)
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define AIRFLOW_MAX 200.0

// Global variables for cleanup
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_airflow(float voltage);
void log_data(float airflow);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC (single-ended mode)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel (3 bits), then don't care
    unsigned char tx_buf[3] = {1, (unsigned char)((8 + channel) << 4), 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value: bits 9-2 from rx_buf[1] (lower 2 bits), bits 1-0 from rx_buf[2] (upper 8 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < VOLTAGE_MIN) voltage = VOLTAGE_MIN;
    if (voltage > VOLTAGE_MAX) voltage = VOLTAGE_MAX;
    return (voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN) * AIRFLOW_MAX;
}

// Log data to file with timestamp
void log_data(float airflow) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %.2f SLPM\n", timestamp, airflow);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel (mode 0, active low CS)
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, logging error\n");
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(log_file);
        } else {
            float voltage = (float)adc_value / 1023.0 * 3.3; // 3.3V reference
            float airflow = voltage_to_airflow(voltage);
            log_data(airflow);
        }

        // Sleep for sample interval (100 ms)
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpio delay is in microseconds
    }

    // Cleanup
    cleanup();
    printf("Airflow monitoring stopped.\n");
    return 0;
}

