#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip0"
#define CS_LINE_OFFSET  8          /* GPIO8 = CE0 */
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_HZ       1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_HZ)
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "mcp3008-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       start bit
 *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1, D2 D1 D0 = channel
 *   tx[2] = 0x00                       dummy clocking bytes
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int spi_fd, struct gpiod_line *cs_line, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("gpiod_line_set_value(cs low)");
        return -1;
    }

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("gpiod_line_set_value(cs high)");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static void log_data(FILE *fp, long long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%lld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
    }
    if (fflush(fp) != 0) {
        perror("fflush");
    }
}

int main(void)
{
    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    if (gpio_init() < 0) {
        goto cleanup_spi;
    }

    chip = gpiod_chip_get_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_get_by_name");
        goto cleanup_gpio;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_chip;
    }

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, cs_line, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; continuing\n");
            next.tv_nsec += SAMPLE_PERIOD_NS;
            if (next.tv_nsec >= 1000000000L) {
                next.tv_nsec -= 1000000000L;
                next.tv_sec++;
            }
            nanosleep(&next, NULL);
            continue;
        }

        long long ts = (long long)next.tv_sec * 1000000000LL + next.tv_nsec;
        log_data(fp, ts, adc_value);

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }
        nanosleep(&next, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup_file:
    if (fp) {
        fclose(fp);
    }
cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }
cleanup_gpio:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
cleanup_spi:
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return ret;
}

