#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define ADC_RESOLUTION 1024.0 // 10-bit ADC
#define ADC_VREF 3.3
#define ADXL335_SENSITIVITY 0.3 // 300 mV/g
#define ADXL335_ZERO_G_BIAS 1.5 // 1.5V
#define SAMPLE_RATE 10 // Hz
#define NUM_SAMPLES 100 // Number of samples to average

// Kalman filter parameters
#define Q 0.001 // Process noise covariance
#define R 0.01 // Measurement noise covariance
#define DT 1.0 / SAMPLE_RATE // Time step

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Structure for Kalman filter state
typedef struct {
    double Q;
    double R;
    double DT;
} KalmanFilter;

// Function prototypes
int read_mcp3008(int channel);
double read_adxl335_voltage(int channel);
double convert_voltage_to_acceleration(double voltage);
void kalman_filter(KalmanFilter *filter, double measurement, double *state, double *covariance);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit, single-ended mode, channel select
    char tx_buf[3] = {0x01, (0x08 | channel) << 4, 0x00};
    char rx_buf[3] = {0};

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read voltage from ADXL335
double read_adxl335_voltage(int channel) {
    int adc_value = read_mcp3008(channel);
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }

    double voltage = (adc_value / ADC_RESOLUTION) * ADC_VREF;
    return voltage;
}

// Function to convert voltage to acceleration (g)
double convert_voltage_to_acceleration(double voltage) {
    if (voltage < 0) {
        return 0.0; // Avoid division by zero
    }
    return (voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
}

// Kalman filter implementation
void kalman_filter(KalmanFilter *filter, double measurement, double *state, double *covariance) {
    // Predict step
    double predicted_state = *state;
    double predicted_covariance = *covariance + filter->Q * DT;

    // Update step
    double gain = predicted_covariance / (predicted_covariance + filter->R);
    double corrected_state = predicted_state + gain * (measurement - predicted_state);
    double corrected_covariance = (1.0 - gain) * predicted_covariance;

    *state = corrected_state;
    *covariance = corrected_covariance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize Kalman filter
    KalmanFilter filter;
    filter.Q = Q;
    filter.R = R;
    filter.DT = DT;

    // Initialize state and covariance for Kalman filter
    double state[3] = {0.0, 0.0, 0.0};
    double covariance[3][3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};

    // Main loop
    while (!terminate) {
        // Read voltage from ADXL335 channels
        double voltage_x = read_adxl335_voltage(ADC_CHANNEL_X);
        double voltage_y = read_adxl335_voltage(ADC_CHANNEL_Y);
        double voltage_z = read_adxl335_voltage(ADC_CHANNEL_Z);

        // Check for sensor-absent or bus-error conditions
        if (voltage_x < 0 || voltage_y < 0 || voltage_z < 0) {
            fprintf(stderr, "Error: Sensor read failed, skipping sample\n");
            gpioDelay(1000000 / SAMPLE_RATE); // Wait before next sample
            continue;
        }

        // Convert voltage to acceleration
        double acceleration_x = convert_voltage_to_acceleration(voltage_x);
        double acceleration_y = convert_voltage_to_acceleration(voltage_y);
        double acceleration_z = convert_voltage_to_acceleration(voltage_z);

        // Apply Kalman filter
        kalman_filter(&filter, acceleration_x, &state[0], &covariance[0][0]);
        kalman_filter(&filter, acceleration_y, &state[1], &covariance[1][1]);
        kalman_filter(&filter, acceleration_z, &state[2], &covariance[2][2]);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", state[0], state[1], state[2]);

        // Delay for the specified sample rate
        gpioDelay(1000000 / SAMPLE_RATE);
    }

    // Close SPI channel
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

