#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define NUM_SENSORS 3
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1.0;
    }
    return (double)val;
}

static double calculate_magnetic_field(double v_out) {
    return (v_out - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(double values[NUM_SENSORS]) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", values[0], values[1], values[2]);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int pins[NUM_SENSORS] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    double sensor_values[NUM_SENSORS];
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register signal handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "hall_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_sensor(lines[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d, skipping iteration.\n", i + 1);
                usleep(SAMPLE_INTERVAL_MS * 1000);
                continue;
            }
        }

        double magnetic_field[NUM_SENSORS];
        for (i = 0; i < NUM_SENSORS; i++) {
            magnetic_field[i] = calculate_magnetic_field(sensor_values[i]);
        }

        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        if (magnetic_field[0] > 100.0 || magnetic_field[0] < -100.0 ||
            magnetic_field[1] > 100.0 || magnetic_field[1] < -100.0 ||
            magnetic_field[2] > 100.0 || magnetic_field[2] < -100.0) {
            fprintf(stderr, "Warning: Magnetic field out of range: %.2f, %.2f, %.2f mT\n",
                    magnetic_field[0], magnetic_field[1], magnetic_field[2]);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

