#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, MQTT_QOS);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("Failed to subscribe to topic");
        }
    } else {
        log_error("MQTT connection failed");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Unexpected MQTT disconnect");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;
    if (message->payloadlen > 0) {
        char *payload = malloc(message->payloadlen + 1);
        if (payload == NULL) {
            log_error("Failed to allocate memory for payload");
            return;
        }
        memcpy(payload, message->payload, message->payloadlen);
        payload[message->payloadlen] = '\0';

        cJSON *root = cJSON_Parse(payload);
        if (root == NULL) {
            log_error("JSON parse error");
            free(payload);
            return;
        }

        cJSON *led_state = cJSON_GetObjectItem(root, "led_state");
        if (led_state == NULL) {
            log_error("Missing 'led_state' key");
            cJSON_Delete(root);
            free(payload);
            return;
        }

        if (cJSON_IsBoolean(led_state)) {
            int state = cJSON_GetBoolValue(led_state);
            if (gpioWrite(LED_GPIO, state) != 0) {
                log_error("Failed to write to GPIO");
            }
            free(root);
            free(payload);
        } else {
            log_error("Invalid led_state type");
            cJSON_Delete(root);
            free(payload);
        }
    } else {
        log_error("Empty MQTT message");
    }
}

static void reconnect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m;
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Reconnecting to MQTT broker...\n");
        int delay = 1;
        while (running && delay <= MAX_RECONNECT_DELAY) {
            sleep(delay);
            delay *= 2;
        }
    } else {
        log_error("Reconnect failed");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        log_error("Failed to initialize LED state");
        gpioTerminate();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        log_error("Failed to create MQTT client");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_reconnect_callback_set(mosq, reconnect_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start MQTT loop");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    printf("MQTT client started. Waiting for messages...\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return 0;
}

