#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS 1
#define LOG_FILE "altitude_log.txt"
#define SEA_LEVEL_PRESSURE 101325.0

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle) {
    uint8_t data[24];
    if (i2cReadI2CBlockData(handle, BMP280_REG_CALIB, (char *)data, 24) != 24) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    calib.dig_T1 = (uint16_t)(data[0] | (data[1] << 8));
    calib.dig_T2 = (int16_t)(data[2] | (data[3] << 8));
    calib.dig_T3 = (int16_t)(data[4] | (data[5] << 8));
    calib.dig_P1 = (uint16_t)(data[6] | (data[7] << 8));
    calib.dig_P2 = (int16_t)(data[8] | (data[9] << 8));
    calib.dig_P3 = (int16_t)(data[10] | (data[11] << 8));
    calib.dig_P4 = (int16_t)(data[12] | (data[13] << 8));
    calib.dig_P5 = (int16_t)(data[14] | (data[15] << 8));
    calib.dig_P6 = (int16_t)(data[16] | (data[17] << 8));
    calib.dig_P7 = (int16_t)(data[18] | (data[19] << 8));
    calib.dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    calib.dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int init_bmp280(int handle) {
    int id = i2cReadByteData(handle, BMP280_REG_ID);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data(handle) != 0) return -1;
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas\n");
        return -1;
    }
    if (i2cWriteByteData(handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config\n");
        return -1;
    }
    return 0;
}

static int read_raw_data(int handle, int32_t *temp, int32_t *press) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temp, int32_t *t_fine) {
    double var1 = ((double)raw_temp / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                  ((double)raw_temp / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press, int32_t t_fine) {
    double var1 = ((double)t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * (double)calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)calib.dig_P4 * 65536.0);
    var1 = ((double)calib.dig_P3 * var1 * var1 / 524288.0 + (double)calib.dig_P2 * var1) / 524288.0;
