#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3f
#define LM35_MV_PER_C 10.0f
#define BUFFER_SIZE 120
#define LOG_INTERVAL_SEC 5
#define LOG_FILE "temp_log.dat"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel, float *temperature) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x80 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    *temperature = (float)adc_value * VREF / 1024.0f;
    return 0;
}

static void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->data, 0, sizeof(cb->data));
}

static void add_to_circular_buffer(CircularBuffer *cb, float value) {
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int write_circular_buffer_to_file(CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb+");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    long file_size = ftell(fp);
    if (file_size < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (file_size == 0) {
        if (fwrite(cb->data, sizeof(float), BUFFER_SIZE, fp) != BUFFER_SIZE) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    } else {
        if (fseek(fp, 0, SEEK_SET) != 0) {
            fprintf(stderr, "fseek failed: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }

        if (fwrite(cb->data, sizeof(float), BUFFER_SIZE, fp) != BUFFER_SIZE) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            fclose(fp);
            return -1;
        }
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_mcp3008(MCP3008_CHANNEL, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            add_to_circular_buffer(&temp_buffer, temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        if (write_circular_buffer_to_file(&temp_buffer, LOG_FILE) != 0) {
            fprintf(stderr, "Warning: failed to write circular buffer to file\n");
        }

        for (int i = 0; i < LOG_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

