#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_BUS 1
#define MCP4725_ADDR 0x62
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int set_dac_voltage(float voltage);
void log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    // TMP36: 10mV/°C, 500mV offset
    return (adc_value - 0.5) * 0.01;
}

// Function to set DAC voltage using MCP4725
int set_dac_voltage(float voltage) {
    if (voltage < 0.0 || voltage > 3.3) {
        fprintf(stderr, "Error: Voltage out of range: %.2fV\n", voltage);
        return -1;
    }

    // MCP4725: 12-bit resolution, 0.1% duty cycle
    int dac_value = (int)(voltage / 0.0101);
    if (dac_value < 0 || dac_value > 4095) {
        fprintf(stderr, "Error: DAC value out of range: %d\n", dac_value);
        return -1;
    }

    // Write to I2C DAC
    char buf[2];
    buf[0] = (dac_value >> 4) & 0xFF;
    buf[1] = dac_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed with code %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file);
    printf("%s, ADC: %d, Temperature: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temperature, voltage);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(I2C_BUS, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed with code %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Temperature control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Retrying ADC read... (%d/%d)\n", retries, MAX_RETRIES);
                    gpioDelay(100000); // 100ms delay
                }
            }
        }

        if (success) {
            float temperature = convert_to_celsius(adc_value);
            float voltage = temperature * 3.3 / 100.0; // Linear mapping

            if (set_dac_voltage(voltage) == 0) {
                log_data(adc_value, temperature, voltage);
            } else {
                fprintf(stderr, "Error: Failed to set DAC voltage\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

