#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60

int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

float convert_to_moisture(int adc_value) {
    return (1.0 - (float)adc_value / 1023.0) * 100.0;
}

void log_data(float sensor1, float sensor2, float sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1, sensor2, sensor3);
    fflush(log_file);
}

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        float sensor_values[NUM_SENSORS];
        int adc_values[NUM_SENSORS];
        int error_flag = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_mcp3008(i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                error_flag = 1;
            } else {
                sensor_values[i] = convert_to_moisture(adc_values[i]);
            }
        }

        if (!error_flag) {
            log_data(sensor_values[0], sensor_values[1], sensor_values[2]);
        }

        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

