#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define NUM_RELAYS 4
#define RELAY_ON_TIME_SEC 1
#define RELAY_OFF_TIME_SEC 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void cleanup_resources(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    const unsigned int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    // Open GPIO chip 0 (gpiochip0 on RPi 3B+)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    // Request each relay line as output, initially LOW (inactive)
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            cleanup_resources();
            return EXIT_FAILURE;
        }

        struct gpiod_line_request_config config = {
            .consumer = "relay-sequencer",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
            .flags = 0
        };

        if (gpiod_line_request(relay_lines[i], &config, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", relay_pins[i]);
            cleanup_resources();
            return EXIT_FAILURE;
        }

        // Ensure relay starts in OFF state
        if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set initial state of GPIO line %u\n", relay_pins[i]);
            cleanup_resources();
            return EXIT_FAILURE;
        }
    }

    // Install signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handlers");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            printf("Activating relay %d (BCM %u)\n", i + 1, relay_pins[i]);
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                fprintf(stderr, "Failed to activate relay %d\n", i + 1);
                cleanup_resources();
                return EXIT_FAILURE;
            }

            // Wait for relay ON time, checking for shutdown signal
            for (int t = 0; t < RELAY_ON_TIME_SEC * 10 && keep_running; t++) {
                usleep(100000); // 100 ms
            }

            printf("Deactivating relay %d (BCM %u)\n", i + 1, relay_pins[i]);
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay %d\n", i + 1);
                cleanup_resources();
                return EXIT_FAILURE;
            }

            // Wait for relay OFF time, checking for shutdown signal
            for (int t = 0; t < RELAY_OFF_TIME_SEC * 10 && keep_running; t++) {
                usleep(100000);
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup_resources();
    return EXIT_SUCCESS;
}

