        if (adc_value > SOUND_THRESHOLD) {
            printf("Sound detected (ADC=%d)\n", adc_value);
            gpioWrite(LED_PIN, 1);
            log_event();
            gpioDelay(LED_ON_TIME_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

