#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor driver GPIO pins (L298N) */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CS */

/* Rain sensor threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor PWM parameters */
#define MOTOR_PWM_RANGE 255
#define MOTOR_PWM_DUTY 150

/* Window control duration (seconds) */
#define WINDOW_DURATION 3

/* Polling interval (seconds) */
#define POLL_INTERVAL 1

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; cleanup happens in main loop       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   tx[2] = 0x00  (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10).                  */
/* Higher voltage = dry (0) -> lower ADC = heavy rain (10).          */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0) return -1;
    if (adc_value > 1023) return -1;
    /* Invert: dry = high ADC, heavy rain = low ADC */
    return 10 - (int)(((float)adc_value / 1023.0f) * 10.0f);
}

/* ------------------------------------------------------------------ */
/* Drive motor: IN1=pin, IN2=pin, PWM duty.                          */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int motor_drive(int in1, int in2, int pwm_duty)
{
    if (gpioWrite(in1, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 1) failed\n", in1);
        return -1;
    }
    if (gpioWrite(in2, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, 0) failed\n", in2);
        return -1;
    }
    if (gpioPWM(in1, pwm_duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", in1, pwm_duty);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Close window: motor forward for WINDOW_DURATION seconds.         */
/* ------------------------------------------------------------------ */
static int close_window(void)
{
    printf("Closing window...\n");
    fflush(stdout);

    if (motor_drive(MOTOR_IN1, MOTOR_IN2, MOTOR_PWM_DUTY) != 0)
        return -1;

    for (int i = 0; i < WINDOW_DURATION && program_running; i++)
        sleep(1);

    if (!program_running) return -1;

    if (motor_drive(MOTOR_IN1, MOTOR_IN2, 0) != 0)
        return -1;

    printf("Window closed.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open window: motor reverse for WINDOW_DURATION seconds.           */
/* ------------------------------------------------------------------ */
static int open_window(void)
{
    printf("Opening window...\n");
    fflush(stdout);

    if (motor_drive(MOTOR_IN1, MOTOR_IN2, MOTOR_PWM_DUTY) != 0)
        return -1;

    for (int i = 0; i < WINDOW_DURATION && program_running; i++)
        sleep(1);

    if (!program_running) return -1;

    if (motor_drive(MOTOR_IN1, MOTOR_IN2, 0) != 0)
        return -1;

    printf("Window opened.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log rain reading with timestamp.                                     */
/* ------------------------------------------------------------------ */
static int log_rain_reading(int rain_level)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush on log file failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor */
    if (spi_handle >= 0) {
        motor_drive(MOTOR_IN1, MOTOR_IN2, 0);
        spiClose(spi_handle);
        spi_handle = -1;
    }

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor driver pins */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for motor pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and duty cycle */
    if (gpioSetPWMrange(MOTOR_ENA, MOTOR_PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_ENA, 1000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(MOTOR_ENA, MOTOR_PWM_DUTY) < 0) {
        fprintf(stderr, "Error: gpioPWM initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open rain_log.txt for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("Threshold: %d (close when >=), duration: %d s\n",
           RAIN_THRESHOLD, WINDOW_DURATION);
    fflush(stdout);

    int previous_rain_level = -1;  /* force initial log */

    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying in 1 s...\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        int rain_level = adc_to_rain_level(adc_value);
        if (rain_level < 0) {
            fprintf(stderr, "Error: ADC value out of range, retrying in 1 s...\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        printf("Rain Level: %d (ADC: %d)\n", rain_level, adc_value);
        fflush(stdout);

        if (log_rain_reading(rain_level) != 0) {
            fprintf(stderr, "Warning: failed to log rain reading\n");
        }

        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain level at or above threshold (%d). Closing window...\n",
                   RAIN_THRESHOLD);
            fflush(stdout);
            if (close_window() != 0) {
                fprintf(stderr, "Error: failed to close window\n");
            }
        } else {
            printf("Rain level below threshold (%d). Opening window...\n",
                   RAIN_THRESHOLD);
            fflush(stdout);
            if (open_window() != 0) {
                fprintf(stderr, "Error: failed to open window\n");
            }
        }

        sleep(POLL_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

