#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_DELAY_US 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return val;
}

static void control_led(int on) {
    if (gpioWrite(LED_PIN, on) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on LED pin %d\n", LED_PIN);
    }
}

static void detect_clap(void) {
    int adc = read_adc(MIC_ADC_PIN);
    if (adc < 0) return;
    if (adc > THRESHOLD) {
        control_led(1);
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        printf("[%s] Clap detected! ADC: %d\n", ts, adc);
        gpioDelay(LED_ON_MS * 1000);
        control_led(0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for MIC_ADC_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for LED_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");

    while (running) {
        detect_clap();
        gpioDelay(DEBOUNCE_MS * 1000);
    }

    control_led(0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

