static int gpio_unexport(int pin) {
    FILE *fp = fopen(GPIO_UNEXPORT_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", GPIO_UNEXPORT_PATH, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_DIR_PATH, pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", dir);
    fclose(fp);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    char value[4];
    snprintf(path, sizeof(path), GPIO_VALUE_PATH, pin);
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(value, sizeof(value), fp) == NULL) {
        fprintf(stderr, "Error: Failed to read from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return atoi(value);
}

static float voltage_to_distance(int gpio_value) {
    const float A = 26.0f;
    const float B = -6.0f;
    const float V_MIN = 0.0f;
    const float V_MAX = 3.3f;
    const float D_MIN = 0.0f;
    const float D_MAX = 1000.0f;
    if (gpio_value == 1) {
        return D_MIN + (float)gpio_value * (D_MAX - D_MIN) * (V_MAX - V_MIN) / (V_MAX - V_MIN) + (V_MAX - V_MIN) * (A * V_MIN + B) / (A * V_MIN + B);
