    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) != 0) {
        return 1;
    }
    usleep(100000);

    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder System started. Press Ctrl+C to exit.\n");

    while (running) {
        int gpio_value = gpio_read_value(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Error reading GPIO value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float distance = voltage_to_distance(gpio_value);
        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("Pet Feeder System stopped.\n");
    return 0;
}

