#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define GPIO_CHIP       "gpiochip0"
#define GPIO_CS_LINE    8
#define ADC_CHANNEL     0
#define VREF_MV         3300.0f
#define ADC_MAX         1023
#define DRV5055_SENS_MV_PER_MT 100.0f
#define DRV5055_VCC_MV      1650.0f
#define LOG_FILE        "magnetic_log.txt"
#define SAMPLE_MS       500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int gpio_init(struct gpiod_chip **chip_out, struct gpiod_line **cs_out)
{
    *chip_out = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip_out) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    *cs_out = gpiod_chip_get_line(*chip_out, GPIO_CS_LINE);
    if (!*cs_out) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", GPIO_CS_LINE, strerror(errno));
        gpiod_chip_close(*chip_out);
        *chip_out = NULL;
        return -1;
    }

    if (gpiod_line_request_output(*cs_out, "mcp3008-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(*chip_out);
        *chip_out = NULL;
        *cs_out = NULL;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int fd, int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(*cs_out, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(0): %s\n", strerror(errno));
        return -1;
    }

