        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(*cs_out, 1);
        return -1;
    }

    if (gpiod_line_set_value(*cs_out, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(1): %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_mV(int adc_value)
{
    return (float)adc_value * VREF_MV / (float)ADC_MAX;
}

static float mV_to_mt(float mV)
{
    return (mV - DRV5055_VCC_MV) / DRV5055_SENS_MV_PER_MT;
}

static int log_data(FILE *fp, time_t epoch, float mt)
{
    if (fprintf(fp, "%ld,%.2f\n", (long)epoch, mt) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs = NULL;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        goto cleanup;
    }

    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    if (gpio_init(&chip, &cs) < 0) {
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Logging magnetic field data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
        } else {
            float mV = adc_to_mV(adc_value);
            float mt = mV_to_mt(mV);
            time_t now = time(NULL);
            if (log_data(fp, now, mt) < 0) {
                fprintf(stderr, "Logging failed.\n");
            } else {
                printf("Epoch: %ld, B: %.2f mT\n", (long)now, mt);
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (cs) {
        gpiod_line_release(cs);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

