#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL 0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED 1000000      /* 1 MHz */
#define SPI_FLAGS 0            /* Mode 0, active-low CE */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define VREF 3.3               /* ADC reference voltage */
#define ADC_MAX 1023           /* 10-bit ADC */
#define LED_GPIO 21            /* GPIO pin for LED */
#define FIELD_THRESHOLD 10.0   /* Magnetic field threshold in mT */
#define SENSITIVITY 1.65       /* DRV5055VA sensitivity at 3.3 V (mV/mT) */
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000 /* 100 ms */

/* Global state for cleanup */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read 10-bit value from MCP3008 via SPI */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     * Byte 2: 0x00 (don't care, clocked out to read low byte)
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] (masked 0x03) + rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Convert ADC value to magnetic field strength in mT */
static float adc_to_magnetic(int adc_value) {
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    float quiescent = VREF / 2.0f;
    float field = (voltage - quiescent) * 1000.0f / SENSITIVITY;
    return field;
}

/* Log magnetic field strength with timestamp */
static int log_magnetic_field(float field_strength) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (!tm) {
        perror("localtime failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f mT\n", timestamp, field_strength) < 0) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction failed");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        float field_strength = adc_to_magnetic(adc_value);

        if (log_magnetic_field(field_strength) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        if (field_strength > FIELD_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            printf("Field %.2f mT exceeds threshold! LED ON\n", field_strength);
        } else {
            gpioWrite(LED_GPIO, 0);
            printf("Field %.2f mT below threshold. LED OFF\n", field_strength);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

