#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/* MCP3008 SPI configuration */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0          /* Mode 0, active-low CE */

/* MLX91211 calibration */
#define VREF        5.0        /* MCP3008 VREF (volts) */
#define VOUT_MIN    2.5        /* MLX91211 output at 0 A (volts) */
#define VOUT_MAX    5.0        /* MLX91211 output at +50 A (volts) */
#define CURRENT_MAX 50.0       /* MLX91211 full-scale current (A) */

/* Sampling */
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7). Returns 0-1023 or -1.     */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (single-ended + channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
