#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(struct gpiod_line *line, int pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", pin, strerror(-val));
            return -1;
        }
        if (val == 0) low_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line (sensor1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line (sensor2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w_db01") < 0) {
        perror("gpiod_line_request_input (sensor1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w_db01") < 0) {
        perror("gpiod_line_request_input (sensor2)");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (running) {
        int s1 = read_sensor(line1, SENSOR1_PIN);
        int s2 = read_sensor(line2, SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            break;
        }

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        } else if (s1 == 0) {
            printf("Sensor 1: Object present (GPIO%d = LOW)\n", SENSOR1_PIN);
        } else {
            printf("Sensor 1: No object (GPIO%d = HIGH)\n", SENSOR1_PIN);
        }

        if (s2 == 0) {
            printf("Sensor 2: Object present (GPIO%d = LOW)\n", SENSOR2_PIN);
        } else {
            printf("Sensor 2: No object (GPIO%d = HIGH)\n", SENSOR2_PIN);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

