#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (char)(0x80 | ((channel & 0x07) << 4));
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return adc_value;
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;

    double moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;
    return moisture_level;
}

static int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, moisture_level) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close log file: %s\n", strerror(errno));
        return -1;
    }

    printf("%s,%.2f\n", timestamp, moisture_level);
    return 0;
}

static int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_setup({channel=SPI_CHANNEL, baud=SPI_BAUD, flags=0}) != 0) {
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        for (int i = 0; i < READ_DELAY && !terminate; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

