    if (fprintf(fp, "%s,%.2f\n", timestamp, moisture_level) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close log file: %s\n", strerror(errno));
        return -1;
    }

    printf("%s,%.2f\n", timestamp, moisture_level);
    return 0;
}

static int spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_setup({channel=SPI_CHANNEL, baud=SPI_BAUD, flags=0}) != 0) {
        gpioTerminate();
        return 1;
    }

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        for (int i = 0; i < READ_DELAY && !terminate; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

