#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO        17
#define DEBOUNCE_MS     200
#define POLL_MS         50
#define IMAGE_WIDTH     1280
#define IMAGE_HEIGHT    720
#define IMAGE_SIZE      (IMAGE_WIDTH * IMAGE_HEIGHT * 3)
#define CAPTURE_DIR     "/home/pi/security_cam"
#define TIMESTAMP_LEN   32
#define PATH_LEN        512

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int ensure_capture_dir(void)
{
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        syslog(LOG_ERR, "%s exists but is not a directory", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create capture directory %s", CAPTURE_DIR);
        return -1;
    }
    syslog(LOG_INFO, "Created capture directory: %s", CAPTURE_DIR);
    return 0;
}

static int capture_image(const char *filename)
{
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork() failed: %m");
        return -1;
    }
    if (pid == 0) {
        /* Child process */
        execlp("libcamera-still", "libcamera-still",
               "-o", filename,
               "--width",  "1280",
               "--height", "720",
               "--encoding", "jpeg",
               "--nopreview",
               (char *)NULL);
        /* If execvp returns, it failed */
        syslog(LOG_ERR, "execlp(libcamera-still) failed: %m");
        _exit(127);
    }

    /* Parent: wait for child */
    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR)
            continue;
        syslog(LOG_ERR, "waitpid() failed: %m");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;
    syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
    return -1;
}

static int generate_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed");
        return -1;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        syslog(LOG_ERR, "localtime_r() failed");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return -1;
    }
    return 0;
}

static int save_image(const char *filename)
{
    char ts[TIMESTAMP_LEN];
    if (generate_timestamp(ts, sizeof(ts)) != 0)
        return -1;

    char filepath[PATH_LEN];
    snprintf(filepath, sizeof(filepath), "%s/%s.jpg", CAPTURE_DIR, ts);

    if (access(filepath, F_OK) == 0) {
        syslog(LOG_WARNING, "Image file %s already exists; not overwriting", filepath);
        return 0;
    }

    if (capture_image(filepath) != 0) {
        syslog(LOG_ERR, "Failed to capture image: %s", filepath);
        return -1;
    }

    syslog(LOG_INFO, "Image captured: %s", filepath);
    return 0;
}

int main(void)
{
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO %d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Security camera started (PIR on GPIO%d)", PIR_GPIO);

    int last_state = -1;
    int first_read = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int state = gpioRead(PIR_GPIO);
        if (state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO %d", PIR_GPIO);
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (first_read) {
            last_state = state;
            first_read = 0;
            continue;
        }

        if (state != last_state) {
            if (state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO %d", PIR_GPIO);
                if (save_image(NULL) != 0)
                    syslog(LOG_ERR, "Failed to save image");
            } else {
                syslog(LOG_INFO, "GPIO %d returned to low", PIR_GPIO);
            }
            last_state = state;
            gpioDelay(DEBOUNCE_MS * 1000);
            state = gpioRead(PIR_GPIO);
            if (state < 0) {
                syslog(LOG_ERR, "gpioRead failed during debounce on GPIO %d", PIR_GPIO);
                last_state = -1;
                continue;
            }
            if (state == last_state)
                last_state = state;
        }

        gpioDelay(POLL_MS * 1000);
    }

    syslog(LOG_INFO, "Shutting down security camera");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

