#include <linux/videodev2.h>

#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 5000
#define MAX_BUFFER_SIZE 4096
#define MAX_FRAMES 4
#define MAX_FRAGMENT_SIZE 65000
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS MAX_FRAMES
#define NUM_FRAMES MAX_FRAMES

static volatile sig_atomic_t running = 1;
static int server_ip[4] = {0, 0, 0, 0};
static int server_port = DEFAULT_SERVER_PORT;
static int server_fd = -1;
static int fd = -1;
static unsigned char *buffers[NUM_BUFFERS] = {0};
static unsigned long buffers_size = 0;
static int frame_index = 0;
static int fragment_index = 0;
static int total_fragments = 0;
static int send_queue_size = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(void) {
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        close(fd);
        fd = -1;
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        close(fd);
        fd = -1;
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        fd = -1;
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            close(fd);
            fd = -1;
            return -1;
        }

        buffers[i] = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap failed");
            close(fd);
            fd = -1;
            return -1;
        }
        buffers_size += buf.length;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF failed");
            for (int j = 0; j < i; j++) {
                munmap(buffers[j], buffers[j] ? buffers[j]->length : 0);
            }
            buffers_size = 0;
            close(fd);
            fd = -1;
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i], buffers[i] ? buffers[i]->length : 0);
        }
        buffers_size = 0;
        close(fd);
        fd = -1;
        return -1;
    }

    printf("Camera initialized successfully.\n");
    return 0;
}

static int capture_frame(void) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    if (buf.index >= NUM_BUFFERS) {
        fprintf(stderr, "Buffer index out of range\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    unsigned char *frame = buffers[buf.index];
    int frame_size = buf.bytesused;

    if (frame_size < FRAME_WIDTH * FRAME_HEIGHT) {
        fprintf(stderr, "Frame too small: %d bytes\n", frame_size);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (frame_size > MAX_FRAGMENT_SIZE) {
        fprintf(stderr, "Frame too large: %d bytes\n", frame_size);
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    if (frame_size > 0) {
        memcpy(buffers[frame_index], frame, frame_size);
    }

    frame_index = (frame_index + 1) % NUM_FRAMES;
    if (frame_index == 0) {
        total_fragments = NUM_FRAMES;
        send_queue_size = 0;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

static int send_fragment(void) {
    if (send_queue_size == 0) {
        return 0;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(server_port);

    if (inet_pton(AF_INET, server_ip, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid server IP: %s\n", server_ip);
        return -1;
    }

    char header[32];
    int header_len = snprintf(header, sizeof(header),
        "%d,%d,%d,%d\n",
        frame_index, fragment_index, total_fragments, send_queue_size);
    if (header_len < 0 || (size_t)header_len >= sizeof(header)) {
        fprintf(stderr, "Header too large\n");
        return -1;
    }

    char *payload = malloc(send_queue_size);
    if (!payload) {
        perror("malloc failed");
        return -1;
    }

    memcpy(payload, header, header_len);
    memcpy(payload + header_len, buffers[frame_index], send_queue_size);

    ssize_t sent = sendto(fd, payload, send_queue_size, 0,
        (struct sockaddr *)&addr, sizeof(addr));
    free(payload);

    if (sent < 0) {
        perror("sendto failed");
        return -1;
    }

    send_queue_size = 0;
    return 0;
}

static void cleanup(void) {
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (buffers[i]) {
                munmap(buffers[i], buffers[i] ? buffers[i]->length : 0);
                buffers[i] = NULL;
            }
        }
        close(fd);
        fd = -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%4s%4s%4s%4s", &server_ip[0], &server_ip[1], &server_ip[2], &server_ip[3]) != 4) {
        fprintf(stderr, "Invalid server IP format\n");
        return 1;
    }

    server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid server port: %s\n", argv[2]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (init_camera() < 0) {
        return 1;
    }

    printf("Streaming to %s:%d...\n", server_ip, server_port);

    while (running) {
        if (capture_frame() < 0) {
            break;
        }

        if (send_fragment() < 0) {
            break;
        }
    }

    cleanup();
    printf("Streaming stopped.\n");
    return 0;
}

