#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS   4
#define JPEG_BUF_SIZE ((IMAGE_WIDTH * IMAGE_HEIGHT) * 3 + 512)

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int fd, struct v4l2_capability *cap) {
    memset(cap, 0, sizeof(*cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }
    if (cap->width != IMAGE_WIDTH || cap->height != IMAGE_HEIGHT) {
        fprintf(stderr, "Device does not support %dx%d\n", cap->width, cap->height);
        return -1;
    }
    return 0;
}

static int request_format(int fd, struct v4l2_format *fmt) {
    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->.fmt.pix.width = IMAGE_WIDTH;
    fmt->fmt.pix.height = IMAGE_HEIGHT;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt->pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device did not accept MJPEG format\n");
        return -1;
    }
    return 0;
}

static int request_buffers(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;
    if (xioctl(fd, VIDIOC_REQBUFS, &buf) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (buf->length < (IMAGE_WIDTH * IMAGE_HEIGHT * 3 + 512)) {
        fprintf(stderr, "Buffer too small: %d bytes\n", buf->length);
        return -1;
    }
    return 0;
}

static int queue_buffer(int fd, struct v4l2_buffer *buf, enum v4l2_buf_type type, int delay_time) {
    memset(buf, 0, sizeof(*buf));
    buf->type = type;
    buf->index = 0;
    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int dequeue_buffer(int fd, struct v4l2_buffer *buf, enum v4l2_buf_type type, int delay_time) {
    memset(buf, 0, sizeof(*buf));
