                position, SERVO_MIN, SERVO_MAX);
        return -1;
    }
    int pulse_us = PWM_MIN_US +
                   (position - SERVO_MIN) * (PWM_MAX_US - PWM_MIN_US) / (SERVO_MAX - SERVO_MIN);
    int duty = (pulse_us * PWM_RANGE) / PWM_PERIOD_MS;
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpiod_line_set_value(line, duty > 0 ? 1 : 0) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL, *tilt_line = NULL,
                       *tilt_up_line = NULL, *tilt_down_line = NULL,
                       *pan_left_line = NULL, *pan_right_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line  = gpiod_chip_get_line(chip, PAN_SERVO_LINE);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_LINE);
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_LINE);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_LINE);
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT_LINE);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_LINE);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line ||
        !pan_left_line || !pan_right_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "pan-servo", 0) < 0) {
        perror("gpiod_line_request_output pan");
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "tilt-servo", 0) < 0) {
        perror("gpiod_line_request_output tilt");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_up_line, "tilt-up",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input tilt-up");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_down_line, "tilt-down",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input tilt-down");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_left_line, "pan-left",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input pan-left");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(pan_right_line, "pan-right",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input pan-right");
        goto cleanup;
    }

    int pan_pos  = SERVO_MIN;
    int tilt_pos = SERVO_MIN;
    int tilt_up_state = 0;
    int tilt_down_state = 0;
    int pan_left_state = 0;
    int pan_right_state = 0;

    while (running) {
        int tilt_up_val = gpiod_line_get_value(tilt_up_line);
        int tilt_down_val = gpiod_line_get_value(tilt_down_line);
        int pan_left_val = gpiod_line_get_value(pan_left_line);
        int pan_right_val = gpiod_line_get_value(pan_right_line);

        if (tilt_up_val < 0 || tilt_down_val < 0 ||
            pan_left_val < 0 || pan_right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        tilt_up_state = (tilt_up_val == 0) ? 1 : 0;
        tilt_down_state = (tilt_down_val == 0) ? 1 : 0;
        pan_left_state = (pan_left_val == 0) ? 1 : 0;
        pan_right_state = (pan_right_val == 0) ? 1 : 0;

        if (tilt_up_state) {
            tilt_pos += SERVO_STEP;
            if (tilt_pos > SERVO_MAX) tilt_pos = SERVO_MAX;
            else if (tilt_pos < SERVO_MIN) tilt_pos = SERVO_MIN;
            if (set_servo(tilt_line, tilt_pos) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo\n");
                break;
            }
        }
        if (tilt_down_state) {
            tilt_pos -= SERVO_STEP;
            if (tilt_pos < SERVO_MIN) tilt_pos = SERVO_MIN;
            else if (tilt_pos > SERVO_MAX) tilt_pos = SERVO_MAX;
            if (set_servo(tilt_line, tilt_pos) < 0) {
                fprintf(stderr, "Error: failed to set tilt servo\n");
                break;
            }
        }
        if (pan_left_state) {
            pan_pos += SERVO_STEP;
            if (pan_pos > SERVO_MAX) pan_pos = SERVO_MAX;
            else if (pan_pos < SERVO_MIN) pan_pos = SERVO_MIN;
            if (set_servo(pan_line, pan_pos) < 0) {
                fprintf(stderr, "Error: failed to set pan servo\n");
                break;
            }
        }
        if (pan_right_state) {
            pan_pos -= SERVO_STEP;
            if (pan_pos < SERVO_MIN) pan_pos = SERVO_MIN;
            else if (pan_pos > SERVO_MAX) pan_pos = SERVO_MAX;
            if (set_servo(pan_line, pan_pos) < 0) {
                fprintf(stderr, "Error: failed to set pan servo\n");
                break;
            }
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pan_line)  gpiod_line_release(pan_line);
    if (tilt_line) gpiod_line_release(tilt_line);
    if (tilt_up_line) gpiod_line_release(tilt_up_line);
    if (tilt_down_line) gpiod_line_release(tilt_down_line);
    if (pan_left_line) gpiod_line_release(pan_left_line);
    if (pan_right_line) gpiod_line_release(pan_right_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

