#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define CAMERA_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

typedef struct {
    void *start;
    size_t length;
} buffer_t;

static int x(int x, int y, int w, int h, int *buf) {
    if (x < 0) x = 0;
    if (x + w > h) w = h - x;
    if (y < 0) y = 0;
    if (y + h > w) h = w - y;
    int sum = 0;
    for (int dy = 0; dy < h; dy++) {
        for (int dx = 0; dx < w; dx++) {
            int i = y + dy, j = x + dx;
            sum += buf[i * w + j];
        }
    }
    return sum / (BLUR_RADIUS * BLUR_RADIUS);
}

static int apply_blur(const unsigned char *src, unsigned char *dst, int w, int h) {
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int val = xint32_t(x) * xint32_t(x) + yint32_t(y) * yint32_t(y);
            val = xint32_t(val) + BLUR_RADIUS * BLUR_RADIUS;
            val = (val < 0) ? 0 : (val > 255) ? 255 : val;
            dst[y * w + x] = (unsigned char)val;
        }
    }
    return 0;
}

static int save_jpeg(const unsigned char *img, int w, int h, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *out = NULL;
    unsigned char *row_ptr = NULL;
    int row_stride = w * 3;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &out);

    cinfo.image_width = w;
    cinfo.image_height = h;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    row_ptr = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, 1, w * 3);
    if (!row_ptr) { jpeg_destroy_compress(&cinfo); return -1; }

    while (cinfo.next_scanline < cinfo.image_height) {
        unsigned char *scanline = row_ptr + cinfo.next_scanline * row_stride;
        memcpy(scanline, img + cinfo.next_scanline * w * 3, w * 3);
        jpeg_write_scanlines(&cinfo, &row_ptr, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    out = fopen(filename, "wb");
    if (!out) { fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno)); return -1; }
    if (fwrite(img, 1, w * h * 3, out) != (size_t)(w * h * 3)) { fprintf(stderr, "Error writing %s\n", filename); fclose(out); return -1; }
    fclose(out);
    return 0;
}

static int capture_frame(int fd, buffer_t *buf, size_t *n_buffers, size_t *n_frames) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) { if (errno == EINTR) return 0; fprintf(stderr, "select error: %s\n", strerror(errno)); return -1; }
    if (r == 0) { fprintf(stderr, "select timeout\n"); return -1; }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) { fprintf(stderr, "VIDIOC_DQBUF error: %s\n", strerror(errno)); return -1; }
    *n_frames = buf.index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) { fprintf(stderr, "VIDIOC_QBUF error: %s\n", strerror(errno)); return -1; }
    return 0;
}

int main(void) {
    int fd = -1;
    buffer_t *buffers = NULL;
    size_t n_buffers = 0;
    size_t n_frames = 0;
    unsigned char *rgb = NULL;
    unsigned char *yuyv = NULL;
    char filename[64];
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) { fprintf(stderr, "Cannot open %s: %s\n", CAMERA_DEVICE, strerror(errno)); return 1; }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) { fprintf(stderr, "VIDIOC_QUERYCAP error: %s\n", strerror(errno)); close(fd); return 1; }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) { fprintf(stderr, "Device does not support video capture\n"); close(fd); return 1; }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) { fprintf(stderr, "Device does not support streaming\n"); close(fd); return 1; }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) { fprintf(stderr, "VIDIOC_S_FMT error: %s\n", strerror(errno)); close(fd); return 1; }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) { fprintf(stderr, "Device does not support YUYV\n"); close(fd); return 1; }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) { fprintf(stderr, "VIDIOC_REQBUFS error: %s\n", strerror(errno)); close(fd); return 1; }
    if (req.count < 2) { fprintf(stderr, "Insufficient buffers\n"); close(fd); return 1; }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) { fprintf(stderr, "Out of memory\n"); close(fd); return 1; }

    for (n_buffers = 0; n_buffers < req.count; n_buffers++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) { fprintf(stderr, "VIDIOC_QUERYBUF error: %s\n", strerror(errno)); goto cleanup; }
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) { fprintf(stderr, "mmap error: %s\n", strerror(errno)); goto cleanup; }
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) { fprintf(stderr, "VIDIOC_QBUF error: %s\n", strerror(errno)); goto cleanup; }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) { fprintf(stderr, "VIDIOC_STREAMON error: %s\n", strerror(errno)); goto cleanup; }

    while (!stop_flag) {
        if (capture_frame(fd, buffers, &n_buffers, &n_frames) < 0) break;
        if (n_frames > 0) {
            yuyv = buffers[n_frames % n_buffers].start;
            rgb = malloc(WIDTH * HEIGHT * 3);
            if (!rgb) { fprintf(stderr, "Out of memory\n"); goto cleanup; }
            apply_blur((unsigned char *)yuyv, rgb, WIDTH, HEIGHT);
            if (save_jpeg(rgb, WIDTH, HEIGHT, filename) < 0) {
                free(rgb);
                goto cleanup;
            }
            printf("Saved: %s\n", filename);
            free(rgb);
        }
    }

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
                buffers[i].start = NULL;
            }
        }
        close(fd);
    }
    if (yuyv) munmap(yuyv, WIDTH * HEIGHT * 2);
    if (rgb) free(rgb);
    if (buffers) free(buffers);
    return 0;
}

