        if (buffers[n_buffers].start == MAP_FAILED) { fprintf(stderr, "mmap error: %s\n", strerror(errno)); goto cleanup; }
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) { fprintf(stderr, "VIDIOC_QBUF error: %s\n", strerror(errno)); goto cleanup; }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) { fprintf(stderr, "VIDIOC_STREAMON error: %s\n", strerror(errno)); goto cleanup; }

    while (!stop_flag) {
        if (capture_frame(fd, buffers, &n_buffers, &n_frames) < 0) break;
        if (n_frames > 0) {
            yuyv = buffers[n_frames % n_buffers].start;
            rgb = malloc(WIDTH * HEIGHT * 3);
            if (!rgb) { fprintf(stderr, "Out of memory\n"); goto cleanup; }
            apply_blur((unsigned char *)yuyv, rgb, WIDTH, HEIGHT);
            if (save_jpeg(rgb, WIDTH, HEIGHT, filename) < 0) {
                free(rgb);
                goto cleanup;
            }
            printf("Saved: %s\n", filename);
            free(rgb);
        }
    }

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
                buffers[i].start = NULL;
            }
        }
        close(fd);
    }
    if (yuyv) munmap(yuyv, WIDTH * HEIGHT * 2);
    if (rgb) free(rgb);
    if (buffers) free(buffers);
    return 0;
}

