#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int fd = -1;
static struct v4l2_capability cap = {0};
static struct v4l2_frmsizeenum fs = {0};
static struct v4l2_frameinterval fi = {0};
static struct v4l2_fmtdesc fm = {0};
static struct v4l2_frmsizeenum *frms = NULL;
static struct v4l2_frameinterval *intervals = NULL;
static int num_frms = 0;
static int num_intervals = 0;
static int autofocus_supported = 0;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void cleanup(void) {
    if (fd >= 0) {
        enum_v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0)
            fprintf(stderr, "Warning: VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        if (frms) free(frms);
        if (intervals) free(intervals);
        fd = -1;
    }
}

int main(void) {
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Camera capabilities:\n");
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap.version >> 16) & 0xFF,
           (cap.version >> 8) & 0xFF,
