#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_CENTER 1500
#define SERVO_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE || pulse_width > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(pin=%d, pulse=%d) failed\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static int map_range(int x, int in_min, int in_max, int out_min, int out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize servos to center position */
    if (set_servo(PAN_SERVO_PIN, SERVO_CENTER) < 0 ||
        set_servo(TILT_SERVO_PIN, SERVO_CENTER) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Camera pan-tilt system started.\n");
    printf("  Pan servo: GPIO%d (center=%d us)\n", PAN_SERVO_PIN, SERVO_CENTER);
    printf("  Tilt servo: GPIO%d (center=%d us)\n", TILT_SERVO_PIN, SERVO_CENTER);
    printf("  Buttons: UP=GPIO%d, DOWN=GPIO%d, LEFT=GPIO%d, RIGHT=GPIO%d\n",
           UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("  Pulse range: %d-%d us, step=%d us\n", SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_STEP);
    printf("Press Ctrl+C to exit.\n");

    int pan_pulse = SERVO_CENTER;
    int tilt_pulse = SERVO_CENTER;

    while (running) {
        int up_pressed = gpioRead(UP_BUTTON_PIN);
        int down_pressed = gpioRead(DOWN_BUTTON_PIN);
        int left_pressed = gpioRead(LEFT_BUTTON_PIN);
        int right_pressed = gpioRead(RIGHT_BUTTON_PIN);

        if (up_pressed == 0) {
            pan_pulse = map_range(pan_pulse + SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
            tilt_pulse = map_range(tilt_pulse + SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        } else if (down_pressed == 0) {
            pan_pulse = map_range(pan_pulse - SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
            tilt_pulse = map_range(tilt_pulse - SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        } else if (left_pressed == 0) {
            pan_pulse = map_range(pan_pulse - SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
            tilt_pulse = map_range(tilt_pulse - SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        } else if (right_pressed == 0) {
            pan_pulse = map_range(pan_pulse + SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
            tilt_pulse = map_range(tilt_pulse + SERVO_STEP, SERVO_MIN_PULSE, SERVO_MAX_PULSE, SERVO_MIN_PULSE, SERVO_MAX_PULSE);
        }

        if (set_servo(PAN_SERVO_PIN, pan_pulse) < 0 ||
            set_servo(TILT_SERVO_PIN, tilt_pulse) < 0) {
            fprintf(stderr, "Error: failed to update servo positions\n");
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

