#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/wait.h.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_DIR "motion_captures"
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_US 100000
#define MAX_FILE_SIZE 1024

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int capture_image(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s --width %d --height %d --quality 85 --nopreview 2>/dev/null",
        filename, CAPTURE_WIDTH, CAPTURE_HEIGHT);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute libcamera-still\n");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *timestamp, int motion_detected, int gpio_pin) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init() failed\n");
        return -1;
    }
    char *url = malloc(256);
    if (!url) {
        fprintf(stderr, "Error: malloc() failed for URL\n");
        curl_easy_cleanup(curl);
        return -1;
    }
    int ret = snprintf(url, 256, "http://%s:%d/upload", filename, 80);
    if (ret < 0 || (size_t)ret >= 255) {
        fprintf(stderr, "Error: URL buffer too small\n");
        free(url);
        curl_easy_cleanup(curl);
        return -1;
    }
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Error: curl_slist_append() failed\n");
        free(url);
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion_detected\":%d,\"gpio_pin\":%d}",
        filename, timestamp, motion_detected, gpio_pin);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    CURLcode res = curl_easy_perform(curl);
    curl_slist_free_all(headers);
    free(url);
    if (res != CURLE_OK) {
        fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }
    curl_easy_cleanup(curl);
    return 0;
}

static int create_capture_directory(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: %s exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        perror("Error: mkdir() failed");
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("Error: clock_gettime() failed");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
        perror("Error: localtime_r() failed");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    size_t used = strlen(buf);
    if (used + 8 >= len) {
        fprintf(stderr, "Error: timestamp buffer too small\n");
        return -1;
    }
    snprintf(buf + used, len - used, ".%06ldZ", ts.tv_nsec / 1000);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);
    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Error: invalid port number: %s\n", argv[2]);
        return EXIT_FAILURE;
    }
    curl_global_init(CURL_GLOBAL_ALL);
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", PIR_GPIO);
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", PIR_GPIO);
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    if (create_capture_directory() != 0) {
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction() failed");
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
    }
    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);
    while (running) {
        int motion_detected = 0;
        int level = gpioRead(PIR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed\n", PIR_GPIO);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (level == 1) {
            motion_detected = 1;
        }
        if (motion_detected) {
            char timestamp[32];
            if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                gpioDelay(DEBOUNCE_MS * 1000);
                continue;
            }
            char filename[MAX_FILE_SIZE];
            snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);
            if (capture_image(filename) != 0) {
                fprintf(stderr, "Error: image capture failed for %s\n", filename);
            } else {
                printf("Motion detected! Captured: %s\n", filename);
                if (send_data(filename, timestamp, motion_detected, PIR_GPIO) != 0) {
                    fprintf(stderr, "Error: data send failed for %s\n", filename);
                }
            }
            gpioDelay(DEBOUNCE_MS * 1000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }
    printf("\nShutting down...\n");
    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

