#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_GPIO_LINE	17
#define IMAGE_DIR	"/home/pi/images"
#define LOG_FILE	"/home/pi/motion_capture.log"
#define DEBOUNCE_MS	50
#define POLL_TIMEOUT_MS	100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
	(void)sig;
	program_running = 0;
}

static void log_event(const char *message)
{
	FILE *fp = fopen(LOG_FILE, "a");
	if (!fp) {
		fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
		return;
	}
	time_t t = time(NULL);
	struct tm tm;
	if (localtime_r(&t, &tm)) {
		fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
			tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
			tm.tm_hour, tm.tm_min, tm.tm_sec, message);
	}
	fclose(fp);
}

static int generate_filename(char *filename, size_t filename_size)
{
	time_t t = time(NULL);
	struct tm tm;
	if (!localtime_r(&t, &tm)) {
		return -1;
	}
	if (strftime(filename, filename_size, "%Y%m%d_%H%M%S_%m.jpg", &tm) == 0) {
		return -1;
	}
	return 0;
}

static int capture_image(const char *filename)
{
	char command[512];
	int ret = snprintf(command, sizeof(command),
		"libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
		filename);
	if (ret < 0 || (size_t)ret >= sizeof(command)) {
		return -1;
	}

	int status = system(command);
	if (status == -1) {
		return -1;
	}
	if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
		return -1;
	}
	return 0;
}

int main(void)
{
	struct gpiod_chip *chip = NULL;
	struct gpiod_line *pir_line = NULL;
	int ret = EXIT_FAILURE;

	struct sigaction sa;
	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = signal_handler;
	sigemptyset(&sa.sa_mask);
	sa.sa_flags = 0;
	if (sigaction(SIGINT, &sa, NULL) == -1) {
		fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
		return EXIT_FAILURE;
	}
	if (sigaction(SIGTERM, &sa, NULL) == -1) {
		fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
		return EXIT_FAILURE;
	}

	chip = gpiod_chip_open_by_name("gpiochip0");
	if (!chip) {
		fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
		return EXIT_FAILURE;
	}

	pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
	if (!pir_line) {
		fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
		goto cleanup;
	}

	if (gpiod_line_request_falling_edge_events(pir_line, "motion-capture") < 0) {
		fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
			PIR_GPIO_LINE, strerror(errno));
		goto cleanup;
	}

	printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", PIR_GPIO_LINE);

	while (program_running) {
		struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
		int event = gpiod_line_event_wait(pir_line, &ts);
		if (event < 0) {
			if (errno == EINTR) {
				continue;
			}
			fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
			break;
		}
		if (event == 0) {
			continue;
		}

		struct gpiod_line_event ev;
