#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd, struct v4l2_capability *cap, struct v4l2_format *fmt) {
    *fd = open(DEVICE_NAME, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap->capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(fmt, 0, sizeof(*fmt));
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->.fmt.pix.width = 640;
    fmt->fmt.pix.height = 480;
    fmt->fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt->fmt.pix.width != 640 || fmt->fmt.pix.height != 480) {
        fprintf(stderr, "Device did not accept requested format\n");
        close(*fd);
        return -1;
    }

    return 0;
}

static int start_streaming(int fd) {
    struct v4l2_requestbuffers *req;
    struct v4l2_buffer *buf;
    unsigned int i;

    req = malloc(sizeof(*req));
    if (!req) {
        perror("malloc");
        return -1;
    }
    req->count = 1;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, req) < 0) {
        perror("VIDIOC_REQBUFS");
        free(req);
        return -1;
    }

    buf = malloc(sizeof(*buf));
    if (!buf) {
        perror("malloc");
        free(req);
        return -1;
    }
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        free(buf);
        free(req);
        return -1;
    }

    req->length = buf->length;
    req->bytesused = buf->bytesused;

    if (mmap(buf->start, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset) == MAP_FAILED) {
        perror("mmap");
        munmap((void *)buf->start, buf->length);
        free(buf);
        free(req);
        return -1;
    }

    buf->length = 0;
    buf->bytesused = 0;
    buf->offset = 0;

    if (xioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap((void *)buf->start, buf->length);
        free(buf);
        free(req);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap((void *)buf->start, buf->length);
        free(buf);
        free(req);
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char **frame, size_t *frame_size) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Capture timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *frame = (unsigned char *)buf.m.map;
    *frame_size = buf.bytesused;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 0;
}

static int crop_frame(const unsigned char *frame, size_t frame_size, int x, int y, int w, int h, unsigned char *cropped) {
    size_t crop_size = (size_t)w * (size_t)h * 2;
    if (frame_size < crop_size) {
        fprintf(stderr, "Frame too small for crop\n");
        return -1;
    }

    size_t offset = (size_t)y * 2;
    memcpy(cropped, frame + offset, (size_t)w * (size_t)h * 2);

    return 0;
}

static int save_frame(const unsigned char *cropped, size_t frame_size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t written = fwrite(cropped, 1, frame_size, fp);
    if (written != (size_t)frame_size) {
        fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    unsigned char *frame = NULL;
    size_t frame_size = 0;
    unsigned char *cropped = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    if (init_camera(&fd, &cap, &fmt) < 0) {
        goto cleanup;
    }

    if (start_streaming(fd) < 0) {
        goto cleanup;
    }

    printf("Capturing frame...\n");
    if (capture_frame(fd, &frame, &frame_size) < 0) {
        goto cleanup;
    }

    printf("Cropping frame...\n");
    cropped = malloc(frame_size);
    if (!cropped) {
        perror("malloc");
        goto cleanup;
    }
    if (crop_frame(frame, frame_size, 100, 50, 200, 150, cropped) < 0) {
        goto cleanup;
    }

    printf("Saving cropped frame...\n");
    if (save_frame(cropped, frame_size, OUTPUT_FILE) < 0) {
        goto cleanup;
    }

    printf("Frame saved to %s\n", OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        if (munmap((void *)frame, frame_size) < 0) {
            perror("munmap");
        }
        if (munmap((void *)cropped, frame_size) < 0) {
            perror("munmap cropped");
        }
        close(fd);
    }
    free(cropped);
    return ret;
}

