#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_nibble(int handle, unsigned char nibble, int is_char) {
    unsigned char data = (nibble & 0xF0) | (is_char ? LCD_CHR : 0);
    data |= LCD_BACKLIGHT;
    data |= ENABLE;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(100);
    data &= ~ENABLE;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(100);
    return 0;
}

static int lcd_send_command(int handle, unsigned char cmd) {
    return lcd_write_nibble(handle, cmd >> 4, 0);
}

static int lcd_send_data(int handle, unsigned char data) {
    return lcd_write_nibble(handle, data & 0xF0, 1);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_send_command(handle, 0x33) < 0) return -1;
    if (lcd_send_command(handle, 0x32) < 0) return -1;
    if (lcd_send_command(handle, 0x28) < 0) return -1;
    if (lcd_send_command(handle, 0x0C) < 0) return -1;
    if (lcd_send_command(handle, 0x06) < 0) return -1;
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_clear(int handle) {
    return lcd_send_command(handle, 0x01);
}

static int lcd_set_cursor(int handle, int row, int col) {
    int addr = (row == 0) ? (col & 0x0F) : (0x40 | (col & 0x0F));
    return lcd_send_command(handle, 0x80 | addr);
}

static int lcd_print(int handle, const char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        return lcd_send_data(handle, (unsigned char)str[i]);
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    i2c_handle = i2cOpen(I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", LCD_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (lcd_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize LCD\n");
        cleanup();
        return 1;
    }

    double total_volume = 0.0;
    int pulses = 0;
    time_t last_flow_update = time(NULL);

    while (running) {
        int pulse_count = 0;
        int timeout = 1000000;
        while (running && pulse_count < 100) {
            int level = gpioRead(FLOW_SENSOR_GPIO);
            if (level < 0) {
                fprintf(stderr, "GPIO read error\n");
                break;
            }
            if (level == 1) {
                pulse_count++;
                if (pulse_count >= 100) break;
            }
            gpioDelay(1000);
        }

        if (!running) break;

        if (pulse_count >= 100) {
            pulses = pulse_count;
            double flow_rate = (pulses / PULSES_PER_LITER) * 60.0;
            time_t now = time(NULL);
            if (difftime(now, last_flow_update) >= 10.0) {
                total_volume += flow_rate;
                char line1[20], line2[20];
                snprintf(line1, sizeof(line1), "Flow: %.2f LPM", flow_rate);
                snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);
                lcd_clear(i2c_handle);
                lcd_set_cursor(i2c_handle, 0, 0);
                lcd_print(i2c_handle, line1);
                lcd_set_cursor(i2c_handle, 1, 0);
                lcd_print(i2c_handle, line2);
                last_flow_update = now;
            }
        }

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

