#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define SAMPLE_INTERVAL_SEC 1
#define MAX_PULSES 1000000
#define ZERO_PULSES_TIMEOUT_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int lcd_write_nibble(int handle, unsigned char nibble) {
    int data = (nibble & 0xF0) | 0x04 | 0x01;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(2000);
    data = (nibble & 0xF0) | 0x04 | 0x02;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(2000);
    data = (nibble & 0xF0) | 0x04 | 0x01;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(2000);
    data = (nibble & 0xF0) | 0x04 | 0x02;
    if (i2cWriteByteData(handle, 0, data) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_command(int handle, unsigned char cmd) {
    return lcd_write_nibble(handle, cmd & 0xF0);
}

static int lcd_data(int handle, unsigned char data) {
    return lcd_write_nibble(handle, (data & 0xF0) | 0x40);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    if (lcd_command(handle, 0x30) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x30) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x30) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x20) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x28) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x08) < 0) return -1;
    gpioDelay(5000);
    if (lcd_command(handle, 0x01) < 0) return -1;
    gpioDelay(5000);
    return 0;
}

static int lcd_clear(int handle) {
    if (lcd_command(handle, 0x01) < 0) return -1;
    gpioDelay(2000);
    return 0;
}

static int lcd_set_cursor(int handle, int row, int col) {
    unsigned char addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    return lcd_command(handle, addr);
}

static int lcd_print(int handle, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        if (lcd_data(handle, (unsigned char)text[i]) < 0) return -1;
    }
    return 0;
}

static int lcd_set_line(int handle, int line, const char *text) {
    if (lcd_clear(handle) < 0) return -1;
    if (lcd_set_cursor(handle, line, 0) < 0) return -1;
    return lcd_print(handle, text);
}

static int lcd_set_flow_rate(int handle, float flow_rate) {
    char line1[17];
    char line2[17];
    snprintf(line1, sizeof(line1), "Flow Rate: %.2f", flow_rate);
    snprintf(line2, sizeof(line2), "L/min");
    return lcd_set_line(handle, 0, line1);
}

static int read_flow_rate(int gpio_pin, float *flow_rate) {
    int pulses = 0;
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        int val = gpioRead(gpio_pin);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
            return -1;
        }
        if (val == 1) pulses++;
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed >= SAMPLE_INTERVAL_SEC) {
            *flow_rate = (float)pulses / PULSES_PER_LITER * 60.0;
            return 0;
        }
    }
    return 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        lcd_clear(i2c_handle);
        lcd_write_nibble(i2c_handle, 0x03);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

