#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

/* BCM GPIO numbers for rows (anodes) and columns (cathodes) */
static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

static int set_row(struct gpiod_line *line, int row, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error: failed to set row %d to %d\n", row, val);
        return -1;
    }
    return 0;
}

static int set_col(struct gpiod_line *line, int col, int val) {
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error: failed to set col %d to %d\n", col, val);
        return -1;
    }
    return 0;
}

static int clear_matrix(struct gpiod_line *lines[NUM_ROWS][NUM_COLS]) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            set_row(lines[r][c], r, 0);
            set_col(lines[r][c], c, 1);
        }
    }
    return 0;
}

static int scan_row(struct gpiod_line *lines[NUM_ROWS][NUM_COLS], int row, int pattern) {
    for (int c = 0; c < NUM_COLS; c++) {
        int val = (pattern == 1) ? 1 : 0;
        if (set_col(lines[row][c], c, val) < 0) return -1;
    }
    set_row(lines[row][0], row, 1); /* row HIGH for common-anode */
    usleep(SCAN_DELAY_US);
    for (int c = 0; c < NUM_COLS; c++) {
        set_col(lines[row][c], c, 0);
    }
    return 0;
}

static int display_wave(struct gpiod_line *lines[NUM_ROWS][NUM_COLS],
                        int wave, int direction) {
    int pattern = (direction == 1) ? 1 : 0;
    for (int row = 0; row < NUM_ROWS && keep_running; row++) {
        if (scan_row(lines, row, pattern) < 0) return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_ROWS][NUM_COLS];
    int ret = 1;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0\n");
        return 1;
    }

    /* Request row lines as outputs, initially low */
    for (int r = 0; r < NUM_ROWS; r++) {
        lines[r] = gpiod_chip_get_line(chip, row_pins[r]);
        if (!lines[r]) {
            fprintf(stderr, "Error: failed to get row line %d\n", row_pins[r]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[r], "led_matrix", 0) < 0) {
            fprintf(stderr, "Error: failed to request row %d as output\n", row_pins[r]);
            goto cleanup;
        }
    }

    /* Request column lines as outputs, initially high (cathodes off) */
    for (int c = 0; c < NUM_COLS; c++) {
        lines[c] = gpiod_chip_get_line(chip, col_pins[c]);
        if (!lines[c]) {
            fprintf(stderr, "Error: failed to get col line %d\n", col_pins[c]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[c], "led_matrix", 1) < 0) {
            fprintf(stderr, "Error: failed to request col %d as output\n", col_pins[c]);
            goto cleanup;
        }
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        goto cleanup;
    }

    /* Initialize matrix to off */
    clear_matrix(lines);

    /* Wave patterns: left-to-right (1) and right-to-left (0) */
    int wave1[NUM_ROWS] = {1, 1, 1, 1, 1, 1, 1, 1};
    int wave2[NUM_ROWS] = {0, 0, 0, 0, 0, 0, 0, 0};

    while (keep_running) {
        /* Display left-to-right wave */
        if (display_wave(lines, wave1, 1) < 0) break;
        /* Display right-to-left wave */
        if (display_wave(lines, wave2, 0) < 0) break;
    }

    ret = 0;

cleanup:
    /* Turn off all LEDs and release lines */
    clear_matrix(lines);
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            gpiod_line_release(lines[r][c]);
        }
    }
    gpiod_chip_close(chip);
    return ret;
}

