#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_set_value(row_lines[i], 1);
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_set_value(col_lines[i], 1);
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            cleanup();
            return 1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get column line %u\n", col_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request column line %u as output\n", col_pins[i]);
            cleanup();
            return 1;
        }
    }

    while (1) {
        for (int c = 0; c < NUM_COLS; c++) {
            if (gpiod_line_set_value(col_lines[c], 0) < 0) {
                perror("gpiod_line_set_value column");
                cleanup();
                return 1;
            }
            for (int r = 0; r < NUM_ROWS; r++) {
                if (gpiod_line_set_value(row_lines[r], 1) < 0) {
                    perror("gpiod_line_set_value row");
                    cleanup();
                    return 1;
                }
            }
            usleep(DELAY_MS * 1000);
            for (int r = 0; r < NUM_ROWS; r++) {
                if (gpiod_line_set_value(row_lines[r], 0) < 0) {
                    perror("gpiod_line_set_value row");
                    cleanup();
                    return 1;
                }
            }
            for (int r = 0; r < NUM_ROWS; r++) {
                if (gpiod_line_set_value(row_lines[r], 1) < 0) {
                    perror("gpiod_line_set_value row");
                    cleanup();
                    return 1;
                }
            }
        }
    }

    cleanup();
    return 0;
}

