/*
 * VL53L3CX Multi-Target ToF Sensor Interface for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX requires a proprietary ST Ultra Lite Driver (ULD) firmware
 * download and initialization sequence. This code stubs the proprietary
 * initialization with a placeholder register write to demonstrate the I2C
 * communication and error handling. A real implementation would require
 * downloading the ULD firmware and following the ST-provided initialization
 * sequence (available in the ST Ultra Lite Driver SDK).
 *
 * Compile: gcc -o vl53l3cx vl53l3cx.c -lpigpio -lrt
 * Run:     sudo ./vl53l3cx
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L3CX I2C default address (SDO tied to GND) */
#define VL53L3CX_ADDR 0x29

/* VL53L3CX Register Addresses (16-bit, big-endian on the bus) */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START       0x0000
#define VL53L3CX_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L3CX_REG_RESULT_DISTANCE         0x0096

/* Expected Model ID for VL53L3CX */
#define VL53L3CX_MODEL_ID 0xEA

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address and a 16-bit value (big-endian) */
static int vl53l3cx_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register value (big-endian) */
static int vl53l3cx_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }

    *value = ((uint16_t)(data_buf[0] & 0xFF) << 8) | (uint16_t)(data_buf[1] & 0xFF);
    return 0;
}

/* Initialize the VL53L3CX sensor */
static int vl53l3cx_init(int handle) {
    uint16_t model_id = 0;

    /* Verify sensor identity */
    if (vl53l3cx_read_reg16(handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read Model ID register.\n");
        return -1;
    }

    if (model_id != VL53L3CX_MODEL_ID) {
        fprintf(stderr, "Error: Invalid Model ID (0x%04X). Expected 0x%04X.\n", model_id, VL53L3CX_MODEL_ID);
        return -1;
    }

    printf("VL53L3CX detected. Model ID: 0x%04X\n", model_id);

    /* Placeholder: Stub the proprietary ULD initialization sequence */
    /* In a real implementation, this would download the ULD firmware and
     * follow the ST-provided initialization sequence. */
    printf("Stub: Initializing VL53L3CX...\n");
    if (vl53l3cx_write_reg16(handle, 0x0000, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to initialize VL53L3CX.\n");
        return -1;
    }
    printf("VL53L3CX initialized successfully.\n");

    return 0;
}

/* Read distance data from the VL53L3CX */
static int vl53l3cx_read_distance(int handle, uint16_t *distance) {
    uint16_t status = 0;

    /* Start a single measurement */
    if (vl53l3cx_write_reg16(handle, VL53L3CX_REG_SYSTEM_MODE_START, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }

    /* Poll for data ready (bit 0 of RESULT_RANGE_STATUS) */
    for (int i = 0; i < 100; i++) {
        if (vl53l3cx_read_reg16(handle, VL53L3CX_REG_RESULT_RANGE_STATUS, &status) != 0) {
            fprintf(stderr, "Error: Failed to read range status.\n");
            return -1;
        }

        if (status & 0x0001) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x0001)) {
        fprintf(stderr, "Error: Measurement timeout.\n");
        return -1;
    }

    /* Read the distance */
    if (vl53l3cx_read_reg16(handle, VL53L3CX_REG_RESULT_DISTANCE, distance) != 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }

    return 0;
}

/* Log the distance data with an ISO-8601 timestamp */
static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s - Distance: %u mm\n", timestamp, distance);
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(1, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", VL53L3CX_ADDR);
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (vl53l3cx_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Starting distance measurements...\n");

    /* Main loop */
    while (!terminate) {
        uint16_t distance = 0;

        if (vl53l3cx_read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean up */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

