        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
            return -1;
        }
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,distance\n");
        }
    }

    if (fprintf(log_file, "%s,%u\n", timestamp, distance) < 0) {
