#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI1145_ADDR    0x60
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_US      500000  /* 500 ms */

/* Si1145 register addresses */
#define REG_PART_ID    0x00
#define REG_HW_KEY     0x07
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_IRQ_STATUS 0x0A
#define REG_COMMAND    0x18
#define REG_ALS_VIS    0x22
#define REG_ALS_IR     0x24
#define REG_PS1        0x2A

#define HW_KEY_VAL     0x17
#define CMD_RESET      0x01
#define CMD_PS_FORCE   0x05
#define CMD_ALS_FORCE  0x06
#define CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a Si1145 register; returns 0 on success, -1 on error. */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): pigpio error %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read a single byte from a Si1145 register; returns 0 on success, -1 on error. */
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): pigpio error %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int si1145_read_reg16(int handle, uint8_t reg, uint16_t *value)
{
    uint8_t lo, hi;
    if (si1145_read_reg(handle, reg, &lo) < 0) return -1;
    if (si1145_read_reg(handle, reg + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Initialize the Si1145 sensor; returns 0 on success, -1 on error. */
static int si1145_init(int handle)
{
    uint8_t part_id;

    /* Verify sensor presence by reading PART_ID */
    if (si1145_read_reg(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    printf("Si1145 detected (PART_ID = 0x%02X)\n", part_id);

    /* Write HW_KEY to enable the device */
    if (si1145_write_reg(handle, REG_HW_KEY, HW_KEY_VAL) < 0)
        return -1;

    /* Software reset */
    if (si1145_write_reg(handle, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* Set measurement rates: ALS_VIS = 0x0A (1 sample/second), ALS_IR = 0x0A, PS1 = 0x0A */
    if (si1145_write_reg(handle, REG_MEAS_RATE0, 0x0A) < 0) return -1;
    if (si1145_write_reg(handle, REG_MEAS_RATE1, 0x0A) < 0) return -1;

    /* Clear any stale IRQ by writing to IRQ_STATUS register */
    if (si1145_write_reg(handle, REG_IRQ_STATUS, 0x01) < 0) return -1;

    /* Start autonomous measurements */
    if (si1145_write_reg(handle, REG_COMMAND, CMD_PSALS_FORCE) < 0)
        return -1;

    gpioDelay(10000);  /* 10 ms for first conversion */
    return 0;
}

/* Log a reading with an ISO-8601 timestamp. */
static void log_reading(FILE *fp, uint16_t prox, uint16_t vis, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(fp, "%s, Proximity: %u, Ambient Light (VIS): %u, Ambient Light (IR): %u\n",
            ts, prox, vis, ir);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): pigpio error %d\n",
                I2C_BUS, SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging to %s every 500 ms. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t prox, vis, ir;

        if (si1145_read_reg16(g_i2c_handle, REG_PS1, &prox) < 0 ||
            si1145_read_reg16(g_i2c_handle, REG_ALS_VIS, &vis)  < 0 ||
            si1145_read_reg16(g_i2c_handle, REG_ALS_IR,   &ir)   < 0) {
            fprintf(stderr, "Read error — continuing\n");
        } else {
            log_reading(g_log_file, prox, vis, ir);
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_log_file)  fclose(g_log_file);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

