#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEASRATE0 0x08
#define SI1145_REG_MEASRATE1 0x09
#define SI1145_REG_CHLIST   0x4F
#define SI1145_REG_COMMAND  0x30
#define SI1145_REG_PS1     0x18
#define SI1145_REG_ALS_VIS 0x22

#define SI1145_PART_ID     0x45
#define SI1145_HW_KEY_VAL  0x17
#define SI1145_CHLIST_PS1  0x01
#define SI1145_CHLIST_ALS_VIS 0x02
#define SI1145_CMD_PS_FORCE 0x07
#define SI1145_CMD_ALS_FORCE 0x06

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u): %s\n",
                reg, len, rc < 0 ? pigpio_error(rc) : "short read");
        return -1;
    }
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;

    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). Wrong sensor or not present.\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_CHLIST, SI1145_CHLIST_PS1 | SI1145_CHLIST_ALS_VIS) < 0) return -1;

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    uint8_t buf[2];
    if (read_block(SI1145_REG_PS1, buf, 2) < 0) return -1;
    *prox = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_ambient_light(uint16_t *als) {
    uint8_t buf[2];
    if (read_block(SI1145_REG_ALS_VIS, buf, 2) < 0) return -1;
    *als = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, prox, als);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0, als = 0;
        int ok = 1;

        if (read_proximity(&prox) < 0) ok = 0;
        if (ok && read_ambient_light(&als) < 0) ok = 0;

        if (ok) {
            log_data(prox, als);
        } else {
            fprintf(stderr, "Sensor read error - skipping log entry.\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

