        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). Wrong sensor or not present.\n",
                part_id, SI1145_PART_ID);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEASRATE1, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_CHLIST, SI1145_CHLIST_PS1 | SI1145_CHLIST_ALS_VIS) < 0) return -1;

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    uint8_t buf[2];
    if (read_block(SI1145_REG_PS1, buf, 2) < 0) return -1;
    *prox = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_ambient_light(uint16_t *als) {
    uint8_t buf[2];
    if (read_block(SI1145_REG_ALS_VIS, buf, 2) < 0) return -1;
    *als = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static void log_data(uint16_t prox, uint16_t als) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, prox, als);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_data.log", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox = 0, als = 0;
        int ok = 1;

        if (read_proximity(&prox) < 0) ok = 0;
        if (ok && read_ambient_light(&als) < 0) ok = 0;

        if (ok) {
            log_data(prox, als);
        } else {
            fprintf(stderr, "Sensor read error - skipping log entry.\n");
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

