#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define WATERING_THRESHOLD 15.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL 60
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 100
#define ECHO_TIMEOUT_US 100000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void log_distance(float distance) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance = %.2f cm\n", ts, distance);
    fflush(log_file);
}

static void log_error(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: ERROR: %s\n", ts, msg);
    fflush(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line(trigger)");
        return -1;
    }
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line(echo)");
        return -1;
    }
    if (gpiod_line_request_output(trigger_line, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (trigger_line) {
        gpiod_line_set_value(trigger_line, 0);
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

static int trigger_sensor(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("gpiod_line_set_value(trigger high)");
        return -1;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("gpiod_line_set_value(trigger low)");
        return -1;
    }
    return 0;
}

static int wait_for_edge(struct gpiod_line *line, int target, long *timeout_us) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    *timeout_us = ECHO_TIMEOUT_US;
    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (val == target) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000L + (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed >= *timeout_us) {
            return -2; /* timeout */
        }
    }
    return -1;
}

static float measure_distance(void) {
    if (trigger_sensor() < 0) return -1.0f;
    long t0, t1;
    int rc;
    long timeout_us = ECHO_TIMEOUT_US;

    rc = wait_for_edge(echo_line, 1, &timeout_us);
    if (rc < 0) {
        log_error("Echo timeout: sensor absent or wiring fault");
        return -1.0f;
    }
    if (rc == -2) {
        log_error("Echo timeout: echo stuck high");
        return -1.0f;
    }
    t0 = clock_gettime(CLOCK_MONOTONIC, &start);

    rc = wait_for_edge(echo_line, 0, &timeout_us);
    if (rc < 0) {
        log_error("Echo timeout: sensor absent or wiring fault");
        return -1.0f;
    }
    if (rc == -2) {
        log_error("Echo timeout: echo stuck low");
        return -1.0f;
    }
    t1 = clock_gettime(CLOCK_MONOTONIC, &start);

    long pulse_us = (t1.tv_sec - t0.tv_sec) * 1000000L + (t1.tv_nsec - t0.tv_nsec) / 1000L;
    float distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0f;
    return distance;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    if (init_gpio() < 0) {
        log_error("GPIO initialization failed");
        cleanup();
        return 1;
    }

    log_message("Plant watering system started.");

    while (program_running) {
        float distance = measure_distance();
        if (distance < 0) {
            log_error("Distance measurement failed");
        } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            log_error("Distance out of range");
        } else {
            log_distance(distance);
            if (distance < WATERING_THRESHOLD) {
                log_message("Time to water the plant!");
            }
        }
        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

