#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_ADDR 0x39
#define I2C_BUS 1

#define REG_ID 0x92
#define REG_ENABLE 0x80
#define REG_ATIME 0x81
#define REG_WTIME 0x83
#define REG_PPULSE 0x8E
#define REG_CONTROL 0xF1
#define REG_CONFIG2 0x90
#define REG_CDATAL 0x96
#define REG_CDATAH 0x97
#define REG_RDATAL 0x98
#define REG_RDATAH 0x99
#define REG_GDATAL 0x9A
#define REG_GDATAH 0x9B
#define REG_PDATA 0x9C

#define EXPECTED_ID 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int apds9960_init(void) {
    uint8_t id = 0;
    if (i2c_read_byte(REG_ID, &id) < 0) {
        fprintf(stderr, "Failed to read APDS9960 ID register\n");
        return -1;
    }
    if (id != EXPECTED_ID) {
        fprintf(stderr, "APDS9960 ID mismatch: got 0x%02X, expected 0x%02X\n", id, EXPECTED_ID);
        return -1;
    }

    if (i2c_write_byte(REG_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(REG_ATIME, 0xDB) < 0) return -1;
    if (i2c_write_byte(REG_WTIME, 0xF6) < 0) return -1;
    if (i2c_write_byte(REG_PPULSE, 0x87) < 0) return -1;
    if (i2c_write_byte(REG_CONTROL, 0x03) < 0) return -1;
    if (i2c_write_byte(REG_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

static int read_color_proximity(uint16_t *r, uint16_t *g, uint16_t *b, uint8_t *prox) {
    if (i2c_read_word(REG_CDATAL, r) < 0) return -1;
    if (i2c_read_word(REG_CDATAH, r) < 0) return -1;
    if (i2c_read_word(REG_RDATAL, g) < 0) return -1;
    if (i2c_read_word(REG_RDATAH, g) < 0) return -1;
    if (i2c_read_word(REG_GDATAL, b) < 0) return -1;
    if (i2c_read_word(REG_GDATAH, b) < 0) return -1;
    if (i2c_read_byte(REG_PDATA, prox) < 0) return -1;
    return 0;
}

static void log_data(uint16_t r, uint16_t g, uint16_t b, uint8_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, prox);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, APDS9960_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    fprintf(log_file, "# APDS9960 color proximity log started\n");
    fprintf(log_file, "# timestamp,r,g,b,proximity\n");
    fflush(log_file);

    uint16_t r, g, b;
    uint8_t prox;

    while (!terminate) {
        if (read_color_proximity(&r, &g, &b, &prox) == 0) {
            if (prox > PROXIMITY_THRESHOLD) {
                log_data(r, g, b, prox);
            }
        } else {
            fprintf(stderr, "I2C read error, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, APDS9960_ADDR, 0);
