#define REG_PS_DATA1 0x25

#define CMD_RESET 0x01
#define CMD_PS_FORCE 0x0F

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write reg 0x%02X val 0x%02X failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, REG_MEAS_RATE0, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    return i2c_read_reg16(fd, REG_PS_DATA0, prox);
}

static int calculate_bpm(uint16_t prox) {
    /* Placeholder: 1 Hz sample rate -> 1000 samples/s -> 1 sample = 1 BPM */
    return (int)(prox / 1000);
}

static void log_data(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, bpm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", SI1182_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    fp = fopen("heartrate.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open heartrate.csv: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fprintf(fp, "# timestamp,bpm\n");
    fflush(fp);

    printf("Logging heart rate to heartrate.csv (Ctrl+C to stop)\n");

    while (running) {
        uint16_t prox;
        if (read_proximity(i2c_fd, &prox) < 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
        } else {
            int bpm = calculate_bpm(prox);
            log_data(fp, bpm);
            printf("Proximity=0x%04X  BPM=%d\n", prox, bpm);
        }
        usleep(100000);
    }

    printf("\nShutting down cleanly...\n");
    if (fp) fclose(fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

