#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_TRIGGER 17
#define LOG_FILE "distance_log.txt"
#define MEAS_TIMEOUT_MS 100

/* VL53L0X register addresses */
#define REG_SYSRANGE_START 0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): pigpio error %d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, len %u): pigpio error %d\n", reg, len, rc);
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C read short: got %d of %u bytes at reg 0x%02X\n", rc, len, reg);
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    /* Verify sensor presence by reading the model ID register (0x010F) */
    uint8_t model_id = 0;
    if (i2c_read_block(handle, 0x010F, &model_id, 1) < 0) {
        fprintf(stderr, "Cannot read model ID - sensor not present at 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0xEACC) - wrong sensor?\n", model_id);
        return -1;
    }

    /* Start a single ranging measurement */
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    int elapsed = 0;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until it sets (data ready) */
    while (elapsed < MEAS_TIMEOUT_MS) {
        if (i2c_read_block(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
        elapsed += 1;
    }

    if (elapsed >= MEAS_TIMEOUT_MS) {
        fprintf(stderr, "Timeout waiting for measurement (sensor absent or bus error)\n");
        return -1;
    }

    /* Read 14-byte result block: [status, range_status, ...] */
    uint8_t buf[14];
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* Distance is bytes 10-11 (big-endian 16-bit) */
    *distance_mm = ((uint16_t)buf[10] << 8) | buf[11];
    return 0;
}

static void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%u\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_TRIGGER);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_TRIGGER);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: pigpio error %d\n", I2C_BUS, VL53L0X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fprintf(log_file, "# timestamp,distance_mm\n");
    fflush(log_file);

    printf("VL53L0X distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        if (gpioTrigger(GPIO_TRIGGER, 1000, 1) < 0) {
            fprintf(stderr, "gpioTrigger failed\n");
