#define I2C_BUS        1
#define CH101_ADDR     0x45
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_US      200000   /* 200 ms between samples */
#define TRIGGER_US     50000    /* 50 ms trigger wait */
#define TRIGGER_VAL    0x01     /* CH101 trigger bit */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value (big-endian) to the CH101 register              */
/* ------------------------------------------------------------------ */
static int ch101_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value (big-endian) from the CH101 register            */
/* ------------------------------------------------------------------ */
static int ch101_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and read the 16-bit distance                 */
/* ------------------------------------------------------------------ */
static int ch101_read_distance(int handle, uint16_t *distance_mm)
{
    if (ch101_write_reg(handle, 0x00, 0x0001) != 0)
        return -1;

    gpioDelay(TRIGGER_US);

    uint16_t raw;
    if (ch101_read_reg(handle, 0x00, &raw) != 0)
        return -1;

    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Format current local time as YYYY-MM-DD HH:MM:SS                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file               */
/* ------------------------------------------------------------------ */
static int log_reading(FILE *file, const char *timestamp, uint16_t distance_mm)
{
    if (fprintf(file, "%s, %u\n", timestamp, distance_mm) < 0) {
        perror("fprintf to log file");
        return -1;
    }
    if (fflush(file) != 0) {
        perror("fflush log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, CH101_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(g_log_file);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CH101 distance logger started.  Bus %d, addr 0x%02X, log %s\n",
           I2C_BUS, CH101_ADDR, LOG_FILE);
    printf("Press Ctrl-C to stop.\n");

    /* ---- main sampling loop ---- */
    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read error — continuing\n");
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));

            if (log_reading(g_log_file, ts, distance_mm) != 0) {
                fprintf(stderr, "Logging failed — continuing\n");
            } else {
                printf("%s  Distance: %u mm\n", ts, distance_mm);
            }
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

