static int read_distance(float *distance) {
    char buf[4];
    int result;

    /* Trigger a measurement by writing 0x01 to register 0x00 */
    result = i2cWriteByteData(i2c_handle, 0x00, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing trigger command: %d\n", result);
        return -1;
