#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %s (attempt %d/%d)\n",
                reg, strerror(errno), retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static int write_register(int handle, uint8_t reg, uint16_t value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cWriteWordData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X): %s (attempt %d/%d)\n",
                reg, strerror(errno), retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, 0x07, 0x01) != 0) {
        fprintf(stderr, "Failed to write reset command to Si1182\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 sensor logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t proximity = 0, ambient = 0;

        if (read_register(i2c_handle, PROXIMITY_REG, &proximity) != 0) {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        if (read_register(i2c_handle, AMBIENT_REG, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
        }

        if (log_data(log_file, proximity, ambient) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

