#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define DISTANCE_THRESHOLD_MM 1000
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_COUNT 10
#define CYCLE_DELAY_MS 100
#define MEASUREMENT_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_response(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {SENSOR_ADDR, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_cmd(fd, cmd, sizeof(cmd)) < 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_response(fd, resp, sizeof(resp)) < 0) {
        return -1;
    }

    if (resp[0] != SENSOR_ADDR) {
        fprintf(stderr, "Sensor response header mismatch: 0x%02X (expected 0x%02X)\n",
                resp[0], SENSOR_ADDR);
        return -1;
    }

    *distance_mm = (resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Intrusion detected! Average distance: %d mm\n", ts, distance_mm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int sum = 0;
        int valid_samples = 0;

        for (int i = 0; i < SAMPLE_COUNT && running; i++) {
            int dist;
            if (read_distance(i2c_fd, &dist) == 0) {
                sum += dist;
                valid_samples++;
            } else {
                fprintf(stderr, "Sensor read failed at sample %d\n", i);
            }
            usleep(CYCLE_DELAY_MS * 1000);
        }

        if (valid_samples > 0) {
            int avg = sum / valid_samples;
            if (avg < DISTANCE_THRESHOLD_MM) {
                log_intrusion(log_fp, avg);
            }
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_fp) {
        fclose(log_fp);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

