#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L0X_ADDR   0x29
#define MODEL_ID_REG   0xC0
#define EXPECTED_MODEL 0xEE
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write reg 0x%02X val 0x%02X failed: %s\n", reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg8(handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Cannot read model ID - sensor may be absent\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL);
        return -1;
    }
    printf("VL53L0X detected (model ID 0x%02X)\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    uint8_t status = 0;
    int timeout = 100;

    if (i2c_write_reg8(handle, SYSRANGE_START, 0x01) < 0) {
        return -1;
    }

    while (timeout-- > 0) {
        if (i2c_read_reg8(handle, RESULT_INTERRUPT_STATUS, &status) < 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000);
        timeout = 100;
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for ranging completion\n");
        return -1;
    }

    uint8_t range_low = 0, range_high = 0;
    if (i2c_read_reg8(handle, RESULT_RANGE_STATUS, &range_low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(handle, RESULT_RANGE_STATUS + 1, &range_high) < 0) {
        return -1;
    }

    *distance_mm = (uint16_t)((range_high << 8) | range_low);
    if (i2c_write_reg8(handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting periodic distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Warning: distance read failed, retrying next cycle\n");
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%s Distance: %u mm\n", ts, distance);
            fflush(stdout);
        }
        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

