        fprintf(stderr, "Failed to configure Si1182\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 proximity sensor initialized. Reading every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

