            fprintf(stderr, "I2C read error during IRQ poll\n");
            break;
        }

        if (irq & 0x01) {
            uint16_t prox = 0;
            if (read_proximity(g_i2c_handle, &prox) == 0) {
                printf("Proximity: %u\n", prox);
