                fprintf(stderr, "Failed to read proximity data\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

