#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x4C
#define DIST_REG       0x00
#define MM_PER_COUNT   0.125f
#define POLL_MS        500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = MLX75030_ADDR;
    msgs[0].flags = 0;            /* write */
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = MLX75030_ADDR;
    msgs[1].flags = I2C_M_RD;     /* read */
    msgs[1].len   = 2;
    msgs[1].buf   = buf;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C_RDWR read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, MLX75030_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    /* Verify sensor presence by reading the distance register */
    uint16_t dummy;
    if (i2c_read_reg16(fd, DIST_REG, &dummy) != 0) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, DIST_REG, &raw) != 0) {
            /* transient I2C error: retry next cycle */
            struct timespec ts = {0, POLL_MS * 1000000L};
            nanosleep(&ts, NULL);
            continue;
        }

        float distance_mm = (float)raw * MM_PER_COUNT;
        printf("Distance: %.2f mm\n", distance_mm);
        fflush(stdout);

        struct timespec ts = {0, POLL_MS * 1000000L};
        nanosleep(&ts, NULL);
    }

    close(fd);
    return EXIT_SUCCESS;
}

