#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  200000   /* 200 ms timeout for echo edges */
#define TRIGGER_PULSE_US 10
#define MAX_DISTANCE_CM  38.0f  /* HC-SR04 max range ~38 cm */
#define SAMPLE_INTERVAL_US 1000000 /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on invalid pulse.
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -1; /* timeout waiting for echo start */
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            return -2; /* timeout waiting for echo end */
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

static float calculate_distance(long pulse_us)
{
    return (float)pulse_us * 0.0343f / 2.0f;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d | Sample interval: %d us\n",
           TRIGGER_PIN, ECHO_PIN, SAMPLE_INTERVAL_US);
    printf("  Press Ctrl+C to exit.\n\n");

    while (g_running) {
        /* Send 10 us trigger pulse */
        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set trigger high.\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set trigger low.\n");
            break;
        }

        long pulse_us = measure_echo_pulse();

        if (pulse_us < 0) {
            if (pulse_us == -1) {
                fprintf(stderr, "Warning: echo start timeout (no object detected).\n");
            } else {
                fprintf(stderr, "Warning: echo end timeout (sensor not responding).\n");
            }
        } else if (pulse_us > MAX_DISTANCE_CM * 1000000L) {
            fprintf(stderr, "Warning: pulse duration %.1f us exceeds max (%.1f us).\n",
                    pulse_us, MAX_DISTANCE_CM * 1000000L);
        } else {
            float distance = calculate_distance(pulse_us);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[32];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            if (timeinfo == NULL) {
                fprintf(stderr, "Warning: localtime() failed.\n");
            } else {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("[%s] Distance: %.2f cm\n", timestamp, distance);
                fflush(stdout);
            }
        }

        /* Sleep for the remainder of the 1-second interval */
        uint32_t elapsed = 0;
        while (g_running && elapsed < SAMPLE_INTERVAL_US) {
            gpioDelay(1000);
            elapsed += 1000;
        }
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

