#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_FRAME_SIZE 128
#define MAGIC_WORD_SIZE 8
#define ALERT_DURATION_MS 2000
#define POLL_DELAY_US 10000

#define MAGIC_WORD_0 0x02
#define MAGIC_WORD_1 0x01
#define MAGIC_WORD_2 0x04
#define MAGIC_WORD_3 0x03
#define MAGIC_WORD_4 0x06
#define MAGIC_WORD_5 0x05
#define MAGIC_WORD_6 0x08
#define MAGIC_WORD_7 0x07

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error reading UART: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly\n");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int detect_intrusion(const uint8_t *data, int data_len) {
    if (data_len < DATA_FRAME_SIZE) return 0;

    uint8_t magic[MAGIC_WORD_SIZE];
    memcpy(magic, data, MAGIC_WORD_SIZE);

    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        if (data[i * 2 + 1] != MAGIC_WORD_1) return 0;
        if (data[i * 2] != MAGIC_WORD_0) return 0;
        if (data[i * 2 + 2] != MAGIC_WORD_2) return 0;
        if (data[i * 2 + 3] != MAGIC_WORD_3) return 0;
        if (data[i * 2 + 4] != MAGIC_WORD_4) return 0;
        if (data[i * 2 + 5] != MAGIC_WORD_5) return 0;
        if (data[i * 2 + 6] != MAGIC_WORD_6) return 0;
        if (data[i * 2 + 7] != MAGIC_WORD_7) return 0;

        int16_t range = (int16_t)((data[i * 2 + 8] << 8) | data[i * 2 + 9]);
        if (range > 0 && range < (int)RANGE_THRESHOLD) {
            return 1;
        }
    }
    return 0;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t data[DATA_FRAME_SIZE];
    int data_len = 0;

    while (running) {
        if (read_exact(uart_fd, data, DATA_FRAME_SIZE) == 0) {
            data_len = DATA_FRAME_SIZE;

            if (detect_intrusion(data, data_len)) {
                gpioWrite(GPIO_LED, 1);
                gpioDelay(ALERT_DURATION_MS * 1000);
                gpioWrite(GPIO_LED, 0);
                log_intrusion(RANGE_THRESHOLD);
            }
        } else {
            gpioDelay(POLL_DELAY_US);
            continue;
        }
    }

    cleanup();
    return 0;
}

