        fprintf(stderr, "Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    int prev_state = -1;
    int first_read = 1;

    while (program_running) {
        int val = gpiod_line_get_value(sensor_line);
        if (val < 0) {
            fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
            log_event("Error reading sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (first_read) {
            prev_state = val;
            first_read = 0;
        } else {
            if (val != prev_state) {
                if (val == 0) {
                    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                        fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
                    } else {
                        log_event("Obstacle detected");
                    }
                    prev_state = 0;
                } else {
                    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                        fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
                    } else {
                        log_event("Obstacle cleared");
                    }
                    prev_state = 1;
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

