#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DIST_HIGH_REG  0x31
#define DIST_LOW_REG   0x32
#define DIST_THRESHOLD 10.0f
#define ALERT_GPIO     17
#define SAMPLE_US      100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    int hi = i2cReadByteData(g_i2c_handle, DIST_HIGH_REG);
    if (hi < 0) {
        fprintf(stderr, "I2C read error high byte: %d\n", hi);
        return -1;
    }
    int lo = i2cReadByteData(g_i2c_handle, DIST_LOW_REG);
    if (lo < 0) {
        fprintf(stderr, "I2C read error low byte: %d\n", lo);
        return -1;
    }
    *distance_cm = (uint16_t)((hi << 8) | (lo & 0xFF));
    return 0;
}

static int log_distance(uint16_t distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%s, Distance: %u cm\n", ts, distance_cm);
    if (fclose(fp) != 0) {
        perror("fclose log file");
        return -1;
    }
    return 0;
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) < 0) {
        fprintf(stderr, "gpioWrite alert ON failed\n");
        return;
    }
    gpioDelay(500000);
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite alert OFF failed\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode alert GPIO %d failed\n", ALERT_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ICU-20201 distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            if (distance < DIST_THRESHOLD) {
                trigger_alert();
            }
        } else {
            fprintf(stderr, "Distance read failed; skipping cycle.\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
    return 0;
}

