#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS 1

#define REG_MODEL_ID 0x010F
#define REG_SYSRANGE_START 0x007
#define REG_SYSRANGE_STOP 0x008
#define REG_RESULT_INTERRUPT_STATUS 0x013
#define REG_RESULT_RANGE_STATUS 0x078
#define REG_SYSTEM_INTERRUPT_CLEAR 0x014
#define REG_SYSTEM_MODE_START 0x0000
#define REG_SYSTEM_MODE_STOP 0x0001
#define REG_SYSTEM_RESET 0x0000
#define REG_SYSTEM_INTERRUPT_CLEAR_BIT 0x01

#define EXPECTED_MODEL_ID 0xEA
#define RESET_DELAY_US 2000
#define START_DELAY_US 2000
#define POLL_TIMEOUT_US 100000
#define LOOP_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_byte(uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) return -1;
    return 0;
}

static int i2c_read_word(uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, 2) != 2) return -1;
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl53l1x_init(void) {
    uint8_t model_id = 0;
    if (i2c_read_byte(REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X).\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    if (i2c_write_byte(REG_SYSTEM_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);

    if (i2c_write_byte(REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }
    gpioDelay(START_DELAY_US);

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 0;

    while (timeout < POLL_TIMEOUT_US) {
        if (i2c_read_byte(REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status.\n");
            return -1;
        }
        if (status & 0x01) break;
        gpioDelay(1000);
        timeout += 1000;
    }

    if (timeout >= POLL_TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for data-ready.\n");
        return -1;
    }

    uint16_t range = 0;
    if (i2c_read_word(REG_RESULT_RANGE_STATUS, &range) < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }

    if (i2c_write_byte(REG_SYSTEM_INTERRUPT_CLEAR, REG_SYSTEM_INTERRUPT_CLEAR_BIT) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupt.\n");
        return -1;
    }

    *distance = range;
    return 0;
}

static void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("distance_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Failed to open log file.\n");
            return;
        }
        if (ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,distance_mm\n");
        }
    }

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file);
}

static void parking_assistance(uint16_t distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init() < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(&distance) == 0) {
            log_data(distance);
            parking_assistance(distance);
        } else {
            fprintf(stderr, "Warning: Read failed, retrying...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

