#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */
#define MIN_DISTANCE   50.0f    /* mm */
#define MAX_DISTANCE   500.0f   /* mm */
#define MIN_FREQ       10.0f    /* Hz */
#define MAX_FREQ       1.0f     /* Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit big-endian register from the CH201.
 * Returns 0 on success, -1 on failure.
 */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cReadI2CBlockData(handle, reg, buf, 2);
        if (rc == 2) {
            *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Trigger a measurement and read the 16-bit distance register.
 * Returns 0 on success, -1 on failure.
 */
static int read_distance(int handle, float *distance_mm)
{
    uint16_t raw;

    if (read_reg16(handle, 0x00, &raw) != 0) {
        fprintf(stderr, "Failed to read distance register\n");
        return -1;
    }

    *distance_mm = (float)raw;
    return 0;
}

static float map_distance_to_freq(float distance_mm)
{
    if (distance_mm < MIN_DISTANCE) distance_mm = MIN_DISTANCE;
    if (distance_mm > MAX_DISTANCE) distance_mm = MAX_DISTANCE;
    return MIN_FREQ + (distance_mm - MIN_DISTANCE) *
           (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);
}

static void set_led_frequency(int gpio, float freq_hz)
{
    if (freq_hz <= 0.0f)
        gpioWrite(gpio, 0);
    else
        gpioSetPWMfrequency(gpio, (int)freq_hz);
}

static void log_data(float distance_mm, float freq_hz)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("%s  Distance: %.2f mm  Blink: %.2f Hz\n",
           ts, distance_mm, freq_hz);
    fflush(stdout);
}

int main(void)
{
    float distance_mm;
    float freq_hz;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    while (g_running) {
        rc = read_distance(g_i2c_handle, &distance_mm);
        if (rc == 0) {
            freq_hz = map_distance_to_freq(distance_mm);
            set_led_frequency(LED_GPIO, freq_hz);
            log_data(distance_mm, freq_hz);
        } else {
            fprintf(stderr, "Distance read failed; continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

