#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LOG_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_US 100000
#define MEASUREMENT_DELAY_US 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int trigger_measurement(void) {
    char cmd = 0x01;
    int rc = i2cWriteDevice(i2c_handle, &cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "Error: I2C write failed (rc=%d).\n", rc);
        return -1;
    }
    return 0;
}

static int read_distance(uint16_t *distance_cm) {
    char buf[2];
    int rc = i2cReadDevice(i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: I2C read failed (rc=%d).\n", rc);
        return -1;
    }

    *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int log_distance(uint16_t distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%u\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed.\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    printf("MLX75030 distance logger started. Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        uint16_t distance = 0;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (trigger_measurement() != 0) {
                gpioDelay(RETRY_DELAY_US);
                continue;
            }

            gpioDelay(MEASUREMENT_DELAY_US);

            if (read_distance(&distance) == 0) {
                success = 1;
                break;
            }

            gpioDelay(RETRY_DELAY_US);
        }

        if (success) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Warning: Failed to log distance.\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read distance after %d attempts.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

