#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 10000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
            return;
        }
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    int last_state_1 = read_sensor(SENSOR_1_GPIO);
    int last_state_2 = read_sensor(SENSOR_2_GPIO);

    if (last_state_1 < 0 || last_state_2 < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Proximity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state_1 = read_sensor(SENSOR_1_GPIO);
        int current_state_2 = read_sensor(SENSOR_2_GPIO);

        if (current_state_1 < 0 || current_state_2 < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (current_state_1 != last_state_1) {
            if (current_state_1 == 0) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
            last_state_1 = current_state_1;
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        if (current_state_2 != last_state_2) {
            if (current_state_2 == 0) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
            last_state_2 = current_state_2;
            gpioDelay(DEBOUNCE_MS * 1000);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

