#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VL53L5CX_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define NUM_ZONES 64

/* VL53L5CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_MODE 0x0001
#define REG_SYSTEM_START 0x0002
#define REG_RESULT_RANGE_STATUS 0x0014
#define REG_RESULT_DISTANCE 0x001E
#define REG_RESULT_ZONE_CONFIG 0x0020
#define REG_RESULT_ZONE_DATA 0x0022

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l5cx_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x00) < 0) return -1;
    usleep(10000); /* 10 ms settle */
    if (i2c_write_reg16(fd, REG_SOFT_RESET, 0x01) < 0) return -1;
    usleep(10000);

    /* Set 8x8 zone grid (64 zones) */
    if (i2c_write_reg16(fd, REG_RESULT_ZONE_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg16(fd, REG_RESULT_ZONE_DATA, 0x00) < 0) return -1;

    /* Start ranging */
    if (i2c_write_reg16(fd, REG_SYSTEM_START, 0x01) < 0) return -1;
    usleep(10000);

    return 0;
}

static int vl53l5cx_read_distance(int fd, uint8_t *distances, size_t num) {
    uint8_t status;
    uint8_t data[8];

    /* Check if data is ready */
    if (i2c_read_reg16(fd, REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if (!(status & 0x01)) {
        return 1; /* No new data yet */
    }

    /* Read 8 bytes of distance data (2 bytes per zone) */
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, data, 8) < 0) return -1;

    for (size_t i = 0; i < num; i++) {
        distances[i] = data[i * 2];
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t distances[NUM_ZONES];
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        goto cleanup;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        goto cleanup;
    }

    printf("VL53L5CX initialized. Reading %d zones every 500 ms...\n", NUM_ZONES);

    while (running) {
        if (vl53l5cx_read_distance(fd, distances, NUM_ZONES) < 0) {
            fprintf(stderr, "Error reading distance data.\n");
            break;
        }

        for (size_t i = 0; i < NUM_ZONES; i++) {
            printf("Zone %zu: %u\n", i, distances[i]);
        }
        fflush(stdout);

        usleep(500000); /* 500 ms */
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

