        distances[i] = data[i * 2];
    }
    return 0;
}

int main(void) {
    int fd = -1;
    uint8_t distances[NUM_ZONES];
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VL53L5CX_ADDR, strerror(errno));
        goto cleanup;
    }

    if (vl53l5cx_init(fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        goto cleanup;
    }

    printf("VL53L5CX initialized. Reading %d zones every 500 ms...\n", NUM_ZONES);

    while (running) {
        if (vl53l5cx_read_distance(fd, distances, NUM_ZONES) < 0) {
            fprintf(stderr, "Error reading distance data.\n");
            break;
        }

        for (size_t i = 0; i < NUM_ZONES; i++) {
            printf("Zone %zu: %u\n", i, distances[i]);
        }
        fflush(stdout);

        usleep(500000); /* 500 ms */
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return ret;
}

