        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %s\n",
                MLX75030_ADDR, I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
