#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L4CX_ADDR  0x29

/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET          0x7FFF
#define REG_SYSTEM_START        0x0009
#define REG_INT_STATUS          0x0046
#define REG_RESULT_RANGE_STATUS 0x0086
#define REG_RESULT_DISTANCE     0x0096

#define POLL_INTERVAL_US       500000   /* 500 ms */
#define RESET_DELAY_US         10000    /* 10 ms  */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address.                         */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address.                         */
/* Returns 0 on success and stores value in *out, -1 on error.          */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    char data;

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr 0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    *out = (uint8_t)data;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.    */
/* Returns 0 on success and stores value in *out, -1 on error.         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char hi, lo;

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr 0x%04X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, &hi, 1) != 1) {
        fprintf(stderr, "I2C read high byte from reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, &lo, 1) != 1) {
        fprintf(stderr, "I2C read low byte from reg 0x%04X failed\n", reg);
        return -1;
    }
    *out = (uint16_t)((lo << 8) | hi);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor.                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(RESET_DELAY_US);

    /* Start ranging: write 0x00 to register 0x0009 */
    if (i2c_write_reg8(handle, REG_SYSTEM_START, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres.                                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status;

    /* Poll interrupt status bit 0 (new data ready) */
    if (i2c_read_reg8(handle, REG_INT_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0)
        return 0;  /* no new data yet */

    /* Read 16-bit distance result */
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, distance_mm) != 0)
        return -1;

    /* Clear interrupt by writing 0x01 to the interrupt status register */
    if (i2c_write_reg8(handle, REG_INT_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Format a timestamp string.                                          */
/* ------------------------------------------------------------------ */
static void format_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L4CX default address 0x29 */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L4CX_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, VL53L4CX_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance sensor started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t distance;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            char ts[40];
            format_timestamp(ts, sizeof(ts));
            printf("%s, Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            /* Transient I2C error — skip this cycle and keep running */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

