/*
 * Raspberry Pi 4 Model B - VL53L1X Time-of-Flight Sensor with Buzzer Alert
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO 2 (I2C1 SDA)
 *   VL53L1X SCL -> GPIO 3 (I2C1 SCL)
 *   VL53L1X VDD -> 3.3V
 *   VL53L1X GND -> GND
 *   Buzzer +   -> GPIO 22 (with appropriate current-limiting resistor)
 *   Buzzer -   -> GND
 *
 * Build: gcc -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:   sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define BUZZER_GPIO    22
#define DISTANCE_THRESHOLD_MM 100
#define POLL_DELAY_US  500000  /* 500 ms */

/* VL53L1X register addresses */
#define REG_SOFT_RESET              0x0001
#define REG_SYSTEM_MODE_START       0x0007
#define REG_RESULT_FINAL_CROSSTALK  0x0096
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_SYSTEM_INTERRUPT_CONFIG 0x0089

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (big-endian) on the VL53L1X                */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian) on the VL53L1X                */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data_buf[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%04X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }

    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L1X sensor for continuous ranging                */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Soft reset write failed\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Set I2C slave address (required after reset) */
    if (vl53l1x_write_reg16(handle, 0x0001, 0x29) != 0) {
        fprintf(stderr, "[ERROR] Set I2C slave address failed\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg16(handle, REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Start continuous ranging failed\n");
        return -1;
    }

