    if (vl53l1x_write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Clear interrupt failed\n");
        return -1;
    }

    return 0;
}

