        gpioDelay(1000); /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "[WARN] VL53L1X data not ready after 10 ms\n");
        return -1;
    }

    /* Read the final distance result */
    if (vl53l1x_read_reg16(handle, REG_RESULT_FINAL_CROSSTALK, distance_mm) != 0) {
        return -1;
