#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      (-90.0)
#define MAX_ANGLE      (90.0)
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define TIMEOUT_US     50000
#define LOOP_DELAY_US  200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to write trigger pin low\n");
        return -1;
    }
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise servo to 0\n");
        return -1;
    }
    return 0;
}

static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Servo angle out of range: %d\n", angle);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE +
        (int)((float)angle / (MAX_ANGLE - MIN_ANGLE) *
              (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return -1;
    }
    return 0;
}

static void log_data(float distance) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "Timestamp error, Distance: %.2f cm\n", distance);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Sensor read error, skipping\n");
        } else {
            int angle = (int)((distance - MIN_DISTANCE) /
                              (MAX_DISTANCE - MIN_DISTANCE) *
                              (MAX_ANGLE - MIN_ANGLE) +
                              MIN_ANGLE);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            log_data(distance);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown: stop servo and release pigpio */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

