}

static void log_data(float distance) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    } else {
        fprintf(fp, "Timestamp error, Distance: %.2f cm\n", distance);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    while (running) {
        float distance = measure_distance();
        if (distance < 0.0) {
            fprintf(stderr, "Sensor read error, skipping\n");
        } else {
            int angle = (int)((distance - MIN_DISTANCE) /
                              (MAX_DISTANCE - MIN_DISTANCE) *
                              (MAX_ANGLE - MIN_ANGLE) +
                              MIN_ANGLE);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }
            log_data(distance);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown: stop servo and release pigpio */
    gpioServo(SERVO_PIN, 0);
