#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/msg.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_BUZZER 23
#define DISTANCE_THRESHOLD 100
#define MSG_QUEUE_NAME "/msg_queue"
#define MSG_QUEUE_KEY 1234
#define POLL_DELAY_US 50000

#define REG_SOFT_RESET 0x0000
#define REG_MODEL_ID 0x010F
#define REG_SYSTEM_START 0x0080
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int mq_fd = -1;
static int gpio_initialized = 0;

typedef struct {
    long msc;
    int distance;
} msg_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id;
    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset low.\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg8(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write soft reset high.\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg8(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg8(handle, REG_SYSTEM_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop ranging.\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2c_write_reg8(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(1000);

    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t status;
    if (i2c_read_reg8(handle, REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1;
    }

    uint16_t dist;
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, &dist) != 0) {
        return -1;
    }

    *distance = (int)dist;
    return 0;
}

static void msg_queue_init(int *fd) {
    *fd = msgget(MSG_QUEUE_KEY, 0666 | IPC_CREAT);
    if (*fd == -1) {
        perror("msgget");
        exit(EXIT_FAILURE);
    }
}

static void msg_queue_send(int fd, const msg_t *msg) {
    if (msgsnd(fd, msg, sizeof(msg_t), 0) == -1) {
        perror("msgsnd");
        exit(EXIT_FAILURE);
    }
}

static void msg_queue_receive(int fd, msg_t *msg) {
    if (msgrcv(fd, msg, sizeof(msg_t), 0, 0) == -1) {
        perror("msgrcv");
        exit(EXIT_FAILURE);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (mq_fd >= 0) {
        msgctl(mq_fd, IPC_RMID, NULL);
        mq_fd = -1;
    }
    if (gpio_initialized) {
        gpioTerminate();
        gpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }
    gpio_initialized = 1;

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X.\n", VL53L1X_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);
    gpioWrite(GPIO_BUZZER, 0);

    msg_queue_init(&mq_fd);

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            msg_t msg;
            msg.msc = time(NULL);
            msg.distance = distance;
            msg_queue_send(mq_fd, &msg);
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_BUZZER, 1);
                gpioDelay(500000);
                gpioWrite(GPIO_BUZZER, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C communication failure.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
