#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0   /* cm/s */
#define MIN_DISTANCE   2.0       /* cm */
#define MAX_DISTANCE   400.0     /* cm */
#define THRESHOLD_CM   30.0      /* cm */
#define POLL_DELAY_US  100000    /* 100 ms */
#define TRIGGER_PULSE_US 10

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_seen  = 0;
static volatile int      running    = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_seen = 1;
    }
}

static double calculate_distance(uint32_t pulse_us) {
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    double duration = (double)(end_tick - start_tick) / 1000000.0;
    if (duration <= 0.0) {
        return -1.0;
    }
    return (duration * SPEED_OF_SOUND) / 2.0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void control_buzzer(int distance_cm) {
    if (distance_cm < 0) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }
    if (distance_cm < THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void display_distance(int distance_cm) {
    if (distance_cm < 0) {
        printf("Sensor error: no echo received (timeout/no object)\n");
    } else if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        printf("Out of range: %.1f cm\n", distance_cm);
    } else {
        printf("Distance: %.1f cm\n", distance_cm);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_sensor();
        gpioDelay(POLL_DELAY_US);

        if (!echo_seen) {
            gpioWrite(BUZZER_PIN, 0);
            continue;
        }

        double distance = calculate_distance(0);
        display_distance((int)distance);
        control_buzzer((int)distance);

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

