#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define LOG_FILE    "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define MEASURE_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 60000
#define MIN_VALID_PULSE_US 100
#define MAX_VALID_PULSE_US 30000
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Echo edge timestamps in microseconds (32-bit pigpio tick) */
static volatile uint32_t echo_rising_tick = 0;
static volatile uint32_t echo_falling_tick = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on both rising and falling edges of  */
/* the ECHO pin.  We capture the falling edge as the echo pulse end.   */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        echo_rising_tick = tick;
    } else if (level == 0) {
        echo_falling_tick = tick;
        /* pigpio ticks are 32-bit; handle wraparound */
        uint32_t pulse_us = echo_falling_tick - echo_rising_tick;
        if (pulse_us > MAX_VALID_PULSE_US) {
            fprintf(stderr, "Warning: echo pulse %u us exceeds max (%d us) — possible timeout or no object\n",
                    pulse_us, MAX_VALID_PULSE_US);
            return;
        }
        if (pulse_us < MIN_VALID_PULSE_US) {
            fprintf(stderr, "Warning: echo pulse %u us below min (%d us) — noise or out of range\n",
                    pulse_us, MIN_VALID_PULSE_US);
            return;
        }
        double distance = (double)pulse_us * SOUND_SPEED_CM_PER_US / 2.0;
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *tstruct = localtime_r(&now, &tm_buf);
        char ts[32];
        if (tstruct) {
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tstruct);
        } else {
            snprintf(ts, sizeof(ts), "unknown-time");
        }
        printf("%s  Distance: %.2f cm  (pulse %u us)\n", ts, distance, pulse_us);
        fflush(stdout);

        if (log_file) {
            fprintf(log_file, "%s  Distance: %.2f cm  (pulse %u us)\n", ts, distance, pulse_us);
            fflush(log_file);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the trigger pin                         */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* let sensor settle */

    /* ---- Open log file ---- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler\n");
    }

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register echo callback on GPIO %d\n", ECHO_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.  TRIG=GPIO%d  ECHO=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE);
    fflush(stdout);

    /* ---- Main measurement loop ---- */
    while (running) {
        trigger_sensor();

        /* Wait for echo falling edge (timeout if no echo within 60 ms) */
        uint32_t start_wait = gpioTick();
        uint32_t timeout_start = start_wait;
        while (running) {
            uint32_t now = gpioTick();
            if (now >= timeout_start + ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout — no object detected within %d us\n",
                        ECHO_TIMEOUT_US);
                break;
            }
            if (echo_falling_tick != 0) {
                break; /* echo received */
            }
            gpioDelay(100); /* poll every 100 us */
        }

        if (!running) {
            break;
        }

        if (echo_falling_tick == 0) {
            fprintf(stderr, "Warning: no echo received — skipping cycle\n");
        } else {
            printf("Measurement complete.\n");
            fflush(stdout);
        }

        gpioDelay(MEASURE_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

