static void log_event(const char *event, int distance) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - %s - Distance: %d cm\n", timestamp, event, distance);
    fflush(log_file);
}

