#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET 0x000B
#define VL53L1X_SYSTEM_MODE_START 0x0080
#define VL53L1X_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_RESULT_DISTANCE 0x0096
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x0086

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *value) {
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0) {
        return -1;
    }
    char data[1];
    if (i2cReadI2CBlockData(handle, addr[0], data, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

static int vl53l1x_init(int handle) {
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset (2nd time)\n");
        return -1;
    }
    gpioDelay(10000);

    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance_mm) {
    uint8_t status = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_RANGE_STATUS, &status) < 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data yet */
    }

    uint8_t dist = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, &dist) < 0) {
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

static void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s - %s\n", timestamp, event);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioTerminate();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    int distance_mm;
    int gate_open = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);

    log_file = fopen("gate_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int ret = vl53l1x_read_distance(i2c_handle, &distance_mm);
        if (ret == 0) {
            if (distance_mm <= DISTANCE_THRESHOLD_MM && !gate_open) {
                gpioWrite(GATE_OPEN_PIN, 1);
                gpioWrite(GATE_CLOSE_PIN, 0);
                log_event("Gate opened");
                gate_open = 1;
            } else if (distance_mm > DISTANCE_THRESHOLD_MM && gate_open) {
                gpioWrite(GATE_OPEN_PIN, 0);
                gpioWrite(GATE_CLOSE_PIN, 1);
                log_event("Gate closed");
                gate_open = 0;
            }
        } else if (ret < 0) {
            log_event("Error: I2C read failure");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Gate control system stopped.\n");
    return 0;
}

