#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define POLL_TIMEOUT_MS 1000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %d\n", reg, rc);
    }
    return rc;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    int rc = i2cWriteDevice(handle, reg_buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %d\n", reg, rc);
        return -1;
    }
    rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(1000);
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status;
    int poll_count = 0;
    int timeout = POLL_TIMEOUT_MS;

    while (poll_count < POLL_TIMEOUT_MS) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(1000);
        poll_count++;
    }

    if (poll_count >= POLL_TIMEOUT_MS) {
        fprintf(stderr, "VL53L1X data-ready timeout\n");
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void motor_set(int forward, int backward) {
    if (gpioWrite(MOTOR_FORWARD_PIN, forward) < 0) {
        fprintf(stderr, "Failed to write forward pin\n");
    }
    if (gpioWrite(MOTOR_BACKWARD_PIN, backward) < 0) {
        fprintf(stderr, "Failed to write backward pin\n");
    }
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
}

static void distance_callback(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    static int last_motor_state = 0;
    uint16_t distance;

    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
