    if (gpioSetISRFuncEx(MOTOR_FORWARD_PIN, RISING_EDGE, 0, distance_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on forward pin\n");
        i2cClose(i2c_handle);
