static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static const int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &id) < 0) return -1;
    if (id != 0x00) {
        fprintf(stderr, "MPR121 not detected (ID=0x%02X, expected 0x00)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG4, 0x08) < 0) return -1;

    uint8_t autoconfig[6];
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG0, &autoconfig[0]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG1, &autoconfig[1]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG2, &autoconfig[2]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG3, &autoconfig[3]) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        uint8_t reg = 0x41 + (i * 2);
        if (i2c_write_reg8(fd, reg, 0x0B) < 0) return -1;
        if (i2c_write_reg8(fd, reg + 1, 0xC8) < 0) return -1;
    }

    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG0, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG11, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG12, 0x00) < 0) return -1;

