static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void set_led_pattern(int pattern) {
    int vals[4] = {0, 0, 0, 0};
    for (int i = 0; i < 4; i++) {
        vals[i] = (pattern >> (3 - i)) & 1;
    }
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], vals[i]);
        }
    }
}

static void log_event(uint16_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s: Touch status = 0x%04X\n", ts, status);
        fflush(log_fp);
    }
    printf("%s: Touch status = 0x%04X\n", ts, status);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        fclose(log_fp);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(led_lines[j]);
            }
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_fp);
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "touch_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(led_lines[j]);
            }
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_fp);
            return 1;
        }
    }

    uint16_t prev_status = 0;
    while (running) {
        uint16_t status;
        if (read_touch_status(i2c_fd, &status) < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            usleep(100000);
            continue;
        }

        if (status == 0) {
            printf("No electrodes touched\n");
        } else {
            log_event(status);
            uint16_t mask = status & 0x0FFF;
            int pattern = 0;
            for (int i = 0; i < 12; i++) {
                if (mask & (1 << i)) {
                    pattern |= (1 << (11 - i));
                }
            }
            set_led_pattern(pattern);
        }

        prev_status = status;
        usleep(50000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_fp);
    return 0;
}

