#define MPR121_MHDF11 0x7A
#define MPR121_MHDT11 0x7B
#define MPR121_SOFTRESET 0x80
#define MPR121_AUTOCONFIG0 0x5B
#define MPR121_AUTOCONFIG1 0x5C
#define MPR121_AUTOCONFIG2 0x5D
#define MPR121_AUTOCONFIG3 0x5E
#define MPR121_ELECTRODECONFIG 0x5F
#define MPR121_DEBOUNCE 0x5C
#define MPR121_CONFIG1 0x5D
#define MPR121_CONFIG2 0x5E
#define MPR121_CONFIG3 0x5F
#define MPR121_CONFIG4 0x60
#define MPR121_ELECTRODECONFIG2 0x61
#define MPR121_ELECTRODECONFIG3 0x62
#define MPR121_ELECTRODECONFIG4 0x63
#define MPR121_ELECTRODECONFIG5 0x64
#define MPR121_ELECTRODECONFIG6 0x65
#define MPR121_ELECTRODECONFIG7 0x66
#define MPR121_ELECTRODECONFIG8 0x67
#define MPR121_ELECTRODECONFIG9 0x68
#define MPR121_ELECTRODECONFIG10 0x69
#define MPR121_ELECTRODECONFIG11 0x6A
#define MPR121_ELECTRODECONFIG12 0x6B

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL};
static const int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, MPR121_SOFTRESET, &id) < 0) return -1;
    if (id != 0x00) {
        fprintf(stderr, "MPR121 not detected (ID=0x%02X, expected 0x00)\n", id);
        return -1;
    }

    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG4, 0x08) < 0) return -1;

    uint8_t autoconfig[6];
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG0, &autoconfig[0]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG1, &autoconfig[1]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG2, &autoconfig[2]) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_AUTOCONFIG3, &autoconfig[3]) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        uint8_t reg = 0x41 + (i * 2);
        if (i2c_write_reg8(fd, reg, 0x0B) < 0) return -1;
        if (i2c_write_reg8(fd, reg + 1, 0xC8) < 0) return -1;
    }

    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG0, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG11, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECTRODECONFIG12, 0x00) < 0) return -1;

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void set_led_pattern(int pattern) {
    int vals[4] = {0, 0, 0, 0};
    for (int i = 0; i < 4; i++) {
        vals[i] = (pattern >> (3 - i)) & 1;
    }
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], vals[i]);
        }
    }
}

static void log_event(uint16_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (log_fp) {
        fprintf(log_fp, "%s: Touch status = 0x%04X\n", ts, status);
        fflush(log_fp);
    }
    printf("%s: Touch status = 0x%04X\n", ts, status);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        fclose(log_fp);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(led_lines[j]);
            }
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_fp);
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "touch_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(led_lines[j]);
            }
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_fp);
            return 1;
        }
    }

    uint16_t prev_status = 0;
    while (running) {
        uint16_t status;
        if (read_touch_status(i2c_fd, &status) < 0) {
            fprintf(stderr, "I2C read error, continuing...\n");
            usleep(100000);
            continue;
        }

        if (status == 0) {
            printf("No electrodes touched\n");
        } else {
            log_event(status);
            uint16_t mask = status & 0x0FFF;
            int pattern = 0;
            for (int i = 0; i < 12; i++) {
                if (mask & (1 << i)) {
                    pattern |= (1 << (11 - i));
                }
            }
            set_led_pattern(pattern);
        }

        prev_status = status;
        usleep(50000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_fp);
    return 0;
}

