#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_DEVICE_ID 0x5B
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_ECR 0x5F

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E0RTH, 0x05) < 0) return -1;

    if (mpr121_write(MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALL, 0x00) < 0) return -1;

    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int read_device_id(uint8_t *id) {
    int val = i2cReadByteData(i2c_handle, MPR121_DEVICE_ID);
    if (val < 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    *id = (uint8_t)val;
    return 0;
}

static void log_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t device_id = 0;
    if (read_device_id(&device_id) < 0) {
        fprintf(stderr, "Error reading device ID. Check wiring.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("MPR121 detected (Device ID: 0x%02X)\n", device_id);

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int data = i2cReadByteData(i2c_handle, MPR121_ECR);
        if (data < 0) {
            fprintf(stderr, "Error reading ECR register\n");
            break;
        }

        if (data & 0x01) {
            printf("Proximity detected on electrode 0\n");
            gpioWrite(LED_GPIO, 1);
            log_event();
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

