        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int data = i2cReadByteData(i2c_handle, MPR121_ECR);
        if (data < 0) {
            fprintf(stderr, "Error reading ECR register\n");
            break;
        }

        if (data & 0x01) {
            printf("Proximity detected on electrode 0\n");
            gpioWrite(LED_GPIO, 1);
            log_event();
            gpioDelay(1000000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(10000);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

