#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define TRIGGER_HOLD_US 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_distance(FILE *fp, float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo);

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(fp, "%s, ERROR: out of range (%.2f cm)\n", timestamp, distance_cm);
    } else {
        fprintf(fp, "%s, %.2f cm\n", timestamp, distance_cm);
    }
    fflush(fp);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger_line = NULL;
    struct gpiod_line *echo_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("gpiod_chip_get_line trigger");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("gpiod_chip_get_line echo");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trigger");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo_line, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int echo_state = 0;
        int timeout = 0;

        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value trigger low");
            goto cleanup;
        }
        usleep(TRIGGER_HOLD_US);

        /* 10 us high pulse */
        if (gpiod_line_set_value(trigger_line, 1) < 0) {
            perror("gpiod_line_set_value trigger high");
            goto cleanup;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trigger_line, 0) < 0) {
            perror("gpiod_line_set_value trigger low");
            goto cleanup;
        }

        /* Wait for echo rising edge */
        while (echo_state == 0 && program_running) {
            echo_state = gpiod_line_get_value(echo_line);
            if (echo_state < 0) {
                perror("gpiod_line_get_value echo");
                goto cleanup;
            }
            if (timeout++ > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo rising edge\n");
                goto cleanup;
            }
            usleep(1);
        }

        if (!program_running) {
            break;
        }

        if (echo_state == 0) {
            fprintf(stderr, "Sensor absent: echo never rose\n");
            goto cleanup;
        }

        /* Measure echo pulse width */
        int pulse_width = 0;
        timeout = 0;
        while (program_running) {
            echo_state = gpiod_line_get_value(echo_line);
            if (echo_state < 0) {
                perror("gpiod_line_get_value echo");
                goto cleanup;
            }
            if (echo_state == 1) {
                break;
            }
            if (timeout++ > TIMEOUT_US) {
                fprintf(stderr, "Timeout measuring echo pulse width\n");
                goto cleanup;
            }
            usleep(1);
        }

        if (!program_running) {
            break;
        }

        if (timeout == 0) {
            fprintf(stderr, "Timeout measuring echo pulse width\n");
            goto cleanup;
        }

        pulse_width = timeout;

        float distance_cm = (float)pulse_width * SPEED_OF_SOUND_CM_PER_US / 2.0f;

        if (log_distance(log_fp, distance_cm) != 0) {
            fprintf(stderr, "Failed to log distance\n");
        }

        printf("Distance: %.2f cm (pulse: %d us)\n", distance_cm, pulse_width);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger_line) gpiod_line_release(trigger_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

