#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <stdint.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TRIGGER_US 10
#define SAMPLE_INTERVAL_US 1000000
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000
#define SPEED_OF_SOUND 343.0
#define LOG_FILE_SIZE_LIMIT 1048576

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick = 0;
static volatile int g_echo_received = 0;
static volatile int g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        g_start_tick = tick;
        g_echo_received = 0;
    } else if (level == 0) {
        g_end_tick = tick;
        g_echo_received = 1;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIG_PIN %d as output.\n", TRIG_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on ECHO_PIN.\n");
        return -1;
    }
    if (gpioWrite(TRIG_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIG_PIN low.\n");
        return -1;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to set ISR function on ECHO_PIN.\n");
        return -1;
    }
    return 0;
}

static int trigger_sensor(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_US);
    gpioWrite(TRIG_PIN, 0);
    return 0;
}

static double calculate_distance(uint32_t pulse_us) {
    if (pulse_us == 0) {
        return -1.0;
    }
    double distance = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
    return distance;
}

static int log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(g_log_fp, "%s, Distance: %.2f meters\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush failed on log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Error: trigger pulse failed.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        uint32_t start_tick = gpioTick();
        uint32_t end_tick = 0;
        uint32_t elapsed = 0;
        int timeout = 0;

        while (g_running && elapsed < 500000) {
            end_tick = gpioTick();
            elapsed = end_tick - start_tick;
            if (end_tick > start_tick) {
                break;
            }
            gpioDelay(100);
            timeout++;
            if (timeout > 500) {
                break;
            }
        }

        if (!g_running) {
            break;
        }

        if (end_tick == 0) {
            fprintf(stderr, "Warning: no echo received within timeout.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t pulse_us = end_tick - start_tick;
        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: pulse width %u us out of range.\n", pulse_us);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double distance = calculate_distance(pulse_us);
        if (distance < 0.0) {
            fprintf(stderr, "Warning: invalid distance calculation.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error: failed to log distance.\n");
        }

        printf("Distance: %.2f meters\n", distance);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

