#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "gate_log.txt"
#define POLL_DELAY_US 100000

/* VL53L1X register addresses */
#define REG_MODEL_ID 0x010F
#define REG_SYSRANGE_START 0x0015
#define REG_RANGE_CONFIG 0x0021
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x008A

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint16_t val) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    if (i2cWriteDevice(handle, buf, 4) != 0) return -1;
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) != 0) {
        log_message("Error: Failed to read model ID from sensor.");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Unexpected model ID 0x%04X (expected 0xEA).", model_id);
        log_message(msg);
        return -1;
    }
    if (i2c_write_reg16(handle, REG_RANGE_CONFIG, 0x00) != 0) {
        log_message("Error: Failed to set ranging mode.");
        return -1;
    }
    if (i2c_write_reg16(handle, REG_SYSRANGE_START, 0x01) != 0) {
        log_message("Error: Failed to start ranging.");
        return -1;
    }
    log_message("VL53L1X sensor initialized successfully.");
    return 0;
}

static int read_distance_cm(int handle, float *distance_cm) {
    uint16_t status, dist;
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status) != 0) {
        log_message("Error: Failed to read range status.");
        return -1;
    }
    if ((status & 0x01) == 0) {
        log_message("Warning: No new data available.");
        return 1;
    }
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, &dist) != 0) {
        log_message("Error: Failed to read distance.");
        return -1;
    }
    *distance_cm = (float)dist / 10.0f;
    return 0;
}

static void control_gate(int gpio_pin, int distance_cm) {
    int target = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(gpio_pin, target) != 0) {
        log_message("Error: Failed to write GPIO pin.");
    } else {
        char msg[64];
        snprintf(msg, sizeof(msg), "Gate %s (distance: %.2f cm).", target ? "OPEN" : "CLOSED", distance_cm);
        log_message(msg);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0);
    log_message("Gate control system started.");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float distance_cm;
        int rc = read_distance_cm(i2c_handle, &distance_cm);
        if (rc == 0) {
            control_gate(GATE_GPIO, distance_cm);
        } else if (rc < 0) {
            log_message("Error reading distance, attempting re-initialization.");
            if (vl53l1x_init(i2c_handle) != 0) {
                log_message("Re-initialization failed, exiting.");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_message("Shutting down gracefully.");
    gpioWrite(GATE_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

