#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define SERVO_MIN_US   500
#define SERVO_MAX_US   2500
#define SERVO_ANGLE_MIN 0.0
#define SERVO_ANGLE_MAX 180.0
#define MOVING_AVG_SIZE 5
#define ECHO_TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static volatile uint32_t echo_start_tick = 0;
static volatile uint32_t echo_end_tick   = 0;
static volatile int echo_ready = 0;
static volatile int pulse_ready = 0;
static volatile int pulse_us = 0;

static double distance_history[MOVING_AVG_SIZE];
static int history_index = 0;
static int history_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        echo_start_tick = tick;
        echo_ready = 0;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_ready = 1;
        pulse_ready = 1;
    }
}

static double calculate_distance(uint32_t pulse_us) {
    if (pulse_us <= 0) return -1.0;
    double distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static double moving_average(void) {
