#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>

#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define DEFAULT_THRESHOLD 1000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile int proximity_value = 0;
static volatile int threshold = DEFAULT_THRESHOLD;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, data);
    }
    return data;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
    }
    return result;
}

static int read_proximity(int handle) {
    int high = i2c_read_byte(handle, PROXIMITY_HIGH_REG);
    if (high < 0) return -1;
    int low = i2c_read_byte(handle, PROXIMITY_LOW_REG);
    if (low < 0) return -1;
    return (high << 8) | low;
}

static void log_data(int proximity, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, threshold <= proximity ? "SAFE" : "ALERT");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data;
    pthread_mutex_lock(&mutex);
    int prox = read_proximity(i2c_handle);
    if (prox >= 0) {
        if (prox <= threshold) {
            log_data(prox, threshold);
        } else {
            log_data(prox, threshold);
            fprintf(stderr, "ALERT: Proximity exceeded threshold!\n");
        }
    }
    pthread_mutex_unlock(&mutex);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_handle = i2cOpen(I2C_BUS, strtol(optarg, NULL, 0), 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
                    return 1;
                }
                break;
            case 't':
                threshold = strtol(optarg, NULL, 0);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Using default: %d\n", DEFAULT_THRESHOLD);
                    threshold = DEFAULT_THRESHOLD;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

