#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define PWM_PIN     18

#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  200.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define PWM_DUTY_CYCLE   128   /* 50% of 255 */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000 /* 200 ms */
#define SAMPLE_DELAY_US  10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout or error.
 */
static double measure_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    /* Speed of sound ~343 m/s => 0.0343 us/cm */
    double distance = (double)pulse_width * 0.0343 / 2.0;
    return distance;
}

/*
 * Map distance (cm) to frequency (Hz) using a logarithmic formula.
 * Returns frequency in [MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ].
 */
static int calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double ratio = distance / MAX_DISTANCE_CM;
    double log_ratio = log10(ratio);
    double freq = MIN_FREQUENCY_HZ * pow(10.0, log_ratio);
    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return (int)freq;
}

/*
 * Generate a tone on the PWM pin using pigpio's hardware-timed PWM.
 * frequency: Hz, duty_cycle: 0-255 (50% = 128).
 * Returns 0 on success, -1 on error.
 */
static int generate_tone(int frequency, int duty_cycle) {
    if (frequency <= 0 || duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid tone parameters\n");
        return -1;
    }

    /* pigpio hardware-timed PWM uses a single wave with a 32-bit period.
     * The period is set by gpioSetPWMfrequency and gpioSetPWMrange.
     * We use a 32-bit period that is the inverse of the frequency in us. */
    uint32_t period_us = 1000000 / frequency;
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        return -1;
    }
    if (gpioSetPWMrange(PWM_PIN, 255) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        return -1;
    }

    /* Set duty cycle (50% = 128) */
    if (gpioPWM(PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed\n");
        return -1;
    }

    /* Wait for the tone to complete (round up to nearest period) */
    uint32_t complete_tick = gpioTick() + period_us;
    while (gpioTick() < complete_tick) {
        gpioDelay(100); /* 100 us granularity */
    }

    /* Turn off tone */
    gpioPWM(PWM_PIN, 0);
    return 0;
}

int main(void) {
    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
