#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000 /* 200 ms */
#define SAMPLE_DELAY_US  10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout or error.
 */
static double measure_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - echo_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_width = echo_end - echo_start;
    /* Speed of sound ~343 m/s => 0.0343 us/cm */
    double distance = (double)pulse_width * 0.0343 / 2.0;
    return distance;
}

/*
 * Map distance (cm) to frequency (Hz) using a logarithmic formula.
 * Returns frequency in [MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ].
 */
static int calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double ratio = distance / MAX_DISTANCE_CM;
    double log_ratio = log10(ratio);
    double freq = MIN_FREQUENCY_HZ * pow(10.0, log_ratio);
    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
