#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR        0x60
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_HW_KEY  0x07
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_RESET 0x30
#define SI1120_PART_ID 0x41
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write 0x%02X to reg 0x%02X failed (attempt %d/%d): rc=%d\n",
                value, reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) { *value = (uint8_t)rc; return 0; }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1) gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_word(int handle, uint8_t reg_low, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_byte(handle, reg_low, &low) != 0) return -1;
    if (i2c_read_byte(handle, reg_low + 1, &high) != 0) return -1;
    *value = (uint16_t)((high << 8) | low);
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id;
    if (i2c_read_byte(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }
    if (i2c_write_byte(handle, SI1120_REG_RESET, 0x01) != 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
