#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1182_I2C_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 100

/* Si1182 register addresses */
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_MEAS_RATE 0x08
#define SI1182_REG_ALS_DATA0 0x22
#define SI1182_REG_ALS_DATA1 0x23
#define SI1182_REG_PS_DATA0 0x24
#define SI1182_REG_PS_DATA1 0x25

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

static int init_si1182(int fd) {
    uint16_t part_id;
    if (i2c_read_reg16(fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read part ID - sensor may be absent or bus error.\n");
        return -1;
    }
    printf("Si1182 Part ID: 0x%04X\n", part_id);

    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE, 0x07) < 0) {
        fprintf(stderr, "Failed to set measurement rate.\n");
        return -1;
    }
    printf("Si1182 initialized successfully.\n");
    return 0;
}

static int read_sensor_data(int fd, uint16_t *als_raw, uint16_t *ps_raw) {
    if (i2c_read_reg16(fd, SI1182_REG_ALS_DATA0, als_raw) < 0) return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PS_DATA0, ps_raw) < 0) return -1;
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static int log_data(const char *timestamp, uint16_t als_raw, uint16_t ps_raw) {
    if (fprintf(g_log_fp, "%s,%u,%u\n", timestamp, als_raw, ps_raw) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1182_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_si1182(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        fclose(g_log_fp);
        close(g_i2c_fd);
        return 1;
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_raw, ps_raw;
        if (read_sensor_data(g_i2c_fd, &als_raw, &ps_raw) < 0) {
            fprintf(stderr, "Sensor read error - continuing.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (log_data(timestamp, als_raw, ps_raw) < 0) {
            fprintf(stderr, "Logging failed, continuing.\n");
        }

        printf("%s - ALS: %u lux, Proximity: %u\n", timestamp, als_raw, ps_raw);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

