#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND 0.0343  /* cm/us */
#define DISTANCE_THRESHOLD 20.0 /* cm */
#define TRIGGER_PULSE_US  10
#define LOOP_DELAY_US     1000000 /* 1 second */

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_rising = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        start_tick = tick;
        echo_rising = 1;
    } else if (level == 0 && echo_rising) {
        end_tick = tick;
        echo_rising = 0;
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write trigger pin low\n");
        gpioTerminate();
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert callback on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    trigger_sensor();

    /* Wait for echo rising edge (timeout 1 second) */
    uint32_t timeout = 0;
    while (!echo_rising && running) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= 1000000) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }

    if (!running) return -1.0;

    /* Wait for echo falling edge (timeout 1 second) */
    timeout = 0;
    while (echo_rising && running) {
        gpioDelay(100);
        timeout += 100;
        if (timeout >= 1000000) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }

    if (!running) return -1.0;

    uint32_t pulse_width = end_tick - start_tick;
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

static void control_buzzer(double distance) {
    int level = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(BUZZER_PIN, level) != 0) {
        fprintf(stderr, "Error: failed to write buzzer pin %d\n", BUZZER_PIN);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: measurement failed, retrying...\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

