#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_MIN_ANGLE      0
#define SERVO_MAX_ANGLE      180

#define MAX_DISTANCE_CM 200.0
#define MIN_DISTANCE_CM 20.0
#define ECHO_TIMEOUT_US  30000  /* 30 ms timeout for echo */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in centimeters using the HC-SR04.
 * Returns distance on success, -1.0 on timeout or sensor error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick;

    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1.0;
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - echo_start;
    float distance = (float)pulse_width / 58.0f;  /* cm */
    return distance;
}

/*
 * Set servo angle (0-180 degrees) using pigpio hardware PWM.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) return -1;

    int pulse_width = SERVO_MIN_PULSE_WIDTH +
        (int)((float)angle / 180.0f * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) return -1;
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(500000);  /* 500 ms settle */

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: echo timeout or sensor error.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);

            int angle = (int)((distance - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * 180.0f);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Warning: failed to set servo angle.\n");
            }
        }

        gpioDelay(100000);  /* 100 ms */
    }

    /* Cleanup */
    gpioServo(SERVO_PIN, 0);  /* Stop servo PWM */
    gpioTerminate();
    printf("\nParking Assist System stopped.\n");
    return EXIT_SUCCESS;
}

