#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 0.0343  /* cm/us */
#define MIN_DISTANCE   20.0    /* cm */
#define MAX_DISTANCE   200.0   /* cm */
#define MIN_ANGLE      0.0
#define MAX_ANGLE      180.0
#define TIMEOUT_US     50000   /* 50 ms timeout for echo */
#define TRIGGER_PULSE  10      /* us */
#define CYCLE_DELAY    100000  /* 100 ms between measurements */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using HC-SR04.
 * Returns distance on success, -1.0 on timeout.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_start;

    /* Ensure trigger is low before starting */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5); /* 5 us settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND / 2.0f;

    if (distance < 0.0f || distance > 400.0f) {
        fprintf(stderr, "Error: distance out of range (%.1f cm)\n", distance);
        return -1.0;
    }
    return distance;
}

/*
 * Set servo angle (0-180 degrees).
 * pulse_width in microseconds: 500 us for 0 deg, 2500 us for 180 deg.
 */
static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse_width = 500 + (angle * 2000) / 180;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_width);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Error: sensor read failed, retrying...\n");
            gpioDelay(CYCLE_DELAY);
            continue;
        }

        int angle = 0;
        if (distance < MIN_DISTANCE) {
            angle = MIN_ANGLE;
        } else if (distance > MAX_DISTANCE) {
            angle = MAX_ANGLE;
        } else {
            angle = (int)((distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE));
        }

        set_servo_angle(angle);
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        gpioDelay(CYCLE_DELAY);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0); /* Stop servo PWM */
    gpioTerminate();
    return EXIT_SUCCESS;
}

