#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>

#define SI7005_ADDR 0x40
#define SI7005_REG_TEMP 0x01
#define SI7005_REG_HUM 0x02
#define SI7005_REG_CONFIG 0x03
#define SI7005_CONFIG_TEMP_INT 0x00
#define SI7005_CONFIG_HEATER 0x00
#define SI7005_CONFIG_RESET 0x80

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", SI7005_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int configure_sensor(void) {
    if (i2cWriteByteData(i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_RESET) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10000);
    if (i2cWriteByteData(i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_TEMP_INT | SI7005_CONFIG_HEATER) < 0) {
        fprintf(stderr, "Error configuring sensor\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    int raw_temp, raw_hum;
    int ret;

    ret = i2cReadWordData(i2c_handle, SI7005_REG_TEMP);
    if (ret < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", ret);
        return -1;
    }
    raw_temp = (ret >> 8) | (ret << 8);

    ret = i2cReadWordData(i2c_handle, SI7005_REG_HUM);
    if (ret < 0) {
        fprintf(stderr, "Error reading humidity register: %d\n", ret);
        return -1;
    }
    raw_hum = (ret >> 8) | (ret << 8);

    *temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)raw_hum) / 65536.0f - 6.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Attempting I2C recovery...\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C recovery failed. Exiting.\n");
                break;
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Sensor reconfiguration failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(2000000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

