#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define I2C_BUS           1
#define MEASURE_CMD       0xFD
#define MEASURE_DELAY_US  10000   /* 10 ms (datasheet: typ 8.5 ms) */
#define SAMPLE_PERIOD_S   5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (polynomial 0x31, init 0xFF) per SHT40 datasheet ---- */
static uint8_t sht40_crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int open_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Sensor may be absent or bus unavailable.\n",
                        g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed.\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed.\n");
        return -1;
    }

    /* Validate CRCs */
    if (sht40_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }
    if (sht40_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = -6.0f  + 125.0f  * (float)rh_raw / 65535.0f;

    /* Clamp humidity to valid range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sht40(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Warning: sensor read failed, re-opening I2C bus.\n");
            if (open_i2c() != 0) {
                fprintf(stderr, "Fatal: could not re-open I2C bus. Exiting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

