#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define TEMP_REG 0x00
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(err_fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s (errno: %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg, strerror(errno));
    fflush(err_fp);
}

static void log_data(float temp) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp);
    fflush(log_fp);
}

static int read_temperature(float *temp) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        log_error("I2C read failed");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temp = (float)raw / 100.0f;
    return 0;
}

static void cleanup(void) {
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (err_fp) { fclose(err_fp); err_fp = NULL; }
    if (i2c_handle >= 0) { i2cClose(i2c_handle); i2c_handle = -1; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        log_error("Failed to open error log file");
        fclose(log_fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            log_data(temp);
        } else {
            log_error("Failed to read temperature");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    cleanup();
    return 0;
}

