#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define LOG_FILE "pressure_log.csv"
#define POLL_INTERVAL_US 1000000
#define MEASUREMENT_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[9];
    int ret;

    ret = i2cWriteDevice(handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "Error writing command to I2C device: %d\n", ret);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    ret = i2cReadDevice(handle, (char *)buf, 9);
    if (ret != 9) {
        fprintf(stderr, "Error reading from I2C device: expected 9 bytes, got %d\n", ret);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_pressure = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t scale_temperature = (uint16_t)((buf[8] << 8) | buf[9]);

    if (scale_pressure == 0 || scale_temperature == 0) {
        fprintf(stderr, "Invalid scale factor values (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / scale_pressure;
    *temperature = (float)raw_temperature / scale_temperature;

    return 0;
}

static int log_data(const char *filename, float pressure, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    fclose(fp);

    if (file_exists) {
        printf("File %s already exists. Writing header row...\n", LOG_FILE);
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            perror("Error creating log file");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
        fclose(fp);
    }

    float pressure, temperature;
    while (running) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

