#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR 0x44
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sht40_read(int fd, float *temperature, float *humidity) {
    uint8_t cmd = 0xFD;
    uint8_t buf[6];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    ssize_t n = read(fd, buf, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_hum  = ((uint16_t)buf[3] << 8) | buf[4];

