static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int sdp31_write_cmd(int handle, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, 2);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write attempt %d/%d failed (rc=%d)\n", attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
}

static int sdp31_read_data(int handle, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read attempt %d/%d failed (rc=%d)\n", attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_BASE_US * (1 << attempt));
    }
    return -1;
