#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP_NOHOLD 0xF3
#define CMD_HUM_NOHOLD 0xF5
#define MEAS_DELAY_US  20000   /* 20 ms worst-case conversion time */
#define SAMPLE_INTERVAL 5       /* seconds between samples */
#define LOG_FILE        "sensor_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one measurement from the Si7015.                             */
/* Returns 0 on success, -1 on I2C error.                              */
/* ------------------------------------------------------------------ */
static int read_si7015(int handle, uint8_t cmd, uint16_t *raw_out)
{
    char buf[2];

    /* Send the command (single byte write) */
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteByte(0x%02X) failed: %s\n",
                cmd, pigpio_error(i2cWriteByte(handle, cmd)));
        return -1;
    }

    /* Wait for conversion to complete (No Hold Master mode: ~20 ms) */
    gpioDelay(MEAS_DELAY_US);

    /* Read two bytes of data */
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2): %s\n",
                bytes_read, pigpio_error(bytes_read));
        return -1;
    }

    *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw temperature to Celsius.                                 */
/* ------------------------------------------------------------------ */
static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

/* ------------------------------------------------------------------ */
/* Convert raw humidity to %RH, clamped to [0, 100].                   */
/* ------------------------------------------------------------------ */
static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Log one reading to the file and stdout.                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n",
            ts, temperature, humidity);
    fflush(fp);

    printf("%s, Temperature: %.2f C, Humidity: %.2f %%RH\n",
           ts, temperature, humidity);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    if (g_fp != NULL) {
        fclose(g_fp);
        g_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si7015 address 0x40 */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_fp = fopen(LOG_FILE, "a");
    if (g_fp == NULL) {
        fprintf(stderr, "Error: cannot open '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        int ok = 1;

        /* Read temperature */
        if (read_si7015(g_i2c_handle, CMD_TEMP_NOHOLD, &raw_temp) != 0) {
            ok = 0;
        }

        /* Read humidity */
        if (ok && read_si7015(g_i2c_handle, CMD_HUM_NOHOLD, &raw_hum) != 0) {
            ok = 0;
        }

        if (ok) {
            float temperature = convert_temperature(raw_temp);
            float humidity    = convert_humidity(raw_hum);
            log_data(g_fp, temperature, humidity);
        } else {
            fprintf(stderr, "Warning: sensor read failed — skipping sample\n");
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

