#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define BUFFER_SIZE 60
#define MEAS_TEMP_HOLD 0xE3
#define MEAS_HUMID_HOLD 0xE5
#define MEAS_RETRY_COUNT 3
#define MEAS_RETRY_DELAY_US 10000
#define MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(void) {
    buffer_index = 0;
    buffer_count = 0;
}

static void add_to_circular_buffer(time_t ts, float temp, float hum) {
    circular_buffer[buffer_index].timestamp = ts;
    circular_buffer[buffer_index].temperature = temp;
    circular_buffer[buffer_index].humidity = hum;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static int read_sensor(float *temperature, float *humidity) {
    int retries = 0;
    int result;

    while (retries < MEAS_RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, MEAS_TEMP_HOLD);
        if (result < 0) {
            fprintf(stderr, "I2C write error (temp): %d, retry %d/%d\n", result, retries + 1, MEAS_RETRY_COUNT);
            gpioDelay(MEAS_RETRY_DELAY_US);
            retries++;
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)temperature, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read error (temp): %d, retry %d/%d\n", result, retries + 1, MEAS_RETRY_COUNT);
            gpioDelay(MEAS_RETRY_DELAY_US);
            retries++;
            continue;
        }

        *temperature = (175.72f * (uint16_t)((uint8_t)temperature[0] | ((uint8_t)temperature[1] << 8))) / 65536.0f - 46.85f;

        result = i2cWriteByte(i2c_handle, MEAS_HUMID_HOLD);
        if (result < 0) {
            fprintf(stderr, "I2C write error (humid): %d, retry %d/%d\n", result, retries + 1, MEAS_RETRY_COUNT);
            gpioDelay(MEAS_RETRY_DELAY_US);
            retries++;
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        result = i2cReadDevice(i2c_handle, (char *)humidity, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read error (humid): %d, retry %d/%d\n", result, retries + 1, MEAS_RETRY_COUNT);
            gpioDelay(MEAS_RETRY_DELAY_US);
            retries++;
            continue;
        }

        *humidity = (125.0f * (uint16_t)((uint8_t)humidity[0] | ((uint8_t)humidity[1] << 8))) / 65536.0f - 6.0f;

        return 0;
    }

    return -1;
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (Temp: %.2f C)\n", temperature);
    } else if (temperature < TEMP_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (Temp: %.2f C)\n", temperature);
    }
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    add_to_circular_buffer(now, temperature, humidity);
    printf("Timestamp: %ld, Temperature: %.2f C, Humidity: %.2f %%\n", (long)now, temperature, humidity);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting FAN_GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_sensor(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    init_circular_buffer();
    printf("Circular buffer initialized.\n");

    return EXIT_SUCCESS;
}

