#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_SEC 1

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d, expected %d)\n", rc, len);
        return -1;
    }
    return 0;
}

static int verify_crc(const uint8_t *data, int len) {
    for (int i = 0; i < len; i += 2) {
        if (crc8(&data[i], 2) != data[i+2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }
    return 0;
}

static int read_scd40_data(float *co2, float *temp, float *hum) {
    uint8_t buf[9];
    int rc;

    rc = send_command(0xE4B8);
    if (rc < 0) return -1;

    time_sleep(MEASUREMENT_DELAY_SEC);

    rc = read_measurement(buf, 9);
    if (rc < 0) return -1;

    if (verify_crc(buf, 6) < 0) return -1;

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw  = (buf[6] << 8) | buf[7];

    *co2 = (float)co2_raw;
    *temp = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *hum  = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static int log_data(float co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(0x3F86);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(0x21B1) < 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    time_sleep(1.0);

    while (!terminate) {
        uint8_t buf[9];
        int rc = read_scd40_data(NULL, NULL, NULL);
        if (rc < 0) {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle\n");
        } else {
            float co2, temp, hum;
            if (read_scd40_data(&co2, &temp, &hum) == 0) {
                if (log_data(co2, temp, hum) < 0) {
                    fprintf(stderr, "Warning: log write failed\n");
                }
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

