#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_ADDR             0x62
#define I2C_BUS                1
#define LED_GPIO                17
#define CO2_THRESHOLD           1000
#define BUFFER_SIZE             20
#define MEASUREMENT_INTERVAL_S  5
#define MAX_POLL_ATTEMPTS       100

/* SCD40 command codes (16-bit, big-endian on the bus) */
#define CMD_START_PERIODIC      0x21B1
#define CMD_STOP_PERIODIC       0x3F86
#define CMD_READ_MEASUREMENT    0xEC05
#define CMD_GET_DATA_READY      0xE4B8

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* Circular buffer of 20 readings */
typedef struct {
    float  co2;
    float  temperature;
    float  humidity;
} sensor_data_t;

static sensor_data_t g_buffer[BUFFER_SIZE];
static int           g_head = 0;
static int           g_count = 0;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit command to the SCD40                                    */
/* ------------------------------------------------------------------ */
static int scd40_write_command(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice failed for cmd 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit command and wait for completion                        */
/* ------------------------------------------------------------------ */
static int scd40_read_command(uint16_t cmd, uint16_t *response)
{
    if (scd40_write_command(cmd) < 0)
        return -1;

    /* SCD40 needs up to ~45 ms for a command to complete */
    gpioDelay(50000); /* 50 ms */

    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed for cmd 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "Short read for cmd 0x%04X: got %d bytes\n", cmd, rc);
        return -1;
    }

    /* Validate CRC on each 2-byte data word */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on cmd 0x%04X\n", cmd);
        return -1;
    }
    *response = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one measurement (9 bytes: 3 words + 3 CRC bytes)                 */
/* ------------------------------------------------------------------ */
static int scd40_read_measurement(sensor_data_t *data)
{
    uint16_t raw[3];
    uint8_t  buf[9];

    if (scd40_write_command(CMD_READ_MEASUREMENT) < 0)
        return -1;

    gpioDelay(50000); /* 50 ms measurement conversion time */

    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed for measurement (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Short read for measurement: got %d bytes\n", rc);
        return -1;
    }

    /* Validate CRC on each 2-byte data word */
    for (int w = 0; w < 3; w++) {
        if (crc8(&buf[w * 3], 2) != buf[w * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", w);
            return -1;
        }
    }

    /* SCD40 data order: [CO2_hi, CO2_lo, CO2_crc], [T_hi, T_lo, T_crc], [RH_hi, RH_lo, RH_crc] */
    uint16_t co2_raw  = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw   = ((uint16_t)buf[6] << 8) | buf[7];

    /* Convert raw values to physical units (per SCD40 datasheet) */
    data->co2 = (float)co2_raw;
    data->temperature = (float)temp_raw / 100.0f;
    data->humidity = (float)rh_raw / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Check if data is ready (bit 0 of status word)                        */
/* ------------------------------------------------------------------ */
static int scd40_data_ready(void)
{
    uint16_t status;
    if (scd40_read_command(CMD_GET_DATA_READY, &status) < 0)
        return -1;
    return (status & 0x0001) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Add a reading to the circular buffer                                */
/* ------------------------------------------------------------------ */
static void buffer_add(float co2, float temp, float rh)
{
    g_buffer[g_head].co2 = co2;
    g_buffer[g_head].temperature = temp;
    g_buffer[g_head].humidity = rh;
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

/* ------------------------------------------------------------------ */
/* Print the current buffer contents                                     */
/* ------------------------------------------------------------------ */
static void print_buffer(void)
{
    printf("\n--- Last %d readings ---\n", g_count);
    for (int i = 0; i < g_count; i++) {
        int idx = (g_head - g_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] CO2: %7.1f ppm  T: %5.2f C  RH: %5.1f %%\n",
               i, g_buffer[idx].co2, g_buffer[idx].temperature, g_buffer[idx].humidity);
    }
    printf("--- End of buffer ---\n\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
