}

/* ------------------------------------------------------------------ */
/* Print the current buffer contents                                     */
/* ------------------------------------------------------------------ */
static void print_buffer(void)
{
    printf("\n--- Last %d readings ---\n", g_count);
    for (int i = 0; i < g_count; i++) {
        int idx = (g_head - g_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] CO2: %7.1f ppm  T: %5.2f C  RH: %5.1f %%\n",
               i, g_buffer[idx].co2, g_buffer[idx].temperature, g_buffer[idx].humidity);
    }
    printf("--- End of buffer ---\n\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
