{
    if (g_i2c_handle >= 0) {
        scd40_write_command(CMD_STOP_PERIODIC);
        gpioDelay(10000); /* 10 ms stop delay */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
