                I2C_BUS, SCD40_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        cleanup();
