#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define TH_TIMEOUT_US 50000         /* 50 ms timeout for TH edge */
#define TL_TIMEOUT_US 50000         /* 50 ms timeout for TL edge */
#define MIN_TEMP_C -40.0f
#define MAX_TEMP_C 150.0f
#define MAX_READINGS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Wait for a specific level (0 or 1) on GPIO.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) {
            return -1;
        }
    }
    return 0;
}

/*
 * Measure high pulse width (TH) and total cycle width (TL).
 * Returns 0 on success, -1 on timeout or read error.
 */
static int read_tmp05(uint32_t *th, uint32_t *tl) {
    uint32_t th_start = 0, tl_start = 0;
    int th_ok = 0, tl_ok = 0;

    /* Wait for rising edge (start of high pulse) */
    if (wait_level(GPIO_PIN, 1, TH_TIMEOUT_US) != 0) {
        return -1;
    }
    th_start = gpioTick();

    /* Wait for falling edge (end of high pulse) */
    if (wait_level(GPIO_PIN, 0, TH_TIMEOUT_US) != 0) {
        return -1;
    }
    *th = gpioTick() - th_start;

    /* Wait for rising edge (end of cycle) */
    if (wait_level(GPIO_PIN, 1, TL_TIMEOUT_US) != 0) {
        return -1;
    }
    tl_start = gpioTick();

    /* Wait for falling edge (end of cycle) */
    if (wait_level(GPIO_PIN, 0, TL_TIMEOUT_US) != 0) {
        return -1;
    }
    *tl = gpioTick() - tl_start;

    th_ok = 1;
    tl_ok = 1;
    return 0;
}

static float convert_to_celsius(uint32_t th, uint32_t tl) {
    if (tl == 0) {
        return -999.0f;  /* guard against division by zero */
    }
    return 4215.0f - (2143.0f * (float)th / (float)tl);
}

static void log_temperature(float temp) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    uint32_t th, tl;
    int consecutive_errors = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGINT handler\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGTERM handler\n");
    }

    printf("Temperature monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        if (read_tmp05(&th, &tl) == 0) {
            float temp = convert_to_celsius(th, tl);

            if (temp >= MIN_TEMP_C && temp <= MAX_TEMP_C) {
                log_temperature(temp);
                consecutive_errors = 0;
            } else {
                log_error("Temperature reading out of valid range");
                consecutive_errors++;
            }

            if (consecutive_errors >= MAX_READINGS) {
                log_error("SENSOR MALFUNCTION: 3 consecutive invalid readings");
                consecutive_errors = 0;
            }
        } else {
            log_error("Sensor read timeout or error");
            consecutive_errors++;
        }

        if (running) {
            gpioDelay(SAMPLE_INTERVAL_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

