#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_S 5
#define LOG_FILE_NAME "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht35(int handle, sensor_data_t *data) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int result;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        result = i2cWriteDevice(handle, (char *)cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (attempt %d)\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];

        data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        data->humidity = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT35 after %d attempts\n", RETRY_COUNT);
    data->temperature = NAN;
    data->humidity = NAN;
    return -1;
}

static void add_offset(sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    double t = (double)utc->tm_hour + (double)utc->tm_min / 60.0 + (double)utc->tm_sec / 3600.0;
    double offset = 2.0f * sin(2.0f * M_PI * t / 3600.0f);
    data->temperature += offset;
    offset = 5.0f * sin(2.0f * M_PI * t / 3600.0f);
    data->humidity += offset;
}

static void log_data(FILE *fp, sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sht35(i2c_handle, &sensor_data) == 0) {
            add_offset(&sensor_data);
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values\n");
        }
        sleep(LOG_INTERVAL_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

