#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400  /* single-shot, high repeatability, clock stretching disabled */
#define CSV_FILE       "environment.csv"
#define SAMPLE_PERIOD  5       /* seconds */
#define MEASURE_DELAY  20000   /* microseconds (20 ms > 15 ms min) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Open CSV; write header if file is empty ---- */
static int open_csv(void)
{
    FILE *fp = fopen(CSV_FILE, "r");
    if (fp) {
        if (fseek(fp, 0, SEEK_END) == 0)
            return 0;                 /* file is empty */
        fclose(fp);
    }
    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        perror("fopen(CSV write)");
        return -1;
    }
    fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    fclose(fp);
    return 0;
}

/* ---- Read one SHT35 sample; returns 0 on success, -1 on error ---- */
static int read_sht35(int handle, float *temp_c, float *rh_pct)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY);  /* >= 15 ms */

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    if (sht35_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh_pct = 100.0f * (float)h_raw / 65535.0f;

    /* Clamp humidity to physical range */
    if (*rh_pct < 0.0f)   *rh_pct = 0.0f;
    if (*rh_pct > 100.0f) *rh_pct = 100.0f;

    return 0;
}

/* ---- Append one CSV row ---- */
static int log_data(float temp_c, float rh_pct)
{
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("fopen(CSV append)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
    fclose(fp);
    return 0;
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CSV header ---- */
    if (open_csv() != 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT35 logging started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float temp_c, rh_pct;

        if (read_sht35(g_i2c_handle, &temp_c, &rh_pct) == 0) {
            if (log_data(temp_c, rh_pct) != 0)
                fprintf(stderr, "Logging failed\n");
            else
                printf("%s  T=%.2f C  RH=%.2f %%\n",
                       "read", temp_c, rh_pct);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

