#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "environment.log"
#define READ_INTERVAL_SEC 5
#define MEAS_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, float *out) {
    uint8_t buf[3];
    int timeout = 0;

    if (i2c_write_cmd(fd, cmd) < 0) return -1;

    while (timeout < MEAS_TIMEOUT_MS) {
        if (i2c_read_bytes(fd, buf, 3) < 0) return -1;
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
            return -1;
        }
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out = (175.72f * raw) / 65536.0f - 46.85f;
        return 0;
    }
    fprintf(stderr, "Measurement 0x%02X timed out after %d ms\n", cmd, MEAS_TIMEOUT_MS);
    return -1;
}

static int read_humidity(int fd, float *out) {
    return read_measurement(fd, 0xF5, out);
}

static int read_temperature(int fd, float *out) {
    return read_measurement(fd, 0xF3, out);
}

static int read_paired(int fd, float *temp, float *hum) {
    if (read_humidity(fd, hum) < 0) return -1;
    if (read_temperature(fd, temp) < 0) return -1;
    return 0;
}

static void log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }
    fclose(fp);
}

static void reset_sensor(int fd) {
    if (i2c_write_cmd(fd, 0xFE) < 0) return;
    usleep(10000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Greenhouse monitoring started. Logging to '%s' every %d s.\n", LOG_FILE, READ_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 0;

        if (read_paired(g_i2c_fd, &temp, &hum) == 0) {
            ok = 1;
        } else {
            reset_sensor(g_i2c_fd);
        }

        if (ok) {
            log_data(temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

