#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_US 45000
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "airflow.dat"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int sdp810_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int sdp810_read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: Failed to read data from sensor\n");
        return -1;
    }
    return 0;
}

static int sdp810_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", SDP810_ADDR, I2C_BUS);
        gpioTerminate();
        return -1;
    }

    if (sdp810_write_command(MEASUREMENT_COMMAND) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int sdp810_read(float *pressure, float *temperature) {
    uint8_t buf[9];
    if (sdp810_read_data(buf, 9) != 0) return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    uint16_t scale_factor = (buf[6] << 8) | buf[7];
    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor - 1000.0f;
    *temperature = (float)raw_temperature / 200.0f - 45.0f;

    return 0;
}

static int log_data(float pressure, float temperature) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "wb");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
            return -1;
        }
    }

    if (fwrite(&pressure, sizeof(float), 1, log_file) != 1 ||
        fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        fprintf(stderr, "Error: Failed to write data to log file\n");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }

    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: Failed to set signal handlers");
        return 1;
    }

    if (sdp810_init() != 0) {
        return 1;
    }

    uint32_t next_tick = gpioTick();

    while (!terminate) {
        float pressure, temperature;

        if (sdp810_read(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        next_tick += SAMPLE_INTERVAL_US;
        uint32_t now = gpioTick();
        if (next_tick > now) {
            gpioDelay(next_tick - now);
        } else {
            fprintf(stderr, "Warning: Sample interval overshot, skipping\n");
        }
    }

    cleanup();
    return 0;
}

