#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "flow_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor(uint16_t *raw) {
    char buf[2];
    int ret = i2cReadDevice(i2c_handle, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", ret);
        return -1;
    }
    *raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static float calculate_flow_rate(uint16_t raw) {
    /* 14-bit data: bits 15:2 are flow, status bits are bits 1:0 of the 16-bit word */
    uint16_t flow_raw = (raw >> 2) & 0x3FFF;
    /* Linear transfer function: 1638 counts = 0 SLPM, 14745 counts = 10 SLPM */
    float flow = (float)flow_raw * 10.0f / 14745.0f;
    return flow;
}

static int set_fan_speed(float flow_rate) {
    int duty = (int)(flow_rate / 10.0f * PWM_RANGE);
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(float flow_rate) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", ts, flow_rate);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Airflow control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw;
        if (read_sensor(&raw) == 0) {
            float flow_rate = calculate_flow_rate(raw);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
            printf("Flow: %.2f SLPM, Fan: %d%%\n", flow_rate, (duty / PWM_RANGE) * 100);
        } else {
            fprintf(stderr, "Sensor read failed; keeping fan at 50%%\n");
            set_fan_speed(5.0f);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Airflow control stopped.\n");
    return 0;
}

