#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  1.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++)
        cb->buffer[i] = 0.0f;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/*
 * Read temperature from STLM75.
 * Returns 0 on success, -1 on error.
 */
static int read_temperature(int handle, float *out_temp)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }

    /* pigpio returns bytes in little-endian order; swap to get MSB first. */
    uint16_t swapped = ((uint16_t)raw >> 8) | ((uint16_t)raw << 8);
    uint8_t  msb = (uint8_t)(swapped >> 7);
    uint8_t  lsb = (uint8_t)(swapped & 0x7F);

    /* STLM75: 9-bit two's-complement, MSB = sign bit, LSB = data bits 7..0. */
    int8_t signed_val = (int8_t)(msb << 7 | lsb);
    *out_temp = (float)signed_val / 2.0f;
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);

            int led_state = (avg > TEMP_THRESHOLD) ? 1 : 0;
            if (gpioWrite(LED_GPIO, led_state) < 0)
                fprintf(stderr, "Warning: failed to write LED GPIO\n");

            if (led_state)
                printf("Threshold exceeded! LED ON\n");
            else
                printf("Threshold not exceeded. LED OFF\n");
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

