#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 100000
#define MEASUREMENT_INTERVAL_US 2000000

#define CMD_START_CONTINUOUS_MEASUREMENT 0x0300
#define CMD_READ_MEASUREMENT 0x0000
#define CMD_READ_DATA_READY 0x0202
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0400

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t scd30_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_read_bytes(uint8_t *buf, int len) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error: I2C read failed, expected %d bytes, got %d\n", len, bytes_read);
        return -1;
    }
    return 0;
}

static int scd30_init(void) {
    if (scd30_write_command(CMD_START_CONTINUOUS_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command(CMD_READ_DATA_READY) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_write_command(CMD_START_CONTINUOUS_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    return 0;
}

static int scd30_data_ready(void) {
    uint8_t buf[3];
    if (scd30_write_command(CMD_READ_DATA_READY) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_read_bytes(buf, 3) != 0)
        return -1;
    if (scd30_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready flag\n");
        return -1;
    }
    uint16_t ready = (buf[0] << 8) | buf[1];
    return (ready & 0x07FF) != 0 ? 1 : 0;
}

static int scd30_read_measurement(uint8_t *buf) {
    if (scd30_write_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(10000);
    if (scd30_read_bytes(buf, 18) != 0)
        return -1;
    if (scd30_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on CO2 value\n");
        return -1;
    }
    if (scd30_crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: CRC mismatch on temperature value\n");
        return -1;
    }
    if (scd30_crc8(buf + 7, 2) != buf[9]) {
        fprintf(stderr, "Error: CRC mismatch on humidity value\n");
        return -1;
    }
    return 0;
}

static void log_data(float co2, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

static void control_ventilation(float co2) {
    if (co2 < 800.0f) {
        gpioWrite(4, 0);
        gpioWrite(5, 0);
        gpioWrite(6, 0);
        gpioWrite(7, 0);
        printf("Ventilation: OFF (CO2: %.2f ppm)\n", co2);
    } else if (co2 < 1200.0f) {
        gpioWrite(4, 0);
        gpioWrite(5, 1);
        gpioWrite(6, 0);
        gpioWrite(7, 0);
        printf("Ventilation: LOW (CO2: %.2f ppm)\n", co2);
    } else {
        gpioWrite(4, 1);
        gpioWrite(5, 1);
        gpioWrite(6, 1);
        gpioWrite(7, 1);
        printf("Ventilation: HIGH (CO2: %.2f ppm)\n", co2);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 0;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (scd30_init() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    gpioSetMode(4, PI_OUTPUT);
    gpioSetMode(5, PI_OUTPUT);
    gpioSetMode(6, PI_OUTPUT);
    gpioSetMode(7, PI_OUTPUT);

    while (!terminate) {
        int ready = scd30_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: Data-ready poll failed\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint8_t buf[18];
        if (scd30_read_measurement(buf) != 0) {
            fprintf(stderr, "Error: Measurement read failed\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint16_t co2_raw = (buf[0] << 8) | buf[1];
        uint16_t temp_raw = (buf[3] << 8) | buf[4];
        uint16_t hum_raw = (buf[7] << 8) | buf[8];

        float co2 = (float)co2_raw;
        float temperature = (float)temp_raw / 100.0f;
        float humidity = (float)hum_raw / 100.0f;

        log_data(co2, temperature, humidity);
        control_ventilation(co2);

        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
    gpioDelay(10000);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

