        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure_pa;
    int consecutive_errors = 0;

    while (running) {
        if (read_sdp32(i2c_handle, &pressure_pa) == 0) {
            log_data(pressure_pa);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Failed to read sensor data (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Sensor not responding. Exiting.\n");
                break;
            }
        }

        gpioDelay(interval_us);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

