#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define CMD_CONT_MEAS  0x3615
#define CONV_DELAY_US  45000   /* 45 ms conversion time */
#define SAMPLE_PERIOD  1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Read one continuous-measurement frame ----
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (uint8_t)(CMD_CONT_MEAS >> 8), (uint8_t)(CMD_CONT_MEAS & 0xFF) };
    uint8_t buf[9];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice failed: %d\n", rc);
        return -1;
    }

    gpioDelay(CONV_DELAY_US);

    rc = i2cReadDevice(handle, (char *)buf, 9);
    if (rc < 0) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Short read: got %d bytes, expected 9\n", rc);
        return -1;
    }

    /* CRC check on each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure word\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale-factor word\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_press  = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_temp   = (int16_t)((buf[8] << 8) | buf[8]);

    if (scale_press == 0 || scale_temp == 0) {
        fprintf(stderr, "Invalid scale factors (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_press;
    *temperature = (float)raw_temp / 200.0f;
    return 0;
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa differential pressure sensor (I2C 0x%02X)\n", SDP810_ADDR);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Sensor read error (bus or CRC).\n");
        } else {
            fprintf(stderr, "CRC mismatch on sensor data.\n");
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

