        fprintf(stderr, "i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 9) {
        fprintf(stderr, "Short read: got %d bytes, expected 9\n", rc);
        return -1;
    }

    /* CRC check on each 3-byte word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure word\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature word\n");
        return -2;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale-factor word\n");
        return -2;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_press  = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t scale_temp   = (int16_t)((buf[8] << 8) | buf[8]);

    if (scale_press == 0 || scale_temp == 0) {
        fprintf(stderr, "Invalid scale factors (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)raw_pressure / (float)scale_press;
    *temperature = (float)raw_temp / 200.0f;
    return 0;
}

int main(void) {
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa differential pressure sensor (I2C 0x%02X)\n", SDP810_ADDR);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "Sensor read error (bus or CRC).\n");
        } else {
            fprintf(stderr, "CRC mismatch on sensor data.\n");
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

