#define HDC1000_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define CONVERSION_DELAY_MS 20
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_hdc1000(int fd, float *temperature, float *humidity) {
    if (i2c_write_reg8(fd, CONFIG_REG, 0x40) < 0) {
        return -1;
    }
    usleep(CONVERSION_DELAY_MS * 1000);

    uint16_t raw_temp;
    if (i2c_read_reg16(fd, TEMP_REG, &raw_temp) < 0) {
        return -1;
    }

    uint16_t raw_hum;
    if (i2c_read_reg16(fd, TEMP_REG + 2, &raw_hum) < 0) {
        return -1;
    }

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 sensor reader started on %s (addr 0x%02X). Press Ctrl+C to exit.\n", I2C_BUS, HDC1000_ADDR);

    while (g_running) {
        float temperature, humidity;
        if (read_hdc1000(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

