#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SI7051_ADDR 0x40
#define I2C_BUS 1
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
        if (result == 2) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
            *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed (result=%d)\n", attempt + 1, result);
        if (attempt < MAX_RETRIES - 1) {
            gpioDelay(100000); /* 100 ms backoff */
        }
    }
    return -1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (error=%d)\n",
                I2C_BUS, SI7051_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7051 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        if (read_temperature(&temperature) == 0) {
            printf("%s - Temperature: %.2f C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "%s - Error: Failed to read temperature after %d retries\n",
                    timestamp, MAX_RETRIES);
        }
        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

