#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICP10101_ADDR  0x63
#define MEAS_CMD       0x40
#define OTP_CMD        0x50
#define READ_LEN       6
#define SAMPLE_PERIOD  5.0
#define MEAS_DELAY_US  7000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_otp(int handle, uint8_t *buf, size_t len) {
    if (i2cWriteByte(handle, OTP_CMD) < 0) return -1;
    gpioDelay(1000);
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int read_measurement(int handle, uint8_t *buf, size_t len) {
    if (i2cWriteByte(handle, MEAS_CMD) < 0) return -1;
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int read_sensor(int handle, float *temperature, float *pressure) {
    uint8_t buf[READ_LEN];
    if (read_measurement(handle, buf, READ_LEN) < 0) {
        fprintf(stderr, "Error: I2C read measurement failed\n");
        return -1;
    }
    uint32_t raw_t = ((uint32_t)buf[0] << 8) | buf[1];
    uint32_t raw_p = ((uint32_t)buf[2] << 8) | buf[3];
    uint32_t raw_p2 = ((uint32_t)buf[4] << 8) | buf[5];

    /* Datasheet compensation formulas */
    float scale_factor_lut = 0.0f;
    float scale_factor_h  = 0.0f;
    float scale_factor_p  = 0.0f;

    if (raw_t == 0xFFFF && raw_p == 0xFFFF && raw_p2 == 0xFFFF) {
        fprintf(stderr, "Error: Sensor absent (all 0xFF)\n");
        return -1;
    }
    if (raw_t == 0xFFFF || raw_p == 0xFFFF || raw_p2 == 0xFFFF) {
        fprintf(stderr, "Error: Sensor absent (invalid data)\n");
        return -1;
    }

    /* LUT: 0x0000 -> 0x0000, 0x0001 -> 0x0001, ... */
    scale_factor_lut = (float)raw_t / 0xFFFFf;
    /* H: 0x0000 -> 0x0000, 0x0001 -> 0x0001, ... */
    scale_factor_h  = (float)raw_p / 0xFFFFf;
    /* P: 0x0000 -> 0x0000, 0x0001 -> 0x0001, ... */
    scale_factor_p  = (float)raw_p2 / 0xFFFFf;

    /* Scale factors are computed from OTP coefficients */
