#define MEASUREMENT_CMD_MSB 0x36
#define MEASUREMENT_CMD_LSB 0x2F
#define MEASUREMENT_DELAY_US 8000
#define LOG_FILE "airflow_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp800(int handle, float *pressure) {
    uint8_t cmd[2] = {MEASUREMENT_CMD_MSB, MEASUREMENT_CMD_LSB};
    uint8_t buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed (rc=%d)\n", rc);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d)\n", rc);
        return -1;
    }
    if (rc != 3) {
        fprintf(stderr, "Error: short read (%d bytes)\n", rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw / 60.0f;
    return 0;
}

static int log_data(const char *filename, float pressure) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

