        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int write_header = (fp == NULL);
    if (fp) {
        fclose(fp);
    }

    fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("Error creating log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (write_header) {
        fprintf(fp, "timestamp,pressure_pa\n");
    }
    fclose(fp);

    printf("SDP800 differential pressure logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float pressure;
        if (read_sdp800(i2c_handle, &pressure) == 0) {
            if (log_data(LOG_FILE, pressure) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping log\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

