#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MLX90821_ADDR  0x40
#define PRESSURE_REG   0x00
#define SCALE_FACTOR   0.01f
#define MIN_PRESSURE   200.0f
#define MAX_PRESSURE   250.0f
#define LOG_FILE       "pressure_log.csv"
#define RETRY_COUNT    3
#define RETRY_DELAY_US 100000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure)
{
    char buf[2];
    int  bytes_read;

    bytes_read = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2)\n", bytes_read);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", ts, pressure);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    float pressure;
    int   retry;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    printf("Tire Pressure Monitoring System started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        retry = 0;
        while (retry < RETRY_COUNT && g_running) {
            if (read_pressure(&pressure) == 0) {
                log_pressure(pressure);
                break;
            }
            retry++;
            if (retry < RETRY_COUNT) {
                fprintf(stderr, "Warning: I2C read failed, retrying (%d/%d)...\n", retry, RETRY_COUNT);
                usleep(RETRY_DELAY_US);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Error: I2C read failed after %d retries, attempting to re-open bus\n", RETRY_COUNT);
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            if (init_i2c() != 0) {
                fprintf(stderr, "Error: I2C re-initialisation failed, exiting\n");
                break;
            }
            continue;
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure %.2f kPa out of safe range [%.0f, %.0f] kPa\n",
                    pressure, MIN_PRESSURE, MAX_PRESSURE);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

