#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define SYNC_US (SYNC_TICKS * TICK_US)
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define NIBBLES 4
#define SCALE 0.1
#define OFFSET 0.0
#define LOG_FILE "pressure_log.txt"
#define READ_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(int gpio) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: SENT nibble timeout on GPIO %d\n", gpio);
            return -1;
        }
    }
    uint32_t end = gpioTick();
    uint32_t ticks = end - start;
    if (ticks < NIBBLE_MIN_TICKS || ticks > NIBBLE_MAX_TICKS) {
        fprintf(stderr, "Error: Invalid nibble pulse width %u us on GPIO %d\n", ticks, gpio);
        return -1;
    }
    return (int)(ticks / TICK_US);
}

static int read_sent_data(int gpio, int *data) {
    for (int i = 0; i < NIBBLES; i++) {
        int n = read_sent_nibble(gpio);
        if (n < 0) return -1;
        data[i] = n;
    }
    return 0;
}

static int validate_sent_data(int *data) {
    int sum = data[0] + data[1] + data[2] + data[3];
    if (sum % 16 != data[3]) {
        fprintf(stderr, "Error: SENT checksum mismatch (sum=0x%02X, calc=0x%02X)\n", sum, data[3]);
        return -1;
    }
    return 0;
}

static float convert_to_pressure(int raw_data) {
    return (float)raw_data * SCALE + OFFSET;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    printf("Pressure monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENT_GPIO);

    while (running) {
        int data[NIBBLES];
        if (read_sent_data(SENT_GPIO, data) < 0) {
            fprintf(stderr, "Error reading SENT data\n");
            gpioDelay(100000);
            continue;
        }
        if (validate_sent_data(data) < 0) {
            fprintf(stderr, "Error validating SENT data\n");
            gpioDelay(100000);
            continue;
        }
        int raw = (data[0] << 8) | (data[1] << 4) | data[2];
        float pressure = convert_to_pressure(raw);
        log_pressure(pressure);
        printf("Pressure: %.2f Pa\n", pressure);
        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

