#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define TEMP_LSB       0.0078125f
#define BUFFER_SIZE    100
#define LOG_FILE       "temperature_log.dat"
#define SAMPLE_US     5000000  /* 5 seconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature from TMP117.  Returns 0 on success, -1 on error.   */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temperature)
{
    char buf[2];
    int  result;

    result = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2)\n",
                result);
        return -1;
    }

    /* TMP117 sends MSB first */
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                            (uint16_t)(uint8_t)buf[1]);
    *temperature = (float)raw * TEMP_LSB;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one temperature reading to the circular buffer.             */
/* ------------------------------------------------------------------ */
static void add_to_buffer(float temperature, float *buffer,
                          int *index, int size)
{
    buffer[*index] = temperature;
    *index = (*index + 1) % size;
}

/* ------------------------------------------------------------------ */
/* Flush the entire buffer to the binary log file.                    */
/* ------------------------------------------------------------------ */
static void flush_buffer_to_file(float *buffer, int size)
{
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    size_t written = fwrite(buffer, sizeof(float), size, fp);
    if (written != (size_t)size) {
        fprintf(stderr, "Error writing to log file (wrote %zu of %d)\n",
                written, size);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float temperature;
    float buffer[BUFFER_SIZE];
    int   buffer_index = 0;
    int   buffer_count  = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C handle --- */
    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMP117 temperature logger started.  Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            add_to_buffer(temperature, buffer, &buffer_index, BUFFER_SIZE);
            buffer_count++;

            printf("Temperature: %.4f C\n", temperature);

            if (buffer_count >= BUFFER_SIZE) {
                flush_buffer_to_file(buffer, BUFFER_SIZE);
                buffer_count = 0;
            }
        } else {
            fprintf(stderr, "Warning: temperature read failed, skipping sample\n");
        }

        /* Sleep 5 seconds, but wake early if a signal arrives */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    flush_buffer_to_file(buffer, BUFFER_SIZE);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

