#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI7202_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor(float *field_gauss, float *temp_celsius) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    int raw_field = (buf[0] << 8) | buf[1];
    int raw_temp = (buf[0] << 8) | buf[1];
    *field_gauss = (float)raw_field * 0.1f;
    *temp_celsius = (float)raw_temp * 0.01f - 25.0f;
    return 0;
}

static int log_data(float field_gauss, float temp_celsius) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
            return -1;
        }
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Field(Gauss),Temperature(C)\n");
        }
    }

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, field_gauss, temp_celsius) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Si7202 rotational speed measurement started. Press Ctrl+C to stop.\n");

    while (running) {
        float field_gauss, temp_celsius;
        if (read_sensor(&field_gauss, &temp_celsius) == 0) {
            if (log_data(field_gauss, temp_celsius) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
            if (log_file != NULL) {
                fprintf(log_file, "Error reading sensor data,NaN,NaN\n");
                fflush(log_file);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

