#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3
#define READ_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "Initial I2C init failed. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);

            if (consecutive_failures >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max consecutive failures reached. Exiting.\n");
                break;
            }

            if (init_i2c() != 0) {
                fprintf(stderr, "Reinit failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(READ_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

