#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define SAMPLE_INTERVAL_US 2000000
#define START_LOW_US 18000
#define START_HIGH_US 40
#define RESP_LOW_US 80
#define RESP_HIGH_US 80
#define BIT_LOW_US 50
#define BIT_HIGH_US 26
#define TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_fp);
}

static void log_error(const char *msg) {
    char buf[256];
    snprintf(buf, sizeof(buf), "ERROR: %s", msg);
    log_message(buf);
}

static void log_reading(float temp, float hum) {
    char buf[128];
    snprintf(buf, sizeof(buf), "Temperature: %.1f C, Humidity: %.1f %%", temp, hum);
    log_message(buf);
}

static int wait_level(int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(DHT11_GPIO) != level) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    uint32_t t0, t1, t2, t3, t4, t5;

    log_message("DHT11 read started");

    /* --- Start signal: pull low for >= 18 ms, then release --- */
    if (gpioSetMode(DHT11_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT11_GPIO, 0) < 0) return -1;
    gpioDelay(START_LOW_US);
    if (gpioWrite(DHT11_GPIO, 1) < 0) return -1;
    gpioDelay(START_HIGH_US);

    /* --- Sensor response: 80 us low + 80 us high --- */
    if (wait_level(0, TIMEOUT_US) < 0) return -2;  /* sensor absent (line stuck low) */
    if (wait_level(1, TIMEOUT_US) < 0) return -2;  /* sensor absent (line stuck high) */
    if (wait_level(0, TIMEOUT_US) < 0) return -3;  /* response timeout */

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Each bit starts with 50 us low */
        if (wait_level(1, TIMEOUT_US) < 0) return -4;
        /* High pulse duration determines bit value */
        t0 = gpioTick();
        if (wait_level(0, TIMEOUT_US) < 0) return -5;
        t1 = gpioTick();
        if (t1 - t0 > BIT_HIGH_US) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) {
        return -6;
    }

    /* DHT11: humidity in bytes 0-1, temperature in bytes 2-3 */
    *hum = (float)data[0] + (float)data[1] / 10.0f;
    *temp = (float)data[2] + (float)data[3] / 10.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("DHT11 reader started");

    while (running) {
        float temp, hum;
        int rc = read_dht11(&temp, &hum);

        if (rc == 0) {
            log_reading(temp, hum);
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "DHT11 read failed (code %d)", rc);
            log_error(msg);
        }

        /* Sleep in small increments so signals are caught promptly */
        uint32_t remaining = SAMPLE_INTERVAL_US;
        while (remaining > 0 && running) {
            uint32_t chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    log_message("DHT11 reader stopping");
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

