#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SHT31_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define MEASUREMENT_CMD 0x2C06
#define MEASUREMENT_DELAY_US 15000
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_S 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
        *humidity = 100.0f * (float)raw_hum / 65535.0f;

        return 0;
    }

    return -1;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, SHT31_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,ERROR,SENSOR_FAILURE\n", timestamp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

