#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68
#define ADPD105_ID_VALUE 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from 0x%02X: expected %u, got %d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int verify_device_id(int handle) {
    uint8_t id = 0;
    if (read_register(handle, ADPD105_REG_ID, &id) != 0) {
        return -1;
    }
    if (id != ADPD105_ID_VALUE) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X) at 0x%02X\n", id, ADPD105_ID_VALUE, handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[3];
    if (read_block(handle, ADPD105_REG_RED, buf, 3) != 0) return -1;
    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    if (read_block(handle, ADPD105_REG_GREEN, buf, 3) != 0) return -1;
    *green = (uint16_t)((buf[1] << 8) | buf[0]);
    if (read_block(handle, ADPD105_REG_BLUE, buf, 3) != 0) return -1;
    *blue = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float r = (float)red / 65535.0f;
    float g = (float)green / 65535.0f;
    float b = (float)blue / 65535.0f;
    float x = 0.412453f * r + 0.212671f * g + 0.082151f * b;
    float y = 0.357580f * r + 0.715160f * g + 0.072280f * b;
    float z = 0.0193346f * r + 0.1191936f * g + 0.9502270f * b;
    float x_prime = 0.412453f * y + 0.212671f * z;
    float y_prime = 0.715160f * y + 0.072280f * z;
    float cct = 449.0f * (x_prime / x_prime + y_prime / y_prime) - 440.0f;
    if (cct < 170.0f) cct = 170.0f;
    if (cct > 650.0f) cct = 650.0f;
    return cct;
}

static void log_cct(float cct) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s,%.2f\n", timestamp, cct);
    fflush(log_fp);
}

static void cleanup(void) {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
        i2c_handle_2 = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADPD105_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", ADPD105_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        i2c_handle_1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device_id(i2c_handle_1) != 0 || verify_device_id(i2c_handle_2) != 0) {
        fprintf(stderr, "Sensor verification failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Average_CCT\n");
        fflush(log_fp);
    }

    printf("Starting data acquisition. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t red1 = 0, green1 = 0, blue1 = 0;
        uint16_t red2 = 0, green2 = 0, blue2 = 0;
        int ok1 = 0, ok2 = 0;

        if (read_sensor_data(i2c_handle_1, &red1, &green1, &blue1) == 0) {
            ok1 = 1;
        }
        if (read_sensor_data(i2c_handle_2, &red2, &green2, &blue2) == 0) {
            ok2 = 1;
        }

        if (ok1 && ok2) {
            float cct1 = calculate_cct(red1, green1, blue1);
            float cct2 = calculate_cct(red2, green2, blue2);
            float avg_cct = (cct1 + cct2) / 2.0f;
            log_cct(avg_cct);
            printf("Average CCT: %.2f\n", avg_cct);
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read error\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

