#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN 0.0f
#define PMAX 800.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_register(uint8_t reg, uint16_t *out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed for register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint16_t raw_pressure, raw_temperature;

    if (read_register(PRESSURE_REG, &raw_pressure) != 0) {
        return -1;
    }
    if (read_register(TEMPERATURE_REG, &raw_temperature) != 0) {
        return -1;
    }

    *pressure = ((float)raw_pressure - OUTPUT_MIN) * (PMAX - PMIN) / (OUTPUT_MAX - OUTPUT_MIN);
    *temperature = (float)raw_temperature * 0.01f - 40.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n",
                timestamp, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "# Tire Pressure Monitoring System started\n");
    fprintf(log_file, "# I2C bus %d, sensor 0x%02X, log file %s\n",
            I2C_BUS, MLX90824_ADDR, LOG_FILE);
    fflush(log_file);

    while (!terminate) {
        float pressure, temperature;

        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

