#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define SAMPLE_INTERVAL  1.0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temp_out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error (rc=%d)\n", rc);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 1;
    *temp_out = (float)raw * 0.5f;
    return 0;
}

static void control_fan(float avg_temp) {
    static int fan_on = 0;
    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void update_buffer(float temp, float *buf, int *idx, int size) {
    buf[*idx] = temp;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float *buf, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buf[i];
    return (size > 0) ? (sum / (float)size) : 0.0f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, LM75B_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp_buf[BUFFER_SIZE];
    int buf_idx = 0;

    while (running) {
        float temp;
        if (read_temperature(i2c_handle, &temp) == 0) {
            update_buffer(temp, temp_buf, &buf_idx, BUFFER_SIZE);
            float avg = calculate_average(temp_buf, BUFFER_SIZE);
            printf("Temp: %.2f C, Avg: %.2f C\n", temp, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Read error; will retry next cycle\n");
        }
        time_sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

