#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    msgs[0].addr  = STTS2004_ADDR;
    msgs[0].flags = 0;
    msgs[0].len   = 1;
    msgs[0].buf   = &reg;

    msgs[1].addr  = STTS2004_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len   = 2;
    msgs[1].buf   = buf;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C_RDWR read failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float raw_to_celsius(int16_t raw)
{
    return (float)raw / 16.0f;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int led_state = 0;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "stts2004-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(fd, TEMP_REG, &raw) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            goto cleanup;
        }

        float temp = raw_to_celsius(raw);

        if (temp > TEMP_HIGH && led_state == 0) {
            if (gpiod_line_set_value(led, 1) < 0) {
                fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
                goto cleanup;
            }
            led_state = 1;
        } else if (temp < TEMP_LOW && led_state == 1) {
            if (gpiod_line_set_value(led, 0) < 0) {
                fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
                goto cleanup;
            }
            led_state = 0;
        }

        printf("Temperature: %.2f C, LED: %s\n",
               temp, led_state ? "ON" : "OFF");
        fflush(stdout);

        sleep(POLL_INTERVAL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fd >= 0)
        close(fd);

    return rc;
}

