#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3

/* Si7021 commands (no master hold) */
#define CMD_MEASURE_TEMP_NOHOLD  0xF3
#define CMD_MEASURE_RH_NOHOLD    0xF5
#define CMD_READ_TEMP_PREV_RH   0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single command byte to the Si7021 */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* Read `len` bytes from the Si7021 after issuing a command */
static int si7021_read_data(int handle, uint8_t cmd, uint8_t *buf, uint8_t len)
{
    int rc;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (rc < 0) {
            fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) attempt %d failed: %d\n",
                    cmd, attempt + 1, rc);
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }

        gpioDelay(20000); /* 20 ms conversion time */

        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len) {
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadDevice(0x%02X) attempt %d returned %d (expected %d)\n",
                cmd, attempt + 1, rc, len);
        gpioDelay(10000);
    }
    return -1;
}

/* Read temperature in degrees Celsius; returns 0 on success, -1 on error */
static int read_temperature(int handle, float *temp_c)
{
    uint8_t buf[2];
    if (si7021_read_data(handle, CMD_MEASURE_TEMP_NOHOLD, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

/* Read relative humidity in percent; returns 0 on success, -1 on error */
static int read_humidity(int handle, float *hum_pct)
{
    uint8_t buf[2];
    if (si7021_read_data(handle, CMD_MEASURE_RH_NOHOLD, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *hum_pct = (125.0f * (float)raw) / 65536.0f - 6.0f;
    if (*hum_pct < 0.0f)   *hum_pct = 0.0f;
    if (*hum_pct > 100.0f) *hum_pct = 100.0f;
    return 0;
}

/* Read temperature from the previous RH measurement */
static int read_previous_temperature(int handle, float *temp_c)
{
    uint8_t cmd = CMD_READ_TEMP_PREV_RH;
    uint8_t buf[2];
    if (si7021_write_cmd(handle, cmd) != 0)
        return -1;

    gpioDelay(20000); /* 20 ms conversion */

    if (si7021_read_data(handle, 0, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (175.72f * (float)raw) / 65536.0f - 46.85f;
    return 0;
}

static void log_data(float temp_c, float hum_pct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        fprintf(stderr, "Logging to %s failed; writing to stdout only.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
        fflush(fp);
    } else {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
    }

    printf("%s,%.2f,%.2f\n", ts, temp_c, hum_pct);
    fflush(stdout);
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(log file)");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
    }
    fprintf(stderr, "[ERROR] %s\n", msg);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SI7021_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Quick presence check: try reading the electronic ID byte (0x0F) */
    uint8_t id_buf[1];
    if (si7021_read_data(g_i2c_handle, 0x0F, id_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] Sensor not responding at 0x%02X — check wiring/power\n", SI7021_ADDR);
        log_error("Sensor not detected");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read firmware revision (0x94) */
    uint8_t rev_buf[1];
    if (si7021_read_data(g_i2c_handle, 0x94, rev_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] Failed to read firmware revision\n");
        log_error("Firmware revision read failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    uint16_t rev = ((uint16_t)rev_buf[0] << 8) | rev_buf[1];
