#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define I2C_BUS 1
#define LOG_FILE "enviro_log.txt"
#define CONVERSION_DELAY_US 20000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(int handle) {
    // Configuration: 14-bit temp, 14-bit humidity, no heater, no config bit
    // Bits 7:4 = 0011 (14-bit temp), Bits 3:0 = 0011 (14-bit humidity)
    // Value = 0x33
    if (i2cWriteByteData(handle, CONFIG_REG, 0x33) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    // Write pointer to register 0x00 to start a single measurement
    if (i2cWriteByte(handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error setting pointer register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 20 ms for 14-bit)
    gpioDelay(CONVERSION_DELAY_US);

    // Read 4 bytes: 2 bytes temp, 2 bytes humidity
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data (read %d bytes)\n", bytes_read);
        return -1;
    }

    // Convert raw values
    int raw_temp = (buf[0] << 8) | buf[1];
    int raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X\n", I2C_BUS, HDC1080_ADDR);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting HDC1080 logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        float temperature, humidity;

        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            } else {
                printf("Logged: %.2f C, %.2f %%\n", temperature, humidity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Sleep 5 seconds, checking terminate flag every second
        for (int i = 0; i < 5 && !terminate; i++) {
            gpioDelay(1000000); // 1 second
        }
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return 0;
}

