    if (i2c_write_cmd(fd, MEAS_CMD_HIGHREP, 0xE0) < 0)
        return -1;

    usleep(CONV_DELAY_MS * 1000);

    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        fprintf(stderr, "I2C read failed: expected 3 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temp_c)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, temp_c);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, LOOP_DELAY_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp_c;
        if (read_temperature(g_i2c_fd, &temp_c) == 0) {
            log_temperature(g_log_fp, temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(LOOP_DELAY_S);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

