#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define READ_INTERVAL_SEC 5
#define LOGGING_INTERVAL_SEC 60
#define MEASUREMENT_DELAY_SEC 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE000
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_running = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int read_measurement(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_sensor_data(int *co2, float *temperature, float *humidity) {
    if (i2c_write_command(CMD_READ_MEASUREMENT) != 0)
        return -1;

    gpioDelay(10000);

    uint8_t buf[9];
    if (read_measurement(buf, 9) != 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    *co2 = (int)co2_raw;
    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(circular_buffer_t *cb, sensor_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static void *logging_thread(void *arg) {
    (void)arg;
    while (running) {
        if (logging_running) {
            time_t now = time(NULL);
            FILE *fp = fopen(LOG_FILE, "a");
            if (!fp) {
                log_error("Cannot open log file for append");
                continue;
            }
            fprintf(fp, "%ld", (long)now);
            for (int i = 0; i < buffer.count; i++) {
                int idx = (buffer.tail + i) % BUFFER_SIZE;
                fprintf(fp, ",%d,%.2f,%.2f", buffer.data[idx].co2,
                        buffer.data[idx].temperature, buffer.data[idx].humidity);
            }
            fclose(fp);
        }
        sleep(LOGGING_INTERVAL_SEC);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    logging_running = 0;
}

static void buffer_flush(circular_buffer_t *cb) {
    time_t now = time(NULL);
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Cannot open log file for flush");
        return;
    }
    fprintf(fp, "%ld", (long)now);
    for (int i = 0; i < buffer.count; i++) {
        int idx = (buffer.tail + i) % BUFFER_SIZE;
        fprintf(fp, ",%d,%.2f,%.2f", buffer.data[idx].co2,
                buffer.data[idx].temperature, buffer.data[idx].humidity);
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (i2c_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        i2c_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (i2c_write_command(CMD_READ_MEASUREMENT) != 0) {
            log_error("Failed to request measurement");
            sleep(READ_INTERVAL_SEC);
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_SEC * 1000000);

        int co2;
        float temperature, humidity;
        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data = { time(NULL), co2, temperature, humidity };
            buffer_add(&buffer, data);
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(READ_INTERVAL_SEC);
    }

    pthread_join(log_thread, NULL);
    buffer_flush(&buffer);

    i2c_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

