#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define LOG_FILE "sdp810_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MEAS_DELAY_US 45000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sdp810(int handle, float *pressure, float *temperature) {
    uint8_t cmd[2] = { (CMD_CONT_MEAS >> 8) & 0xFF, CMD_CONT_MEAS & 0xFF };
    uint8_t buf[9];
    int ret;

    ret = i2cWriteDevice(handle, (char *)cmd, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    ret = i2cReadDevice(handle, (char *)buf, 9);
    if (ret != 9) {
        fprintf(stderr, "I2C read error: expected 9 bytes, got %d\n", ret);
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC error on scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure * (float)scale_factor / 1000.0f;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SDP810_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
