#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_START_REG 0x05
#define CALIB_LEN 4
#define MEASURE_REG 0x00
#define MEASURE_CMD 0x00
#define SAMPLE_INTERVAL_SEC 5
#define MEASURE_DELAY_US 10000

static int i2c_handle = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t program_running = 1;

static uint16_t calib[2];
static int16_t calib2[2];

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_calibration_data(void) {
    uint8_t buf[CALIB_LEN];
    if (i2cReadI2CBlockData(i2c_handle, CALIB_START_REG, (char *)buf, CALIB_LEN) != CALIB_LEN) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < 2; i++) {
        calib[i] = (uint16_t)buf[2 * i];
        calib2[i] = (int16_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor_data(float *pressure, float *temperature) {
    uint8_t data[6];
    if (i2cWriteByteData(i2c_handle, MEASURE_REG, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadI2CBlockData(i2c_handle, MEASURE_REG, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    uint32_t raw_pressure = ((uint32_t)data[0] << 16) | ((uint32_t)data[1] << 8) | data[2];
    uint32_t raw_temperature = ((uint32_t)data[3] << 16) | ((uint32_t)data[4] << 8) | data[5];

    float p = (float)raw_pressure;
    float t = (float)raw_temperature;

    float p_comp = p * 0.0001f - 45000.0f;
    float t_comp = t * 0.00001f - 25.0f;
    float p_out = p_comp / (1.0f + t_comp * 0.0001f);
    float t_out = t_comp / 100.0f;

    *pressure = p_out;
    *temperature = t_out;
    return 0;
}

