    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(data_file);
    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

