    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    data_file = fopen("environmental_data.txt", "a");
    if (!data_file) {
        fprintf(stderr, "Error: Failed to open data file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        float pressure, temperature;
        if (read_sensor_data(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (data_file) fclose(data_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

