#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define I2C_BUS 1
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 15000
#define READ_BUFFER_SIZE 6

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int i2c_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = 0xFD;
    unsigned char data[READ_BUFFER_SIZE];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(MEASUREMENT_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)data, READ_BUFFER_SIZE) != READ_BUFFER_SIZE) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            continue;
        }

        unsigned int raw_temperature = (data[0] << 8) | data[1];
        unsigned int raw_humidity = (data[2] << 8) | data[3];

        *temperature = -45.0f + 175.0f * (float)raw_temperature / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_humidity / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 sensor after %d attempts.\n", MAX_RETRIES);
    return -1;
}

void handle_client(int client_socket) {
    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    char response[1024];

    if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        snprintf(response, sizeof(response),
                 "HTTP/1.1 200 OK\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
                 "<meta charset=\"UTF-8\"></head><body>"
                 "<h1>SHT40 Sensor Data</h1>"
                 "<p>Timestamp: %s</p>"
                 "<p>Temperature: %.2f &deg;C</p>"
                 "<p>Humidity: %.2f %%</p></body></html>",
                 timestamp, temperature, humidity);
    } else {
        snprintf(response, sizeof(response),
                 "HTTP/1.1 500 Internal Server Error\r\n"
                 "Content-Type: text/html\r\n"
                 "Connection: close\r\n"
                 "\r\n"
                 "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
                 "<meta charset=\"UTF-8\"></head><body>"
                 "<h1>Error Reading Sensor</h1>"
                 "<p>Failed to read sensor data.</p></body></html>");
    }

    send(client_socket, response, strlen(response), 0);
    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Could not create socket");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
