        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Climate Monitoring System\n");
    printf("Reading temperature from TMP102 at 0x%02X every %d seconds. Press Ctrl+C to exit.\n", TMP102_ADDR, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(LOG_FILE, temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature reading\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read temperature\n");
        }

        if (running) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_SEC, 0);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

