#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR 0x40
#define I2C_BUS 1
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG_REG 0x0F
#define TEMP_LOW_REG 0x00
#define HUMID_LOW_REG 0x02
#define MAX_RETRIES 3
#define POLL_TIMEOUT_MS 500

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int trigger_measurement(int handle) {
    uint8_t config = 0x01; /* Heater disabled, 14-bit temp, 14-bit humidity */
    if (write_register(handle, CONFIG_REG, config) < 0) {
        return -1;
    }
    /* Poll MEASUREMENT_CONFIG until bit 0 clears (data ready) */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        uint8_t cfg;
        if (read_register(handle, MEASUREMENT_CONFIG, &cfg) < 0) {
            return -1;
        }
        if (cfg & 0x01) {
            return 0; /* Data ready */
        }
        gpioDelay(1000); /* 1 ms */
    }
    fprintf(stderr, "Timeout waiting for measurement to complete\n");
    return -1;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t low, high;
    if (read_register(handle, TEMP_LOW_REG, &low) < 0) {
        return -1;
    }
    if (read_register(handle, TEMP_LOW_REG + 1, &high) < 0) {
        return -1;
    }
    uint16_t raw = (uint16_t)((high << 8) | low);
    *temperature = (float)raw / 65536.0f * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint8_t low, high;
    if (read_register(handle, HUMID_LOW_REG, &low) < 0) {
        return -1;
    }
    if (read_register(handle, HUMID_LOW_REG + 1, &high) < 0) {
        return -1;
    }
    uint16_t raw = (uint16_t)((high << 8) | low);
    *humidity = (float)raw / 65536.0f * 100.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC2010 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (trigger_measurement(i2c_handle) == 0) {
                float temperature, humidity;
                if (read_temperature(i2c_handle, &temperature) == 0 &&
                    read_humidity(i2c_handle, &humidity) == 0) {
                    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
                    success = 1;
                    break;
                }
            }
            gpioDelay(100000); /* 100 ms between retries */
        }

        if (!success) {
            fprintf(stderr, "Failed to read sensor after %d attempts\n", MAX_RETRIES);
        }

        if (running) {
            sleep(5);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

