#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define GPIO_CHIP "gpiochip0"
#define RELAY_PIN 17
#define LOG_FILE "reflow_log.csv"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "reflow-oven", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", RELAY_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }

    return 0;
}

static int read_max6675(int *raw_temp) {
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int raw = ((rx[1] & 0x0F) << 8) | rx[2];
    if (raw & 0x04) {
        fprintf(stderr, "MAX6675 open-circuit flag set\n");
        return -1;
    }
    *raw_temp = raw;
    return 0;
}

static double pid_control(double setpoint, double actual, double *integral, double *prev_error) {
    double proportional = setpoint - actual;
    *integral += proportional;
    double derivative = proportional - *prev_error;
    double output = 0.0;
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    output += 0.1 * (*integral) + 0.5 * (derivative);
    *prev_error = actual;
    return output;
}

static int log_data(double temp, double pid_out) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
        fprintf(log_fp, "Timestamp,Temperature_C,PID_Duty\n");
    }

    fprintf(log_fp, "%s,%.2f,%.2f\n", ts, temp, pid_out);
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *prof_fp = fopen("profile.txt", "r");
    if (!prof_fp) {
        fprintf(stderr, "Warning: Could not open profile.txt, using default profile\n");
    } else {
        double target_profile[100];
        int num_points = 0;
        char line[256];
        while (fgets(line, sizeof(line), prof_fp)) {
            char *saveptr = NULL;
            double val = strtof(line, &saveptr);
            if (val >= 0.0 && val <= 100.0) {
                target_profile[num_points++] = val;
            }
            if (num_points >= 100) break;
        }
        fclose(prof_fp);
        if (num_points == 0) {
            fprintf(stderr, "No valid target profile found\n");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    double target_profile[100];
    for (int i = 0; i < num_points; i++) {
        target_profile[i] = target_profile[i] / 100.0;
    }

    double integral = 0.0, prev_error = 0.0;
    double pid_out = 0.0;

    while (running) {
        int raw;
        if (read_max6675(&raw) != 0) {
            fprintf(stderr, "Sensor read error, retrying in %d s\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        double temp = raw / 16.0;
        double setpoint = target_profile[temp % num_points];
        pid_out = pid_control(setpoint, temp, &integral, &prev_error);

        if (gpiod_line_set_value(relay_line, (int)(pid_out * 100.0)) < 0) {
            fprintf(stderr, "Failed to set relay GPIO: %s\n", strerror(errno));
        }

        if (log_data(temp, pid_out) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

