#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_RELAY 17
#define GPIO_PWM 18
#define GPIO_TEMP 4
#define LOG_FILE "greenhouse.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static struct gpiod_line *temp_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp) {
    char path[256];
    char buffer[256];
    int ret;

    snprintf(path, sizeof(path), "/sys/bus/w1/devices/%s/w1_slave", "28-000005c4c4c4");
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (sscanf(buffer, "t=%d", temp) != 1) {
        fprintf(stderr, "Error parsing temperature from %s\n", path);
        return -1;
    }

    return 0;
}

static int set_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        fprintf(stderr, "Error setting relay GPIO %d: %s\n", GPIO_RELAY, strerror(errno));
        return -1;
    }
    return 0;
}

static int set_pwm(int duty_cycle) {
    if (gpiod_line_set_value(pwm_line, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM GPIO %d: %s\n", GPIO_PWM, strerror(errno));
        return -1;
    }
    return 0;
}

static int calculate_pid(float setpoint, float current_temp, float *output) {
    static float integral = 0.0f;
    static float previous_error = 0.0f;
    float error = setpoint - current_temp;
