#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define GPIO_LINE       17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5
#define MAX_RETRIES     3
#define RETRY_DELAY_MS  10
#define MEAS_DELAY_MS   80

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_init(int fd) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    if (i2c_write(fd, init_cmd, sizeof(init_cmd)) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write(fd, cmd, sizeof(cmd)) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        usleep(MEAS_DELAY_MS * 1000);

        if (i2c_read(fd, data, sizeof(data)) < 0) {
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (data[0] & 0x01) {
            fprintf(stderr, "AHT20 busy or not calibrated (status=0x%02X)\n", data[0]);
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint32_t raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4)  |
                       ((uint32_t)data[3] >> 4);

        *humidity = (float)raw / 1024.0f * 100.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_humidity(float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

int main(void) {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        goto cleanup;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    relay = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "aht20-relay", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity = 0.0f;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    fprintf(stderr, "Failed to set relay HIGH: %s\n", strerror(errno));
                }
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    fprintf(stderr, "Failed to set relay LOW: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret = 0;

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

