    if (!relay) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay, "aht20-relay", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float humidity = 0.0f;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay, 1) < 0) {
                    fprintf(stderr, "Failed to set relay HIGH: %s\n", strerror(errno));
                }
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay, 0) < 0) {
                    fprintf(stderr, "Failed to set relay LOW: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret = 0;

cleanup:
    if (relay) {
        gpiod_line_set_value(relay, 0);
        gpiod_line_release(relay);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

