#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTTP_SERVER "http://api.example.com/humidity"
#define HTTP_PORT 80
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    uint16_t raw;
    if (i2c_read_word(fd, 0x1D, &raw) < 0) return -1;
    uint16_t raw_t = raw >> 8;
    uint16_t raw_h = raw & 0xFF;
    if (raw_t & 0x8000) {
        syslog(LOG_ERR, "Temperature flag set (0x%04X), invalid data", raw_t);
        return -1;
    }
    uint8_t crc = (uint8_t)(0xFF ^ raw_h);
    uint8_t calc = 0;
    for (int i = 0; i < 16; i++) {
        calc ^= (raw_h >> i) & 0x01;
        if (calc & 0x80) calc |= 0xFF;
    }
    if (calc != (uint8_t)raw_h) {
        syslog(LOG_ERR, "Humidity CRC mismatch (0x%02X != 0x%02X)", raw_h, calc);
        return -1;
    }
    *humidity = (float)raw_h / 110.0f;
    return 0;
}

static int post_humidity(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket() failed: %s", strerror(errno));
        return -1;
    }
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_SERVER, &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "inet_pton() failed for %s", HTTP_SERVER);
        close(sockfd);
        return -1;
    }
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "connect() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    char body[256];
    int len = snprintf(body, sizeof(body), "{\"humidity\": %.2f}", humidity);
    if (len < 0 || len >= (int)sizeof(body)) {
        syslog(LOG_ERR, "Body formatting failed");
        close(sockfd);
        return -1;
    }
    if (send(sockfd, body, (size_t)len, 0) < 0) {
        syslog(LOG_ERR, "send() failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    openlog("htu21d_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        closelog();
        return 1;
    }
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "open(%s) failed: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "ioctl(I2C_SLAVE, 0x%02X) failed: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "HTU21D monitor started on %s", I2C_BUS);
    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "HTTP POST failed");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

