#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define I2C_BUS 1
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

static bmp280_calib_data calib;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int read_calibration(int handle) {
    uint8_t buf[24];
    if (i2c_read_block(handle, BMP280_REG_CALIB, buf, sizeof(buf)) != (int)sizeof(buf)) {
        return -1;
    }
    calib.dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    calib.dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    calib.dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    calib.dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    calib.dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    calib.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    calib.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    calib.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    calib.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    calib.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    calib.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    calib.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_p, int32_t *raw_t) {
    uint8_t buf[6];
    if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, buf, sizeof(buf)) != (int)sizeof(buf)) {
        return -1;
    }
    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | ((int32_t)buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | ((int32_t)buf[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_t) {
    double var1 = ((double)raw_t / 16384.0 - (double)calib.dig_T1 / 1024.0) * (double)calib.dig_T2;
    double var2 = ((double)raw_t / 131072.0 - (double)calib.dig_T1 / 8192.0) *
                 ((double)raw_t / 131072.0 - (double)calib.dig_T1 / 8192.0) * (double)calib.dig_T3;
    calib.dig_T1 = (uint16_t)(var1 + var2 + (double)calib.dig_T1);
    return var1 + var2;
}

static double compensate_pressure(int32_t raw_p) {
    double var1 = (double)calib.dig_P1 / 16384.0 * compensate_temperature(raw_t);
    double var2 = (double)calib.dig_P2 * compensate_temperature(raw_t) / 16384.0;
    double var3 = (double)calib.dig_P3 * compensate_temperature(raw_t) / 131072.0;
    double var4 = (double)calib.dig_P4 * compensate_temperature(raw_t) / 16384.0;
    double var5 = (double)calib.dig_P5 * compensate_temperature(raw_t) / 131072.0;
    double var6 = (double)calib.dig_P6 * compensate_temperature(raw_t) / 16384.0;
    double var7 = (double)calib.dig_P7 * compensate_temperature(raw_t) / 8192.0;
    double var8 = (double)calib.dig_P8 * compensate_temperature(raw_t) / 32768.0;
    double var9 = (double)calib.dig_P9 * compensate_temperature(raw_t) / 2147483648.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - var1 / 4096.0) * 6250.0 / var2;
    p = (p - var3 / 65536.0) * 6250.0 / var1;
    p = p + var4 / 65536.0;
    p = p * 63.0 + var5 / 65536.0;
    p = p * 63.0 + var6 / 4096.0;
    p = p * 63.0 + var7 / 16384.0;
    p = p * 63.0 + var8 / 8192.0;
    p = p * 63.0 + var9 / 2147483648.0;
    p = p / 64.0;
    return p;
}

static int open_i2c(void) {
    int handle = i2cOpen(I2C_BUS, BMP280_I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BMP280_I2C_ADDR, handle);
    }
    return handle;
}

static int verify_chip_id(int handle) {
    int id = i2cReadByteData(handle, BMP280_REG_CHIP_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read chip ID: %d\n", id);
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    return 0;
}

static int init_bmp280(int handle) {
    if (i2c_write_byte(handle, BMP280_REG_RESET, 0xB6) < 0) return -1;
    gpioDelay(2000);
    if (read_calibration(handle) < 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0xA0) < 0) return -1;
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = open_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    if (verify_chip_id(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    if (init_bmp280(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int32_t raw_p, raw_t;
        if (read_raw_data(i2c_handle, &raw_p, &raw_t) == 0) {
            double temp = compensate_temperature(raw_t);
            double press = compensate_pressure(raw_p);
            printf("T=%.2f C  P=%.2f hPa\n", temp, press);
            if (press > PRESSURE_HIGH_THRESHOLD) {
                log_event("Pressure breach: above threshold");
            } else if (press < PRESSURE_LOW_THRESHOLD) {
                log_event("Pressure breach: below threshold");
            }
        } else {
            fprintf(stderr, "Read failed, re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            for (int i = 0; i < MAX_RETRIES && running; i++) {
                gpioDelay(100000);
                i2c_handle = open_i2c();
                if (i2c_handle >= 0) {
                    if (verify_chip_id(i2c_handle) == 0 && init_bmp280(i2c_handle) == 0) {
                        break;
                    }
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                }
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

