#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO_LINE 17
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

#define TMP117_TEMP_REG 0x00
#define AHT20_INIT_CMD 0xBE 0x08 0x00
#define AHT20_MEASURE_CMD 0xAC 0x33 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd_tmp117 = -1;
static int i2c_fd_aht20 = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu, got %zd (%s)\n", len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_tmp117(void) {
    i2c_fd_tmp117 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd_tmp117, I2C_SLAVE, TMP117_ADDR) < 0) {
        fprintf(stderr, "Failed to set TMP117 I2C address 0x%02X: %s\n", TMP117_ADDR, strerror(errno));
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    uint8_t init_cmd[3] = {AHT20_INIT_CMD, 0x00, 0x00};
    if (i2c_write_cmd(i2c_fd_tmp117, init_cmd, sizeof(init_cmd)) < 0) {
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
        return -1;
    }
    usleep(10000);
    return 0;
}

static int init_aht20(void) {
    i2c_fd_aht20 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd_aht20, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set AHT20 I2C address 0x%02X: %s\n", AHT20_ADDR, strerror(errno));
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
        return -1;
    }
    uint8_t init_cmd[3] = {AHT20_INIT_CMD, 0x00, 0x00};
    if (i2c_write_cmd(i2c_fd_aht20, init_cmd, sizeof(init_cmd)) < 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_tmp117(float *temp) {
    uint8_t cmd[2] = {TMP117_TEMP_REG, 0x00};
    if (i2c_write_cmd(i2c_fd_tmp117, cmd, sizeof(cmd)) < 0) return -1;
    usleep(10000);
    uint8_t buf[2];
    if (i2c_read_bytes(i2c_fd_tmp117, buf, sizeof(buf)) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw * 0.0078125f;
    return 0;
}

static int read_aht20(float *hum, float *temp) {
    uint8_t cmd[3] = {AHT20_MEASURE_CMD, 0x00, 0x00};
    if (i2c_write_cmd(i2c_fd_aht20, cmd, sizeof(cmd)) < 0) return -1;
    usleep(10000);
    uint8_t buf[7];
    if (i2c_read_bytes(i2c_fd_aht20, buf, sizeof(buf)) < 0) return -1;
    if (buf[0] & 0x80) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }
    uint32_t raw_hum = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | ((uint32_t)buf[3] >> 4);
    uint32_t raw_temp = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    *hum = (float)raw_hum / 100.0f;
    *temp = (float)raw_temp * 0.0078125f;
    return 0;
}

static int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        fprintf(stderr, "Failed to read PIR GPIO: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void log_data(float temp, float hum, int motion) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *fp = fopen("daily_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open daily_log.csv: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
}

static void cleanup(void) {
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd_tmp117 >= 0) {
        close(i2c_fd_tmp117);
        i2c_fd_tmp117 = -1;
    }
    if (i2c_fd_aht20 >= 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_tmp117() < 0 || init_aht20() < 0) {
        fprintf(stderr, "Sensor initialization failed. Continuing with warnings.\n");
    }

    while (running) {
        float temp, hum;
        int motion = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_tmp117(&temp) == 0) ok = 1;
            if (ok) break;
            fprintf(stderr, "TMP117 read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "TMP117 unavailable after %d retries\n", MAX_RETRIES);
            temp = -999.0f;
        }

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_aht20(&hum, &temp) == 0) ok = 1;
            if (ok) break;
            fprintf(stderr, "AHT20 read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "AHT20 unavailable after %d retries\n", MAX_RETRIES);
            hum = -1.0f;
        }

        motion = read_pir();
        if (motion < 0) {
            fprintf(stderr, "PIR read failed\n");
        }

        log_data(temp, hum, motion);
        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return 0;
}

