    }
    if (i2c_fd_aht20 >= 0) {
        close(i2c_fd_aht20);
        i2c_fd_aht20 = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_GPIO_LINE, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_tmp117() < 0 || init_aht20() < 0) {
        fprintf(stderr, "Sensor initialization failed. Continuing with warnings.\n");
    }

    while (running) {
        float temp, hum;
        int motion = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_tmp117(&temp) == 0) ok = 1;
            if (ok) break;
            fprintf(stderr, "TMP117 read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "TMP117 unavailable after %d retries\n", MAX_RETRIES);
            temp = -999.0f;
        }

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_aht20(&hum, &temp) == 0) ok = 1;
            if (ok) break;
            fprintf(stderr, "AHT20 read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            fprintf(stderr, "AHT20 unavailable after %d retries\n", MAX_RETRIES);
            hum = -1.0f;
        }

        motion = read_pir();
        if (motion < 0) {
            fprintf(stderr, "PIR read failed\n");
        }

        log_data(temp, hum, motion);
        sleep(SAMPLE_INTERVAL_S);
    }

    cleanup();
    return 0;
}

