#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (rain_line == NULL) {
        perror("gpiod_chip_get_line(rain_sensor)");
        goto cleanup;
    }

    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    if (enable_line == NULL) {
        perror("gpiod_chip_get_line(enable)");
        goto cleanup;
    }

    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (in1_line == NULL) {
        perror("gpiod_chip_get_line(in1)");
        goto cleanup;
    }

    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (in2_line == NULL) {
        perror("gpiod_chip_get_line(in2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain_sensor)");
        goto cleanup;
    }

    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("gpiod_line_request_output(enable)");
        goto cleanup;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started.");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error reading rain sensor.");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected!");

            if (gpiod_line_set_value(enable_line, 1) < 0) {
                perror("gpiod_line_set_value(enable, 1)");
                log_event("Error enabling motor.");
                break;
            }

            if (gpiod_line_set_value(in1_line, 1) < 0) {
                perror("gpiod_line_set_value(in1, 1)");
                log_event("Error setting IN1 high.");
                break;
            }

            if (gpiod_line_set_value(in2_line, 0) < 0) {
                perror("gpiod_line_set_value(in2, 0)");
                log_event("Error setting IN2 low.");
                break;
            }

            log_event("Motor running forward for 5 seconds.");

            for (int i = 0; i < MOTOR_RUN_SEC && program_running; i++) {
                sleep(1);
            }

            if (gpiod_line_set_value(enable_line, 0) < 0) {
                perror("gpiod_line_set_value(enable, 0)");
                log_event("Error stopping motor.");
                break;
            }

            if (gpiod_line_set_value(in1_line, 0) < 0) {
                perror("gpiod_line_set_value(in1, 0)");
                log_event("Error setting IN1 low.");
                break;
            }

            if (gpiod_line_set_value(in2_line, 0) < 0) {
                perror("gpiod_line_set_value(in2, 0)");
                log_event("Error setting IN2 low.");
                break;
            }

            log_event("Motor stopped.");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Rain sensor monitoring stopped.");
    ret = EXIT_SUCCESS;

cleanup:
    if (enable_line != NULL) {
        gpiod_line_set_value(enable_line, 0);
        gpiod_line_release(enable_line);
    }
    if (in1_line != NULL) {
        gpiod_line_set_value(in1_line, 0);
        gpiod_line_release(in1_line);
    }
    if (in2_line != NULL) {
        gpiod_line_set_value(in2_line, 0);
        gpiod_line_release(in2_line);
    }
    if (rain_line != NULL) {
        gpiod_line_release(rain_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

