    var1 = (((calib.dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int32_t)calib.dig_P2) * var1) >> 1)) >> 18;
    var1 = ((((32768 + var1)) * ((int32_t)calib.dig_P1)) >> 15);
    if (var1 == 0) return 0;
    p = (((uint32_t)(((1048576) - adc_P) - (var2 >> 12))) * 3125);
    if (p < 0x80000000) {
        p = (p * 2) / (uint32_t)var1;
    } else {
        p = (p / (uint32_t)var1) * 2;
    }
    var1 = (((int32_t)calib.dig_P9) * (int32_t)((p >> 3) * (p >> 3))) >> 12;
    var2 = (((int32_t)(p >> 2)) * ((int32_t)calib.dig_P8)) >> 13;
    p = (uint32_t)((int32_t)p + ((var1 + var2 + calib.dig_P7) >> 4));
    return p;
}

static int read_bmp280(int handle, float *temperature, float *pressure) {
    uint8_t data[6];
    int32_t adc_P, adc_T;

    if (i2c_write_byte(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_byte(handle, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    gpioDelay(10000);

    for (int i = 0; i < 50; i++) {
        if (i2c_read_block(handle, BMP280_REG_PRESS_MSB, data, 6) == 0) break;
        gpioDelay(2000);
        if (i == 49) return -1;
    }

    adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    int32_t temp_comp = compensate_temperature(adc_T);
    uint32_t press_comp = compensate_pressure(adc_P);

    *temperature = (float)temp_comp / 100.0f;
    *pressure = (float)press_comp / 256.0f;
    return 0;
}

static int send_udp_packet(int sock, const char *json_string) {
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        return -1;
    }

    if (sendto(sock, json_string, strlen(json_string), 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    int id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found (chip ID: 0x%02X, expected: 0x%02X)\n", id, BMP280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature, pressure;
        if (read_bmp280(i2c_handle, &temperature, &pressure) == 0) {
            char json_string[128];
            snprintf(json_string, sizeof(json_string), "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);
            if (send_udp_packet(udp_socket, json_string) < 0) {
                fprintf(stderr, "UDP send failed\n");
            }
        } else {
            fprintf(stderr, "BMP280 read failed\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    fprintf(stderr, "Shutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (udp_socket >= 0) close(udp_socket);
    gpioTerminate();
    return 0;
}

