#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20
#define SAMPLE_INTERVAL_US 1000000

#define TEMP_LOW 25.0
#define TEMP_MID 40.0
#define TEMP_HIGH 60.0

typedef struct {
    time_t timestamp;
    float temperature;
    int pwm_duty;
} TemperatureData;

static TemperatureData temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

static int read_max31855(int spi_handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        if (raw & 0x00000001) {
            fprintf(stderr, "MAX31855 fault: OC\n");
        }
        if (raw & 0x00000002) {
            fprintf(stderr, "MAX31855 fault: SCG\n");
        }
        if (raw & 0x00000004) {
            fprintf(stderr, "MAX31855 fault: SCV\n");
        }
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temperature = thermocouple_temp * 0.25f;
    return 0;
}

static int calculate_pwm(float temperature) {
    if (temperature < TEMP_LOW) {
        return 0;
    } else if (temperature < TEMP_MID) {
        return (int)(((temperature - TEMP_LOW) / (TEMP_MID - TEMP_LOW)) * 50);
    } else if (temperature < TEMP_HIGH) {
        return (int)(((temperature - TEMP_MID) / (TEMP_HIGH - TEMP_MID)) * 150);
    } else {
        return 255;
    }
}

static void log_temperature_data(float temperature, int pwm_duty) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    temperature_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_buffer(void) {
    printf("\n--- Temperature Log ---\n");
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&temperature_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Temp: %.2f C, PWM: %d\n",
               time_str, temperature_buffer[idx].temperature,
               temperature_buffer[idx].pwm_duty);
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        int pwm_duty = -1;

        if (read_max31855(spi_handle, &temperature) == 0) {
            pwm_duty = calculate_pwm(temperature);
            if (gpioPWM(FAN_GPIO, pwm_duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO%d\n", FAN_GPIO);
            }
            log_temperature_data(temperature, pwm_duty);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping fan update\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return EXIT_SUCCESS;
}

