#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define OSS 3
#define I2C_BUS 1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(i2c_handle, reg) < 0) return -1;
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {reg, val};
    return (i2cWriteDevice(i2c_handle, buf, 2) == 0) ? 0 : -1;
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2c_read_reg(BMP180_REG_CAL_AC1, buf, 22) < 0) return -1;
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 || ac6 == 0) return -1;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2c_write_reg(BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    uint8_t buf[3];
    if (i2c_read_reg(BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - OSS);
    return 0;
}

static int read_bmp180(int32_t *ut, int32_t *up, float *temp, float *press) {
    if (read_raw_temperature(ut) < 0) return -1;
    if (read_raw_pressure(up) < 0) return -1;
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *temp = ((b5 + 8) >> 4) / 10.0f;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *press = (float)(p + ((x1 + x2 + 3791) >> 4));
    return 0;
}

static void log_data(float temp, float press) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, press);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Log open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Logging started. Press Ctrl+C to exit.\n");
    while (running) {
        int32_t ut, up;
        float temp, press;
        if (read_bmp180(&ut, &up, &temp, &press) == 0) {
            log_data(temp, press);
        } else {
            fprintf(stderr, "BMP180 read error\n");
        }
        gpioDelay(1000000);
    }
    printf("\nShutting down...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

