#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5

#define MAX31865_REG_TEMP 0x00
#define MAX31865_REG_FAULT 0x01
#define MAX31865_REG_CONFIG 0x02
#define MAX31865_REG_RTD_MSB 0x03
#define MAX31865_REG_RTD_LSB 0x04
#define MAX31865_REG_RTD_MSB2 0x05
#define MAX31865_REG_RTD_LSB2 0x06

#define MAX31865_CONFIG_RTD_3WIRE 0x0000
#define MAX31865_CONFIG_BIAS_EN 0x0001
#define MAX31865_CONFIG_RTD_3WIRE_BIAS_EN 0x0002

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int max31865_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = {reg, value};
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int max31865_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};
    if (spi_transfer(tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int max31865_init(void) {
    if (max31865_write_reg(MAX31865_REG_CONFIG, MAX31865_CONFIG_RTD_3WIRE_BIAS_EN) < 0) {
        fprintf(stderr, "Failed to enable RTD bias\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

static int max31865_read_temperature(float *temperature) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};

    tx[0] = MAX31865_REG_RTD_MSB;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = 0x00;
    tx[4] = 0x00;
    tx[5] = 0x00;
    tx[6] = 0x00;

    if (max31865_write_reg(MAX31865_REG_CONFIG, MAX31865_CONFIG_RTD_3WIRE_BIAS_EN) < 0) {
        fprintf(stderr, "Failed to set config register\n");
        return -1;
    }

    if (spi_transfer(tx, rx, 7) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint16_t rtd_msb = (rx[2] << 8) | rx[3];
    uint16_t rtd_lsb = (rx[4] << 8) | rx[5];
    uint16_t rtd_msb2 = (rx[6] << 8) | rx[7];

    if (rtd_msb & 0x0001) {
        fprintf(stderr, "RTD fault detected\n");
        return -1;
    }

    uint16_t rtd_value = (rtd_msb2 << 8) | rtd_lsb;
    float rtd_resistance = 100.0f * rtd_value;

    if (rtd_resistance <= 10.0f) {
        fprintf(stderr, "Invalid RTD resistance: %.2f ohms\n", rtd_resistance);
        return -1;
    }

    float rtd_alpha = 0.0039083f;
    float rtd_beta = 0.000000577f;
    float rtd_gamma = 0.0000000001f;
    float rtd_z = 0.0000000001f;

    float rtd_r = rtd_resistance;
    float rtd_rtd = rtd_resistance - 100.0f;
    float rtd_rtd_rtd = rtd_rtd * rtd_rtd;

    float temp = (rtd_alpha * rtd_rtd_rtd) / rtd_rtd - (rtd_beta * rtd_rtd) + rtd_gamma;

    *temperature = temp;
    return 0;
}

static void log_data(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "max31865-cs", 1) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return 1;
    }

    if (max31865_init() < 0) {
        fprintf(stderr, "MAX31865 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
        fflush(log_file);
    }

    printf("Starting MAX31865 temperature logging. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature;
        int ret = max31865_read_temperature(&temperature);

        if (ret == 0) {
            log_data(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

