#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bme280_init(int fd) {
    uint8_t chip_id;
    if (i2c_read_burst(fd, BME280_REG_ID, &chip_id, 1) < 0) return -1;
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_byte(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) return -1;
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_burst(fd, BME280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "BME280 reset timeout\n");
        return -1;
    }

    if (i2c_write_byte(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_byte(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read_raw(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    return i2c_read_burst(fd, reg, buf, len);
}

static int bme280_convert_data(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (bme280_read_raw(fd, BME280_REG_DATA, data, 8) < 0) return -1;

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    int32_t var1, var2, t_fine;
    var1 = ((((raw_temp >> 3) - ((int32_t)0x16)) * ((int32_t)0x16)) >> 15) * ((int32_t)0.02);
    var2 = (((((raw_temp >> 4) - ((int32_t)0x06)) * ((raw_temp >> 4) - ((int32_t)0x06))) >> 12) * ((int32_t)0.01));
    t_fine = var1 + var2;
    *temp = (float)((t_fine * 5 + 128) >> 8) / 100.0f;

    var1 = ((int32_t)t_fine) - 128000;
    var2 = var1 * var1 * (int32_t)0.0078;
    var2 = var2 + ((var1 * (int32_t)0.035) * 16384);
    var1 = ((var1 * var1 * (int32_t)0.0078) / 16384) * 0.00001;
    *hum = (float)(var1 + 0.5f);

    *press = (float)(raw_press * 10000.0f) / 65536.0f;
    return 0;
}

static int log_data(FILE *fp, float temp, float hum, float press) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temp, hum, press) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

