        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bme280_init(i2c_fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
        fflush(log_fp);
    }

    printf("Logging BME280 data to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temp, hum, press;
        if (bme280_convert_data(i2c_fd, &temp, &hum, &press) == 0) {
            if (log_data(log_fp, temp, hum, press) < 0) {
