#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define I2C_BUS 1
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define PRESSURE_THRESHOLD 5.0f
#define SAMPLE_INTERVAL_US 50000
#define BMP180_OSS 0

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_CAL_AC1 0x88
#define BMP180_CAL_AC2 0xAC
#define BMP180_CAL_AC3 0xAE
#define BMP180_CAL_AC4 0xB0
#define BMP180_CAL_AC5 0xB2
#define BMP180_CAL_AC6 0xB4
#define BMP180_CAL_B1 0xB6
#define BMP180_CAL_B2 0xB8
#define BMP180_CAL_MB 0xBA
#define BMP180_CAL_MC 0xBC
#define BMP180_CAL_MD 0xBE

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int timer_id = -1;
static float pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    int result;
    int16_t val;

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC1);
    if (result < 0) return -1;
    ac1 = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC1 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC2);
    if (result < 0) return -1;
    ac2 = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC2 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC3);
    if (result < 0) return -1;
    ac3 = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC3 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC4);
    if (result < 0) return -1;
    ac4 = (uint16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC4 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC5);
    if (result < 0) return -1;
    ac5 = (uint16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC5 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_AC6);
    if (result < 0) return -1;
    ac6 = (uint16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_AC6 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_B1);
    if (result < 0) return -1;
    b1 = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_B1 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_B2);
    if (result < 0) return -1;
    b2 = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_B2 + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_MB);
    if (result < 0) return -1;
    mb = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_MB + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_MC);
    if (result < 0) return -1;
    mc = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_MC + 1) & 0xFF));

    result = i2cReadByteData(i2c_handle, BMP180_CAL_MD);
    if (result < 0) return -1;
    md = (int16_t)((result << 8) | (i2cReadByteData(i2c_handle, BMP180_CAL_MD + 1) & 0xFF));

    return 0;
}

static int read_raw_temperature(int *raw_temp) {
    int result;
    char buf[2];

    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E);
    if (result < 0) return -1;
    gpioDelay(5000);

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2);
    if (result != 2) return -1;

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_pressure(int *raw_pressure) {
    int result;
    char buf[3];

    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));
    if (result < 0) return -1;
    gpioDelay(5000 + (3000 << BMP180_OSS));

    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3);
    if (result != 3) return -1;

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static float calculate_pressure(int raw_pressure, int raw_temperature) {
    long x1 = ((long)raw_temperature - (long)ac6) * (long)ac5 >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6 >> 12)) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    long b4 = ((x1 + x2 + 32768) >> 15) * (long)ac4 >> 15;
    long b7 = ((long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    long p;
    if (b7 < 0) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0f;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int raw_pressure, raw_temperature;

    if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        return;
    }
    if (read_raw_temperature(&raw_temperature) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        return;
    }

    float pressure = calculate_pressure(raw_pressure, raw_temperature);
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i];
    float average_pressure = sum / buffer_count;

    if (buffer_count == BUFFER_SIZE) {
        if (average_pressure > average_pressure + PRESSURE_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1);
            gpioDelay(1000000);
            gpioWrite(ALERT_GPIO, 0);
        }
    }
}

static void cleanup(void) {
    if (timer_id >= 0) {
        gpioSetTimerFuncEx(timer_id, 0, NULL, NULL);
        gpioSetTimerFuncEx(timer_id, 0, NULL, NULL);
        timer_id = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        cleanup();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    timer_id = gpioSetTimerFuncEx(0, 50, timer_callback, NULL);
    if (timer_id < 0) {
        fprintf(stderr, "Error setting up timer\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

