static int bmp280_init(int fd, const char *addr) {
    uint8_t chip_id;
    if (i2c_read_reg8(fd, BMP280_REG_CHIP_ID, &chip_id) < 0) {
        fprintf(stderr, "Error: failed to read chip ID from 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip ID 0x%02X does not match expected 0x%02X\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    uint8_t calib[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, calib, 24) < 0) {
        fprintf(stderr, "Error: failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    bmp280_calib_t cal;
    cal.dig_T1 = (uint16_t)(calib[0]  | (calib[1]  << 8));
    cal.dig_T2 = (int16_t)(calib[2]  | (calib[3]  << 8));
    cal.dig_T3 = (int16_t)(calib[4]  | (calib[5]  << 8));
    cal.dig_P1 = (uint16_t)(calib[6]  | (calib[7]  << 8));
    cal.dig_P2 = (int16_t)(calib[8]  | (calib[9]  << 8));
    cal.dig_P3 = (int16_t)(calib[10] | (calib[11] << 8));
    cal.dig_P4 = (int16_t)(calib[12] | (calib[13] << 8));
    cal.dig_P5 = (int16_t)(calib[14] | (calib[15] << 8));
    cal.dig_P6 = (int16_t)(calib[16] | (calib[17] << 8));
    cal.dig_P7 = (int16_t)(calib[18] | (calib[19] << 8));
    cal.dig_P8 = (int16_t)(calib[20] | (calib[21] << 8));
    cal.dig_P9 = (int16_t)(calib[22] | (calib[23] << 8));
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (i2c_read_reg8(fd, BMP280_REG_STATUS, &status) < 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(1000);
    }
    if (status & 0x08) {
        fprintf(stderr, "Error: measurement timeout\n");
        return -1;
    }
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    int32_t var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    int32_t var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double compensate_pressure(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal) {
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0.0;
    int64_t p = 1048576 - raw_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (double)p / 256.0;
}

static int log_data(double temp, double press) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", ts, temp, press) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    int addr = BMP280_ADDR_DEFAULT;
    int found = 0;
    for (int i = 0; i < 2; i++) {
        if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
            addr = BMP280_ADDR_FALLBACK;
            if (ioctl(g_i2c_fd, I2C_SLAVE, addr) < 0) {
                fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", addr, strerror(errno));
                addr = BMP280_ADDR_FALLBACK;
                continue;
            }
            addr = BMP280_ADDR_DEFAULT;
            found = 1;
        }
    }
    if (!found) {
        fprintf(stderr, "Error: no BMP280 found at 0x%02X or 0x%02X\n", BMP280_ADDR_DEFAULT, BMP280_ADDR_FALLBACK);
        close(g_i2c_fd);
        return 1;
    }
    if (bmp280_init(g_i2c_fd, BMP280_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Error: BMP280 init failed\n");
        close(g_i2c_fd);
        return 1;
    }
    printf("BMP280 initialized at 0x%02X\n", BMP280_ADDR_DEFAULT);
    while (g_running) {
        int32_t raw_t, raw_p, t_fine;
        if (bmp280_read_raw(g_i2c_fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Warning: read failed, retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }
        double temp = compensate_temperature(raw_t, (bmp280_calib_t){0}, &t_fine) / 100.0;
        double press = compensate_pressure(raw_p, t_fine, (bmp280_calib_t){0});
        if (log_data(temp, press) < 0) {
            fprintf(stderr, "Warning: log write failed\n");
        }
        printf("T: %.2f °C, P: %.2f hPa\n", temp, press);
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }
    printf("\nExiting cleanly.\n");
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

