#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDR 0x48
#define LM75_TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static float running_average = 0.0f;
static pthread_t data_thread;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float read_temperature(int fd) {
    int16_t raw;
    if (i2c_read_reg16(fd, LM75_TEMP_REG, &raw) < 0) {
        return -1000.0f;
    }
    return (float)raw / 256.0f;
}

static void *data_thread_func(void *arg) {
    (void)arg;
    while (running) {
        float temp = read_temperature(i2c_fd);
        if (temp < -900.0f) {
            fprintf(stderr, "Sensor read error, attempting re-initialization...\n");
            pthread_mutex_lock(&buffer_mutex);
            buffer_count = 0;
            buffer_index = 0;
            running_average = 0.0f;
            pthread_mutex_unlock(&buffer_mutex);
            if (i2c_fd >= 0) {
                close(i2c_fd);
                i2c_fd = -1;
            }
            i2c_fd = i2c_init();
            if (i2c_fd < 0) {
                fprintf(stderr, "Re-initialization failed, retrying in 1s...\n");
                sleep(1);
                continue;
            }
        } else {
            pthread_mutex_lock(&buffer_mutex);
            temperature_buffer[buffer_index] = temp;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;
            running_average = 0.0f;
            for (int i = 0; i < buffer_count; i++) {
                running_average += temperature_buffer[i];
            }
            running_average /= (float)buffer_count;
            pthread_mutex_unlock(&buffer_mutex);
        }
        sleep(POLL_INTERVAL_SEC);
    }
    return NULL;
}

static void control_led(float avg_temp) {
    int val = (avg_temp > TEMP_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(led_line, val) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (pthread_create(&data_thread, NULL, data_thread_func, NULL) != 0) {
        fprintf(stderr, "Error creating data thread: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        sleep(1);
    }

    pthread_mutex_lock(&buffer_mutex);
    buffer_count = 0;
    buffer_index = 0;
    running_average = 0.0f;
    pthread_mutex_unlock(&buffer_mutex);

    pthread_join(data_thread, NULL);

    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0f;
    }
    pthread_mutex_unlock(&buffer_mutex);

    gpiod_line_set_value(led_line, 0);
    close(i2c_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

