#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

/* BMP180 registers */
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_AC1 0xAA

/* Control commands */
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE 0x34

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (i2c_read_reg(fd, reg, buf, 2) < 0) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg16u(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (i2c_read_reg(fd, reg, buf, 2) < 0) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp180_read_calibration(int fd, bmp180_cal_t *cal) {
    if (i2c_read_reg16(fd, BMP180_REG_CAL_AC1, &cal->ac1) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAC, &cal->ac2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xAE, &cal->ac3) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB0, &cal->ac4) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB2, &cal->ac5) < 0) return -1;
    if (i2c_read_reg16u(fd, 0xB4, &cal->ac6) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB6, &cal->b1) < 0) return -1;
    if (i2c_read_reg16(fd, 0xB8, &cal->b2) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBA, &cal->mb) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBC, &cal->mc) < 0) return -1;
    if (i2c_read_reg16(fd, 0xBE, &cal->md) < 0) return -1;
    return 0;
}

static int bmp180_read_raw_temp(int fd, int32_t *raw) {
    for (int i = 0; i < MAX_RETRIES; i++) {
