#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_US 500000

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CALIB 0xAA
#define BMP180_CALIB_LEN 22

#define BMP180_OSS 0

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;
static double temperature_buffer[BUFFER_SIZE];
static double pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[BMP180_CALIB_LEN];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CALIB, (char *)buf, BMP180_CALIB_LEN) != BMP180_CALIB_LEN) {
        fprintf(stderr, "Error: failed to read BMP180 calibration block\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc = (int16_t)((buf[18] << 8) | buf[19]);
    c->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int oss, int32_t *up) {
    uint8_t cmd = 0x34 + (oss << 6);
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(5000 + (3000 << oss));
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - oss);
    return 0;
}

static double calculate_temperature(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int oss, const bmp180_cal_t *c, double temp) {
    int32_t b5 = (int32_t)(temp - 0.5);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << OSS) + 2) >> 2);
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up;
    if (read_raw_temperature(i2c_handle, &ut) != 0) return;
    if (read_raw_pressure(i2c_handle, BMP180_OSS, &up) != 0) return;
    double temp = calculate_temperature(ut, &cal);
    double pres = calculate_pressure(up, BMP180_OSS, &cal, temp);
    temperature_buffer[buffer_index] = temp;
    pressure_buffer[buffer_index] = pres;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, pres);
}

static void fan_on(void) {
    gpioWrite(FAN_GPIO, 1);
}

static void fan_off(void) {
    gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    fan_off();
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    fan_off();
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

