}

static void fan_on(void) {
    gpioWrite(FAN_GPIO, 1);
}

static void fan_off(void) {
    gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
