#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "heater_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);
    return 0;
}

static int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_max31855(float *temperature) {
    char rx[4] = {0};
    int ret = spiRead(spi_handle, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI read failed: %d\n", ret);
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: %d\n", raw & 0x00010000);
        return -1;
    }
    *temperature = (float)((raw >> 18) & 0x7FFF) / 100.0f;
    return 0;
}

static int calculate_duty_cycle(float current_temp, float target_temp) {
    float error = target_temp - current_temp;
    float integral = 0.0f;
    float kp = 1.0f;
    float ki = 0.1f;
    float dt = (float)SAMPLE_INTERVAL_US / 1000000.0f;
    float duty = kp * error + ki * integral;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > (float)PWM_RANGE) duty = (float)PWM_RANGE;
    integral += error * dt;
    return (int)(duty + 0.5f);
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Temperature(C),DutyCycle\n");
    fflush(log_file);

    float current_temp = 0.0f;
    int duty_cycle = 0;
    int consecutive_errors = 0;

    while (running) {
        if (read_max31855(&current_temp) == 0) {
            consecutive_errors = 0;
            duty_cycle = calculate_duty_cycle(current_temp, TARGET_TEMP);
            gpioPWM(HEATER_GPIO, (int)duty_cycle);
            log_data(current_temp, duty_cycle);
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive SPI errors, resetting heater\n");
                gpioPWM(HEATER_GPIO, 0);
                log_data(0.0f, 0);
                consecutive_errors = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
