#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define TEMP_FILE  "/sys/class/thermal/thermal_zone0/temp"
#define POLL_US    500000   /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius from the sysfs file.
 * Returns 0 on success, -1 on error (value set to -1 on error).
 */
static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    *temp_out = temp;
    return 0;
}

/*
 * Map temperature (m°C) to RGB values for a common-anode LED.
 * Below 40000 m°C -> solid Blue (R=0,G=0,B=255)
 * 40000-59999 m°C -> solid Green (R=0,G=255,B=0)
 * 60000 m°C and above -> solid Red (R=255,G=0,B=0)
 */
static void set_led_color(int red, int green, int blue)
{
    /* Common-anode: fully on (0) = channel fully on, fully off (255) = channel fully off */
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n", strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as hardware PWM outputs */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 (0-255) for common-anode LED */
    if (gpioSetPWMrange(RED_PIN, 255) != 0 ||
        gpioSetPWMrange(GREEN_PIN, 255) != 0 ||
        gpioSetPWMrange(BLUE_PIN, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start (common-anode: duty 255 = off) */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    printf("Mood light started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int temp;
        if (read_cpu_temp(&temp) != 0) {
            /* Skip this cycle rather than using a bogus value */
            gpioDelay(POLL_US);
            continue;
        }

        int red, green, blue;
        if (temp < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temp < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        set_led_color(red, green, blue);
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
               temp, red, green, blue);
        fflush(stdout);

        gpioDelay(POLL_US);
    }

    /* Clean shutdown: turn off all channels (duty 255 = off) */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    gpioTerminate();
    printf("\nMood light stopped.\n");
    return EXIT_SUCCESS;
}

