#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int i;

    if (gpioSetMode(DHT22_GPIO, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_GPIO, 0) < 0) return -1;
    gpioDelay(2000);

    if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) return -1;
    gpioDelay(30);

    for (i = 0; i < 85; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 1 && count < 100) {
            gpioDelay(1);
            count++;
        }
        if (count == 0) return -2;
        count = 0;
        while (gpioRead(DHT22_GPIO) == 0 && count < 100) {
            gpioDelay(1);
            count++;
        }
        if (count == 0) return -2;
        count = 0;
        while (gpioRead(DHT22_GPIO) == 1 && count < 100) {
            gpioDelay(1);
            count++;
        }
        if (count == 0) return -2;
        data[bit_idx / 8] <<= 1;
        if (count > 1) data[bit_idx / 8] |= 1;
        bit_idx++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) *temperature = -*temperature;
    return 0;
}

static size_t write_cb(char *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

static int send_post_request(float temperature, float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    char json[128];
    snprintf(json, sizeof(json), "{\"temperature\":%.2f,\"humidity\":%.2f}", temperature, humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) { curl_easy_cleanup(curl); return -1; }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_cb);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    if (res != CURLE_OK) return -2;
    if (http_code != 200) return -3;

    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    float temperature, humidity;
    int retries = 0;

    while (running) {
        int ret = read_dht22(&temperature, &humidity);
        if (ret == 0) {
            retries = 0;
            if (send_post_request(temperature, humidity) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Failed to send POST request\n");
            }
        } else {
            fprintf(stderr, "DHT22 read failed (code %d), retrying...\n", ret);
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            sleep(READ_INTERVAL_SEC);
        }
    }

    gpioTerminate();
    return 0;
}

