#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

#define BUTTON_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000
#define DEBOUNCE_US 200000

static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_button_tick = 0;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    logging_enabled = 0;
    gpioWrite(BUTTON_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

static int read_calibration_data(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read BMP180 calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    if (ac1 == 0 || ac6 == 0) {
        fprintf(stderr, "Error: Invalid calibration data (zero or NaN)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read temperature data\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    uint8_t cmd = 0x34 + (3 << 6);
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to write pressure command\n");
        return -1;
    }
    gpioDelay(26000);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read pressure data\n");
        return -1;
    }
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - 3);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << 3) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f hPa\n", ts, pressure);
    fclose(fp);
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0) {
        uint32_t diff = tick - last_button_tick;
        if (diff > DEBOUNCE_US) {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
            last_button_tick = tick;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL);
    signal(SIGINT, signal_handler);
    printf("BMP180 pressure logger started. Press button on GPIO4 to toggle logging.\n");
    while (1) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                int32_t b5 = compute_b5(ut);
                int32_t pressure = compute_pressure(up, b5);
                float hPa = pressure / 100.0f;
                log_pressure(hPa);
            } else {
                fprintf(stderr, "Error: Failed to read sensor data\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    return 0;
}

