#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define MAX_DELAY_MS 2000
#define READ_INTERVAL_S 10
#define DHT_TIMEOUT_US 1000

typedef struct {
    char server_url[256];
    int server_port;
    int server_protocol;
} ServerConfig;

static volatile sig_atomic_t running = 1;
static ServerConfig server_config = { "http://your-server.com/api/humidity", 80, "http" };

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int last_state = PI_HIGH;
    int timeout = 0;

    if (gpioSetMode(DHT22_PIN, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(DHT22_PIN, PI_LOW) < 0) return -1;
    gpioDelay(2000);
    if (gpioWrite(DHT22_PIN, PI_HIGH) < 0) return -1;
    gpioDelay(30);
    if (gpioWrite(DHT22_PIN, PI_LOW) < 0) return -1;
    gpioDelay(180);

    if (gpioSetMode(DHT22_PIN, PI_INPUT) < 0) return -1;

    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (++timeout > DHT_TIMEOUT_US) return -2;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_PIN) == PI_LOW) {
        if (++timeout > DHT_TIMEOUT_US) return -2;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (++timeout > DHT_TIMEOUT_US) return -2;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_PIN) == PI_LOW) {
        if (++timeout > DHT_TIMEOUT_US) return -2;
        gpioDelay(1);
    }
    timeout = 0;
    while (gpioRead(DHT22_PIN) == PI_HIGH) {
        if (++timeout > DHT_TIMEOUT_US) return -2;
        gpioDelay(1);
    }

    for (int i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_PIN) == last_state) {
            if (++timeout > DHT_TIMEOUT_US) return -2;
            gpioDelay(1);
        }
        last_state = gpioRead(DHT22_PIN);
        if (timeout > 50) return -2;
        if (i % 2 == 0) {
            data[bit_idx / 8] <<= 1;
            if (gpioRead(DHT22_PIN) == PI_LOW) data[bit_idx / 8] |= 1;
        }
        bit_idx++;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) return -1;

    char json[256];
    int len = snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);
    if (len < 0 || len >= (int)sizeof(json)) return -1;

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) { curl_easy_cleanup(curl); return -1; }

    curl_easy_setopt(curl, CURLOPT_URL, server_config.server_url);
    curl_easy_setopt(curl, CURLOPT_PORT, server_config.server_port);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        return -2;
    }
    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "HTTP POST returned status code: %ld", http_code);
        return -2;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:p:")) != -1) {
        switch (opt) {
            case 's': strncpy(server_config.server_url, optarg, sizeof(server_config.server_url) - 1); server_config.server_url[sizeof(server_config.server_url) - 1] = '\0'; break;
            case 'p': server_config.server_port = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url] [-p server_port]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 humidity monitor (server: %s:%d)", server_config.server_url, server_config.server_port);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    float humidity;
    int consecutive_failures = 0;

    while (running) {
        int ret = read_dht22(&humidity);
        if (ret == 0) {
            consecutive_failures = 0;
            if (post_humidity(humidity) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%, POST successful", humidity);
            } else {
                syslog(LOG_ERR, "Failed to POST humidity data");
            }
        } else {
            consecutive_failures++;
            syslog(LOG_ERR, "DHT22 read failed (code %d)", ret);
            if (consecutive_failures >= MAX_RETRIES) {
                syslog(LOG_ERR, "Max retries reached, skipping this cycle");
                consecutive_failures = 0;
            } else {
                syslog(LOG_WARNING, "Retrying in %d seconds...", MAX_DELAY_MS);
                gpioDelay(MAX_DELAY_MS * 1000);
            }
        }

        for (int i = 0; i < READ_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioTerminate();
    curl_global_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

