/*
 * Raspberry Pi 5 Active Cooler Fan Controller
 * Uses the sysfs thermal framework (no third-party GPIO library).
 *
 * Build: gcc -O2 -Wall -o fan_control fan_control.c
 * Run:   sudo ./fan_control
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_SPEED_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

/* Tiered fan speed map */
#define FAN_SPEED_OFF 0
#define FAN_SPEED_LOW 1
#define FAN_SPEED_MED 2
#define FAN_SPEED_HIGH 3

/* Temperature thresholds (°C) */
#define TEMP_LOW  45.0f
#define TEMP_MED  55.0f
#define TEMP_HIGH 65.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU temperature in millidegrees Celsius. Returns -1 on error. */
static int read_cpu_temp(void)
{
    int fd = open(CPU_TEMP_PATH, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }

    char buf[32];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    int saved_errno = errno;
    close(fd);

    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", CPU_TEMP_PATH, strerror(saved_errno));
        return -1;
    }
    buf[n] = '\0';

    char *endptr;
    long millideg = strtol(buf, &endptr, 10);
    if (endptr == buf || millideg < 0) {
        fprintf(stderr, "Invalid temperature value: %s\n", buf);
        return -1;
    }
    return (int)millideg;
}

/* Write fan speed to sysfs. Returns 0 on success, -1 on error. */
static int write_fan_speed(int speed)
{
    if (speed < 0 || speed > 3) {
        fprintf(stderr, "Invalid fan speed: %d (must be 0-3)\n", speed);
        return -1;
    }

    char path[128];
    snprintf(path, sizeof(path), "%s", FAN_SPEED_PATH);

    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", path, strerror(errno));
        return -1;
    }

    char val[4];
    snprintf(val, sizeof(val), "%d", speed);
    ssize_t n = write(fd, val, strlen(val));
    int saved_errno = errno;
    close(fd);

    if (n < 0) {
        fprintf(stderr, "write(%s): %s\n", path, strerror(saved_errno));
        return -1;
    }
    return 0;
}

/* Log a fan speed change with timestamp. */
static void log_fan_speed_change(int speed)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] Fan speed changed to %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, speed);
    } else {
        fprintf(fp, "[timestamp error] Fan speed changed to %d\n", speed);
    }
    fclose(fp);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Determine the cooling device path (thermal_zone0 or cooling_device0) */
    char cooling_device_path[128];
    snprintf(cooling_device_path, sizeof(cooling_device_path),
             "/sys/class/thermal/cooling_device0");

    struct stat st;
    if (stat(cooling_device_path, &st) == 0) {
        /* cooling_device0 exists; use it */
        printf("Using cooling device path: %s\n", cooling_device_path);
    } else if (stat(CPU_TEMP_PATH, &st) == 0) {
        /* thermal_zone0 exists; use it */
        printf("Using CPU temperature path: %s\n", CPU_TEMP_PATH);
    } else {
        fprintf(stderr, "Neither cooling_device0 nor thermal_zone0 found. "
                        "Ensure the Active Cooler is enabled and the "
                        "Raspberry Pi 5 is booted.\n");
        return EXIT_FAILURE;
    }

    /* Read and validate the cooling device's max_state */
    int max_state = -1;
    int fd = open(cooling_device_path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", cooling_device_path, strerror(errno));
        return EXIT_FAILURE;
    }

    char buf[16];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    int saved_errno = errno;
    close(fd);

    if (n < 0) {
        fprintf(stderr, "read(%s): %s\n", cooling_device_path, strerror(saved_errno));
        return EXIT_FAILURE;
    }
    buf[n] = '\0';

    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf || val < 0 || val > 3) {
        fprintf(stderr, "Invalid max_state value: %s\n", buf);
        return EXIT_FAILURE;
    }
    max_state = (int)val;
    printf("Cooling device max_state: %d\n", max_state);

    int current_speed = -1;
    int last_speed = -1;

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d s.\n",
                    POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int desired_speed;
        if (temp < TEMP_LOW) {
            desired_speed = FAN_SPEED_OFF;
        } else if (temp < TEMP_MED) {
            desired_speed = FAN_SPEED_LOW;
        } else if (temp < TEMP_HIGH) {
            desired_speed = FAN_SPEED_MED;
        } else {
            desired_speed = FAN_SPEED_HIGH;
        }

        if (desired_speed != current_speed) {
            if (write_fan_speed(desired_speed) == 0) {
                current_speed = desired_speed;
                last_speed = desired_speed;
                log_fan_speed_change(desired_speed);
            } else {
                fprintf(stderr, "Failed to write fan speed. Retrying in %d s.\n",
                        POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Graceful shutdown: stop the fan and log the shutdown */
    printf("\nShutting down...\n");
    if (write_fan_speed(FAN_SPEED_OFF) != 0) {
        fprintf(stderr, "Failed to stop fan during shutdown.\n");
    }
    log_fan_speed_change(FAN_SPEED_OFF);
    printf("Fan stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

