#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define TARGET_TEMP 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define SAMPLE_INTERVAL 1.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    double kp, ki, kd;
    double target;
    double integral, previous_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

static void log_data(double temp, double pwm, double pid_out) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] Temp=%.2fC, PWM=%.1f, PID=%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, pwm, pid_out);
    fflush(log_file);
}

static int read_max31855(double *temp) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        log_message("SPI transfer failed");
        return -1;
    }
    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);
    if (raw & 0x00010000) {
        if (raw & 0x00000004) log_message("Fault: Open circuit");
        else if (raw & 0x00000002) log_message("Fault: Short to GND");
        else if (raw & 0x00000001) log_message("Fault: Short to VCC");
        else log_message("Unknown fault");
        return -1;
    }
    *temp = (double)((raw >> 18) & 0x3FFF) / 100.0;
    return 0;
}

static double pid_control(PIDController *pid, double setpoint, double actual) {
    double error = setpoint - actual;
    pid->integral += error;
    double derivative = error - pid->previous_error;
    double output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static void set_heater(double duty) {
    if (gpioPWM(HEATER_GPIO, (int)duty) < 0) {
        log_message("gpioPWM failed");
    }
}

static void cleanup(void) {
    set_heater(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }
    log_message("Program started");

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_message("SPI open failed");
        cleanup();
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    set_heater(0);

    PIDController pid = {KP, KI, KD, TARGET_TEMP, 0.0, 0.0};
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

