#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define MIN_DUTY 0
#define MAX_DUTY 100
#define POLL_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int calculate_duty_cycle(int temp_milli) {
    if (temp_milli <= MIN_TEMP) {
        return MIN_DUTY;
    }
    if (temp_milli >= MAX_TEMP) {
        return MAX_DUTY;
    }
    return MIN_DUTY + (int)(((float)(temp_milli - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * (MAX_DUTY - MIN_DUTY));
}

static int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

static int log_data(int temp_milli, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, temp_milli, duty_cycle);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (set_fan_speed(0) != 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading temperature, retrying...\n");
            sleep(POLL_INTERVAL);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temp_milli);
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed\n");
        }

        if (log_data(temp_milli, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(POLL_INTERVAL);
    }

    set_fan_speed(0);
    gpioTerminate();
    return 0;
}

