/*
 * TMAG5110A1 Dual Hall-Effect Rotary Encoder Monitor
 * Board: Raspberry Pi 4 Model B
 * Library: pigpio
 *
 * Wiring:
 *   Sensor A Channel A  -> GPIO17 (BCM)
 *   Sensor B Channel A  -> GPIO18 (BCM)
 *   Sensor A Channel B  -> GPIO17 (BCM)
 *   Sensor B Channel B  -> GPIO18 (BCM)
 *
 * The TMAG5110A1 has an open-drain output.  We enable internal pull-ups
 * so the pin reads HIGH when the sensor is energized and LOW when it
 * is de-energized.
 *
 * Build: gcc -Wall -Wextra -O2 -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:   sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18

#define PULSES_PER_REVOLUTION 360.0
#define LOG_FILE "encoder_log.txt"

/* Quadrature state machine: 0 = A LOW, 1 = A HIGH, 2 = B LOW, 3 = B HIGH */
typedef enum {
    STATE_A_LOW = 0,
    STATE_A_HIGH = 1,
    STATE_B_LOW = 2,
    STATE_B_HIGH = 3
} EncoderState;

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_data(EncoderState state, double angle)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, State: %d, Angle: %.2f\n",
                timestamp, (int)state, angle);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    EncoderState state = STATE_A_LOW;
    double angle = 0.0;
    int last_a = gpioRead(SENSOR_A_PIN);
    int last_b = gpioRead(SENSOR_B_PIN);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-up resistors so the pin reads HIGH when the
     * sensor is energized and LOW when it is de-energized. */
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", SENSOR_A_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d.\n", SENSOR_B_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Read initial states so we can detect a power-on glitch. */
    last_a = gpioRead(SENSOR_A_PIN);
    last_b = gpioRead(SENSOR_B_PIN);

    if (last_a < 0 || last_b < 0) {
        fprintf(stderr, "Error: Failed to read initial GPIO states.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGINT handler.\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Could not register SIGTERM handler.\n");
    }

    printf("Monitoring TMAG5110A1 encoder on GPIO%d and GPIO%d. "
           "Press Ctrl+C to exit.\n", SENSOR_A_PIN, SENSOR_B_PIN);

    while (g_running) {
        int a = gpioRead(SENSOR_A_PIN);
        int b = gpioRead(SENSOR_B_PIN);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error: GPIO read failure (A=%d, B=%d).\n", a, b);
            break;
        }

        /* Detect state transitions. */
        if (a != last_a) {
            if (a == 1) {
                state = STATE_A_HIGH;
            } else {
                state = STATE_A_LOW;
            }
            angle += (state == STATE_A_HIGH) ? 1.0 : -1.0;
            if (angle >= PULSES_PER_REVOLUTION) {
                angle -= PULSES_PER_REVOLUTION;
            }
            log_data(state, angle);
        }

        if (b != last_b) {
            if (b == 1) {
                state = STATE_B_HIGH;
            } else {
                state = STATE_B_LOW;
            }
            angle += (state == STATE_B_HIGH) ? 1.0 : -1.0;
            if (angle >= PULSES_PER_REVOLUTION) {
                angle -= PULSES_PER_REVOLUTION;
            }
            log_data(state, angle);
        }

        last_a = a;
        last_b = b;

        gpioDelay(1000); /* 1 ms delay to reduce CPU usage */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

