#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define AUDIO_INPUT_PIN 17
#define GAIN_CONTROL_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_INTERVAL_MS 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *fp, int level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *audio_line = NULL;
    struct gpiod_line *gain_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name(%s) failed: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    audio_line = gpiod_chip_get_line(chip, AUDIO_INPUT_PIN);
    if (audio_line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n", AUDIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_CONTROL_PIN);
    if (gain_line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n", GAIN_CONTROL_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(audio_line, "audio_monitor") < 0) {
        fprintf(stderr, "Error: gpiod_line_request_input(%d) failed: %s\n", AUDIO_INPUT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(gain_line, "audio_monitor", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output(%d) failed: %s\n", GAIN_CONTROL_PIN, strerror(errno));
        goto cleanup;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int last_state = 0;
    int first_read = 1;

    while (program_running) {
        int current_state = gpiod_line_get_value(audio_line);
        if (current_state < 0) {
            fprintf(stderr, "Error: gpiod_line_get_value(%d) failed: %s\n", AUDIO_INPUT_PIN, strerror(errno));
            goto cleanup;
        }

        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else {
            if (current_state == 1 && last_state == 0) {
                if (log_event(log_fp, 1) == 0) {
                    printf("Peak detected!\n");
                } else {
                    fprintf(stderr, "Error: Failed to log peak event.\n");
                }
            }
            last_state = current_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nAudio monitoring stopped.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    if (gain_line != NULL) {
        gpiod_line_release(gain_line);
    }
    if (audio_line != NULL) {
        gpiod_line_release(audio_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

