#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_CMD_MSB 0x36
#define FLOW_CMD_LSB 0x08
#define FLOW_READ_LEN 3
#define SAMPLE_INTERVAL_US 1000000
#define LOG_FILE "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    uint8_t cmd[2] = {FLOW_CMD_MSB, FLOW_CMD_LSB};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to write start measurement command to sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buf[FLOW_READ_LEN];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buf, FLOW_READ_LEN);
    if (bytes_read != FLOW_READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes, got %d).\n", FLOW_READ_LEN, bytes_read);
        return -1;
    }

    uint16_t raw_flow = ((uint16_t)buf[0] << 8) | buf[1];
    uint8_t crc = sensirion_crc8(buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch (calc=0x%02X, recv=0x%02X).\n", crc, buf[2]);
        return -1;
    }

    *flow_rate = (float)raw_flow / 1000.0f;
    return 0;
}

static void log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return;
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d addr 0x%02X (err=%d).\n", I2C_BUS, SLF3S_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Flow monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            log_flow_rate(flow_rate);
            printf("Flow rate: %.2f uL/min\n", flow_rate);
        } else {
            fprintf(stderr, "Warning: Skipping reading due to sensor error.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

