#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5

#define TVOC_REG 0x00
#define ECO2_REG 0x05

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(int handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(handle, TVOC_REG, (char *)data, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

static int calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    int iaq = 100 - (int)((tvoc / 10.0) + ((eco2 - 400) / 50.0));
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;
    return iaq;
}

static int log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d,%u,%u\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,ECO2\n");
        fflush(log_file);
    }

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t data[7];
        if (read_sensor_data(i2c_handle, data) != 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        uint16_t tvoc = (data[1] << 8) | data[2];
        uint16_t eco2 = (data[5] << 8) | data[6];

        int iaq = calculate_iaq(tvoc, eco2);

        if (log_data(log_file, iaq, tvoc, eco2) != 0) {
            fprintf(stderr, "Logging error, continuing...\n");
        }

        printf("IAQ: %d, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc, eco2);

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

