#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define FILENAME "audio_capture.pcm"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_pcm_data(int fd, const uint8_t *data, int num_samples) {
    size_t total_bytes = num_samples * sizeof(uint8_t);
    size_t written = 0;
    while (written < total_bytes) {
        ssize_t n = write(fd, data + written, total_bytes - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        written += (size_t)n;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "inmp441_lr", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int fd = open("/dev/snd/pcmC0D0c", O_RDWR);
    if (fd < 0) {
        perror("open /dev/snd/pcmC0D0c");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct snd_pcm_hw_params_t *hw_params = NULL;
    struct snd_pcm_hw_params_t *params = NULL;
    int err = snd_pcm_open(&params, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        perror("snd_pcm_open");
        goto cleanup;
    }

    err = snd_pcm_hw_params_alloca(&hw_params);
    if (err < 0) {
        perror("snd_pcm_hw_params_alloca");
        goto cleanup;
    }

    err = snd_pcm_hw_params_any(params, hw_params);
    if (err < 0) {
        perror("snd_pcm_hw_params_any");
        goto cleanup;
    }

    err = snd_pcm_hw_params_set_access(params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        perror("snd_pcm_hw_params_set_access");
        goto cleanup;
    }

    err = snd_pcm_hw_params_set_format(params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        perror("snd_pcm_hw_params_set_format");
        goto cleanup;
    }

    err = snd_pcm_hw_params_set_channels(params, NUM_CHANNELS);
    if (err < 0) {
        perror("snd_pcm_hw_params_set_channels");
        goto cleanup;
    }

    err = snd_pcm_hw_params_set_rate_near(params, &hw_params->rate, NULL, 0);
    if (err < 0) {
        perror("snd_pcm_hw_params_set_rate_near");
        goto cleanup;
    }

    err = snd_pcm_hw_params(params, hw_params);
    if (err < 0) {
        perror("snd_pcm_hw_params");
        goto cleanup;
    }

    if (snd_pcm_prepare(params) < 0) {
        perror("snd_pcm_prepare");
        goto cleanup;
    }

    int file_fd = open(FILENAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        perror("open file");
        goto cleanup;
    }

    uint8_t *pcm_data = malloc(SAMPLE_RATE * NUM_CHANNELS * sizeof(uint8_t));
    if (!pcm_data) {
        perror("malloc");
        close(file_fd);
        goto cleanup;
    }

    while (running) {
        uint8_t *buffer = malloc(SAMPLE_RATE * NUM_CHANNELS * sizeof(uint8_t));
        if (!buffer) {
            perror("malloc");
            break;
        }

        int bytes_to_read = SAMPLE_RATE * NUM_CHANNELS;
        int bytes_read = snd_pcm_readi(params, buffer, bytes_to_read);
        if (bytes_read < 0) {
            if (errno == EINTR) continue;
            perror("snd_pcm_readi");
            break;
        }
        if (bytes_read == 0) {
            fprintf(stderr, "snd_pcm_readi returned 0 (end of stream)\n");
            break;
        }

        for (int i = 0; i < bytes_read; i++) {
            int32_t raw = (int32_t)buffer[i];
            // INMP441 outputs 24-bit data left-justified in a 32-bit frame.
            // Extract the 24-bit data and right-shift to produce 16-bit PCM.
            raw = raw >> 8;
            pcm_data[i * NUM_CHANNELS + i % NUM_CHANNELS] = (uint8_t)raw;
        }

        if (write_pcm_data(file_fd, pcm_data, bytes_read) < 0) {
            perror("write_pcm_data");
            break;
        }

        free(buffer);
    }

    free(pcm_data);
    close(file_fd);
    snd_pcm_drain(params);
    snd_pcm_close(&params);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

cleanup:
    if (params) snd_pcm_close(&params);
    if (fd >= 0) close(fd);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

