#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 255
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set fan pin mode.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize fan PWM to 0.\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        log_event("System shutting down.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioPWM(FAN_PIN, 0);
    gpioWrite(FLAME_SENSOR_PIN, 1);
    gpioTerminate();
}

static void control_fan(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    if (gpioPWM(FAN_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Warning: failed to set PWM duty cycle.\n");
    }
}

static void log_flame_event(void) {
    log_event("Flame detected!");
}

static void log_flame_end_event(void) {
    log_event("Flame ended.");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        log_event("Fatal: GPIO initialization failed.");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    log_event("System started.");

    int last_state = 1;
    int flame_active = 0;
    uint32_t flame_start_tick = 0;
    uint32_t flame_end_tick = 0;
    int flame_detected = 0;

    while (running) {
        int current_state = gpioRead(FLAME_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: failed to read flame sensor pin.\n");
            break;
        }

        if (current_state == 0 && last_state == 1) {
            uint32_t now = gpioTick();
            if (flame_detected) {
                if (now - flame_end_tick > 100000) {
                    log_flame_end_event();
                    flame_active = 0;
                    control_fan(0);
                }
            } else {
                if (now - flame_start_tick > 100000) {
                    log_flame_event();
                    flame_active = 1;
                    control_fan(0);
                    flame_detected = 1;
                    flame_start_tick = now;
                }
            }
        }

        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (!flame_detected) {
                if (now - flame_start_tick > 100000) {
                    log_flame_end_event();
                    flame_active = 0;
                    control_fan(0);
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

