#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define DATA_SIZE 32768

#define MAGIC_NUMBER 0x544d4454
#define FRAME_HEADER_SIZE 40
#define FRAME_DATA_SIZE 32768

typedef struct {
    uint32_t magic_number;
    uint32_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} __attribute__((packed)) frame_header_t;

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, int len) {
    int status = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (status != len) {
        fprintf(stderr, "SPI transfer failed: expected %d bytes, got %d\n", len, status);
        return -1;
    }
    return 0;
}

static int write_frame_header(FILE *f, const frame_header_t *hdr) {
    uint8_t buf[FRAME_HEADER_SIZE];
    buf[0] = (uint8_t)(hdr->magic_number & 0xFF);
    buf[1] = (uint8_t)((hdr->magic_number >> 8) & 0xFF);
    buf[2] = (uint8_t)((hdr->magic_number >> 16) & 0xFF);
    buf[3] = (uint8_t)((hdr->magic_number >> 24) & 0xFF);
    memcpy(buf + 4, &hdr->timestamp, sizeof(hdr->timestamp));
    memcpy(buf + 16, &hdr->start_frequency, sizeof(hdr->start_frequency));
    memcpy(buf + 28, &hdr->end_frequency, sizeof(hdr->end_frequency));
    memcpy(buf + 40, &hdr->num_chirps, sizeof(hdr->num_chirps));
    memcpy(buf + 52, &hdr->num_samples, sizeof(hdr->num_samples));
    memcpy(buf + 64, &hdr->frame_period_ms, sizeof(hdr->frame_period_ms));
    if (fwrite(buf, 1, FRAME_HEADER_SIZE, f) != FRAME_HEADER_SIZE) {
        fprintf(stderr, "Failed to write frame header\n");
        return -1;
    }
    return 0;
}

static int read_frame_data(FILE *f, uint8_t *data, int len) {
    if (fwrite(data, 1, len, f) != len) {
        fprintf(stderr, "Failed to write frame data\n");
        return -1;
    }
    return 0;
}

static void log_frame(FILE *f, const uint8_t *data, int len) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(f, "%s.%09ld, Frame %d, Data: ", time_str, ts.tv_nsec, len);
    for (int i = 0; i < len; i++) {
        fprintf(f, "%02x ", data[i]);
    }
    fprintf(f, "\n");
    fflush(f);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP);

    log_file = fopen("radar_data.log", "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (write_frame_header(log_file, &frame_header_t {
        .magic_number = MAGIC_NUMBER,
        .timestamp = 0,
        .start_frequency = 77,
        .end_frequency = 79,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period_ms = 100
    }) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int ready = gpioRead(DATA_READY_PIN);
        if (ready < 0) {
            fprintf(stderr, "GPIO read error\n");
            break;
        }
        if (ready == 0) {
            continue;
        }

        uint8_t *data = malloc(DATA_SIZE);
        if (!data) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }

        if (spi_transfer(data, data, DATA_SIZE) != 0) {
            free(data);
            break;
        }

        frame_header_t hdr;
        hdr.magic_number = MAGIC_NUMBER;
        hdr.timestamp = 0;
        hdr.start_frequency = 77;
        hdr.end_frequency = 79;
        hdr.num_chirps = 64;
        hdr.num_samples = 256;
        hdr.frame_period_ms = 100;

        if (write_frame_header(log_file, &hdr) != 0) {
            free(data);
            break;
        }

        log_frame(log_file, data, DATA_SIZE);
        free(data);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

