/*
 * flame_detect.c - SainSmart IR Flame Detection Sensor Module reader
 * Board:  Raspberry Pi 3 Model B+
 * API:    libgpiod v2.x (gpiod_line_config, gpiod_line_settings, etc.)
 * Sensor: SainSmart IR Flame Detection Module (digital OUT)
 * Wiring: DOUT -> GPIO17 (pin 11), VCC -> 3.3V, GND -> GND
 * Logic:  DOUT is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_S  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] ", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *line_settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure line settings ---------------------------------- */
    line_settings = gpiod_line_settings_new();
    if (line_settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed\n");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP);

    /* ---- Configure line offsets ----------------------------------- */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new() failed\n");
        goto cleanup;
    }

    unsigned int offsets[1] = { GPIO_LINE_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 1, line_settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request configuration ------------------------------------- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new() failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* ---- Request the line ----------------------------------------- */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- Main loop ------------------------------------------------ */
    while (g_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value() failed: %s\n",
                    strerror(errno));
            break;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_req != NULL)
        gpiod_line_request_release(line_req);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (line_settings != NULL)
        gpiod_line_settings_free(line_settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return ret;
}

