#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    int pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int pin = pins[i];

        if (gpioSetMode(pin, PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pin);
            return -1;
        }

        if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", pin);
            return -1;
        }
    }
    return 0;
}

static void log_touch_state(int states[NUM_CHANNELS])
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long elapsed_ms = (long)(ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);

    printf("[%ld ms] ", elapsed_ms);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("CH%d=%d ", i + 1, states[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int states[NUM_CHANNELS];
    int last_states[NUM_CHANNELS];

    for (int i = 0; i < NUM_CHANNELS; i++) {
        states[i] = gpioRead(pins[i]);
        last_states[i] = states[i];
    }

    while (g_running) {
        log_touch_state(states);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            states[i] = gpioRead(pins[i]);
            if (states[i] != last_states[i]) {
                last_states[i] = states[i];
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

