#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info);
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Allocate line settings: bias disabled, pull-up disabled */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    /* Allocate line config */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    /* Allocate request config */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        perror("gpiod_request_config_new");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ttp226-touch");

    /* Add lines to the line config */
    if (gpiod_line_config_add_line_settings(line_cfg, gpio_pins, NUM_CHANNELS, settings) != 0) {
        perror("gpiod_line_config_add_line_settings");
        goto cleanup;
    }

    /* Request the lines */
    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("TTP226 8-channel touch sensor reader started. Press Ctrl+C to exit.\n");
    printf("Timestamp,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7,Channel8\n");

    /* Main polling loop */
    while (program_running) {
        int values[NUM_CHANNELS];
        int i;

        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_request_get_value(request, gpio_pins[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n", gpio_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        print_timestamp();
        printf("%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

