#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_tilt_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "unknown-time");
    }

    if (state == 0) {
        printf("%s - Tilted\n", timestamp);
    } else {
        printf("%s - Not Tilted\n", timestamp);
    }
    fflush(stdout);
}

int main(void)
{
    int ret;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        fprintf(stderr, "       Ensure pigpiod is not running and you have root privileges.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO 4 as input with internal pull-up --- */
    if (gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d.\n", TILT_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d.\n", TILT_SENSOR_GPIO);
    printf("Polling every %d ms. Press Ctrl+C to exit.\n", POLL_INTERVAL_US / 1000);
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_SENSOR_GPIO);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for GPIO %d (code %d).\n",
                    TILT_SENSOR_GPIO, level);
            break;
        }

        log_tilt_state(level);

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

