#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define REG_PART_ID 0x00
#define REG_HW_KEY 0x07
#define REG_CHLIST 0x01
#define REG_ALS_VIS_DATA0 0x22
#define REG_UVINDEX 0x2D
#define REG_COMMAND 0x46

#define HW_KEY_VAL 0x17
#define CHLIST_EN_UV 0x01
#define CHLIST_EN_ALS_VIS 0x02
#define CHLIST_EN_ALS_IR 0x04
#define CHLIST_EN_ALS_VIS_IR 0x06

#define CMD_ALS_FORCE 0x06
#define CMD_RESET 0x01

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n", reg, val, pigpio_error(rc));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;

    if (read_reg(REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent or bus error\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (write_reg(REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_HW_KEY, HW_KEY_VAL) < 0) return -1;

    uint8_t chlist = CHLIST_EN_UV | CHLIST_EN_ALS_VIS;
    if (write_reg(REG_CHLIST, chlist) < 0) return -1;

    if (write_reg(REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_uv_index(float *uv_index) {
    uint8_t val = 0;
    if (read_reg(REG_UVINDEX, &val) < 0) return -1;
    *uv_index = (float)val;
    return 0;
}

static int read_als_visible(uint16_t *als_visible) {
    uint8_t lo = 0, hi = 0;
    if (read_reg(REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (read_reg(REG_ALS_VIS_DATA0 + 1, &hi) < 0) return -1;
    *als_visible = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, SI1145_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    printf("Si1145 initialized. Logging to uv_als_log.csv. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float uv_index = 0.0f;
        uint16_t als_visible = 0;

        if (read_uv_index(&uv_index) < 0) {
            fprintf(stderr, "Error reading UV index\n");
        } else if (read_als_visible(&als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible\n");
        } else {
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

