    if (write_reg(REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(REG_HW_KEY, HW_KEY_VAL) < 0) return -1;

    uint8_t chlist = CHLIST_EN_UV | CHLIST_EN_ALS_VIS;
    if (write_reg(REG_CHLIST, chlist) < 0) return -1;

    if (write_reg(REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int read_uv_index(float *uv_index) {
    uint8_t val = 0;
    if (read_reg(REG_UVINDEX, &val) < 0) return -1;
    *uv_index = (float)val;
    return 0;
}

static int read_als_visible(uint16_t *als_visible) {
    uint8_t lo = 0, hi = 0;
    if (read_reg(REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (read_reg(REG_ALS_VIS_DATA0 + 1, &hi) < 0) return -1;
    *als_visible = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, SI1145_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    printf("Si1145 initialized. Logging to uv_als_log.csv. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float uv_index = 0.0f;
        uint16_t als_visible = 0;

        if (read_uv_index(&uv_index) < 0) {
            fprintf(stderr, "Error reading UV index\n");
        } else if (read_als_visible(&als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible\n");
        } else {
            log_data(uv_index, als_visible);
            printf("UV Index: %.2f, ALS Visible: %u\n", uv_index, als_visible);
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

