#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define ALARM_GPIO     17
#define FLOW_SCALE     0.036f
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define READ_INTERVAL  1
#define MEAS_DELAY_MS  100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    uint8_t buf[9];
    if (i2c_read_bytes(fd, 0x00, buf, 9) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on CRC data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * FLOW_SCALE;
    return 0;
}

static void log_flow_rate(FILE *fp, float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, flow1, flow2);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd1 = open(I2C_BUS, O_RDWR);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(fd1);
        return 1;
    }
    if (i2c_write_cmd(fd1, 0x08, 0x3608) < 0) {
        fprintf(stderr, "Failed to start sensor 1\n");
        close(fd1);
        return 1;
    }
    usleep(MEAS_DELAY_MS * 1000);

    int fd2 = open(I2C_BUS, O_RDWR);
    if (fd2 < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        close(fd1);
        return 1;
    }
    if (ioctl(fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(fd1);
        close(fd2);
        return 1;
    }
    if (i2c_write_cmd(fd2, 0x08, 0x3608) < 0) {
        fprintf(stderr, "Failed to start sensor 2\n");
        close(fd1);
        close(fd2);
        return 1;
    }
    usleep(MEAS_DELAY_MS * 1000);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        close(fd1);
        close(fd2);
        return 1;
    }
    struct gpiod_line *alarm = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }
    if (gpiod_line_request_output(alarm, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(alarm);
        gpiod_chip_close(chip);
        close(fd1);
        close(fd2);
        return 1;
    }

    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = (read_flow_rate(fd1, &flow1) == 0);
        int ok2 = (read_flow_rate(fd2, &flow2) == 0);

        if (ok1 && ok2) {
            log_flow_rate(fp, flow1, flow2);
            float avg = (flow1 + flow2) / 2.0f;
            int alarm_state = (avg < FLOW_THRESHOLD) ? 1 : 0;
            if (gpiod_line_set_value(alarm, alarm_state) < 0) {
                fprintf(stderr, "Failed to set alarm GPIO: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
        }

        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    gpiod_line_set_value(alarm, 0);
    gpiod_line_release(alarm);
    gpiod_chip_close(chip);
    fclose(fp);
    close(fd1);
    close(fd2);
    return 0;
}

