static int buffer_count = 0;

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int signal)
{
    (void)signal;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure the sensor pin.                    */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to enable pull-up on GPIO %d.\n",
                SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the sensor value.                                            */
/* Returns 0 if an obstacle is detected (LOW), 1 if clear (HIGH),    */
/* -1 on read error.                                                 */
/* ------------------------------------------------------------------ */
static int read_sensor(void)
{
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (code %d).\n",
                SENSOR_GPIO, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Add a new event to the circular buffer.                            */
/* ------------------------------------------------------------------ */
static void add_event(time_t timestamp, int sensor_value)
{
    circular_buffer[buffer_head].timestamp = timestamp;
    circular_buffer[buffer_head].sensor_value = sensor_value;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Print the contents of the circular buffer in chronological order.  */
/* ------------------------------------------------------------------ */
static void print_buffer(void)
{
    printf("\n--- Obstacle Detection Log ---\n");
    int start = (buffer_count == BUFFER_SIZE)
                ? buffer_head
                : 0;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm tm_info;
        if (localtime_r(&circular_buffer[idx].timestamp,
                        &tm_info) != NULL) {
            strftime(time_str, sizeof(time_str),
                     "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str) - 1);
            time_str[sizeof(time_str) - 1] = '\0';
        }
        printf("  [%3d] %s  (GPIO %d, %s)\n",
               i + 1, time_str,
               SENSOR_GPIO, circular_buffer[idx].sensor_value == 0 ? "OBSTACLE" : "CLEAR");
    }
    printf("--- End of Log ---\n");
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            /* Read error — wait and retry. */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Warning: time() failed: %s\n",
                        strerror(errno));
            } else {
                add_event(now, sensor_value);
                printf("ALERT: Obstacle detected! (GPIO %d, %s)\n",
                       SENSOR_GPIO, sensor_value == 0 ? "OBSTACLE" : "CLEAR");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

