#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55
#define D7S_REG_X_LSB  0x2A
#define D7S_REG_X_MSB  0x2B
#define D7S_REG_Y_LSB  0x2C
#define D7S_REG_Y_MSB  0x2D
#define D7S_REG_Z_LSB  0x2E
#define D7S_REG_Z_MSB  0x2F
#define D7S_REG_MODE   0x1D
#define D7S_REG_STATUS 0x1B
#define D7S_MODE_ACTIVE 0x10
#define D7S_STATUS_ACTIVE 0x01
#define SAMPLE_MS      500
#define MAX_INIT_MS    1000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, int16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int init_d7s(int fd) {
    if (i2c_write_reg8(fd, D7S_REG_MODE, D7S_MODE_ACTIVE) < 0) return -1;
    usleep(10000);
    uint8_t status;
    for (int i = 0; i < MAX_INIT_MS; i++) {
        if (i2c_read_reg8(fd, D7S_REG_STATUS, &status) < 0) return -1;
        if (status & D7S_STATUS_ACTIVE) return 0;
        usleep(1000);
    }
    fprintf(stderr, "D7S did not enter active mode within %d ms\n", MAX_INIT_MS);
    return -1;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, D7S_REG_X_LSB, x) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Y_LSB, y) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Z_LSB, z) < 0) return -1;
    return 0;
}

static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_d7s(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_fp = fopen("fan_health.csv", "a");
    if (!g_fp) {
        fprintf(stderr, "fopen fan_health.csv failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    fseek(g_fp, 0, SEEK_END);
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,x,y,z\n");
        fflush(g_fp);
    }

    printf("Monitoring D7S vibration sensor. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read failed; retrying next cycle\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        log_sample(g_fp, x, y, z);
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_fp) fclose(g_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

