#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 23
#define SENSOR_2_GPIO 24
#define LED_GPIO     25
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode)
{
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", gpio);
        return -1;
    }
    return v;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_1_GPIO, PI_INPUT) != 0 ||
        safe_set_mode(SENSOR_2_GPIO, PI_INPUT) != 0 ||
        safe_set_mode(LED_GPIO, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* KY-032 OUT is active-LOW: 0 = obstacle detected */
    if (safe_write(LED_GPIO, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = safe_read(SENSOR_1_GPIO);
        int s2 = safe_read(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            /* Read error — turn LED off and wait briefly before retry */
            safe_write(LED_GPIO, 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Obstacle detected when either sensor reads LOW (active-LOW) */
        if (s1 == 0 || s2 == 0) {
            if (safe_write(LED_GPIO, 1) != 0) {
                /* Non-fatal: keep running */
            }
        } else {
            if (safe_write(LED_GPIO, 0) != 0) {
                /* Non-fatal: keep running */
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    safe_write(LED_GPIO, 0);
    gpioTerminate();
    printf("\nObstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

