#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_THRESHOLD_SEC 2
#define LOG_FILE "stall_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(value));
        return -1;
    }
    return value;
}

static int is_stalled(int s1, int s2) {
    return (s1 == 0 && s2 == 0) && (gpioTick() - (gpioTick() / 1000000) * 1000000) >= (STALL_THRESHOLD_SEC * 1000000);
}

static int log_stall(void) {
    FILE *fp = fopen(LOG_FILE, "a");
