#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x0E
#define CSV_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000  /* 100 ms */

/* TMAG5170-Q1 register addresses */
#define REG_DEVICE_ID   0x00
#define REG_DEVICE_ID_VAL 0x8D
#define REG_X_MSB       0x01
#define REG_X_LSB       0x02
#define REG_Y_MSB       0x03
#define REG_Y_LSB       0x04
#define REG_Z_MSB       0x05
#define REG_Z_LSB       0x06
#define REG_RANGE       0x0F
#define REG_MODE        0x10
#define REG_CONFIG      0x11

/* Range: 50 mT (bits[1:0]=00) */
#define RANGE_50MT      0x00
/* Mode: continuous-conversion (bits[1:0]=11) */
#define MODE_CONTINUOUS 0x03
/* Config: 50 Hz ODR, 1.35 ms period, 1 sample per conversion */
#define CONFIG_50HZ     0x00

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_fp        = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, val, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, expected=%u, got=%d): %s\n",
                reg, len, rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int verify_device_id(void)
{
    uint8_t id = 0;
    if (i2c_read_reg(REG_DEVICE_ID, &id) != 0)
        return -1;
    if (id != REG_DEVICE_ID_VAL) {
        fprintf(stderr, "Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, REG_DEVICE_ID_VAL);
        return -1;
    }
    return 0;
}

static int configure_sensor(void)
{
    if (i2c_write_reg(REG_MODE, MODE_CONTINUOUS) != 0)
        return -1;
    if (i2c_write_reg(REG_RANGE, RANGE_50MT) != 0)
        return -1;
    if (i2c_write_reg(REG_CONFIG, CONFIG_50HZ) != 0)
        return -1;
    return 0;
}

static int read_magnetic_field(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(REG_X_MSB, buf, sizeof(buf)) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(g_fp);
}

static void cleanup(void)
{
    if (g_fp) {
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device_id() != 0) {
        fprintf(stderr, "TMAG5170-Q1 not detected at 0x%02X\n", I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_fp = fopen(CSV_FILE, "a");
    if (!g_fp) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_fp, 0, SEEK_END);
    if (ftell(g_fp) == 0) {
        fprintf(g_fp, "timestamp,x_mT,y_mT,z_mT\n");
        fflush(g_fp);
    }

    printf("Logging TMAG5170-Q1 data to %s (Ctrl+C to stop)\n", CSV_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_magnetic_field(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Read error; continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

