#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <stdatomic.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */

static atomic_int pulse_count = 0;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback: fires on every edge of the sensor pin.       */
/* We only count rising edges (magnetization -> Hall output goes HIGH). */
/* ------------------------------------------------------------------ */
static void sensor_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {
        atomic_fetch_add(&pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses per second.                                 */
/* One pulse per revolution per second.                               */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int pulses, double interval_us)
{
    if (interval_us <= 0.0) {
        return 0.0;
    }
    return (double)pulses / (double)interval_us * 60.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped RPM line to the log file and stdout.           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush of log file failed\n");
        return -1;
    }

    printf("%s %.2f RPM\n", timestamp, rpm);
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable callback first so no more pulses arrive during teardown. */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input with internal pull-up ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90217 RPM monitor started on BCM GPIO %d.\n", SENSOR_PIN);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (!terminate) {
        /* Reset pulse count at start of each 1-second window. */
        atomic_store(&pulse_count, 0);

        /* Wait for the 1-second interval to elapse. */
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses = atomic_exchange(&pulse_count, 0);
        double rpm = calculate_rpm(pulses, (double)SAMPLE_INTERVAL_US);

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

