#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature states */
#define STATE_A 0
#define STATE_B 1
#define STATE_C 2
#define STATE_D 3

/* Direction: +1 = CW, -1 = CCW, 0 = no change */
typedef enum {
    CW = +1,
    CCW = -1,
    NO_CHANGE = 0
} Direction;

static volatile int running = 1;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

/* Shared state between ISR and main loop */
static int prev_state = 0;
static int current_state = 0;
static Direction direction = NO_CHANGE;

/* Function prototypes */
static void sensor_callback(int gpio, int level, uint32_t tick);
static void log_rotation(const char *timestamp, Direction dir);
static void signal_handler(int sig);
static void cleanup(void);

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-up resistors */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up alert callback for both sensors */
    if (gpioSetAlertFunc(SENSOR_A_GPIO, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_B_GPIO, sensor_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    /* Main loop: wait for rotation events */
    while (running) {
        gpioDelay(100000); /* 100 ms sleep to reduce CPU usage */
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ISR callback: called on every edge of both sensors */
static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;

    /* Only act on rising/falling edges (level == 1 or level == 0) */
    if (level != 1 && level != 0) {
        return;
    }

    /* Read current state */
    int current = gpioRead(gpio);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", gpio);
        return;
    }

    /* Update shared state atomically */
    pthread_mutex_lock(&state_mutex);
    if (current != prev_state) {
        current_state = current;
        prev_state = current;
        if (current_state != current_state) {
            /* State change detected; re-sync */
            current_state = current;
            prev_state = current;
        }
    }
    pthread_mutex_unlock(&state_mutex);

    /* Determine direction based on quadrature state machine */
    if (current_state == 0) {
        direction = NO_CHANGE;
    } else if (current_state == 1) {
        direction = CW;
    } else if (current_state == 2) {
        direction = CCW;
    } else if (current_state == 3) {
        direction = NO_CHANGE;
    }
}

/* Log rotation event with millisecond timestamp */
static void log_rotation(const char *timestamp, Direction dir) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    if (dir == NO_CHANGE) {
        fprintf(log_file, "%s, No Change\n", timestamp);
    } else if (dir == CW) {
        fprintf(log_file, "%s, CW\n", timestamp);
    } else if (dir == CCW) {
        fprintf(log_file, "%s, CCW\n", timestamp);
    }

    fflush(log_file);
}

/* Signal handler: set running flag to 0 */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Cleanup: close log file and terminate pigpio */
static void cleanup(void) {
    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);
}

