#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define BUFFER_SIZE  100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    time_t timestamp;
    int    sensor_pin;
    int    state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_event(int sensor_pin, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].state     = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static void print_log_buffer(void)
{
    printf("\n--- Log Buffer Contents ---\n");
    int start = (buffer_index - buffer_count + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        if (localtime_r(&log_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }
        printf("  [%3d] Sensor %d: %s  ->  %s\n",
               idx, log_buffer[idx].sensor_pin,
               log_buffer[idx].state ? "Touched" : "Released",
               log_buffer[idx].state ? "Touched" : "Released");
    }
    printf("--- End of Log Buffer ---\n\n");
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_2_PIN);
        return -1;
    }

    /* Start with LEDs off */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: turn off LEDs and terminate pigpio */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_1_PIN);
        } else if (s1 == 1) {
            log_event(SENSOR_1_PIN, 1);
            if (gpioWrite(LED_1_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_1_PIN);
            }
        } else {
            log_event(SENSOR_1_PIN, 0);
            if (gpioWrite(LED_1_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_1_PIN);
            }
        }

        if (s2 < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_2_PIN);
        } else if (s2 == 1) {
            log_event(SENSOR_2_PIN, 1);
            if (gpioWrite(LED_2_PIN, 1) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_2_PIN);
            }
        } else {
            log_event(SENSOR_2_PIN, 0);
            if (gpioWrite(LED_2_PIN, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", LED_2_PIN);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_log_buffer();
    cleanup_gpio();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

