    int previous_state = -1;  /* Unknown initial state */
    int current_state;

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO 17 as input with internal pull-up resistor */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
