    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Cannot register SIGINT handler\n");
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: Cannot register SIGTERM handler\n");
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_GPIO);

    /* Main polling loop */
    while (program_running) {
        current_state = read_rain_sensor();

        if (current_state < 0) {
            /* Sensor read error — log and continue */
            log_message("Error: Failed to read rain sensor");
        } else if (current_state != previous_state) {
            const char *message = (current_state == 1) ? "Rain Detected" : "No Rain";
            log_message(message);
            printf("%s\n", message);
            previous_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);  /* 500 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

