#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 2

// Define the debounce time in microseconds (5 ms)
#define DEBOUNCE_TIME_US 5000

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_data(int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors for the sensors (DRV5032FJDBZR has internal pull-up)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor with debounce
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_TIME_US); // Debounce delay

    // If the state changed, return the new state
    if (state != gpioRead(gpio_pin)) {
        return state;
    }

    return state;
}

// Function to log data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to clean up resources before exiting
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file for appending
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize variables to track the last pulse times
    uint32_t last_pulse_time1 = 0;
    uint32_t last_pulse_time2 = 0;

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Calculate the time since the last pulse
        uint32_t current_time = gpioTick();
        uint32_t time_since_last_pulse1 = current_time - last_pulse_time1;
        uint32_t time_since_last_pulse2 = current_time - last_pulse_time2;

        // Check if a pulse has occurred (time since last pulse > 1 revolution)
        if (time_since_last_pulse1 > (PULSES_PER_REVOLUTION * 1000000)) {
            // Calculate RPM
            double rpm = 60.0 / (time_since_last_pulse1 / 1000000.0);
            printf("RPM: %.2f\n", rpm);
            fflush(stdout);

            // Log the data
            log_data(sensor1_state, sensor2_state);

            // Update the last pulse time
            last_pulse_time1 = current_time;
        }

        if (time_since_last_pulse2 > (PULSES_PER_REVOLUTION * 1000000)) {
            // Calculate RPM
            double rpm = 60.0 / (time_since_last_pulse2 / 1000000.0);
            printf("RPM: %.2f\n", rpm);
            fflush(stdout);

            // Log the data
            log_data(sensor1_state, sensor2_state);

            // Update the last pulse time
            last_pulse_time2 = current_time;
        }

        gpioDelay(10000); // Delay for 10 ms to reduce CPU usage
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

