#define REG_ALS_IR_DATA0 0x0A
#define REG_ALS_IR_DATA1 0x0B
#define REG_HR_DATA0 0x02
#define REG_HR_DATA1 0x03
#define REG_SPO2_DATA0 0x04
#define REG_SPO2_DATA1 0x05
#define REG_CONFIG 0x30

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID 0x82

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_si1182(int handle) {
    uint8_t part_id = 0;

    /* Verify sensor presence */
    if (read_reg(handle, REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    /* Write HW_KEY to enable sensor */
    if (write_reg(handle, REG_HW_KEY, 0x17) < 0) {
        return -1;
    }

    /* Configure for continuous measurement */
    if (write_reg(handle, REG_MEAS_RATE, 0x0A) < 0) return -1;
    if (write_reg(handle, REG_ALS_RATE, 0x0A) < 0) return -1;
    if (write_reg(handle, REG_CONFIG, 0x0A) < 0) return -1;

    return 0;
}

static int read_hr_spo2(int handle, int *heart_rate, int *spo2) {
    uint8_t hr_low = 0, hr_high = 0, spo2_low = 0, spo2_high = 0;

    if (read_reg(handle, REG_HR_DATA0, &hr_low) < 0) return -1;
    if (read_reg(handle, REG_HR_DATA1, &hr_high) < 0) return -1;
    if (read_reg(handle, REG_SPO2_DATA0, &spo2_low) < 0) return -1;
    if (read_reg(handle, REG_SPO2_DATA1, &spo2_high) < 0) return -1;

    *heart_rate = (hr_high << 8) | hr_low;
    *spo2 = (spo2_high << 8) | spo2_low;
    return 0;
}

static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    int heart_rate = 0, spo2 = 0;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1182(i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    printf("Starting heart rate and SpO2 logging. Press Ctrl+C to stop.\n");

    while (!terminate) {
        rc = read_hr_spo2(i2c_handle, &heart_rate, &spo2);
        if (rc == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading HR/SPO2 data, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

