#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO    27
#define POLL_DELAY_US 100000  /* 100 ms */
#define THRESHOLD_SEC 2       /* 2 s */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped event to the log file                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    time_t now;
    struct tm tm_info;
    char timestamp[32];

    time(&now);
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; event lost: %s\n", event);
    }
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down resistors so sensors read LOW when idle */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Ensure alarm starts in the OFF state */
    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise alarm state on GPIO %d\n", ALARM_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor value; returns 0, 1, or -1 on error                 */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", gpio_pin);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Activate alarm for 2 seconds, then deactivate it                   */
/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    if (gpioWrite(ALARM_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to activate alarm on GPIO %d\n", ALARM_GPIO);
        return;
    }
    log_event("ALARM: Tilt exceeded threshold — alarm activated");

    /* Sleep 2 s in 100 ms slices so we can respond to signals promptly */
    for (int i = 0; i < 20 && running; i++) {
        gpioDelay(POLL_DELAY_US);
    }

    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate alarm on GPIO %d\n", ALARM_GPIO);
    }
    log_event("ALARM: Tilt exceeded threshold — alarm deactivated");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio and configure GPIO pins */
    if (initialize_gpio() != 0) {
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    log_event("Bridge integrity monitoring started");
    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    /* State machine: idle, tilt-start, tilt-end, alarm-active */
    int tilt_active = 0;
    int alarm_active = 0;

    while (running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            /* Sensor read error — log and continue */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Sensor 1: tilt started */
        if (s1 == 1 && !tilt_active) {
            time_t start = time(NULL);
            log_event("Tilt-start: Sensor 1");
            printf("Tilt-start: Sensor 1\n");
            tilt_active = 1;
        }

        /* Sensor 2: tilt started */
        if (s2 == 1 && !tilt_active) {
            time_t start = time(NULL);
            log_event("Tilt-start: Sensor 2");
            printf("Tilt-start: Sensor 2\n");
            tilt_active = 1;
        }

        /* Sensor 1: tilt ended */
        if (s1 == 0 && tilt_active) {
            time_t end = time(NULL);
            double elapsed = difftime(end, start);
            if (elapsed >= THRESHOLD_SEC) {
                trigger_alarm();
                tilt_active = 0;
            }
        }

        /* Sensor 2: tilt ended */
        if (s2 == 0 && tilt_active) {
            time_t end = time(NULL);
            double elapsed = difftime(end, start);
            if (elapsed >= THRESHOLD_SEC) {
                trigger_alarm();
                tilt_active = 0;
            }
        }

        /* Sensor 1: threshold exceeded (continuous HIGH) */
        if (s1 == 1 && tilt_active) {
            trigger_alarm();
            tilt_active = 0;
        }

        /* Sensor 2: threshold exceeded (continuous HIGH) */
        if (s2 == 1 && tilt_active) {
            trigger_alarm();
            tilt_active = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (gpioWrite(ALARM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to deactivate alarm during shutdown\n");
    }
    log_event("Bridge integrity monitoring stopped");
    fclose(log_file);
    log_file = NULL;
    gpioTerminate();

    return EXIT_SUCCESS;
}

