/*
 * Seismic Monitor for Raspberry Pi 3 Model B+
 * Sensor : Omron D7S-A0011 (I2C 7-bit address 0x1D)
 * Bus    : I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * LED    : GPIO 17 (active-high)
 *
 * Build  : gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run    : sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* raw acceleration magnitude */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_DURATION_US   1000000       /* 1 s */
#define LOG_FILE             "seismic_events.log"
#define MAX_RETRIES          3
#define REG_CTRL1            0x1F          /* Power-down bit (bit 0) */
#define REG_ACCEL_X_L        0x28          /* 3-axis acceleration registers */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  init_sensor(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void log_event(float magnitude);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Initialize sensor: verify presence, clear power-down ---- */
static int init_sensor(void)
{
    int rc;

    /* Verify sensor is responding by reading CTRL1 (should not fail) */
    rc = i2cReadByteData(g_i2c_handle, REG_CTRL1);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Sensor not responding on I2C bus %d addr 0x%02X: rc=%d\n",
                I2C_BUS, I2C_ADDR, rc);
        return -1;
    }

    /* Clear power-down bit (bit 0) so the sensor is ready to operate */
    rc = i2cWriteByteData(g_i2c_handle, REG_CTRL1, 0x00);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] Failed to clear power-down: rc=%d\n", rc);
        return -1;
    }

    return 0;
}

/* ---- Read 3-axis acceleration (6 bytes, little-endian) ---- */
static int read_acceleration(float *x, float *y, float *z)
{
    char buf[6];
    int  rc;
    int  retries = MAX_RETRIES;

    while (retries > 0) {
        /* Read 6 bytes starting at ACCEL_X_L (0x28) */
        rc = i2cReadI2CBlockData(g_i2c_handle, REG_ACCEL_X_L, buf, 6);
        if (rc == 6) {
            int16_t raw_x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            int16_t raw_y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            int16_t raw_z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);

            *x = (float)raw_x;
            *y = (float)raw_y;
            *z = (float)raw_z;
            return 0;
        }
        fprintf(stderr, "[WARN] I2C block read failed (rc=%d), retries left=%d\n",
                rc, retries - 1);
        retries--;
        gpioDelay(1000); /* 1 ms back-off */
    }

    fprintf(stderr, "[ERROR] Acceleration read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ---- Calculate Euclidean magnitude of acceleration ---- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ---- Log event with ISO-8601 timestamp ---- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
