#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    if (gpiod_line_request_output(led_line, "obstacle_led", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "obstacle_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input\n", sensor_pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        int any_detected = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor on GPIO %u\n", sensor_pins[i]);
                goto cleanup;
            }
            if (val == 0) {
                any_detected = 1;
            }
        }

        if (gpiod_line_set_value(led_line, any_detected) < 0) {
            perror("gpiod_line_set_value (LED)");
            goto cleanup;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

