#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"

/* BCM GPIO numbers for the 5 sensors */
static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

/* ------------------------------------------------------------------ */
/* Globals for signal-safe cleanup                                    */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip      = NULL;
static struct gpiod_line  *g_lines[NUM_SENSORS];
static int                 g_lines_requested = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a flame event line to the log file.                          */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_flame_event(int sensor_id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time(): %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf() to log: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush() to log: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose() to log: %s", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single sensor line.                                         */
/* Returns 1 if flame detected (LOW), 0 if no flame (HIGH), -1 on error. */
/* ------------------------------------------------------------------ */
static int read_sensor(unsigned int pin)
{
    struct gpiod_line *line = g_lines[pin - 1];
    if (!line) {
        syslog(LOG_ERR, "g_lines[%u] is NULL", pin);
        return -1;
    }

    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value(%u): %s", pin, strerror(errno));
        return -1;
    }

    /* KY-026 digital output: LOW = flame detected, HIGH = no flame */
    return (val == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Release all requested lines and close the chip.                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    for (int i = 0; i < g_lines_requested; i++) {
        if (g_lines[i]) {
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
        }
    }
    g_lines_requested = 0;

    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "flame_monitor starting (GPIO %u, %u, %u, %u, %u)",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3], sensor_pins[4]);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Request each line as input */
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, sensor_pins[i]);
        if (!g_lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u): %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(g_lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u): %s",
                   sensor_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        g_lines_requested++;
    }

    syslog(LOG_INFO, "Monitoring %d sensors on BCM GPIO %u, %u, %u, %u, %u",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3], sensor_pins[4]);

    /* Main polling loop */
    while (g_running) {
        int flame = 0;
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int v = read_sensor(sensor_pins[i]);
            if (v < 0) {
                read_error = 1;
                break;
            }
            if (v == 1) {
                flame = 1;
            }
        }

        if (flame) {
            /* Debounce: re-read after 50 ms */
            usleep(DEBOUNCE_MS * 1000);
            int recheck = read_sensor(sensor_pins[0]);
            if (recheck < 0) {
                read_error = 1;
            } else if (recheck == 1) {
                if (log_flame_event(i + 1, sensor_pins[i]) != 0) {
                    syslog(LOG_ERR, "Failed to log flame event for sensor %d", i + 1);
                }
            }
        }

        if (read_error) {
            syslog(LOG_ERR, "Sensor read error — aborting");
            break;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

