#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int sensor_index, int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s - Sensor %d (BCM pin %u): %s\n",
           timestamp, sensor_index, touch_pins[sensor_index],
           state ? "Touched" : "Released");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line *lines_bulk;
    struct gpiod_line_request_config req_cfg;
    struct gpiod_line_request *request;
    int prev_states[NUM_CHANNELS];
    int ret;

    memset(prev_states, -1, sizeof(prev_states));

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Build a bulk pointer to the individual GPIO lines */
    lines_bulk = &lines;
    lines_bulk->num_lines = NUM_CHANNELS;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines_bulk->lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
    }

    /* Configure each line as input */
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "ttp226-touch";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    /* Request the bulk of the lines at once (v1.x API) */
    ret = gpiod_line_request_bulk(lines_bulk, &req_cfg, &request);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TTP226 8-channel touch sensor monitoring started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int current_states[NUM_CHANNELS];

        ret = gpiod_line_get_value_bulk(request, current_states);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO values: %s\n", strerror(errno));
            break;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = current_states[i];
            if (state != prev_states[i]) {
                log_touch_event(i, state);
                prev_states[i] = state;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    /* Clean up resources on all exit paths */
    if (request) {
        gpiod_line_release_bulk(request, lines_bulk);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

