#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VEML7700_ADDR 0x10
#define ALS_CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000
#define LUX_TO_RAW 0.0576f
#define LOG_FILE "grow_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_init(void) {
    uint16_t config = 0x0000; /* ALS gain 1/8, 100 ms integration */
    char buf[2] = { (char)(config & 0xFF), (char)((config >> 8) & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: failed to write VEML7700 config register\n");
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    char reg = ALS_DATA_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: failed to select ALS data register\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ALS data\n");
        return -1;
    }
    uint16_t raw = (uint16_t)((uint8_t)data[0]) | ((uint16_t)((uint8_t)data[1]) << 8);
    *lux_out = (float)raw * LUX_TO_RAW;
    return 0;
}

static int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    if (gpioPWM(LED_GPIO, brightness) != 0) {
        fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", LED_GPIO);
        return -1;
    }
    return 0;
}

static int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", ts, lux, brightness, error_code) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X\n", VEML7700_ADDR);
        gpioTerminate();
        return 1;
    }

    if (veml7700_init() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux;
        if (read_lux(&lux) != 0) {
            fprintf(stderr, "Error: sensor read failed, logging error\n");
            log_data(-1.0f, -1, -1);
            set_led_brightness(0);
            sleep(1);
            continue;
        }

        int brightness;
        if (lux < LUX_THRESHOLD_1) {
            brightness = 100;
        } else if (lux < LUX_THRESHOLD_2) {
            brightness = 75;
        } else if (lux < LUX_THRESHOLD_3) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        if (set_led_brightness(brightness) != 0) {
            fprintf(stderr, "Error: LED brightness set failed\n");
            log_data(lux, -1, -1);
        } else {
            log_data(lux, brightness, 0);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    set_led_brightness(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Grow light system stopped.\n");
    return 0;
}

