        if (lux < LUX_THRESHOLD_1) {
            brightness = 100;
        } else if (lux < LUX_THRESHOLD_2) {
            brightness = 75;
        } else if (lux < LUX_THRESHOLD_3) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        if (set_led_brightness(brightness) != 0) {
            fprintf(stderr, "Error: LED brightness set failed\n");
            log_data(lux, -1, -1);
        } else {
            log_data(lux, brightness, 0);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    set_led_brightness(0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Grow light system stopped.\n");
    return 0;
}

