        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(channel_pins[i]);
            if (current_state[i] < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", channel_pins[i]);
                continue;
            }
            if (current_state[i] == 1 && last_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
            last_state[i] = current_state[i];
        }

        if (gpioWrite(LED_PIN, any_touched) != 0) {
            fprintf(stderr, "Error writing to LED pin %d\n", LED_PIN);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nSecurity keypad simulation stopped.\n");

    return EXIT_SUCCESS;
}

