#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810  /* 100 ms conversion, auto-range, continuous */
#define I2C_BUS 1
#define LOG_FILE "light_data.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int opt3001_write_config(int handle, uint16_t config_word) {
    int rc = i2cWriteWordData(handle, CONFIG_REG, config_word);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteWordData(config) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static int opt3001_read_result(int handle, uint16_t *result) {
    int rc = i2cReadWordData(handle, RESULT_REG);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData(result) failed: %d\n", rc);
        return -1;
    }
    /* pigpio returns little-endian word; OPT3001 reports big-endian */
    uint16_t swapped = ((rc & 0xFF) << 8) | ((rc >> 8) & 0xFF);
    *result = swapped;
    return 0;
}

static float lux_from_raw(uint16_t raw) {
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    return (float)mantissa * 0.01f * (float)(1 << exponent);
}

static int log_data(const char *filename, float lux) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", filename);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", timestamp, lux);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (opt3001_write_config(i2c_handle, CONFIG_WORD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* First conversion takes ~100 ms; wait a bit more for safety */
    gpioDelay(150000);

    while (running) {
        uint16_t raw;
        if (opt3001_read_result(i2c_handle, &raw) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float lux = lux_from_raw(raw);
        if (log_data(LOG_FILE, lux) != 0) {
            fprintf(stderr, "Warning: logging failed\n");
        }
        printf("Lux: %.2f\n", lux);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

