#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor GPIO mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert GPIO mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert GPIO state\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor GPIO\n");
        return -1;
    }
    return value;
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) != 0) {
        fprintf(stderr, "Failed to set alert GPIO HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to set alert GPIO LOW\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_event("System started");

    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            log_event("Error reading flame sensor");
        } else if (flame_detected == 0) {
            log_event("Flame detected!");
            trigger_alert();
        } else {
            log_event("No flame detected");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("System shutting down");
    if (log_file) fclose(log_file);
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
    return 0;
}

