#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define MEAS_CMD_MSB   0x36
#define MEAS_CMD_LSB   0x08
#define MEAS_DELAY_US  2000
#define SAMPLE_US      1000000
#define FLOW_SCALE     90.0f
#define MIN_FLOW       0.0f
#define MAX_FLOW       100.0f
#define LOG_FILE       "cooling_log.csv"
#define READ_LEN       3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int start_measurement(void) {
    uint8_t cmd[2] = { MEAS_CMD_MSB, MEAS_CMD_LSB };
    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    return 0;
}

static int read_flow(int16_t *raw_flow, uint8_t *crc) {
    uint8_t buf[READ_LEN];
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "Error reading flow data: got %d bytes, expected %d\n",
                n, READ_LEN);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *crc = buf[2];
    return 0;
}

static float convert_to_ml_min(int16_t raw) {
    return (float)raw / FLOW_SCALE;
}

static void log_data(float flow, int16_t raw, uint8_t crc, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(g_log_fp, "%s,%.2f,%s\n", ts, flow, status);
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        fclose(g_log_fp);
        gpioTerminate();
        return 1;
    }

    if (start_measurement() != 0) {
        fprintf(stderr, "Failed to start measurement\n");
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long sz = ftell(g_log_fp);
    if (sz == 0) {
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_fp);
    }

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw_flow = 0;
        uint8_t crc = 0;
        int rc = read_flow(&raw_flow, &crc);

        if (rc == 0) {
            float flow = convert_to_ml_min(raw_flow);
            if (flow < MIN_FLOW || flow > MAX_FLOW) {
                log_data(0.0f, raw_flow, crc, "INVALID");
                fprintf(stderr, "Flow rate out of range: %.2f ml/min\n", flow);
            } else {
                log_data(flow, raw_flow, crc, "OK");
                printf("Flow: %.2f ml/min (raw=0x%04X crc=0x%02X)\n",
                       flow, raw_flow, crc);
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, re-initializing I2C\n");
                if (init_i2c() != 0) {
                    fprintf(stderr, "Re-init failed, exiting\n");
                    break;
                }
                if (start_measurement() != 0) {
                    fprintf(stderr, "Re-start failed, exiting\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

