#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 4
#define LOG_FILE "flame_events.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    fprintf(fp, "%s - Flame detected\n", timestamp);
    fclose(fp);
}

static void print_alert(const char *timestamp) {
    printf("ALERT: Flame detected at %s\n", timestamp);
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    struct timespec ts;
    char timestamp[32];
    int ret;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line for falling-edge events */
    ret = gpiod_line_request_falling_edge_events(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO %d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main event loop */
    while (program_running) {
        ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* Timeout, no event */
            continue;
        }

        /* Event detected, read it */
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        /* Get current timestamp */
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue;
        }
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

        print_alert(timestamp);
        log_event(timestamp);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

