        int events = gpiod_line_event_wait(touch_line, &(struct timespec){0, POLL_TIMEOUT_MS * 1000000L});
        if (events < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for touch event: %s\n", strerror(errno));
            break;
        }
        if (events == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Error reading touch event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            prev_touch = 1;
            led_state = !led_state;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                fprintf(stderr, "Error setting LED state: %s\n", strerror(errno));
            }
            log_event(log_file, led_state);
        } else {
            prev_touch = 0;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    return ret;
}

