#define BUZZER_MS    2000
#define POLL_SLICE   100
#define CONSUMER     "flame_alert"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
