#include <string.h>
#include <errno.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_US 200000
#define POLL_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_touch_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Warning: gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Warning: strftime failed\n");
        return;
    }

    if (log_fp != NULL) {
        if (fprintf(log_fp, "%s - Touch detected\n", timestamp) < 0) {
            fprintf(stderr, "Warning: fprintf to log failed: %s\n", strerror(errno));
        }
        if (fflush(log_fp) != 0) {
            fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: log file not open\n");
    }
}

static void toggle_led(void) {
    int current = gpioRead(LED_PIN);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead failed on LED pin %d\n", LED_PIN);
        return;
    }
    if (gpioWrite(LED_PIN, !current) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on LED pin %d\n", LED_PIN);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise LED pin %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error: initial gpioRead failed on touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_change_tick = gpioTick();
    int led_state = 0;

    while (running) {
        int current = gpioRead(TOUCH_SENSOR_PIN);
        if (current < 0) {
            fprintf(stderr, "Error: gpioRead failed on touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (current == 1 && last_state == 0) {
            if (gpioTick() - last_change_tick >= DEBOUNCE_US) {
                last_change_tick = gpioTick();
                if (gpioWrite(LED_PIN, led_state) < 0) {
                    fprintf(stderr, "Error: gpioWrite failed on LED pin %d\n", LED_PIN);
                }
                led_state = !led_state;
                log_touch_event();
            }
        }

        last_state = current;
        gpioDelay(POLL_US);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

