static void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id,
                state == SENSOR_PRESENT ? "Magnet Present" : "Magnet Removed");
        fflush(log_file);
    } else {
        fprintf(stderr, "%s - Sensor %d: %s\n", timestamp, sensor_id,
                state == SENSOR_PRESENT ? "Magnet Present" : "Magnet Removed");
    }
}

