#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define LOG_FILE "heart_rate.csv"
#define SAMPLE_INTERVAL_US 1000000
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

/* Si1182 register addresses */
#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_register(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int initialize_sensor(void) {
    uint8_t part_id = 0, hw_rev = 0;

    if (read_register(REG_PART_ID, &part_id) < 0) return -1;
    if (read_register(REG_HW_REV, &hw_rev) < 0) return -1;

    if (part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Sensor not detected: PART_ID=0x%02X, HW_REV=0x%02X\n", part_id, hw_rev);
        return -1;
    }

    if (write_register(REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_register(REG_AVG, 0x04) < 0) return -1;
    if (write_register(REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(float *bpm) {
    int raw = i2cReadWordData(i2c_handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart-rate data: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float moving_average(float new_value, float *buffer, int size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % size;
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

static void log_data(float bpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

int main(void) {
    float bpm_buffer[MOVING_AVG_SIZE] = {0.0f};
    int buffer_index = 0;
    int buffer_count = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float bpm = 0.0f;
        if (read_heart_rate(&bpm) == 0) {
            if (bpm >= MIN_BPM && bpm <= MAX_BPM) {
                bpm = moving_average(bpm, bpm_buffer, MOVING_AVG_SIZE, &buffer_index);
                log_data(bpm);
                printf("BPM: %.2f\n", bpm);
            } else {
                fprintf(stderr, "BPM out of range: %.2f\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate. Retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    return 0;
}

