    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    sensor_cfg = gpiod_line_config_new();
    if (!sensor_cfg) {
        fprintf(stderr, "gpiod_line_config_new (sensor) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_config_reset(sensor_cfg);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(sensor_cfg, &sensor_pins[i], 1, settings) < 0) {
            fprintf(stderr, "Failed to add line settings for GPIO %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
