        if (gpiod_line_config_add_line_settings(output_cfg, &display_pins[i], 1, settings) < 0) {
            fprintf(stderr, "Failed to add line settings for GPIO %u: %s\n",
                    display_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    req_cfg = gpiod_request_config_new();
    if (!req_cfg) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "touch_counter");

    req = gpiod_chip_request_lines(chip, req_cfg, sensor_cfg);
    if (!req) {
        fprintf(stderr, "Failed to request sensor lines: %s\n", strerror(errno));
        goto cleanup;
    }

    output_settings = gpiod_line_settings_new();
    if (!output_settings) {
        fprintf(stderr, "gpiod_line_settings_new (output) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(output_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(output_settings, GPIOD_LINE_VALUE_INACTIVE);

    if (gpiod_line_request_set_config(req, output_cfg, output_settings) < 0) {
        fprintf(stderr, "Failed to set output config: %s\n", strerror(errno));
        goto cleanup;
    }

