    for (int i = 0; i < NUM_CHANNELS; i++)
        prev[i] = gpiod_line_request_get_value(req, i);

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(req, i);
            if (val < 0) {
                fprintf(stderr, "Sensor read error on GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect rising edge: inactive -> active */
            if (val == GPIOD_LINE_VALUE_ACTIVE && prev[i] == GPIOD_LINE_VALUE_INACTIVE) {
                int counter = (prev[i] == GPIOD_LINE_VALUE_INACTIVE) ? 0 : 255;
                counter++;
                if (counter > 255)
                    counter = 0;

                print_touch_event(i + 1, counter);
                log_touch_event(i + 1, counter);
                prev[i] = val;
            }
        }
        msleep(POLL_MS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (req)
        gpiod_line_request_release(req);
    if (req_cfg)
        gpiod_request_config_free(req_cfg);
    if (output_settings)
        gpiod_line_settings_free(output_settings);
    if (output_cfg)
        gpiod_line_config_free(output_cfg);
    if (sensor_settings)
        gpiod_line_settings_free(sensor_settings);
    if (sensor_cfg)
        gpiod_line_config_free(sensor_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    /* Reset all outputs to 0 before exiting */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_set_value(req, i, GPIOD_LINE_VALUE_INACTIVE) < 0)
            fprintf(stderr, "Warning: failed to reset GPIO %u: %s\n",
                    display_pins[i], strerror(errno));
    }

    return ret;
}

