        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpiod_line_request_input(lines[i], "ky033-tracking") < 0) {
            fprintf(stderr, "gpiod_line_request_input failed for BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (write_header_if_new(fp) != 0) {
        goto cleanup;
    }

    printf("Tracking started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (program_running) {
        int vals[NUM_SENSORS];
        int read_ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value failed for BCM %u: %s\n",
                        sensor_pins[i], strerror(errno));
                read_ok = 0;
            }
            vals[i] = val;
        }

        if (log_data(fp, vals) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    return ret;
}

