        .consumer = "tilt-monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };
    if (gpiod_line_request(line17, &config, 0) < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_17, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request(line18, &config, 0) < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_18, strerror(errno));
        cleanup();
        return 1;
    }

    int prev17 = 1, prev18 = 1;
    int debounce17 = 0, debounce18 = 0;
    struct timespec last17 = {0, 0}, last18 = {0, 0};

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Read error on GPIO %d: %s\n", GPIO_17, strerror(errno));
        } else if (val17 == 0 && prev17 == 1 && debounce17 == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last17.tv_sec) * 1000L +
                              (now.tv_nsec - last17.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(1) == 0) {
                    printf("Sensor 1 (GPIO17) tilted\n");
                }
                debounce17 = 1;
                last17 = now;
            }
        } else if (val17 == 1 && debounce17) {
            debounce17 = 0;
        }
        prev17 = val17;

        if (val18 < 0) {
            fprintf(stderr, "Read error on GPIO %d: %s\n", GPIO_18, strerror(errno));
        } else if (val18 == 0 && prev18 == 1 && debounce18 == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - last18.tv_sec) * 1000L +
                              (now.tv_nsec - last18.tv_nsec) / 1000000L;
            if (elapsed_ms >= DEBOUNCE_MS) {
                if (log_event(2) == 0) {
                    printf("Sensor 2 (GPIO18) tilted\n");
                }
                debounce18 = 1;
                last18 = now;
            }
        } else if (val18 == 1 && debounce18) {
            debounce18 = 0;
        }
        prev18 = val18;

        struct timespec sleep_ts = {0, POLL_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_ts, NULL);
    }

    cleanup();
    return 0;
}

