#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_I2C_ADDR 0x49
#define I2C_BUS "/dev/i2c-1"
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_als_vis(int fd, uint16_t *als_vis) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, ALS_VIS_LSB_REG, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, ALS_VIS_MSB_REG, &msb) < 0) return -1;
    *als_vis = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 ALS Visible Data Reader (I2C 0x%02X on %s)\n", SI1175_I2C_ADDR, I2C_BUS);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als_vis;
        if (read_als_vis(fd, &als_vis) < 0) {
            fprintf(stderr, "Error reading ALS visible data. Retrying in %d ms...\n", SAMPLE_INTERVAL_MS);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        printf("ALS Visible: %u\n", als_vis);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret_code;
}

