#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LEFT 2
#define GPIO_MIDDLE 3
#define GPIO_RIGHT 4
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_left = NULL;
    struct gpiod_line *line_middle = NULL;
    struct gpiod_line *line_right = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line_left = gpiod_chip_get_line(chip, GPIO_LEFT);
    line_middle = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    line_right = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!line_left || !line_middle || !line_right) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(line_left, "keywish-left") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LEFT, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line_middle, "keywish-middle") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_MIDDLE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(line_right, "keywish-right") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_RIGHT, strerror(errno));
        goto cleanup;
    }

    printf("Keywish 3-Way Tracking Sensor (libgpiod v1.x)\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (keep_running) {
        int left_val = gpiod_line_get_value(line_left);
        int middle_val = gpiod_line_get_value(line_middle);
        int right_val = gpiod_line_get_value(line_right);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line_left) gpiod_line_release(line_left);
    if (line_middle) gpiod_line_release(line_middle);
    if (line_right) gpiod_line_release(line_right);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

