 *   TTP226 TP2 -> BCM GPIO 6
 *   TTP226 TP3 -> BCM GPIO 13
 *   TTP226 TP4 -> BCM GPIO 19
 *   TTP226 TP5 -> BCM GPIO 26
 *   TTP226 TP6 -> BCM GPIO 12
 *   TTP226 TP7 -> BCM GPIO 16
 *   TTP226 TP8 -> BCM GPIO 20
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 *
 * Run:
 *   ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    printf("[%ld.%09ld] ", (long)ts.tv_sec, (long)ts.tv_nsec);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
