        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("CH%d=%d", i + 1, val);
        }
