#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ   1000
#define PWM_RANGE  255
#define FADE_STEPS 50
#define FADE_SEC   5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_pwm_color(int red, int green, int blue) {
    int red_val = 255 - red;
    int green_val = 255 - green;
    int blue_val = 255 - blue;

    if (gpioPWM(RED_PIN, red_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue_val) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN %d", BLUE_PIN);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on BLUE_PIN %d", BLUE_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on BLUE_PIN %d", BLUE_PIN);
        return -1;
    }
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on RED_PIN %d", RED_PIN);
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on GREEN_PIN %d", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on BLUE_PIN %d", BLUE_PIN);
        return -1;
    }
    return 0;
}

static int generate_hsv_to_rgb(int hue, int saturation, int value, int *r, int *g, int *b) {
    float h = (float)hue / 360.0f;
    float s = (float)saturation / 100.0f;
    float v = (float)value / 100.0f;

    if (s == 0.0f) {
        *r = (int)(v * 255.0f);
        *g = (int)(v * 255.0f);
        *b = (int)(v * 255.0f);
        return 0;
    }

    float h_i = (int)h;
    float f = h - h_i;
    float p = v * (1.0f - s);
    float q = v * (1.0f - s * f);
    float t = v * (1.0f - s * (1.0f - f));

    float h_f = h_i / 6.0f;
    float c = v * (1.0f - s);

    switch ((int)h_f) {
        case 0:
            *r = (int)(c * (1.0f + s * f));
            *g = (int)(c * (1.0f - s * f));
            *b = (int)(t);
            break;
        case 1:
            *r = (int)(t);
            *g = (int)(c * (1.0f + s * f));
            *b = (int)(c * (1.0f - s * f));
            break;
        case 2:
            *r = (int)(c * (1.0f - s * f));
            *g = (int)(t);
            *b = (int)(c * (1.0f + s * f));
            break;
        case 3:
            *r = (int)(c * (1.0f + s * f));
            *g = (int)(c * (1.0f - s * f));
            *b = (int)(t);
            break;
        case 4:
            *r = (int)(t);
            *g = (int)(c * (1.0f - s * f));
            *b = (int)(c * (1.0f + s * f));
            break;
        default:
            *r = (int)(c * (1.0f - s * f));
            *g = (int)(c * (1.0f + s * f));
            *b = (int)(t);
            break;
    }

    *r = (int)((*r + 128) / 2);
    *g = (int)((*g + 128) / 2);
    *b = (int)((*b + 128) / 2);

    if (*r < 0) *r = 0;
    if (*r > 255) *r = 255;
    if (*g < 0) *g = 0;
    if (*g > 255) *g = 255;
    if (*b < 0) *b = 0;
    if (*b > 255) *b = 255;

    return 0;
}

static int choose_random_hue(int *hue) {
    if (rand() == 0) {
        srand(time(NULL));
    }
    *hue = rand() % 360;
    return 0;
}

static int fade_color(int red, int green, int blue, int target_red, int target_green, int target_blue) {
    int step = FADE_STEPS;
    if (step <= 0) step = 1;

    for (int i = 0; i < step && g_running; i++) {
        int r = red + (target_red - red) * i / step;
        int g = green + (target_green - green) * i / step;
        int b = blue + (target_blue - blue) * i / step;

        if (set_pwm_color(r, g, b) < 0) {
            return -1;
        }
        gpioDelay(1000000 / step);
    }
    return 0;
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    int current_hue = 0;
    int target_hue = 0;

    while (g_running) {
        if (choose_random_hue(&current_hue) < 0) {
            syslog(LOG_ERR, "Failed to choose random hue");
            break;
        }

        if (choose_random_hue(&target_hue) < 0) {
            syslog(LOG_ERR, "Failed to choose target hue");
            break;
        }

        if (fade_color(current_hue, current_hue, current_hue, target_hue, target_hue, target_hue) < 0) {
            syslog(LOG_ERR, "PWM set failed during fade");
            break;
        }

        if (g_running) {
            gpioDelay(FADE_SEC * 1000000);
        }
    }

    if (g_running) {
        set_pwm_color(0, 0, 0);
    }

    gpioTerminate();
    closelog();
    return 0;
}

