#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define LED_PIN 17
#define RED_THRESHOLD 200
#define POLL_MS 200

#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write(fd, TCS34725_ENABLE, 0x01) < 0) return -1;
    usleep(3000);
    if (i2c_write(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t c_val, r_val, g_val, b_val;
    if (i2c_read(fd, TCS34725_CDATA, &c_val) < 0) return -1;
    if (i2c_read(fd, TCS34725_RDATA, &r_val) < 0) return -1;
    if (i2c_read(fd, TCS34725_GDATA, &g_val) < 0) return -1;
    if (i2c_read(fd, TCS34725_BDATA, &b_val) < 0) return -1;
    *c = (uint16_t)c_val;
    *r = (uint16_t)r_val;
    *g = (uint16_t)g_val;
    *b = (uint16_t)b_val;
    return 0;
}

static void calibrate(uint16_t raw, uint16_t *gain, uint16_t *offset) {
    *gain = raw / 4;
    *offset = raw - *gain;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        tcs34725_enable(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_enable(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led, "tcs34725_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_enable(i2c_fd);
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 initialized. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read failed, attempting re-initialization...\n");
            tcs34725_enable(i2c_fd);
            usleep(3000);
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting.\n");
                break;
            }
            continue;
        }

        uint16_t r_gain, r_offset, g_gain, g_offset, b_gain, b_offset;
        calibrate(c, &r_gain, &r_offset);
        calibrate(r, &r_gain, &r_offset);
        calibrate(g, &g_gain, &g_offset);
        calibrate(b, &b_gain, &b_offset);

        int led_state = (r_gain > RED_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led, led_state) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }

        printf("C: %5u, R: %5u, G: %5u, B: %5u\n", c, r, g, b);
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    tcs34725_enable(i2c_fd);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

