#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_CONV_MS 180
#define MAX_LUX 1000.0f
#define MIN_BRIGHTNESS 0
#define MAX_BRIGHTNESS 255
#define MAX_LUX_READINGS 1000.0f
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
            fprintf(stderr, "BH1750: write command failed (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }
        gpioDelay(BH1750_CONV_MS * 1000);
        int data = i2cReadDevice(handle, (char *)NULL, 2);
        if (data == 2) {
            uint16_t raw = ((uint16_t)(data[0] & 0xFF) << 8) | (uint16_t)(data[1] & 0xFF);
            *lux_out = (float)raw / 1.2f;
            return 0;
        }
        fprintf(stderr, "BH1750: read failed (attempt %d)\n", retries + 1);
        retries++;
        gpioDelay(100000);
    }
    return -1;
}

static int map_light_to_brightness(float lux) {
    if (lux <= 0.0f) return MIN_BRIGHTNESS;
    if (lux >= MAX_LUX_READINGS) return MAX_BRIGHTNESS;
    float log_lux = (float)log10f(lux + 1.0f);
    float norm = log_lux / log10f(MAX_LUX_READINGS + 1.0f);
    return (int)(MIN_BRIGHTNESS + norm * (MAX_BRIGHTNESS - MIN_BRIGHTNESS));
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    gpioWaveClear();
    gpioPulse_t pulses[NUM_LEDS * 4 + 1];
    int idx = 0;
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t color = ((uint32_t)brightness << 16) | ((uint32_t)brightness << 8) | brightness;
        for (int j = 0; j < 4; j++) {
            pulses[idx].gpioOn = (1 << LED_PIN);
            pulses[idx].gpioOff = 0;
            pulses[idx].usDelay = 1;
            idx++;
            pulses[idx].gpioOn = 0;
            pulses[idx].gpioOff = (1 << LED_PIN);
            pulses[idx].usDelay = 1;
            idx++;
        }
    }
    pulses[idx].gpioOn = 0;
    pulses[idx].gpioOff = 0;
    pulses[idx].usDelay = 0;
    idx++;
    if (gpioWaveAddGeneric(idx, pulses) < 0) {
        fprintf(stderr, "gpioWaveAddGeneric failed\n");
        return;
    }
    int wave_id = gpioWaveCreate();
    if (wave_id < 0) {
        fprintf(stderr, "gpioWaveCreate failed\n");
        return;
    }
    gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
    while (gpioWaveTxBusy()) gpioDelay(100);
    gpioWaveDelete(wave_id);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int bh_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (bh_handle < 0) {
        fprintf(stderr, "Failed to open BH1750 at 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        if (read_bh1750(bh_handle, &lux) != 0) {
            fprintf(stderr, "BH1750 read failed; retrying in 1s\n");
            sleep(1);
            continue;
        }
        int brightness = map_light_to_brightness(lux);
        set_led_brightness(brightness);
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        sleep(1);
    }

    i2cClose(bh_handle);
    gpioTerminate();
    return 0;
}

