#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define NUM_SENSORS 3
#define FADE_DELAY_MS 500
#define LOOP_DELAY_MS 100
#define CONVERSION_DELAY_MS 180

static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, 0x21) < 0) {
        fprintf(stderr, "Error: Failed to write One-Time High-Resolution Mode 2 command to BH1750 handle %d\n", handle);
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_MS * 1000);
    return 0;
}

static int read_bh1750(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 handle %d\n", handle);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int calculate_brightness(int lux) {
    return 31 - (lux * 31) / 65535;
}

static void set_led_brightness(int brightness) {
    if (spi_handle < 0) return;
    uint8_t data[4] = {0x00, 0x00, 0x00, brightness};
    int ret = spiWrite(spi_handle, (char *)data, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: SPI write failed (returned %d)\n", ret);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int valid_handles[NUM_SENSORS];
    int count = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        int h = i2cOpen(I2C_BUS, BH1750_ADDR_LOW, 0);
        if (h >= 0) {
            valid_handles[count++] = h;
            i2cClose(h);
        }
        h = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);
        if (h >= 0) {
            valid_handles[count++] = h;
            i2cClose(h);
        }
    }

    if (count == 0) {
        fprintf(stderr, "Error: No BH1750 sensors found on I2C bus %d\n", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < count; i++) {
        if (init_bh1750(valid_handles[i]) < 0) {
            fprintf(stderr, "Warning: Sensor %d initialization failed, skipping\n", i);
        }
    }

    while (running) {
        int lux_sum = 0;
        int valid_sensors = 0;
        for (int i = 0; i < count; i++) {
            int val = read_bh1750(valid_handles[i]);
            if (val >= 0) {
                lux_sum += val;
                valid_sensors++;
            }
        }

        if (valid_sensors == 0) {
            fprintf(stderr, "Warning: No valid sensor readings, using default brightness\n");
            set_led_brightness(31);
        } else {
            int avg_lux = lux_sum / valid_sensors;
            int brightness = calculate_brightness(avg_lux);
            set_led_brightness(brightness);
        }

        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

