#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int veml7700_init(int fd) {
    // Configuration register: integration time 100ms, gain 1/8
    // Bits: IT=100 (100ms), GAIN=001 (1/8), L=0, O=0
    uint16_t config = 0x0000;
    if (i2c_write_reg(fd, VEML7700_CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) == 0) {
            // Lux = raw * 0.0288 (simplified for default config)
            *lux = (float)raw * 0.0288f;
            return 0;
        }
        retries++;
        if (retries < MAX_RETRIES) {
            usleep(RETRY_DELAY_MS * 1000);
        }
    }
    fprintf(stderr, "Failed to read VEML7700 after %d retries\n", MAX_RETRIES);
    return -1;
}

int ws2812b_init(struct gpiod_line *line) {
    // Set line as output, initially low
    if (gpiod_line_request_output(line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void ws2812b_set_brightness(struct gpiod_line *line, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    // Simple threshold-based control for bit-banging feasibility
    if (brightness > 128) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }
}

void ws2812b_cleanup(struct gpiod_line *line) {
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;
    float lux;
    int brightness;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (ws2812b_init(line) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        ws2812b_cleanup(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        ws2812b_cleanup(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (veml7700_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        close(fd);
        ws2812b_cleanup(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (keep_running) {
        if (veml7700_read_lux(fd, &lux) == 0) {
            brightness = (int)(255 * powf(lux / 120000.0f, 1.0f / 2.2f));
            ws2812b_set_brightness(line, brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    close(fd);
    ws2812b_cleanup(line);
    gpiod_chip_close(chip);
    return 0;
}

