    fflush(stdout);

    for (int i = 0; i < LED_BLINK_Cycles; i++) {
        if (!running) break;
        if (gpiod_line_set_value(LED_PIN, 1) < 0) {
            log_event("Error: failed to set LED high");
            return;
        }
        usleep(LED_BLINK_ON_MS * 1000);
        if (gpiod_line_set_value(LED_PIN, 0) < 0) {
            log_event("Error: failed to set LED low");
            return;
