        if (gpiod_line_set_value(BUZZER_PIN, 1) < 0) {
            log_event("Error: failed to set buzzer high");
            return;
        }
        usleep(SELF_TEST_BUZZER_PATTERNS_MS_5 * 1000);
    }

    log_event("Self-test complete");
}

static int read_flame_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        log_event("Error: failed to read flame sensor");
        return -1;
    }
    return val;
}

static void activate_alert(void) {
    if (gpiod_line_set_value(BUZZER_PIN, 1) < 0) {
        log_event("Error: failed to activate buzzer");
        return;
    }
    if (gpiod_line_set_value(LED_PIN, 1) < 0) {
        log_event("Error: failed to activate LED");
        return;
    }
}

static void deactivate_alert(void) {
    if (gpiod_line_set_value(BUZZER_PIN, 0) < 0) {
        log_event("Error: failed to deactivate buzzer");
        return;
    }
    if (gpiod_line_set_value(LED_PIN, 0) < 0) {
        log_event("Error: failed to deactivate LED");
        return;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!flame_line || !buzzer_line || !led_line) {
        perror("gpiod_chip_get_line");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input (flame)");
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpiod_line_request_output(buzzer_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (led)");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    log_event("Flame sensor monitoring started");

    self_test();

    int flame_detected = 0;
    int consecutive_flame = 0;
    int error_count = 0;

    while (running) {
        int val = read_flame_sensor(flame_line);
        if (val < 0) {
            error_count++;
            if (error_count > 10) {
                log_event("Too many read errors, aborting");
                ret = EXIT_FAILURE;
                break;
            }
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }
        error_count = 0;

        if (val == FLAME_DETECTED) {
            consecutive_flame++;
            if (consecutive_flame >= SELF_TEST_READINGS) {
                log_event("Flame detected");
                activate_alert();
                flame_detected = 1;
            }
        } else {
            consecutive_flame = 0;
            if (flame_detected) {
                log_event("Flame gone");
                deactivate_alert();
                flame_detected = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (flame_line) gpiod_line_release(flame_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

