static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 to continuous high-res mode\n");
        return -1;
    }
    usleep(180000);
    return 0;
}

static int read_bh1750(int fd, uint16_t *raw) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float calculate_average_lux(const uint16_t *buffer, int size) {
    float sum = 0.0f;
    int count = 0;
    for (int i = 0; i < size; i++) {
        sum += (float)buffer[i];
        count++;
    }
    return (count > 0) ? (sum / count) : 0.0f;
}

static int gpio_export(int pin) {
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    gpio_exported = 1;
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open direction file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) < 0) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open value file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) < 0) {
        fprintf(stderr, "Failed to set value: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static void blink_led(int pin, float avg_lux) {
    float rate = 0.5f + (avg_lux / 1000.0f) * 4.5f;
    if (rate < 0.5f) rate = 0.5f;
    if (rate > 5.0f) rate = 5.0f;
    int half_period_us = (int)(rate * 1000000.0f / 2.0f);
    int on_us = half_period_us;
    int off_us = half_period_us;
    while (running) {
        gpio_set_value(pin, 1);
        usleep(on_us);
        if (!running) break;
        gpio_set_value(pin, 0);
        usleep(off_us);
    }
}

