        return 1;
    }

    if (gpio_set_direction(GPIO_LED, "out") < 0) {
        close(i2c_fd);
        return 1;
    }

    uint16_t lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (running) {
        uint16_t raw;
        if (read_bh1750(i2c_fd, &raw) < 0) {
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float lux = (float)raw / 1.2f;
        lux_buffer[buffer_index] = (uint16_t)raw;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) buffer_count++;

        float avg = calculate_average_lux(lux_buffer, buffer_count);
        blink_led(GPIO_LED, avg);
        printf("Lux: %.2f, Avg: %.2f\n", (float)raw, avg);
        usleep(SAMPLE_INTERVAL_US);
    }

