    gpio_set_value(GPIO_LED, 0);
    if (gpio_exported) {
        int fd = open("/sys/class/gpio/unexport", O_WRONLY);
        if (fd >= 0) {
            char buf[32];
            snprintf(buf, sizeof(buf), "%d", GPIO_LED);
            write(fd, buf, strlen(buf));
            close(fd);
        }
    }
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

