#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Segment patterns for digit 5 (common cathode: 1 = on)
const unsigned char digit5[8] = {
    0b01111, // a,b,c,d,e,f,g,dp
    0b01111,
    0b01111,
    0b01111,
    0b01111,
    0b01111,
    0b01111,
    0b01111
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

void cleanup(void) {
    if (latch_line) {
        gpiod_line_set_value(latch_line, 0);
        gpiod_line_release(latch_line);
    }
    if (clock_line) {
        gpiod_line_set_value(clock_line, 0);
        gpiod_line_release(clock_line);
    }
    if (data_line) {
        gpiod_line_set_value(data_line, 0);
        gpiod_line_release(data_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Failed to get GPIO lines");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("Failed to request GPIO lines as output");
        cleanup();
        return -1;
    }

    return 0;
}

void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        int bit = (data >> i) & 1;
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            perror("Failed to set clock high");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_value(data_line, bit) < 0) {
            perror("Failed to set data line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_value(clock_line, 0) < 0) {
            perror("Failed to set clock low");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        perror("Failed to set latch high");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(latch_line, 0) < 0) {
        perror("Failed to set latch low");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void display_digit(int digit) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }
    shift_out(digit5[digit]);
}

int main(void) {
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(5);
        usleep(500000); // 500 ms
        display_digit(0);
        usleep(500000); // 500 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

