#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_PERIOD_MS 2000
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge events */
    if (gpiod_line_request_falling_edge_events(button_line, "blink_button") < 0) {
        perror("gpiod_line_request_falling_edge_events (button)");
        goto cleanup;
    }

    /* Main loop */
    while (running) {
        /* Blink LED with 2-second period */
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("gpiod_line_set_value (LED on)");
            goto cleanup;
        }
        usleep(BLINK_PERIOD_MS * 1000);
        if (!running) break;

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("gpiod_line_set_value (LED off)");
            goto cleanup;
        }
        usleep(BLINK_PERIOD_MS * 1000);
    }

    /* Stop blinking on exit */
    gpiod_line_set_value(led_line, 0);

    printf("Button pressed! Exiting.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (led_line) gpiod_line_release(led_line);
    if (button_line) gpiod_line_release(button_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

