    ret = gpiod_line_request_output(led_line, "blink-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* Request button as input with internal pull-down */
    ret = gpiod_line_request_input_flags(btn_line, "blink-btn",
                                         GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("Blink LED on GPIO%d, button on GPIO%d. Press Ctrl+C to exit.\n",
           LED_PIN, BUTTON_PIN);

    while (running) {
        int val = gpiod_line_get_value(btn_line);
        if (val < 0) {
            perror("gpiod_line_get_value(BUTTON)");
            break;
        }

        if (val == 1) {
            /* Button pressed: blink LED */
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
