            if (ret < 0) {
                perror("gpiod_line_set_value(LED off)");
                break;
            }
            usleep(BLINK_MS * 1000);
        } else {
            /* Button released: turn LED off */
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("gpiod_line_set_value(LED off)");
                break;
            }
        }
    }

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (btn_line) {
        gpiod_line_release(btn_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

