#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

#define PWM_PERIOD_NS 10000000  // 10 ms = 100 Hz
#define PWM_DUTY_MAX 100
#define PWM_STEP_NS 1000        // 1 ms per step for busy-wait

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

void cleanup(void) {
    if (red_line) {
        gpiod_line_release(red_line);
        red_line = NULL;
    }
    if (green_line) {
        gpiod_line_release(green_line);
        green_line = NULL;
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
        blue_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int init_gpio(void) {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return -1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    if (!red_line) {
        perror("gpiod_chip_get_line (RED)");
        return -1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        perror("gpiod_chip_get_line (GREEN)");
        return -1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        perror("gpiod_chip_get_line (BLUE)");
        return -1;
    }

    struct gpiod_line_request_config config = {
        .consumer = "rgb_pwm",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    if (gpiod_line_request(red_line, &config, 0) < 0) {
        perror("gpiod_line_request (RED)");
        return -1;
    }
    if (gpiod_line_request(green_line, &config, 0) < 0) {
        perror("gpiod_line_request (GREEN)");
        return -1;
    }
    if (gpiod_line_request(blue_line, &config, 0) < 0) {
        perror("gpiod_line_request (BLUE)");
        return -1;
    }

    return 0;
}

void set_pwm_value(struct gpiod_line *line, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    int on_ns = (PWM_PERIOD_NS * duty) / PWM_DUTY_MAX;
    int off_ns = PWM_PERIOD_NS - on_ns;

    // Busy-wait with nanosleep for precision
    struct timespec ts = {
        .tv_sec = on_ns / 1000000000L,
        .tv_nsec = on_ns % 1000000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        // Retry if interrupted by signal
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value (on)");
    }
    ts.tv_sec = off_ns / 1000000000L;
    ts.tv_nsec = off_ns % 1000000000L;
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        // Retry if interrupted by signal
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value (off)");
    }
}

int main(void) {
    srand(time(NULL));

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    while (keep_running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        set_pwm_value(red_line, r);
        set_pwm_value(green_line, g);
        set_pwm_value(blue_line, b);

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

