#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM303_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0f
#define POLL_DELAY_US 100000
#define IMPACT_DURATION_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, expected=%u, got=%d)\n", reg, len, rc);
    }
    return rc;
}

static int init_lsm303(void) {
    if (i2c_write_byte(i2c_handle, CTRL_REG1_A, 0x27) < 0) return -1;
    if (i2c_write_byte(i2c_handle, CTRL_REG4_A, 0x00) < 0) return -1;
    return 0;
}

static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(i2c_handle, OUT_X_L_A | 0x80, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_g(int16_t x, int16_t y, int16_t z) {
    const float sensitivity = 16384.0f;
    float x_g = (float)x / sensitivity;
