#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_OUT_X_MSB   0x01

/* Expected device ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* Sensitivity for ±2g range: 4096 counts/g */
#define ACCEL_SENSITIVITY 4096.0f

/* Impact threshold: 2g acceleration -> 19.62 m/s^2 */
#define IMPACT_THRESHOLD_MPS2 19.62f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 50000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ sensor                                    */
/* ------------------------------------------------------------------ */
static int fxos8700_init(int handle)
{
    int status;

    /* Verify device identity */
    status = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I (I2C bus error): %d\n", status);
        return -1;
    }
    if (status != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                status, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (CTRL_REG1 bit 0 = 0) */
    status = i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to set standby mode: %d\n", status);
        return -1;
    }

    /* ±2g range, XYZ_DATA_CFG = 0x00 (14-bit left-justified, 2g/LSB) */
    status = i2cWriteByteData(handle, FXOS8700_XYZ_DATA_CFG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: failed to set XYZ_DATA_CFG: %d\n", status);
        return -1;
    }

    /* Active mode, 200 Hz ODR (CTRL_REG1 bits 3:0 = 0x04) */
    status = i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x04);
    if (status < 0) {
        fprintf(stderr, "Error: failed to set active mode: %d\n", status);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data and convert to m/s^2             */
/* ------------------------------------------------------------------ */
static int fxos8700_read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error: I2C block read failed: %d\n", status);
        return -1;
    }
    if (status != 6) {
        fprintf(stderr, "Error: short read (%d bytes)\n", status);
        return -1;
    }

    /* 14-bit left-justified data: shift right by 2 */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
