#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I        0x0F
#define WHO_AM_I_VAL    0xD3
#define CTRL_REG1       0x20
#define CTRL_REG4       0x23
#define OUT_X_L         0x28
#define SENSITIVITY     0.00875f
#define SAMPLE_RATE_HZ  20.0f
#define SAMPLE_PERIOD_US (1000000.0f / SAMPLE_RATE_HZ)
#define CAL_SAMPLES     100
#define THRESHOLD_DPS   50.0f
#define LOG_FILE        "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(int fd) {
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * SENSITIVITY;
    *y = (float)raw_y * SENSITIVITY;
    *z = (float)raw_z * SENSITIVITY;
    return 0;
}

static void calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off) {
    float x_sum = 0.0f, y_sum = 0.0f, z_sum = 0.0f;
    float x, y, z;
    for (int i = 0; i < CAL_SAMPLES; i++) {
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        usleep(1000);
    }
    *x_off = x_sum / CAL_SAMPLES;
    *y_off = y_sum / CAL_SAMPLES;
    *z_off = z_sum / CAL_SAMPLES;
}

static void log_data(FILE *fp, float x, float y, float z, float x_off, float y_off, float z_off) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, X: %.2f, Y: %.2f, Z: %.2f, X_off: %.2f, Y_off: %.2f, Z_off: %.2f\n",
            ts, x, y, z, x_off, y_off, z_off);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DPS) fprintf(stderr, "WARNING: X axis exceeds threshold: %.2f dps\n", x);
    if (fabsf(y) > THRESHOLD_DPS) fprintf(stderr, "WARNING: Y axis exceeds threshold: %.2f dps\n", y);
    if (fabsf(z) > THRESHOLD_DPS) fprintf(stderr, "WARNING: Z axis exceeds threshold: %.2f dps\n", z);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", GYRO_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_gyro(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    float x_off, y_off, z_off;
    calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off);

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        log_data(g_log_fp, x, y, z, x_off, y_off, z_off);
        check_threshold(x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

