#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define CTRL_REG2_A 0x21
#define CTRL_REG3_A 0x22
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28
#define OUT_X_H_A   0x29
#define OUT_Y_L_A   0x2A
#define OUT_Y_H_A   0x2B
#define OUT_Z_L_A   0x2C
#define OUT_Z_H_A   0x2D
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03

/* Accelerometer full-scale range: +/- 2g */
#define ACCEL_SCALE 0.000244f /* 1 mg/LSB */
#define MAG_SCALE   0.00014f  /* 0.14 mGauss/LSB */

static int i2c_accel_handle = -1;
static int i2c_mag_handle   = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_lsm303(void) {
    /* Accelerometer: 50 Hz, all axes enabled */
    if (write_reg(i2c_accel_handle, CTRL_REG1_A, 0x27) < 0) return -1;
    /* Accelerometer: +/- 2g full scale */
    if (write_reg(i2c_accel_handle, CTRL_REG4_A, 0x00) < 0) return -1;
    /* Magnetometer: continuous-conversion mode */
    if (write_reg(i2c_mag_handle, MR_REG_M, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(float *ax, float *ay, float *az) {
    uint8_t buf[6];
    if (read_block(i2c_accel_handle, OUT_X_L_A | 0x80, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *ax = (float)rx * ACCEL_SCALE;
    *ay = (float)ry * ACCEL_SCALE;
    *az = (float)rz * ACCEL_SCALE;
    return 0;
}

static int read_mag(float *mx, float *my, float *mz) {
    uint8_t buf[6];
    if (read_block(i2c_mag_handle, OUT_X_H_M, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
    *mx = (float)rx * MAG_SCALE;
    *my = (float)ry * MAG_SCALE;
    *mz = (float)rz * MAG_SCALE;
    return 0;
}

static float calc_heading(float mx, float my, float mz) {
    float len = sqrtf(mx * mx + my * my + mz * mz);
    if (len == 0.0f) return 0.0f;
    float h = atan2f(my, mx) * 180.0f / M_PI;
    if (h < 0.0f) h += 360.0f;
    return h;
}

static void log_data(float ax, float ay, float az, float mx, float my, float mz, float heading) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen compass_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            ts, ax, ay, az, mx, my, mz, heading);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_accel_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_accel_handle < 0) {
        fprintf(stderr, "Failed to open I2C for accelerometer: %d\n", i2c_accel_handle);
        gpioTerminate();
        return 1;
    }

    i2c_mag_handle = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_mag_handle < 0) {
        fprintf(stderr, "Failed to open I2C for magnetometer: %d\n", i2c_mag_handle);
        i2cClose(i2c_accel_handle);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialization failed\n");
        i2cClose(i2c_accel_handle);
        i2cClose(i2c_mag_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LSM303 compass running. Press Ctrl+C to stop.\n");

    while (program_running) {
        float ax, ay, az, mx, my, mz, heading;
        if (read_accel(&ax, &ay, &az) < 0) {
            fprintf(stderr, "Accelerometer read error\n");
        } else if (read_mag(&mx, &my, &mz) < 0) {
            fprintf(stderr, "Magnetometer read error\n");
        } else {
            heading = calc_heading(mx, my, mz);
            log_data(ax, ay, az, mx, my, mz, heading);
            printf("Heading: %.2f deg | Accel: %.3f, %.3f, %.3f g | Mag: %.3f, %.3f, %.3f G\n",
                   heading, ax, ay, az, mx, my, mz);
        }
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_accel_handle);
    i2cClose(i2c_mag_handle);
    gpioTerminate();
    return 0;
}

