#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define CONTROL_VALUE 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CONTROL_REG, CONTROL_VALUE) < 0) {
        fprintf(stderr, "Error: Failed to write control register to handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sample(int handle, int16_t *sample) {
    int data = i2cReadWordData(handle, DATA_REG);
    if (data < 0) {
        fprintf(stderr, "Error: Failed to read data from handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    *sample = (int16_t)data;
    return 0;
}

static void compute_tdoa(int16_t sample1, int16_t sample2, struct timespec *ts, long *tdoa_ns) {
    struct timespec ts1, ts2;
    clock_gettime(CLOCK_REALTIME, &ts1);
    clock_gettime(CLOCK_REALTIME, &ts2);
    long diff_ns = (ts2.tv_sec - ts1.tv_sec) * 1000000000L + (ts2.tv_nsec - ts1.tv_nsec);
    *tdoa_ns = diff_ns - (long)sample1 * 1000L - (long)sample2 * 1000L;
}

static int log_data(FILE *fp, struct timespec ts, int16_t sample1, int16_t sample2, long tdoa_ns) {
    if (fprintf(fp, "%ld %ld %d %d %ld\n", ts.tv_sec, ts.tv_nsec, sample1, sample2, tdoa_ns) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct timespec ts;
    long tdoa_ns;
    int16_t sample1, sample2;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle1) < 0 || init_sensor(i2c_handle2) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    while (running) {
        if (read_sample(i2c_handle1, &sample1) < 0 || read_sample(i2c_handle2, &sample2) < 0) {
            fprintf(stderr, "Warning: Sensor read failure, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        compute_tdoa(sample1, sample2, &ts, &tdoa_ns);
        if (log_data(log_file, ts, sample1, sample2, tdoa_ns) < 0) {
            fprintf(stderr, "Warning: Logging failed, continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

