#include <pigpio.h>

/* ADIS16488A SPI read protocol: send 16-bit word, receive 16-bit word back.
 * The requested register's data is returned on the next 16-bit transfer. */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0x80             /* CPHA=1, CPOL=1, aux SPI off */
#define SPI_MODE       3                /* mode 3: CPOL=1, CPHA=1 */

#define GYRO_X_REG     0x04
#define GYRO_Y_REG     0x06
#define GYRO_Z_REG     0x08
#define ACCEL_X_REG    0x0A
#define ACCEL_Y_REG    0x0C
#define ACCEL_Z_REG    0x0E

#define GYRO_SENSITIVITY 0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

#define SAMPLE_PERIOD_US 100000      /* 100 ms */
#define STALL_DELAY_US   40          /* 40 us stall between request and data */

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Read one 16-bit register from the ADIS16488A.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, float *out)
{
    uint8_t tx[2] = { 0x00, (uint8_t)(reg << 1) };
    uint8_t rx[2] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *out = (float)raw * (GYRO_SENSITIVITY / 2.0f); /* ADIS16488A outputs X/Y/Z in mid-scale */
    return 0;
}

static int read_gyro(float *x, float *y, float *z)
{
    return read_register(GYRO_X_REG, x);
}

static int read_accel(float *x, float *y, float *z)
{
    return read_register(ACCEL_X_REG, x);
}

