{
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d, flags 0x%08X)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("imu_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    while (!terminate) {
        float gx = 0, gy = 0, gz = 0, ax = 0, ay = 0, az = 0;
        int err = 0;

        err |= read_gyro(&gx, &gy, &gz);
        err |= read_accel(&ax, &ay, &az);

        if (err) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                    ts, gx, gy, gz, ax, ay, az);
            fflush(fp);
        }

        /* Non-blocking delay so signals are caught promptly */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && !terminate) {
            uint32_t chunk = (remaining > 10000) ? 10000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

