/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI bus 0, chip-select GPIO8 (libgpiod), spidev ioctl
 * Reads gyroscope and accelerometer data via single-register read protocol.
 *
 * Build: gcc -O2 -Wall -o adis16448 adis16448.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ADIS16448 register addresses (single-register read protocol) */
#define REG_XGYRO_OUT  0x04
#define REG_YGYRO_OUT  0x06
#define REG_ZGYRO_OUT  0x08
#define REG_XACCL_OUT  0x0A
#define REG_YACCL_OUT  0x0C
#define REG_ZACCL_OUT  0x0E

/* SPI configuration */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

/* GPIO chip and line for chip-select (libgpiod) */
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8          /* GPIO8 = SPI0 CE0 */

/* Scale factors (from ADIS16448 datasheet) */
#define GYRO_SCALE      0.02f      /* dps/LSB */
#define ACCEL_SCALE     0.00025f   /* g/LSB */

/* Sampling interval */
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single 16-bit register via the ADIS16448 single-register read protocol.
 * Protocol: first 16-bit cycle (mode 0, MSB first) sends the 8-bit register
 * address with bit 7 set (0x80), then a dummy byte.  Second 16-bit cycle
 * sends a dummy byte, then the 16-bit data response.
 * Returns 0 on success, -1 on error. */
static int adis_read_reg(int spi_fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Small delay between the two 16-bit cycles */
    usleep(10);

    tr.tx_buf = (unsigned long)(uint8_t[2] { 0x00, 0x00 });
    tr.rx_buf = (unsigned long)(uint8_t[2] { 0, 0 });
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI dummy transfer failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request CS line */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "Cannot request CS line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16448 reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t gx, gy, gz, ax, ay, az;

        if (adis_read_reg(spi_fd, REG_XGYRO_OUT, &gx) < 0 ||
            adis_read_reg(spi_fd, REG_YGYRO_OUT, &gy) < 0 ||
            adis_read_reg(spi_fd, REG_ZGYRO_OUT, &gz) < 0 ||
            adis_read_reg(spi_fd, REG_XACCL_OUT, &ax) < 0 ||
            adis_read_reg(spi_fd, REG_YACCL_OUT, &ay) < 0 ||
            adis_read_reg(spi_fd, REG_ZACCL_OUT, &az) < 0) {
            fprintf(stderr, "SPI read error — continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float gx_dps = gx * GYRO_SCALE;
        float gy_dps = gy * GYRO_SCALE;
        float gz_dps = gz * GYRO_SCALE;
        float ax_g   = ax * ACCEL_SCALE;
        float ay_g   = ay * ACCEL_SCALE;
        float az_g   = az * ACCEL_SCALE;

        printf("Gyro: X=%.2f Y=%.2f Z=%.2f dps, Accel: X=%.4f Y=%.4f Z=%.4f g\n",
               gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

