#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0

#define ADIS16448_REG_XGYRO_OUT 0x04
#define ADIS16448_REG_YGYRO_OUT 0x06
#define ADIS16448_REG_ZGYRO_OUT 0x08
#define ADIS16448_REG_XACCL_OUT 0x0A
#define ADIS16448_REG_YACCL_OUT 0x0C
#define ADIS16448_REG_ZACCL_OUT 0x0E

#define GYRO_SCALE 0.05f
#define ACCL_SCALE 0.00025f

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint16_t *value) {
    char tx[4] = {0};
    char rx[4] = {0};

    tx[0] = (reg | 0x80) << 1;
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[3];
    return 0;
}

static int spi_write_register(uint8_t reg, uint16_t value) {
    char tx[4] = {0};
    char rx[4] = {0};

    tx[0] = (reg & 0x7F) << 1;
    tx[1] = (value >> 8) & 0xFF;
    tx[2] = value & 0xFF;

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accl_x, float *accl_y, float *accl_z) {
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    uint16_t raw_accl_x, raw_accl_y, raw_accl_z;

    if (spi_read_register(ADIS16448_REG_XGYRO_OUT, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(ADIS16448_REG_YGYRO_OUT, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(ADIS16448_REG_ZGYRO_OUT, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(ADIS16448_REG_XACCL_OUT, &raw_accl_x) != 0) return -1;
    if (spi_read_register(ADIS16448_REG_YACCL_OUT, &raw_accl_y) != 0) return -1;
    if (spi_read_register(ADIS16448_REG_ZACCL_OUT, &raw_accl_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accl_x = (float)raw_accl_x * ACCL_SCALE;
    *accl_y = (float)raw_accl_y * ACCL_SCALE;
    *accl_z = (float)raw_accl_z * ACCL_SCALE;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d)\n", SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;

    while (!terminate) {
        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z, &accl_x, &accl_y, &accl_z) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/s | Accel: X=%.2f, Y=%.2f, Z=%.2f g\n",
                   gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        gpioDelay(100000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

