    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU6886 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms (Ctrl+C to stop).\n");

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 3;
        int success = 0;

        while (retries > 0 && !success) {
            if (read_accel_gyro(fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
                success = 1;
            } else {
                retries--;
                if (retries > 0) {
                    usleep(10000);
                }
            }
        }

        if (success) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
        }

        usleep(50000);
    }

    printf("\nExiting gracefully.\n");
    close(fd);
    return EXIT_SUCCESS;
}

