#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_RANGE 0x2C
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define POLL_DELAY_US 10000
#define LED_ON_DELAY_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int adxl345_write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int adxl345_init(int handle) {
    uint8_t devid = 0;
    if (adxl345_read_register(handle, ADXL345_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID - sensor absent or bus error\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0xE5)\n", devid);
        return -1;
    }

    if (adxl345_write_register(handle, ADXL345_RANGE, 0x00) < 0) return -1;
    if (adxl345_write_register(handle, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (adxl345_write_register(handle, ADXL345_DATA_FORMAT, 0x00) < 0) return -1;
    if (adxl345_write_register(handle, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: %d\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float xg = (float)x / 256.0f;
    float yg = (float)y / 256.0f;
    float zg = (float)z / 256.0f;
    return sqrtf(xg * xg + yg * yg + zg * zg);
}

static void log_impact(float magnitude, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            timestamp, magnitude, x, y, z);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);
            if (magnitude > IMPACT_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_DELAY_US);
                gpioWrite(LED_GPIO, 0);
                log_impact(magnitude, x, y, z);
            }
        } else {
            fprintf(stderr, "Sensor read error - continuing\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

