#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I     0x75
#define WHO_AM_I_VAL 0x12
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 Hz) */
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result != (int)len) {
        fprintf(stderr, "Error reading burst from 0x%02X: expected %u bytes, got %d\n",
                reg, len, result);
        return -1;
    }
    return 0;
}

static int initialize_imu(void) {
    uint8_t who_am_i = 0;

    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (write_register(i2c_handle, PWR_MGMT_1, 0x00) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms stabilization */

    /* Set accelerometer range to +/-2g */
    if (write_register(i2c_handle, ACCEL_CONFIG, 0x00) != 0) {
        return -1;
    }

    /* Set gyroscope range to +/-250 dps */
    if (write_register(i2c_handle, GYRO_CONFIG, 0x00) != 0) {
        return -1;
    }

    return 0;
}

static int read_imu_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];

    if (read_burst(i2c_handle, ACCEL_XOUT_H, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);

    if (read_burst(i2c_handle, GYRO_XOUT_H, buf, sizeof(buf)) != 0) {
        return -1;
    }

    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ICM20602_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (initialize_imu() != 0) {
        fprintf(stderr, "IMU initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,ax,ay,az,gx,gy,gz\n");
    fflush(log_file);

    int16_t ax, ay, az, gx, gy, gz;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_US};

    while (!terminate) {
        if (read_imu_data(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }
        nanosleep(&sleep_time, NULL);
    }

    fprintf(stderr, "\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

