#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6D
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define CTRL3_C 0x12
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

#define ACCEL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define FREEFALL_WINDOW 1.0f
#define SAMPLE_RATE 104.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int read_block(uint8_t reg, char *buf, uint32_t len) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) return -1;
    return i2cReadDevice(i2c_handle, buf, len);
}

static int init_lsm6dsr(void) {
    char id;
    if (read_block(WHO_AM_I, &id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I\n");
        return -1;
    }
    if ((uint8_t)id != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X)\n", (uint8_t)id, WHO_AM_I_VAL);
        return -1;
    }

    if (write_reg(CTRL1_XL, 0x80) != 0) return -1;
    if (write_reg(CTRL2_G, 0x40) != 0) return -1;
    if (write_reg(CTRL3_C, 0x00) != 0) return -1;
    return 0;
}

static int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    if (read_block(OUTX_L_G, buf, 6) != 6) return -1;
    int16_t gx = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t gy = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t gz = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    int16_t ax = (int16_t)((buf[7] << 8) | (uint8_t)buf[6]);
    int16_t ay = (int16_t)((buf[9] << 8) | (uint8_t)buf[8]);
    int16_t az = (int16_t)((buf[11] << 8) | (uint8_t)buf[10]);
    data->x = (float)gx / 131.0f;
    data->y = (float)gy / 131.0f;
    data->z = (float)gz / 131.0f;
    data->x -= 64.0f;
    data->y -= 64.0f;
    data->z -= 64.0f;
    return 0;
}

static void log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm = localtime(&ts.tv_sec);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s.%09ld,%.3f,%.3f,%.3f\n", timestamp, ts.tv_nsec, data->x, data->y, data->z);
    fflush(log_file);
}

static void detect_fall(const sensor_data_t *data) {
    static float accel_mag = 0.0f;
    static struct timespec fall_start = {0, 0};
    static int in_freefall = 0;

    float mag = sqrtf(data->x * data->x + data->y * data->y + data->z * data->z);
    if (mag < ACCEL_THRESHOLD) {
        if (!in_freefall) {
            in_freefall = 1;
            fall_start = *time(NULL);
        }
    } else {
        if (in_freefall) {
            double elapsed = (fall_start.tv_sec - (double)fall_start.tv_sec) +
                             (fall_start.tv_nsec - 1000000000.0) / 1e9;
            if (elapsed >= FREEFALL_WINDOW) {
                if (mag > IMPACT_THRESHOLD) {
                    printf("Impact detected!\n");
                }
                in_freefall = 0;
            }
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "Error: LSM6DSR init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t data;
    while (!terminate) {
        if (read_sensor_data(&data) == 0) {
            log_data(&data);
            detect_fall(&data);
        } else {
            fprintf(stderr, "Error: I2C read failed\n");
        }
        gpioDelay(1000000 / SAMPLE_RATE);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

