/*
 * ADIS16266 Gyroscope SPI Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for SPI communication.
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0)
 *   ADIS16266 SDO -> GPIO9  (SPI0 MISO)
 *   ADIS16266 SDA -> GPIO10 (SPI0 MOSI)
 *   ADIS16266 SCL -> GPIO11 (SPI0 SCLK)
 *   ADIS16266 VDD -> 3.3V
 *   ADIS16266 GND -> GND
 *
 * Build: gcc -o gyro gyro.c -lpigpio -lrt
 * Run:   sudo ./gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_REG_XGYRO_OUT  0x14
#define ADIS16266_REG_WHO_AM_I   0x00
#define ADIS16266_WHO_AM_I_VAL   0x3F5A

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0x3      /* Mode 3: CPOL=1, CPHA=1 */

/* Gyroscope scale factor (degrees/sec per LSB) */
#define GYRO_SCALE 0.0305f

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16266 via SPI.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t reg, uint16_t *value) {
    char tx[2];
    char rx[2];
    int ret;

    /* ADIS16266 SPI read: send register address (bit 7 set) */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }

    /* ADIS16266 returns data in the second byte of the response */
    *value = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0];
    return 0;
}

/* Write a 16-bit register to the ADIS16266 via SPI.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int write_register(uint8_t reg, uint16_t value) {
    char tx[2];
    char rx[2];
    int ret;

    tx[0] = (char)(reg & 0x7F);  /* clear bit 7 for write */
    tx[1] = (char)(value & 0xFFFF);

    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    return 0;
}

/* Initialize the ADIS16266 gyroscope.
 * Returns 0 on success, -1 on failure. */
static int init_gyro(void) {
    uint16_t who_am_i;

    /* Verify device identity */
    if (read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%04X (expected 0x%04X)\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Optional: configure sensor (e.g., set sample rate, enable gyro) */
    /* For production, refer to ADIS16266 datasheet and application notes */
    return 0;
}

/* Read the X-axis angular rate in degrees/sec. */
static int read_gyro_x(float *angle) {
    uint16_t raw;

    if (read_register(ADIS16266_REG_XGYRO_OUT, &raw) != 0) {
        return -1;
    }

    *angle = (float)raw * GYRO_SCALE;
    return 0;
}

/* Log a timestamped reading to the CSV file. */
