#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GYRO_ADDR 0x69
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define GYRO_SENSITIVITY 8.75f
#define SAMPLE_INTERVAL_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gyro(void) {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
            fprintf(stderr, "Error: Failed to write CTRL_REG1 (0x0F)\n");
            retries--;
            gpioDelay(10000);
            continue;
        }
        if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
            fprintf(stderr, "Error: Failed to write CTRL_REG4 (0x00)\n");
            retries--;
            gpioDelay(10000);
            continue;
        }
        int who = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who < 0) {
            fprintf(stderr, "Error: Failed to read WHO_AM_I\n");
            retries--;
            gpioDelay(10000);
            continue;
        }
        if (who != WHO_AM_I_VAL) {
            fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
            retries--;
            gpioDelay(10000);
            continue;
        }
        printf("Gyroscope initialized successfully (WHO_AM_I=0x%02X)\n", who);
        return 0;
    }
    fprintf(stderr, "Error: Gyroscope initialization failed after retries\n");
    return -1;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int bytes = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buf, 6);
    if (bytes != 6) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes)\n", bytes);
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(log_file, "%s.%09ld,%.3f,%.3f,%.3f\n", timestamp, ts.tv_nsec, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", GYRO_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_gyro() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t raw_x, raw_y, raw_z;
    float x, y, z;

    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            x = (float)raw_x / GYRO_SENSITIVITY;
            y = (float)raw_y / GYRO_SENSITIVITY;
            z = (float)raw_z / GYRO_SENSITIVITY;
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

