#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor.  Returns 0 (flame), 1 (no flame), or          */
/* PI_BAD_GPIO on error.                                           */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d (pigpio error %d)\n",
                FLAME_SENSOR_GPIO, level);
        return -1;
    }
    return (level == 0) ? 0 : 1;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped event line to the log file.                      */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_event(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input with internal pull-up ---- */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n",
                FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file in append mode ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected < 0) {
            /* Sensor read error — log and continue */
            if (log_event(-1) != 0) {
                fprintf(stderr, "Error: failed to log sensor read error\n");
            }
        } else {
            /* Flame detected (active-low) */
            if (log_event(flame_detected) != 0) {
                fprintf(stderr, "Error: failed to log flame event\n");
            }
            if (flame_detected) {
                printf("FLAME DETECTED!\n");
                fflush(stdout);
            }
        }

        /* Sleep 500 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

