#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_US      100000  /* 100 ms */

/* D7S-0001 acceleration registers (0x28-0x2D, 6 bytes per axis) */
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, uint8_t reg_msb,
                          int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Probe: read the sensor's device ID register (0x00) to confirm it is present */
    uint8_t id;
    if (i2c_read_reg8(g_i2c_fd, 0x00, &id) < 0) {
        fprintf(stderr, "D7S-0001 not responding at 0x%02X on %s\n",
                D7S_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    printf("D7S-0001 detected at 0x%02X on %s\n", D7S_ADDR, I2C_BUS);

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        fflush(g_log_fp);
    }

    printf("Logging D7S-0001 acceleration to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;

        if (i2c_read_reg16(g_i2c_fd, REG_X_LSB, REG_X_MSB, &x) < 0) {
            fprintf(stderr, "Skipping sample due to X-axis read error\n");
        } else if (i2c_read_reg16(g_i2c_fd, REG_Y_LSB, REG_Y_MSB, &y) < 0) {
            fprintf(stderr, "Skipping sample due to Y-axis read error\n");
        } else if (i2c_read_reg16(g_i2c_fd, REG_Z_LSB, REG_Z_MSB, &z) < 0) {
            fprintf(stderr, "Skipping sample due to Z-axis read error\n");
        } else {
            if (log_data(g_log_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed for this sample\n");
            }
        }

        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

