#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define MMA8452Q_WHO_AM_I    0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x2A
#define MMA8452Q_CTRL_REG1   0x2A
#define MMA8452Q_OUT_X_L     0x01
#define MMA8452Q_OUT_X_H     0x02
#define MMA8452Q_OUT_Y_L     0x03
#define MMA8452Q_OUT_Y_H     0x04
#define MMA8452Q_OUT_Z_L     0x05
#define MMA8452Q_OUT_Z_H     0x06

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear bit 0 of CTRL_REG1 */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1 (standby): %s\n", strerror(errno));
        return -1;
    }

    /* Data rate: 100 Hz (0b010) */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x02) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1 (data rate): %s\n", strerror(errno));
        return -1;
    }

    /* Active mode: set bit 0 */
    if (i2c_write_reg8(fd, MMA8452Q_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1 (active): %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_L, buf, 6) < 0) {
        fprintf(stderr, "Error: failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]) >> 4;
    *y = (int16_t)((buf[3] << 8) | buf[2]) >> 4;
    *z = (int16_t)((buf[5] << 8) | buf[4]) >> 4;
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x;
    double y_g = (double)y;
    double z_g = (double)z;
    return atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error: failed to set I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mma8452q(i2c_fd) < 0) {
        fprintf(stderr, "Error: MMA8452Q initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open fall_log.txt: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Monitoring tilt angle (threshold 45 degrees)...\n");

    while (running) {
        int16_t x, y, z;
        if (read_accelerometer(i2c_fd, &x, &y, &z) < 0) {
            /* I2C error already printed; skip this sample */
            usleep(10000);
            continue;
        }

        double tilt = calculate_tilt_angle(x, y, z);
        if (fabs(tilt) > 45.0) {
            log_fall(x, y, z);
            printf("Fall detected! Logged: X=%d, Y=%d, Z=%d, Tilt=%.2f\n", x, y, z, tilt);
        }

        usleep(10000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

