#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define OUT_X_H        0x29
#define OUT_Y_L        0x2A
#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define SENSITIVITY    0.146f   /* +-4 gauss -> mG/LSB */
#define THRESHOLD_MG   800.0f
#define LOG_FILE       "magnetic_log.txt"
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0) return -1;  /* ODR=80Hz, HP mode */
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0) return -1;  /* Z axis high perf */
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0) return -1;  /* X/Y high perf */
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    if (i2c_read_reg(fd, OUT_X_L, &x_l) < 0) return -1;
    if (i2c_read_reg(fd, OUT_X_H, &x_h) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_L, &y_l) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Y_H, &y_h) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_L, &z_l) < 0) return -1;
    if (i2c_read_reg(fd, OUT_Z_H, &z_h) < 0) return -1;
    int16_t x_raw = (int16_t)((x_h << 8) | x_l);
    int16_t y_raw = (int16_t)((y_h << 8) | y_l);
    int16_t z_raw = (int16_t)((z_h << 8) | z_l);
    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > THRESHOLD_MG) {
        fprintf(stderr, "Metal detected! Total field: %.2f mG\n", mag);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LIS3MDL_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    int retries = 0;
    while (init_lis3mdl(g_i2c_fd) < 0) {
        retries++;
        fprintf(stderr, "LIS3MDL init failed (attempt %d/%d)\n", retries, MAX_RETRIES);
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "LIS3MDL init failed after %d attempts. Exiting.\n", MAX_RETRIES);
            close(g_i2c_fd);
            return 1;
        }
        sleep(1);
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("LIS3MDL initialized. Logging to %s at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Read error; continuing.\n");
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

