#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_STATUS    0x04
#define ADXL354B_REG_XDATA_L   0x08
#define ADXL354B_REG_YDATA_L   0x0B
#define ADXL354B_REG_ZDATA_L   0x0E
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET     0x1F
#define ADXL354B_REG_PARTID    0x01

// ADXL354B Constants
#define ADXL354B_SENSITIVITY 0.0000039f  // 3.9 microg/LSB for +-2g range
#define ADXL354B_RESET_CMD   0x52
#define ADXL354B_PARTID_VAL  0x1D
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl354b_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx, rx, 2);
        if (result == 2) {
            *value = (uint8_t)rx[1];
            return 0;
        }
        fprintf(stderr, "SPI read error on reg 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
        gpioDelay(1000);
        retries--;
    }
    return -1;
}

static int adxl354b_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = {0};
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx, rx, 2);
        if (result == 2) {
            return 0;
        }
        fprintf(stderr, "SPI write error on reg 0x%02X: %d, retries left: %d\n", reg, result, retries - 1);
        gpioDelay(1000);
        retries--;
    }
    return -1;
}

static int adxl354b_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    if (adxl354b_read_register(ADXL354B_REG_XDATA_L, &x_l) != 0) return -1;
    if (adxl354b_read_register(ADXL354B_REG_XDATA_H, &x_h) != 0) return -1;
    if (adxl354b_read_register(ADXL354B_REG_YDATA_L, &y_l) != 0) return -1;
    if (adxl354b_read_register(ADXL354B_REG_YDATA_H, &y_h) != 0) return -1;
    if (adxl354b_read_register(ADXL354B_REG_ZDATA_L, &z_l) != 0) return -1;
    if (adxl354b_read_register(ADXL354B_REG_ZDATA_H, &z_h) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);
    return 0;
}

static int adxl354b_init(void) {
    uint8_t partid;
    if (adxl354b_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID register\n");
        return -1;
    }
    if (partid != ADXL354B_PARTID_VAL) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID_VAL);
        return -1;
    }

    if (adxl354b_write_register(ADXL354B_REG_RESET, ADXL354B_RESET_CMD) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000);

    if (adxl354b_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to clear POWER_CTL\n");
        return -1;
    }
    gpioDelay(1000);

    if (adxl354b_write_register(ADXL354B_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }
    gpioDelay(1000);

    uint8_t status;
    int retries = 10;
    while (retries > 0) {
        if (adxl354b_read_register(ADXL354B_REG_STATUS, &status) == 0) {
            if ((status & 0x02) == 0) {
                break;
            }
        }
        fprintf(stderr, "Status STABLE bit not set (0x%02X), retries left: %d\n", status, retries - 1);
        gpioDelay(1000);
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "ADXL354B did not enter stable mode\n");
        return -1;
    }

    return 0;
}

static void log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 0) | (1 << 6));
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_init() != 0) {
        fprintf(stderr, "ADXL354B initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

