#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADIS16362 Register Addresses (MSB=1 indicates read)
#define REG_X_GYRO 0x04
#define REG_Y_GYRO 0x06
#define REG_Z_GYRO 0x08
#define REG_X_ACCL 0x0A
#define REG_Y_ACCL 0x0C
#define REG_Z_ACCL 0x0E

// Scaling factors (from ADIS16362 datasheet)
#define GYRO_SCALE 0.05f  // deg/sec/LSB
#define ACCL_SCALE 0.0025f // g/LSB

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0 // Mode 3: active-high clock, sampled on trailing edge

// Global variables for cleanup
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(uint8_t reg_addr, int16_t *data);
int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                  float *accel_x, float *accel_y, float *accel_z);
int log_data(float gyro_x, float gyro_y, float gyro_z,
             float accel_x, float accel_y, float accel_z);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Read a 16-bit register from the ADIS16362
// Protocol: send [reg_addr | 0x80] as 2 bytes, then read 2 bytes
int spi_read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Build the read request: [reg_addr | 0x80] (MSB=1 for read)
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00; // Dummy byte to clock out data

    // Transfer the request
    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error on reg 0x%02X: returned %d\n", reg_addr, result);
        return -1;
    }

    // Read the data (2 bytes)
    result = spiXfer(spi_handle, rx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read error on reg 0x%02X: returned %d\n", reg_addr, result);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed value
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    return 0;
}

// Read the 3-axis gyroscope and 3-axis accelerometer data
int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                  float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (spi_read_register(REG_X_GYRO, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(REG_Y_GYRO, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(REG_Z_GYRO, &raw_gyro_z) != 0) return -1;

    // Read accelerometer data
    if (spi_read_register(REG_X_ACCL, &raw_accel_x) != 0) return -1;
    if (spi_read_register(REG_Y_ACCL, &raw_accel_y) != 0) return -1;
    if (spi_read_register(REG_Z_ACCL, &raw_accel_z) != 0) return -1;

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCL_SCALE;
    *accel_y = (float)raw_accel_y * ACCL_SCALE;
    *accel_z = (float)raw_accel_z * ACCL_SCALE;

    return 0;
}

// Log the data to a CSV file
int log_data(float gyro_x, float gyro_y, float gyro_z,
             float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
    struct tm *tm_info;
    char timestamp[40];

