    if (spi_read_register(REG_X_GYRO, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(REG_Y_GYRO, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(REG_Z_GYRO, &raw_gyro_z) != 0) return -1;

    // Read accelerometer data
    if (spi_read_register(REG_X_ACCL, &raw_accel_x) != 0) return -1;
    if (spi_read_register(REG_Y_ACCL, &raw_accel_y) != 0) return -1;
    if (spi_read_register(REG_Z_ACCL, &raw_accel_z) != 0) return -1;

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCL_SCALE;
    *accel_y = (float)raw_accel_y * ACCL_SCALE;
    *accel_z = (float)raw_accel_z * ACCL_SCALE;

    return 0;
}

