#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        return;
    }
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] ", buffer);
}

static void log_message(const char *message) {
    log_timestamp();
    printf("%s\n", message);
    fflush(stdout);
}

static void self_parking_sequence(void) {
    log_message("Self-parking sequence started");
    sleep(2);
    log_message("Self-parking sequence completed");
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Register signal handler for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("Failed to open gpiochip4");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as input */
    ret = gpiod_line_request_input(line, "e18-d80nk-self-parking");
    if (ret < 0) {
        perror("Failed to request GPIO line 17 as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Self-parking sensor monitoring started (GPIO17, E18-D80NK, 30cm range)");

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line 17");
            break;
        }

        if (value == 0) {
            self_parking_sequence();
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up resources on exit */
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    log_message("Self-parking sensor monitoring stopped");
    return EXIT_SUCCESS;
}

