/*
 * Collision avoidance system using two Keyes KY-032 IR obstacle sensors.
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod v2 API
 *
 * Wiring:
 *   KY-032 VCC  -> 3.3 V (pin 1)
 *   KY-032 GND  -> GND   (pin 9)
 *   KY-032 OUT  -> GPIO17 (pin 11)  [active-low: 0 = obstacle, 1 = clear]
 *   KY-032 OUT  -> GPIO27 (pin 13)  [active-low: 0 = obstacle, 1 = clear]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO17           17
#define GPIO27           27
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");
    printf("[%s] ", ts);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get the two GPIO lines --- */
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO17, strerror(errno));
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO27, strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines as inputs (consumer label) --- */
    if (gpiod_line_request_input(line17, "ky032-ir-17") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line27, "ky032-ir-27") < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO27, strerror(errno));
        goto cleanup;
    }

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");
    printf("  Sensor 1: GPIO%d (active-low)\n", GPIO17);
    printf("  Sensor 2: GPIO%d (active-low)\n", GPIO27);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int v17, v27;

        /*
         * gpiod_line_request_input() returns a line object that is
         * valid for the lifetime of the request.  We use a single
         * bulk read via gpiod_line_request_get_values() to read
         * both sensors in a single call.
         */
        struct gpiod_line_request_config req_cfg = {
            .consumer     = "ky032-ir-both",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        };

        if (gpiod_line_request_get_values(line17, &req_cfg, &v17) < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO17, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_get_values(line27, &req_cfg, &v27) < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO27, strerror(errno));
            goto cleanup;
        }

        /* KY-032 output is active-low: 0 = obstacle detected, 1 = clear */
        print_timestamp();
        printf("Sensor 1: %s  Sensor 2: %s\n",
               v17 == 0 ? "OBSTACLE" : "CLEAR",
               v27 == 0 ? "OBSTACLE" : "CLEAR");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (line17)
        gpiod_line_release(line17);
    if (line27)
        gpiod_line_release(line27);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

