#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define ADIS16266_REG_X_OUT 0x04
#define ADIS16266_REG_Y_OUT 0x06
#define ADIS16266_REG_Z_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24
#define ADIS16266_MSC_CTRL_DATA_READY 0x01
#define SCALE_FACTOR 0.02f
#define CS_PIN_LINE 8
#define CONSUMER "adis16266_spi"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adis16266_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int adis16266_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int adis16266_read_xyz(int fd, float *x, float *y, float *z) {
    uint8_t tx[4] = { (uint8_t)(ADIS16266_REG_X_OUT | 0x80), 0x00, 0x00, 0x00 };
    uint8_t rx[4] = {0};

    if (spi_transfer(fd, tx, rx, 4) < 0) return -1;

    int16_t raw_x = (int16_t)((rx[2] << 8) | rx[3]);
    int16_t raw_y = (int16_t)((rx[4] << 8) | rx[5]);
    int16_t raw_z = (int16_t)((rx[6] << 8) | rx[7]);

    *x = (float)raw_x * SCALE_FACTOR;
    *y = (float)raw_y * SCALE_FACTOR;
    *z = (float)raw_z * SCALE_FACTOR;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_PIN_LINE);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, CONSUMER, 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (adis16266_write_reg(spi_fd, ADIS16266_REG_MSC_CTRL, ADIS16266_MSC_CTRL_DATA_READY) < 0) {
        fprintf(stderr, "Failed to enable data ready mode\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    while (running) {
        float x, y, z;
        if (adis16266_read_xyz(spi_fd, &x, &y, &z) == 0) {
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }
        usleep(100000);
    }

    printf("\nExiting...\n");
    gpiod_line_set_value(cs_line, 1);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    return 0;
}

