#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C 7-bit address */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities for default settings */
#define GYRO_SENSITIVITY  0.00875f   /* dps/LSB  */
#define ACCEL_SENSITIVITY 0.000061f  /* g/LSB   */

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Burst-read 12 bytes starting at OUTX_L_G (0x22).
 *   Bytes 0-5 : gyro X/Y/Z (6 bytes)
 *   Bytes 6-11 : accel X/Y/Z (6 bytes)
 * Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z,
                            float *accel_x, float *accel_y, float *accel_z)
{
    char buf[12];

    if (i2cReadI2CBlockData(handle, OUTX_L_G, buf, 12) != 12) {
        fprintf(stderr, "Error: failed to read 12-byte burst from OUTX_L_G\n");
        return -1;
    }

    int16_t raw_gyro_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_gyro_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_gyro_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    int16_t raw_accel_x = (int16_t)((buf[7] << 8) | (uint8_t)buf[6]);
    int16_t raw_accel_y = (int16_t)((buf[9] << 8) | (uint8_t)buf[8]);
    int16_t raw_accel_z = (int16_t)((buf[11] << 8) | (uint8_t)buf[10]);

    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

int main(void)
{
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    int who = i2cReadByteData(g_i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, LSM6DSR_WHO_AM_I);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure accelerometer: +-2g, 104 Hz --- */
    if (i2cWriteByteData(g_i2c_handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1_XL\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure gyroscope: +-250 dps, 104 Hz --- */
    if (i2cWriteByteData(g_i2c_handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error: failed to write CTRL2_G\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &gyro_x, &gyro_y, &gyro_z,
                             &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

