#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to VDD) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_CTRL_REG2   0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB   0x01

/* Magnetometer scale factor (LSB/gauss) */
#define FXOS8700_M_SCALE 0.15f

/* Accelerometer scale factor (LSB/g) */
#define FXOS8700_A_SCALE 0.000061f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on error */
static int reg_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

/* Read one byte from a register; returns 0 on success, -1 on error */
static int reg_read(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read N bytes starting at reg; returns 0 on success, -1 on error */
static int reg_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, expected %u, got %d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* Initialize the FXOS8700 sensor in hybrid mode */
static int init_fxos8700(int handle) {
    uint8_t who_am_i = 0;

    /* Verify sensor identity */
    if (reg_read(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (clear hybrid bit) */
    if (reg_write(handle, FXOS8700_CTRL_REG1, 0x00) != 0) return -1;
    gpioDelay(1000); /* 1 ms */

    /* Configure magnetometer: hybrid mode, 80 Hz ODR */
    if (reg_write(handle, FXOS8700_M_CTRL_REG1, 0x0D) != 0) return -1;
    if (reg_write(handle, FXOS8700_M_CTRL_REG2, 0x00) != 0) return -1;

    /* Configure accelerometer: hybrid mode, 80 Hz ODR */
    if (reg_write(handle, FXOS8700_CTRL_REG1, 0x0D) != 0) return -1;

    gpioDelay(1000); /* 1 ms settling */
    return 0;
}

/* Read 12-byte combined data block and convert to g's and gauss */
static int read_fxos8700(int handle, float *ax, float *ay, float *az,
                          float *mx, float *my, float *mz) {
    uint8_t buf[12];

    if (reg_read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0) {
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 */
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit, no shift needed */
    int16_t raw_mx = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t raw_my = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_mz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = (float)raw_ax * FXOS8700_A_SCALE;
    *ay = (float)raw_ay * FXOS8700_A_SCALE;
    *az = (float)raw_az * FXOS8700_A_SCALE;
    *mx = (float)raw_mx * FXOS8700_M_SCALE;
    *my = (float)raw_my * FXOS8700_M_SCALE;
    *mz = (float)raw_mz * FXOS8700_M_SCALE;
    return 0;
}

int main(void) {
    float ax, ay, az, mx, my, mz;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, FXOS8700_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Reading every 100 ms (Ctrl+C to stop)\n");

    /* Main loop */
    while (g_running) {
        if (read_fxos8700(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%.3f g  Y=%.3f g  Z=%.3f g\n", ax, ay, az);
            printf("Mag:  X=%.3f gauss  Y=%.3f gauss  Z=%.3f gauss\n", mx, my, mz);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Cleanup */
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

