#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_DEVID 0xE5
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int adxl345_init(int fd) {
    uint8_t devid;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Error: Failed to read DEVID register: %s\n", strerror(errno));
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "Error: Invalid DEVID (0x%02X). Sensor not present.\n", devid);
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to write DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accelerometer data: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void calculate_tilt_angles(int16_t x, int16_t y, int16_t z, float *angle_x, float *angle_y, float *angle_z) {
    *angle_x = atan2((float)x, sqrt((float)y * y + (float)z * z)) * 180.0 / M_PI;
    *angle_y = atan2((float)y, sqrt((float)x * x + (float)z * z)) * 180.0 / M_PI;
    *angle_z = atan2((float)z, sqrt((float)x * x + (float)y * y)) * 180.0 / M_PI;
}

void log_tilt_event(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);
    fclose(fp);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: ADXL345 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("ADXL345 initialized. Logging tilt events exceeding %.1f degrees...\n", TILT_THRESHOLD);

    while (running) {
        int16_t x, y, z;
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            float angle_x, angle_y, angle_z;
            calculate_tilt_angles(x, y, z, &angle_x, &angle_y, &angle_z);

            if (fabs(angle_x) > TILT_THRESHOLD || fabs(angle_y) > TILT_THRESHOLD || fabs(angle_z) > TILT_THRESHOLD) {
                log_tilt_event(angle_x);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read accelerometer data. Retrying...\n");
        }
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, ADXL345_REG_POWER_CTL, 0x08);
        close(i2c_fd);
    }
    return 0;
}

