#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_SECONDS 5
#define ALERT_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the line is defined when the sensor is disconnected */
    if (gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed for GPIO %d.\n", SOUND_SENSOR_GPIO);
    }

    return 0;
}

static int read_sound_level(void)
{
    int level = gpioRead(SOUND_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed for GPIO %d (code %d).\n",
                SOUND_SENSOR_GPIO, level);
        return -1;
    }
    return level;
}

static int count_high_readings(int threshold)
{
    int count = 0;
    for (int i = 0; i < WINDOW_SECONDS * 10 && g_running; i++) {
        int level = read_sound_level();
        if (level < 0) {
            return -1;
        }
        if (level == 1) {
            count++;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    return count;
}

static void print_timestamped_alert(int high_count, int threshold)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    printf("[%s] ALERT: High readings count (%d) exceeds threshold (%d).\n",
           timestamp, high_count, threshold);
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: integer >= 1 (number of high readings per 5-second window)\n");
        return EXIT_FAILURE;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring sound levels on GPIO%d. Threshold: %d high readings per 5-second window.\n",
           SOUND_SENSOR_GPIO, threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int high_count = count_high_readings(threshold);
        if (high_count < 0) {
            fprintf(stderr, "Error: failed to read sound sensor during window.\n");
            break;
        }

        if (high_count > threshold) {
            print_timestamped_alert(high_count, threshold);
        } else {
            printf("Status: %d high reading(s) in window.\n", high_count);
            fflush(stdout);
        }

        /* Sleep ALERT_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < ALERT_INTERVAL_S && g_running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
    }

    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

