/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12V electromagnetic door locks (active-HIGH relay modules via TIP120)
 * on GPIO17 (Door A) and GPIO27 (Door B).  libgpiod C API.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 * Run:    ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define DOOR_A_PIN    17
#define DOOR_B_PIN    27
#define UNLOCK_SEC    5
#define CODE_LEN      6
#define LOG_FILE      "access_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int generate_code(char *code, size_t len)
{
    for (size_t i = 0; i < len; i++) {
        code[i] = (rand() % 10) + '0';
    }
    return 0;
}

static int log_access(const char *code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, (unsigned long long)code);
    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL, *line_b = NULL;
    char code[CODE_LEN];
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    srand((unsigned)time(NULL));

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        goto cleanup;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        perror("gpiod_chip_get_line(DOOR_A_PIN)");
        goto cleanup;
    }
    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        perror("gpiod_chip_get_line(DOOR_B_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(line_a)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line_b, "door_access", 0) != 0) {
        perror("gpiod_line_request_output(line_b)");
        goto cleanup;
    }

    if (generate_code(code, sizeof(code)) != 0) {
        fprintf(stderr, "Failed to generate random code.\n");
        goto cleanup;
    }
    printf("Security code: %s\n", code);
    fflush(stdout);

    while (g_running) {
        printf("Enter 6-digit security code: ");
        fflush(stdout);

        char input[CODE_LEN + 1];
        int n = getline(&input, NULL, stdin);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("getline");
            break;
        }
        if (n == 0) {
            printf("Invalid input. Please enter a 6-digit code.\n");
            continue;
        }

        /* Strip trailing newline */
        input[n - 1] = '\0';
        for (int i = 0; i < n; i++) {
            char c = input[i];
            if (!isdigit((unsigned char)c)) {
                input[i] = '\0';
                printf("Invalid input. Please enter a 6-digit code.\n");
                fflush(stdout);
                continue;
            }
        }

        if (strncmp(input, code, n) == 0) {
            printf("Access granted!\n");
            fflush(stdout);

            if (gpiod_line_set_value(line_a, 1) != 0) {
                perror("gpiod_line_set_value(line_a, 1)");
                break;
            }
            sleep(UNLOCK_SEC);
            if (gpiod_line_set_value(line_a, 0) != 0) {
                perror("gpiod_line_set_value(line_a, 0)");
                break;
            }

            if (log_access(code) != 0) {
                fprintf(stderr, "Warning: failed to log access.\n");
            }

            if (generate_code(code, sizeof(code)) != 0) {
                fprintf(stderr, "Failed to generate new code.\n");
                break;
            }
            printf("New security code: %s\n", code);
            fflush(stdout);
        } else {
            printf("Access denied.\n");
            fflush(stdout);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Drive outputs LOW before releasing */
    if (line_a) gpiod_line_set_value(line_a, 0);
    if (line_b) gpiod_line_set_value(line_b, 0);
    if (line_a) gpiod_line_release(line_a);
    if (line_b) gpiod_line_release(line_b);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }
    return ret;
}

