#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define CONVERSION_TIME_MS 180
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_illuminance(int fd, float *lux) {
    uint8_t cmd = 0x21; // One-Time High-Resolution Mode 2
    uint8_t data[2];

    if (i2c_write_byte(fd, cmd) < 0) {
        return -1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    if (i2c_read_bytes(fd, data, 2) < 0) {
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    *lux = (float)raw * 5.0 / 6.0;
    return 0;
}

int log_data(FILE *fp, float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Starting BH1750 light sensor logging. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (read_illuminance(i2c_fd, &lux) == 0) {
            if (log_data(log_fp, lux) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read illuminance, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

