#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_PERIOD_NS 10000000  // 10ms period for 50Hz PWM
#define PWM_DUTY_MAX 1000000    // 100% duty cycle

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_magnetometer(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

float calculate_magnitude(int16_t z) {
    return (float)fabs((float)z);
}

void set_led_brightness(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_DUTY_MAX) duty_cycle = PWM_DUTY_MAX;
    int on_ns = (duty_cycle * PWM_PERIOD_NS) / PWM_DUTY_MAX;
    int off_ns = PWM_PERIOD_NS - on_ns;
    gpiod_line_set_value(led_line, 1);
    gpiod_line_set_value(led_line, 0);
    usleep(on_ns / 1000);
    usleep(off_ns / 1000);
}

void cleanup() {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_magnetometer(i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Magnetometer interface started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping sample\n");
            usleep(100000);
            continue;
        }

        float magnitude = calculate_magnitude(z);
        int duty_cycle = (int)(magnitude * 100);
        set_led_brightness(duty_cycle);
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

