#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C block read error (reg 0x%02X, expected %d): got %d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_hmc5883l(int handle) {
    if (write_reg(handle, HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (write_reg(handle, HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (write_reg(handle, HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (read_block(handle, HMC5883L_DATA_X_MSB, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void compute_hard_iron(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                              int16_t *x_off, int16_t *y_off, int16_t *z_off) {
    *x_off += raw_x;
    *y_off += raw_y;
    *z_off += raw_z;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t x_off = 0, y_off = 0, z_off = 0;
    int16_t raw_x, raw_y, raw_z;
    int sample_count = 0;

    while (running) {
        if (read_magnetometer(i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            sample_count++;
            if (sample_count >= SAMPLE_WINDOW) {
                compute_hard_iron(raw_x, raw_y, raw_z, &x_off, &y_off, &z_off);
                sample_count = 0;
            }
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }

        int16_t corrected_x = raw_x - x_off;
        int16_t corrected_y = raw_y - y_off;
        int16_t corrected_z = raw_z - z_off;

        printf("X: %d, Y: %d, Z: %d\n", corrected_x, corrected_y, corrected_z);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

