/*
 * LSM303D accelerometer monitor with GPIO interrupt on INT1.
 * Board: Raspberry Pi Zero W
 * I2C bus: /dev/i2c-1, LSM303D address 0x1D (SA0 high)
 * INT1: GPIO23 (BCM 23, physical pin 16)
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_INT1_PIN    23

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define BUFFER_SIZE    64
#define SAMPLE_PERIOD_US 10000  /* 10 ms */
#define THRESHOLD_MG    2000
#define THRESHOLD_LSB   (THRESHOLD_MG / 16)

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x[BUFFER_SIZE];
    int16_t y[BUFFER_SIZE];
    int16_t z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void cb_init(circular_buffer_t *cb) {
    memset(cb->x, 0, sizeof(cb->x));
    memset(cb->y, 0, sizeof(cb->y));
    memset(cb->z, 0, sizeof(cb->z));
    cb->head = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, int16_t x, int16_t y, int16_t z) {
    cb->x[cb->head] = x;
    cb->y[cb->head] = y;
    cb->z[cb->head] = z;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* ---- I2C helpers ---- */
static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_smbus_read_byte_data(fd, reg) < 0) return -1;
    *val = (uint8_t)i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, buf) < 0) return -1;
    return 0;
}

/* ---- LSM303D ---- */
static int lsm303d_init(int fd) {
    uint8_t who;
    if (i2c_read_byte(fd, LSM303D_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "I2C read error on WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    /* Accel: 50 Hz ODR, all axes enabled, +/-2g */
    if (i2c_write_byte(fd, LSM303D_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    /* Mag: disabled */
    if (i2c_write_byte(fd, LSM303D_CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    /* INT1: threshold 2000 mg (125 LSB), duration 0 (immediate) */
    if (i2c_write_byte(fd, LSM303D_INT1_CFG, (uint8_t)(THRESHOLD_LSB)) < 0) {
        fprintf(stderr, "Failed to write INT1_CFG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int lsm303d_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, LSM303D_OUT_X_L_A | 0x80, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "I2C block read error: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ---- GPIO interrupt ---- */
static void int1_isr(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s.%03ld] INT1 triggered - dumping last %d samples\n",
           ts_str, ts.tv_nsec / 1000000, BUFFER_SIZE);
    fflush(stdout);

    circular_buffer_t *cb = &g_cb;
    int n = (cb->count < BUFFER_SIZE) ? cb->count : BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        int idx = (cb->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        int16_t x = cb->x[idx];
        int16_t y = cb->y[idx];
        int16_t z = cb->z[idx];
        printf("  sample %d: X=%6d Y=%6d Z=%6d\n", i, x, y, z);
    }
    cb->head = 0;
    cb->count = 0;
}

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_int1_line) {
        gpiod_line_set_value(g_int1_line, 0);
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2c_smbus_write_byte_data(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    circular_buffer_t g_cb;
    cb_init(&g_cb);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D init failed\n");
        close(g_i2c_fd);
        return 1;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, LSM303D_INT1_PIN);
    if (!g_int1_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LSM303D_INT1_PIN, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return 1;
    }

    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d-int1") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                LSM303D_INT1_PIN, strerror(errno));
        gpiod_chip_close(g_chip);
        close(g_i2c_fd);
        return 1;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("LSM303D monitor running. Press Ctrl-C to exit.\n");

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);
    int16_t ax, ay, az;

    while (g_running) {
        if (lsm303d_read_accel(g_i2c_fd, &ax, &ay, &az) < 0) {
            /* I2C error: warn and keep going */
            fprintf(stderr, "Warning: I2C read error, skipping sample\n");
        } else {
            cb_push(&g_cb, ax, ay, az);
        }

        /* Poll for interrupt (rising edge) */
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - next.tv_sec) * 1000000L +
                       (now.tv_nsec - next.tv_nsec);
        if (elapsed >= SAMPLE_PERIOD_US) {
            int1_isr();
            next = now;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

