#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define UART_PORT1 "/dev/serial0"
#define UART_PORT2 "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_MS 2000
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int serial_fd1 = -1;
static int serial_fd2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed for %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed for %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_code(int fd, char *code, int *timeout_sec) {
    char buffer[32];
    int idx = 0;
    *timeout_sec = 0;

    while (running && idx < CODE_LENGTH) {
        char c;
        ssize_t n = read(fd, &c, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                *timeout_sec = 0;
                continue;
            }
            fprintf(stderr, "UART read error on %s: %s\n", fd ? UART_PORT1 : UART_PORT2, strerror(errno));
            return -1;
        } else if (n == 0) {
            *timeout_sec = 0;
            continue;
        }

        if (c >= '0' && c <= '9') {
            code[idx++] = c;
        } else {
            if (idx > 0) {
                code[idx] = '\0';
                return 0;
            }
            *timeout_sec = 0;
            continue;
        }
    }

    if (idx == CODE_LENGTH) {
        return 0;
    }

    if (idx > 0) {
        code[idx] = '\0';
    }
    *timeout_sec = 0;
    return -1;
}

static int compare_codes(const char *code1, const char *code2) {
    return strcmp(code1, code2);
}

static int unlock_doors(void) {
    if (gpioWrite(LOCK1_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO17 HIGH\n");
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO27 HIGH\n");
        gpioWrite(LOCK1_GPIO, 0);
        return -1;
    }
    printf("Unlocking doors...\n");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(LOCK1_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO17 LOW\n");
        return -1;
    }
    if (gpioWrite(LOCK2_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO27 LOW\n");
        return -1;
    }
    printf("Doors locked.\n");
    return 0;
}

static void cleanup(void) {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    if (serial_fd1 >= 0) {
        close(serial_fd1);
        serial_fd1 = -1;
    }
    if (serial_fd2 >= 0) {
        close(serial_fd2);
        serial_fd2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) < 0 || gpioSetMode(LOCK2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    serial_fd1 = init_serial(UART_PORT1);
    if (serial_fd1 < 0) {
        gpioTerminate();
        return 1;
    }

    serial_fd2 = init_serial(UART_PORT2);
    if (serial_fd2 < 0) {
        close(serial_fd1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Press Ctrl+C to exit.\n");

    char code1[CODE_LENGTH] = {0};
    char code2[CODE_LENGTH] = {0};
    int code1_ready = 0;
    int code2_ready = 0;
    int code1_valid = 0;
    int code2_valid = 0;
    int code1_match = 0;
    int code2_match = 0;
    int code_match = 0;

    while (running) {
        int r1 = read_code(serial_fd1, code1, &code1_ready);
        int r2 = read_code(serial_fd2, code2, &code2_ready);

        if (r1 == 0 && code1_ready) {
            code1_valid = 1;
            code1_match = compare_codes(code1, "123456");
            if (code1_match == 0) {
                code1_match = 1;
            }
        } else if (r1 < 0) {
            fprintf(stderr, "Error reading code from %s\n", UART_PORT1);
        }

        if (r2 == 0 && code2_ready) {
            code2_valid = 1;
            code2_match = compare_codes(code2, "123456");
            if (code2_match == 0) {
                code2_match = 1;
            }
        } else if (r2 < 0) {
            fprintf(stderr, "Error reading code from %s\n", UART_PORT2);
        }

        if (code1_valid && code2_valid) {
            if (code1_match && code2_match) {
                code_match = 1;
            }
        }

        if (code_match) {
            if (unlock_doors() == 0) {
                code_match = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

