#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define RELAY_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void log_warning(const char *message) {
    log_event(LOG_WARNING, message);
}

static void log_info(const char *message) {
    log_event(LOG_INFO, message);
}

static void log_error(const char *message) {
    log_event(LOG_ERR, message);
}

static void log_shutdown(void) {
    log_event(LOG_INFO, "Shutting down...");
    closelog();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_info("Starting door strike system...");

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open gpiochip0");
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get relay line");
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_error("Failed to request PIR line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_error("Failed to request relay line as output");
        goto cleanup;
    }

    log_info("GPIO lines initialized successfully.");

    time_t last_motion_time = 0;
    time_t current_time = time(NULL);
    int relay_state = 0;

    while (program_running) {
        int pir_value = gpiod_line_get_value(pir_line);
        if (pir_value < 0) {
            log_error("Failed to read PIR sensor");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            time_t now = time(NULL);
            if (now - last_motion_time > FAILSAFE_TIMEOUT_S) {
                log_warning("Potential PIR sensor malfunction: motion detected continuously for >10s");
                relay_state = 0;
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    log_error("Failed to de-energize relay on failsafe");
                }
            } else {
                log_info("Motion detected!");
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    log_error("Failed to energize relay");
                }
                relay_state = 1;
                last_motion_time = now;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (relay_line) {
        if (relay_state) {
            gpiod_line_set_value(relay_line, 0);
        }
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    log_shutdown();
    return ret;
}

