#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22
#define TIMER_INTERVAL_SEC 60
#define RELAY_ON_TIME_SEC 300
#define NUM_RELAYS 4

static volatile sig_atomic_t program_running = 1;

static const int relay_gpios[NUM_RELAYS] = {RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO};

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) != 0) {
            log_message(LOG_ERR, "Failed to set GPIO mode for relay channel %d", i);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_gpios[i], 1) != 0) { /* HIGH = OFF (active-LOW relay) */
            log_message(LOG_ERR, "Failed to initialize relay channel %d to OFF", i);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void set_relay_state(int relay_index, int state) {
    if (relay_index < 0 || relay_index >= NUM_RELAYS) {
        log_message(LOG_ERR, "Invalid relay index: %d", relay_index);
        return;
    }
    if (gpioWrite(relay_gpios[relay_index], state) != 0) {
        log_message(LOG_ERR, "Failed to write to relay GPIO %d", relay_gpios[relay_index]);
    }
}

static void timer_callback(int timer_id, void *user_data) {
    (void)timer_id;
    (void)user_data;

    static int current_action = 0; /* 0 = activation, 1 = pause, 2 = deactivation */
    static int relay_activation_index = 0;
    static int relay_deactivation_index = 0;
    static int relay_activation_count = 0;
    static int relay_deactivation_count = 0;

    if (current_action == 0) {
        relay_activation_index = (relay_activation_index + 1) % NUM_RELAYS;
        relay_activation_count++;
        if (relay_activation_count == NUM_RELAYS) {
            current_action = 1;
        }
    } else if (current_action == 1) {
        if (relay_activation_count == NUM_RELAYS) {
            current_action = 2;
        }
    } else if (current_action == 2) {
        relay_deactivation_index = (relay_deactivation_index + 1) % NUM_RELAYS;
        relay_deactivation_count++;
        if (relay_deactivation_count == NUM_RELAYS) {
            current_action = 0;
        }
    }

    int relay_index = 0;
    if (current_action == 0) {
        relay_index = relay_activation_index;
    } else if (current_action == 2) {
        relay_index = relay_deactivation_index;
    }

    if (current_action == 0) {
        set_relay_state(relay_index, 0); /* LOW = ON (active-LOW relay) */
        log_message(LOG_INFO, "Relay channel %d activated", relay_index);
    } else if (current_action == 2) {
        set_relay_state(relay_index, 1); /* HIGH = OFF */
        log_message(LOG_INFO, "Relay channel %d deactivated", relay_index);
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register signal handler");
        closelog();
        return 1;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return 1;
    }

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        gpioTerminate();
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (program_running) {
        sleep(1);
    }

    /* Deactivate all relays before cleanup */
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(i, 1);
    }

    gpioSetTimerFuncEx(0, TIMER_INTERVAL_SEC, NULL, NULL); /* disable timer */
    gpioTerminate();
    closelog();
    return 0;
}

