static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_reg8(fd, ACCEL_XOUT_H, &buf[0]) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static int read_latest_data(void) {
    FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open sysfs file: %s\n", strerror(errno));
        return -1;
    }
    if (fscanf(fp, "%d,%d,%d", &accel_buffer[buffer_index][0], &accel_buffer[buffer_index][1], &accel_buffer[buffer_index][2]) != 3) {
        fprintf(stderr, "Failed to parse sysfs data\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    return 0;
}

static void timer_callback(struct itimerspec *it, struct sigevent *se) {
    (void)it; (void)se;
    float x, y, z;
    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
        if (read_latest_data() == 0) {
            printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return 1;
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    timer_id = timer_create(CLOCK_MONOTONIC, &its, NULL);
    if (timer_id < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", strerror(errno));
        timer_delete(timer_id);
        close(i2c_fd);
        return 1;
    }
    if (timer_add(timer_id, &its, NULL) < 0) {
        fprintf(stderr, "Failed to add timer: %s\n", strerror(errno));
        timer_delete(timer_id);
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 data logging started. Press Ctrl+C to stop.\n");

    while (running) {
        read_latest_data();
        usleep(100000);
    }

    printf("\nShutting down...\n");
    timer_delete(timer_id);
    close(i2c_fd);
    return 0;
}

