#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define RELAY1_INTERVAL 2
#define RELAY2_INTERVAL 3
#define RELAY3_INTERVAL 5
#define RELAY4_INTERVAL 7

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set relay value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_lines[4] = {NULL};
    int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int relay_intervals[4] = {RELAY1_INTERVAL, RELAY2_INTERVAL, RELAY3_INTERVAL, RELAY4_INTERVAL};
    struct timespec next_time[4];
    int i;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(relay_lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < 4; i++) {
        if (set_relay(relay_lines[i], 0) < 0) {
            goto cleanup;
        }
    }

    for (i = 0; i < 4; i++) {
        next_time[i].tv_sec = 0;
        next_time[i].tv_nsec = (long)relay_intervals[i] * 1000000000L;
    }

    while (running) {
        for (i = 0; i < 4; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
                fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
                continue;
            }

            if (now.tv_sec > next_time[i].tv_sec ||
                (now.tv_sec == next_time[i].tv_sec && now.tv_nsec >= next_time[i].tv_nsec)) {
                if (set_relay(relay_lines[i], 1) < 0) {
                    goto cleanup;
                }
                next_time[i].tv_sec += (next_time[i].tv_sec > next_time[i].tv_sec + (long)relay_intervals[i] ||
                                        next_time[i].tv_sec == next_time[i].tv_sec + (long)relay_intervals[i] &&
                                        next_time[i].tv_nsec >= next_time[i].tv_nsec);
                else {
                    next_time[i].tv_nsec += (long)relay_intervals[i] * 1000000000L;
                    if (next_time[i].tv_nsec >= 1000000000L) {
                        next_time[i].tv_sec += 1;
                        next_time[i].tv_nsec -= 1000000000L;
                    }
                }
            }
        }
        struct timespec sleep_time = {0, 100000000L};
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    for (i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            set_relay(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

