#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define ALARM_DURATION_MS 3000
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_alarm_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Alarm triggered\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_relay(void) {
    if (gpioWrite(RELAY_GPIO, 1) != 0) {
        fprintf(stderr, "Error activating relay (gpioWrite failed)\n");
        return -1;
    }

    gpioDelay(ALARM_DURATION_MS * 1000);

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error deactivating relay (gpioWrite failed)\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting sound sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing relay state\n");
        gpioTerminate();
        return 1;
    }

    printf("Sound-activated alarm system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_GPIO);

        if (sound_detected < 0) {
            fprintf(stderr, "Error reading sound sensor GPIO\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sound_detected == 1) {
            printf("Sound detected! Activating alarm.\n");

            if (activate_relay() != 0) {
                fprintf(stderr, "Alarm activation failed\n");
            }

            if (log_alarm_event() != 0) {
                fprintf(stderr, "Failed to log alarm event\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");

    return 0;
}

