int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Read multiple bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading %d bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

