    }

    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch. Expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I_VAL, who_am_i);
