    // Initialize circular buffer
    circular_buffer_t gyro_buffer;
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("MPU-6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
