#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define READ_INTERVAL_SEC 5
#define READ_TIMEOUT_MS 1000
#define READ_RETRY_DELAY_US 1000
#define MHZ19B_CMD_LEN 9
#define MHZ19B_CMD 0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79
#define MHZ19B_RESPONSE_LEN 9

static int uart_handle = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void log_error(const char *message) {
    if (!error_log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log_file, "%s: %s\n", ts, message);
    fflush(error_log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error opening UART %s: %d", UART_DEVICE, uart_handle);
        log_error(msg);
        return -1;
    }
    return 0;
}

static int read_mhz19b(float *co2_ppm) {
    unsigned char cmd[MHZ19B_CMD_LEN];
    unsigned char buf[MHZ19B_RESPONSE_LEN];
    int total = 0;
    int elapsed = 0;

    memset(cmd, 0, sizeof(cmd));
    memcpy(cmd, MHZ19B_CMD, MHZ19B_CMD_LEN);

    if (serWrite(uart_handle, (char *)cmd, MHZ19B_CMD_LEN) != MHZ19B_CMD_LEN) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error writing command to UART", uart_handle);
        log_error(msg);
        return -1;
    }

    gpioDelay(100000); /* 100 ms */

    while (total < MHZ19B_RESPONSE_LEN && elapsed < READ_TIMEOUT_MS) {
        int avail = serDataAvailable(uart_handle);
        if (avail < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Error checking UART data availability: %d", avail);
            log_error(msg);
            return -1;
        }
        if (avail > 0) {
            int n = serRead(uart_handle, (char *)(buf + total), MHZ19B_RESPONSE_LEN - total);
            if (n < 0) {
                char msg[128];
                snprintf(msg, sizeof(msg), "Error reading from UART: %d", n);
                log_error(msg);
                return -1;
            }
            total += n;
            elapsed += n * 1000 / BAUD_RATE;
        } else {
            gpioDelay(READ_RETRY_DELAY_US);
        }
    }

    if (total != MHZ19B_RESPONSE_LEN) {
        char msg[128];
        snprintf(msg, sizeof(msg), "UART read timeout: got %d of %d bytes", total, MHZ19B_RESPONSE_LEN);
        log_error(msg);
        return -1;
    }

    unsigned char checksum = 0;
    for (int i = 1; i < MHZ19B_RESPONSE_LEN; i++) {
        checksum += buf[i];
    }
    checksum = (checksum + 1) & 0xFF;

    if (checksum != buf[MHZ19B_RESPONSE_LEN - 1]) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Checksum mismatch: calc=0x%02X recv=0x%02X", checksum, buf[MHZ19B_RESPONSE_LEN - 1]);
        log_error(msg);
        return -1;
    }

    int co2_raw = (buf[2] << 8) | buf[3];
    *co2_ppm = (float)co2_raw;
    return 0;
}

static void log_data(float co2_ppm, int error_flag) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "{\"timestamp\":\"%s\",\"co2_ppm\":%.2f,\"error\":%d}\n", ts, co2_ppm, error_flag);
        fflush(log_file);
    }
    printf("{\"timestamp\":\"%s\",\"co2_ppm\":%.2f,\"error\":%d}\n", ts, co2_ppm, error_flag);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        perror("Error opening error log file");
        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float co2_ppm;
        int rc = read_mhz19b(&co2_ppm);
        if (rc == 0) {
            log_data(co2_ppm, 0);
        } else {
            log_data(0.0f, 1);
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (uart_handle >= 0) serClose(uart_handle);
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    gpioTerminate();
    return 0;
}

