        fclose(log_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float co2_ppm;
        int rc = read_mhz19b(&co2_ppm);
        if (rc == 0) {
