#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HMC5883L_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define HEADING_THRESHOLD 10.0
#define TARGET_HEADING 90.0
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static double x_offset = 0.0;
static double y_offset = 0.0;

typedef struct {
    double heading;
    time_t timestamp;
} HeadingData;

static HeadingData heading_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read error (reg 0x%02X, expected %u, got %d)\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int initialize_hmc5883l(int handle) {
    if (i2c_write_byte(handle, CONFIG_A, 0x70) < 0) return -1;
    if (i2c_write_byte(handle, CONFIG_B, 0x20) < 0) return -1;
    if (i2c_write_byte(handle, MODE, 0x00) < 0) return -1;
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(handle, DATA_START, buf, 6) < 0) return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static double compensate_heading(int16_t raw_x, int16_t raw_y) {
    double x = (double)raw_x - x_offset;
    double y = (double)raw_y - y_offset;
    double heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) heading += 360.0;
    return heading;
}

static void add_to_buffer(double heading) {
    time(&heading_buffer[buffer_index].timestamp);
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(i2c_handle, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double heading = compensate_heading(raw_x, raw_y);
        add_to_buffer(heading);

        double deviation = fabs(heading - TARGET_HEADING);
        gpioWrite(GPIO_PIN, deviation > HEADING_THRESHOLD ? 1 : 0);

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

