#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22
#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define CONVERSION_DELAY_MS 120
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (write(i2c_fd, (unsigned char[]){BH1750_CONTINUOUS_HIGH_RES_MODE}, 1) != 1) {
        fprintf(stderr, "Error writing BH1750 config: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(float *lux) {
    if (i2c_fd < 0) return -1;
    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading BH1750: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting relay %s to %d: %s\n", line ? "line" : "value", value, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(float lux, int red, int green, int blue) {
    if (!log_fp) return -1;
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(log_fp, "%s, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n", timestamp, lux, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (red_line) gpiod_line_set_value(red_line, 0);
    if (green_line) gpiod_line_set_value(green_line, 0);
    if (blue_line) gpiod_line_set_value(blue_line, 0);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as outputs: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (bh1750_init() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        if (bh1750_read_lux(&lux) < 0) {
            fprintf(stderr, "BH1750 read failed, retrying in 1s...\n");
            sleep(1);
            continue;
        }
        int red = 0, green = 0, blue = 0;
        if (lux < 50.0f) {
            red = 1;
        } else if (lux < 150.0f) {
            green = 1;
        } else if (lux < 300.0f) {
            blue = 1;
        } else {
            red = 1;
            green = 1;
            blue = 1;
        }
        if (set_relay(red_line, red) < 0 ||
            set_relay(green_line, green) < 0 ||
            set_relay(blue_line, blue) < 0) {
            fprintf(stderr, "Error setting relay states\n");
        }
        if (log_data(lux, red, green, blue) < 0) {
            fprintf(stderr, "Error logging data\n");
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

