#define MPU6050_GYRO_CONFIG 0x1B

#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MIN 500
#define PWM_DUTY_MAX 2500
#define PWM_DUTY_STEP 5
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_SMPLRT_DIV, 7) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){MPU6050_ACCEL_XOUT_H}, 1) != 1) return -1;
    if (read(fd, buf, 6) != 6) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static int read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){MPU6050_GYRO_XOUT_H}, 1) != 1) return -1;
    if (read(fd, buf, 6) != 6) return -1;
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

