    if (!log_file) return -1;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_pos);
    fflush(log_file);
    return 0;
