    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    while (running) {
        int16_t ax, ay, az, gx, gy, gz;
        int retries = 0;
        int success = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_accel(i2c_fd, &ax, &ay, &az) == 0) {
                if (read_gyro(i2c_fd, &gx, &gy, &gz) == 0) {
                    success = 1;
                    break;
                }
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }
        if (!success) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
            usleep(100000);
            continue;
        }

        float pitch = atan2f((float)ay, sqrtf((float)ax * ax + (float)az * az)) * 180.0f / M_PI;
        float roll = atan2f((float)ax, sqrtf((float)ay * ay + (float)az * az)) * 180.0f / M_PI;
        int servo_pos = (int)roundf(pitch * 100.0f);
        if (servo_pos < 0) servo_pos = 0;
        if (servo_pos > 200) servo_pos = 200;
        if (set_servo_duty(servo_pos * PWM_DUTY_STEP) < 0) {
            fprintf(stderr, "Failed to set servo duty cycle\n");
        }
        log_data(pitch, roll, servo_pos);
        usleep(10000);
    }

    cleanup();
    return 0;
}

