#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_DURATION 1800  /* 30 minutes in seconds */
#define FADE_STEPS 100      /* 100 steps per second */
#define FADE_STEP_DELAY 1   /* 1 second per fade step */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *relays, int *on, int *off) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (i >= 4) break; /* skip header lines */

        char *time_str = strtok(line, ":");
        char *ampm = strtok(NULL, ":");
        char *hour = strtok(NULL, ":");
        char *minute = strtok(NULL, ":");
        char *second = strtok(NULL, ":");

        if (!time_str || !ampm || !hour || !minute || !second) {
            fprintf(stderr, "Invalid schedule format at line %d\n", i + 1);
            fclose(fp);
            return -1;
        }

        int hour_int = atoi(time_str);
        int minute_int = atoi(minute);
        int second_int = atoi(second);

        if (hour_int < 0 || hour_int > 23 || minute_int < 0 || minute_int > 59 || second_int < 0 || second_int > 59) {
            fprintf(stderr, "Invalid time format at line %d\n", i + 1);
            fclose(fp);
            return -1;
        }

        if (strcmp(ampm, "AM") == 0 && hour_int >= 12) {
            hour_int -= 12;
        } else if (strcmp(ampm, "PM") == 0 && hour_int < 12) {
            hour_int += 12;
        }

        relays[i] = atoi(hour_str);
        on[i] = atoi(time_str);
        off[i] = atoi(time_str);

        if (on[i] != 0 && off[i] != 0) {
            fprintf(stderr, "Invalid schedule entry at line %d: on=%d, off=%d\n", i + 1, on[i], off[i]);
            fclose(fp);
            return -1;
        }

        i++;
    }

    fclose(fp);
    return 0;
}

static void set_relay(int pin, int state) {
    gpioWrite(pin, state);
}

static void fade_relay(int pin, int duration, int direction) {
    int duty = 0;
    int step_delay = FADE_STEP_DELAY;

    if (direction == 1) {
        duty = 100;
    } else if (direction == -1) {
        duty = 0;
    } else {
        fprintf(stderr, "Invalid fade direction: %d\n", direction);
        return;
    }

    for (int i = 0; i < duration * FADE_STEPS && running; i++) {
        if (direction == 1) {
            duty += 1;
        } else {
            duty -= 1;
        }

        if (duty < 0) duty = 0;
        if (duty > 100) duty = 100;

        gpioPWM(pin, duty);
        time_sleep(step_delay);
    }

    gpioPWM(pin, 0);
}

static void cleanup(void) {
    set_relay(RELAY1_PIN, 0);
    set_relay(RELAY2_PIN, 0);
    set_relay(RELAY3_PIN, 0);
    set_relay(RELAY4_PIN, 0);
    gpioTerminate();
}

int main(void) {
    int relays[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int on[4] = {0, 0, 0, 0};
    int off[4] = {0, 0, 0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        gpioSetMode(relays[i], PI_OUTPUT);
        gpioSetPWMfrequency(relays[i], 100);
        gpioPWM(relays[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        cleanup();
        return 1;
    }

    if (read_schedule(SCHEDULE_FILE, relays, on, off) != 0) {
        fprintf(stderr, "Failed to read schedule. Exiting.\n");
        cleanup();
        return 1;
    }

    time_t last_check = time(NULL);

    while (running) {
        time_t current_time = time(NULL);

        if (current_time - last_check >= 1) {
            last_check = current_time;

            for (int i = 0; i < 4; i++) {
                if (on[i] && !off[i]) {
                    fade_relay(relays[i], FADE_DURATION, 1);
                } else if (!on[i] && off[i]) {
                    fade_relay(relays[i], FADE_DURATION, -1);
                }
            }
        }

        time_sleep(0.1);
    }

    cleanup();
    return 0;
}

