    time_t last_check = time(NULL);

    while (running) {
        time_t current_time = time(NULL);

        if (current_time - last_check >= 1) {
            last_check = current_time;

            for (int i = 0; i < 4; i++) {
                if (on[i] && !off[i]) {
                    fade_relay(relays[i], FADE_DURATION, 1);
                } else if (!on[i] && off[i]) {
                    fade_relay(relays[i], FADE_DURATION, -1);
                }
            }
        }

        time_sleep(0.1);
    }

    cleanup();
    return 0;
}

