#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  30.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms max wait for echo */
#define LOOP_DELAY_US     20000   /* 20 ms between measurements */
#define MAIN_LOOP_DELAY_US 60000  /* 60 ms total gap */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Measure distance in cm using the HC-SR04.
 * Returns distance on success, or -1.0 on timeout / error.
 */
static float measure_distance(void) {
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_tick = gpioTick();

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    /* Speed of sound ~343 m/s => 0.0343 cm/us */
    float distance = (float)pulse_us * 0.0343f / 2.0f;
    return distance;
}

/*
 * Map distance to frequency.
 * distance_cm is clamped to [MIN_DISTANCE_CM, MAX_DISTANCE_CM].
 */
static int map_distance_to_frequency(float distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    float ratio = (distance_cm - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float freq = MIN_FREQUENCY_HZ + ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ);
    return (int)freq;
}

static void set_buzzer_frequency(int frequency) {
    if (frequency < 0) frequency = 0;
    if (frequency > 1000) frequency = 1000;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: distance measurement failed, skipping cycle\n");
        } else {
            int frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        }

        /* 60 ms total gap between measurements */
        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

