#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(float r, float g, float b) {
    int rc = 0;
    if (r < 0.0f || r > 1.0f) r = 0.0f;
    if (g < 0.0f || g > 1.0f) g = 0.0f;
    if (b < 0.0f || b > 1.0f) b = 0.0f;

    rc |= gpioPWM(RED_PIN, (int)(r * PWM_RANGE));
    rc |= gpioPWM(GREEN_PIN, (int)(g * PWM_RANGE));
    rc |= gpioPWM(BLUE_PIN, (int)(b * PWM_RANGE));
    return rc;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    float proximity = 0.0f;
    float t = 0.0f;
    float dt = 0.02f;

    while (running) {
        proximity = 0.5f + 0.5f * sinf(t);
        if (proximity < 0.0f) proximity = 0.0f;
        if (proximity > 1.0f) proximity = 1.0f;

        if (set_led_color(proximity, proximity, proximity) != 0) {
            fprintf(stderr, "Error: gpioPWM failed.\n");
            break;
        }

        t += dt;
        if (t > 10.0f) t = 0.0f;

        usleep(10000);
    }

    set_led_color(0.0f, 0.0f, 0.0f);
    gpioTerminate();
    return EXIT_SUCCESS;
}

