#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY_50  50000 /* 50% of 1000000 */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t melody_playing = 0;

static const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880, 987};
static const int melody_len = sizeof(melody) / sizeof(melody[0]);

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (now - last_tick < DEBOUNCE_US) {
        return;
    }
    last_tick = now;

    if (melody_playing) {
        melody_playing = 0;
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
    }

    /* Play melody in interrupt context: non-blocking, short bursts */
    for (int i = 0; i < melody_len && running; i++) {
        if (gpioHardwarePWM(BUZZER_PIN, 1, PWM_DUTY_50) < 0) {
            fprintf(stderr, "gpioHardwarePWM failed\n");
            return;
        }
        gpioDelay(1000); /* 1 ms tone */
        if (gpioHardwarePWM(BUZZER_PIN, 0, 0) < 0) {
            fprintf(stderr, "gpioHardwarePWM stop failed\n");
            return;
        }
        gpioDelay(1000); /* 1 ms gap */
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Musical doorbell ready. Press button (GPIO17) to play melody.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (melody_playing) {
            gpioDelay(100000); /* 100 ms */
        }
        gpioDelay(10000); /* 10 ms poll */
    }

    /* Clean shutdown */
    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

