#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT_MS 1000
#define WINDOW_SIZE 5
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file) {
        if (fprintf(log_file, "%s, GPIO%d, %d\n", timestamp, GPIO_LINE_OFFSET, value) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        } else {
            if (fflush(log_file) != 0) {
                fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            }
        }
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void check_window(int new_value) {
    static int window[WINDOW_SIZE] = {0};
    static int idx = 0;
    static int count = 0;

    window[idx] = new_value;
    idx = (idx + 1) % WINDOW_SIZE;
    if (count < WINDOW_SIZE) count++;

    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i] == 1) high_count++;
    }

    if (high_count >= 3) {
        log_event(new_value);
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];
        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
            printf("EARTHQUAKE ALERT: %s - %d events in window\n", timestamp, high_count);
        }
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Timeout must be positive\n");
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    if (gpiod_line_request_input(line, "sw420_vibration") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    printf("Vibration monitoring started on GPIO%d. Poll timeout: %d ms. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, timeout_ms);

    int prev_value = -1;

    while (program_running) {
        struct timespec ts = { .tv_sec = 0, .tv_nsec = POLL_TIMEOUT_MS * 1000000L };
        int ret = gpiod_line_event_wait(line, &ts);

        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        int value = event.event_value;
        if (value < 0) {
            fprintf(stderr, "Invalid event value: %d\n", value);
            continue;
        }

        if (value != prev_value) {
            log_event(value);
            check_window(value);
            prev_value = value;
        }
    }

    printf("\nShutting down...\n");

    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);

    return 0;
}

