#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303_ADDR 0x1E
#define I2C_BUS "/dev/i2c-1"

#define LSM303_REG_M_WHO_AM_I 0x0F
#define LSM303_REG_M_WHO_AM_I_VAL 0x50
#define LSM303_REG_M_CTRL_REG1_M 0x20
#define LSM303_REG_M_CTRL_REG2_M 0x21
#define LSM303_REG_M_MR_REG_M 0x02
#define LSM303_REG_M_OUT_X_L_M 0x03

#define LSM303_CTRL_REG1_M 0x01
#define LSM303_CTRL_REG2_M 0x02
#define LSM303_MR_REG_M 0x03

#define ODR_15HZ 0x04

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_block(fd, LSM303_REG_M_WHO_AM_I, &who_am_i, 1) < 0) return -1;
    if (who_am_i != LSM303_REG_M_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, LSM303_REG_M_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_byte(fd, LSM303_REG_M_CTRL_REG1_M, LSM303_CTRL_REG1_M | ODR_15HZ) < 0) return -1;
    if (i2c_write_byte(fd, LSM303_REG_M_CTRL_REG2_M, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, LSM303_REG_M_MR_REG_M, LSM303_MR_REG_M) < 0) return -1;
    return 0;
}

static int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
