    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float x_offset, float y_offset, float z_offset) {
    float x = (float)raw_x - x_offset;
    float y = (float)raw_y - y_offset;
    float z = (float)raw_z - z_offset;
    return sqrtf(x * x + y * y + z * z);
}

static void calculate_heading(float x, float y, float *heading) {
    float angle = atan2f(y, x) * 180.0f / M_PI;
    if (angle < 0) angle += 360.0f;
