#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_GAP 1
#define POLL_INTERVAL 10

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS] = {NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }

        struct gpiod_line_request_config config = {
            .consumer = "irrigation",
            .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
