/*
 * Automated plant watering system for Raspberry Pi Zero W
 * Uses pigpio for servo control.
 *
 * Wiring:
 *   GPIO17 (physical pin 11) -> Valve servo signal
 *   GPIO18 (physical pin 12) -> Nozzle servo signal
 *
 * Servo pulse widths (microseconds):
 *   500 us  -> 0 degrees
 *   1500 us -> 90 degrees
 *   2500 us -> 180 degrees
 *
 * Moisture threshold: 50
 * Watering cycle: 5 seconds total (2 seconds per nozzle angle + 3-second pause)
 * Cycle interval: 5 seconds between moisture readings
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

#define MOISTURE_THRESHOLD 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

#define SERVO_RETRY_COUNT 3
#define SERVO_RETRY_DELAY_MS 100
#define SERVO_SETTLE_MS 1000
#define SERVO_STEP_MS 100
#define SERVO_HOLD_MS 5000
#define SERVO_CYCLE_MS 2000
#define CYCLE_INTERVAL_MS 5000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);

    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; attempt++) {
        if (gpioServo(pin, pulse_width) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: gpioServo failed on pin %d (attempt %d/%d)\n",
                pin, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1) {
            gpioDelay(SERVO_RETRY_DELAY_MS * 1000);
        }
    }

    fprintf(stderr, "Error: gpioServo failed on pin %d after %d attempts\n",
            pin, SERVO_RETRY_COUNT);
    return -1;
}

static int open_valve(int pin) {
    return set_servo_angle(pin, 90);
}

static int close_valve(int pin) {
    return set_servo_angle(pin, 0);
}

static int sweep_nozzle(int pin, int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
    if (set_servo_angle(pin, angle) != 0) {
        return -1;
    }
    gpioDelay(SERVO_SETTLE_MS * 1000);
    return 0;
}

static int water_plant(int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        printf("Moisture level %d below threshold %d. Opening valve.\n",
               moisture_level, MOISTURE_THRESHOLD);

        if (open_valve(VALVE_SERVO_PIN) != 0) {
            fprintf(stderr, "Error: failed to open valve servo.\n");
            return -1;
        }

        for (int i = 0; i < 5 && g_running; i++) {
            int angle = (i * 36) % 180;
            if (sweep_nozzle(NOZZLE_SERVO_PIN, angle) != 0) {
                fprintf(stderr, "Error: nozzle servo failed at angle %d.\n", angle);
                return -1;
            }
            gpioDelay(SERVO_STEP_MS * 1000);
        }

        if (close_valve(VALVE_SERVO_PIN) != 0) {
            fprintf(stderr, "Warning: failed to close valve servo.\n");
        }

        printf("Watering complete. Valve closed.\n");
        return 0;
    } else {
        printf("Moisture level %d above threshold %d. No watering needed.\n",
               moisture_level, MOISTURE_THRESHOLD);
        return 0;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set valve servo pin %d as output.\n", VALVE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set nozzle servo pin %d as output.\n", NOZZLE_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automated plant watering system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = 20 + (rand() % 80);

        printf("Moisture level: %d\n", moisture_level);

        if (water_plant(moisture_level) != 0) {
            fprintf(stderr, "Error: watering cycle failed.\n");
        }

        if (g_running) {
            gpioDelay(CYCLE_INTERVAL_MS * 1000);
        }
    }

    printf("\nShutting down...\n");
    close_valve(VALVE_SERVO_PIN);
    close_valve(NOZZLE_SERVO_PIN);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

