#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pull) {
    if (gpioSetPullUpDown(gpio, pull) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pull);
        return -1;
    }
    return 0;
}

static int deenergize(void) {
    return safe_write(IN1, 0) && safe_write(IN2, 0) &&
           safe_write(IN3, 0) && safe_write(IN4, 0);
}

static int rotate_steps(int direction) {
    int steps = direction ? STEPS_PER_ROTATION : -STEPS_PER_ROTATION;
    for (int i = 0; i < steps && running; i++) {
        if (safe_write(IN1, 1) ||
            safe_write(IN2, 0) ||
            safe_write(IN3, 0, 0) ||
            safe_write(IN4, 0, 0)) {
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
        if (safe_write(IN1, 0) ||
            safe_write(IN2, 1) ||
            safe_write(IN3, 0, 0) ||
            safe_write(IN4, 0, 0)) {
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int lock_button_pressed(void) {
    if (gpioRead(LOCK_BUTTON) == 0) {
        gpioDelay(10000); /* 10 ms debounce */
        if (gpioRead(LOCK_BUTTON) == 0) {
            return 1;
        }
    }
    return 0;
}

static int unlock_button_pressed(void) {
    if (gpioRead(UNLOCK_BUTTON) == 1) {
        gpioDelay(10000); /* 10 ms debounce */
        if (gpioRead(UNLOCK_BUTTON) == 1) {
            return 1;
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(IN1, PI_OUTPUT) ||
        safe_set_mode(IN2, PI_OUTPUT) ||
        safe_set_mode(IN3, PI_OUTPUT) ||
        safe_set_mode(IN4, PI_OUTPUT) ||
        safe_set_mode(LOCK_BUTTON, PI_INPUT) ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT)) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP)) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic door lock ready. Press LOCK (BCM GPIO24) to rotate 512 steps CW, "
           "UNLOCK (BCM GPIO23) to rotate 512 steps CCW. Press Ctrl+C to exit.\n");

    while (running) {
        if (lock_button_pressed()) {
            printf("Lock pressed: rotating %d steps clockwise...\n", STEPS_PER_ROTATION);
            if (rotate_steps(1) < 0) {
                fprintf(stderr, "Error: lock rotation failed\n");
            }
            if (deenergize() < 0) {
                fprintf(stderr, "Error: failed to de-energize coils after lock\n");
            }
        } else if (unlock_button_pressed()) {
            printf("Unlock pressed: rotating %d steps counter-clockwise...\n", STEPS_PER_ROTATION);
            if (rotate_steps(-1) < 0) {
                fprintf(stderr, "Error: unlock rotation failed\n");
            }
            if (deenergize() < 0) {
                fprintf(stderr, "Error: failed to de-energize coils after unlock\n");
            }
        } else {
            gpioDelay(10000); /* 10 ms idle poll */
        }
    }

    printf("\nShutting down...\n");
    deenergize();
    gpioTerminate();
    return EXIT_SUCCESS;
}

