        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig_line, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int measure_pulse(void) {
    struct timespec t_start, t_now;
    long elapsed_us;

    /* Wait for rising edge */
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (t_now.tv_sec - t_start.tv_sec) * 1000000L +
                     (t_now.tv_nsec - t_start.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    struct timespec t_rise;
    clock_gettime(CLOCK_MONOTONIC, &t_rise);
    long rise_us = (t_rise.tv_sec - t_start.tv_sec) * 1000000L +
                   (t_rise.tv_nsec - t_start.tv_nsec) / 1000L;

    /* Wait for falling edge */
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (t_now.tv_sec - t_rise.tv_sec) * 1000000L +
                     (t_now.tv_nsec - t_rise.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            return -1;
        }
    }

    struct timespec t_fall;
    clock_gettime(CLOCK_MONOTONIC, &t_fall);
    long fall_us = (t_fall.tv_sec - t_rise.tv_sec) * 1000000L +
                   (t_fall.tv_nsec - t_rise.tv_nsec) / 1000L;

    return (int)(fall_us - rise_us);
}

static float calculate_distance(int pulse_us) {
    return (float)pulse_us * 0.01715f;
}

static void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance < 0) {
        fprintf(log_fp, "%s, -1\n", timestamp);
    } else {
        fprintf(log_fp, "%s, %.2f\n", timestamp, distance);
    }
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (running) {
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Trigger pulse failed; skipping cycle.\n");
            usleep(MEASURE_US);
            continue;
        }

        int pulse = measure_pulse();
        if (pulse < 0) {
            fprintf(stderr, "Echo timeout or read error.\n");
            log_distance(-1.0f);
        } else {
            float dist = calculate_distance(pulse);
            log_distance(dist);
            printf("Distance: %.2f cm\n", dist);
        }

        /* Guard against repeated echoes within 60 ms */
        usleep(GUARD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

