#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define DISTANCE_THRESHOLD 50
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0080
#define REG_RESULT_INTERRUPT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE_MSB     0x0096
#define REG_RESULT_DISTANCE_LSB     0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit VL53L1X register */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit value from a 16-bit VL53L1X register */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;

    if (i2cReadDevice(handle, data_buf, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Read a 16-bit distance from the VL53L1X */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint16_t status = 0;

    /* Check if data is ready */
    if (vl53l1x_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if (!(status & 0x01)) {
        /* No new data yet */
        return 1;
    }

    /* Read distance MSB and LSB */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_MSB, distance) != 0)
        return -1;

    /* Read LSB */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE_LSB, distance) != 0)
        return -1;

    /* Clear interrupt by writing 1 to the interrupt status register */
    if (vl53l1x_write_reg16(handle, REG_RESULT_INTERRUPT_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    uint16_t distance = 0;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to VL53L1X */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Software reset */
    ret = vl53l1x_write_reg16(g_i2c_handle, REG_SOFT_RESET, 0x00);
    if (ret != 0) {
        fprintf(stderr, "Error: VL53L1X software reset failed (ret=%d)\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Start continuous ranging */
    ret = vl53l1x_write_reg16(g_i2c_handle, REG_SYSTEM_MODE_START, 0x01);
    if (ret != 0) {
        fprintf(stderr, "Error: VL53L1X start ranging failed (ret=%d)\n", ret);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X proximity door system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        ret = vl53l1x_read_distance(g_i2c_handle, &distance);
        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("Door opened (distance <= %d mm)\n", DISTANCE_THRESHOLD);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: I2C read failure (ret=%d)\n", ret);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

