#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        goto cleanup;
    }
    usleep(100000);

    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) < 0) {
        goto cleanup;
    }

    printf("MPU-6050 Gyroscope Reader (I2C addr 0x%02X)\n", MPU6050_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, GYRO_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Gyroscope read error — continuing.\n");
            usleep(100000);
            continue;
        }

        int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

        float gyro_x = (float)raw_x / 131.0f;
        float gyro_y = (float)raw_y / 131.0f;
        float gyro_z = (float)raw_z / 131.0f;

        printf("Gyro X: %7.2f  Y: %7.2f  Z: %7.2f  (dps)\n", gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting gracefully.\n");
    return ret;
}

