/*
 * Automated plant watering system using libgpiod v1 API.
 *
 * Board:  Raspberry Pi 4 Model B
 * Relays: 4 x 5 V active-low relay modules on BCM GPIO17, GPIO18, GPIO27, GPIO22
 *          (physical pins 11, 12, 13, 15)
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_INTERVAL 86400   /* seconds between watering cycles */
#define POLL_INTERVAL    60      /* seconds between loop iterations */
#define RELAY_ON_TIME    5        /* seconds to keep a relay active */

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_watering_start(void)
{
    FILE *fp = fopen("watering_log.txt", "a");
    if (!fp) {
        perror("fopen(watering_log.txt)");
        return -1;
    }

    time_t t = time(NULL);
