#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define LOG_FILE "smart_lighting.log"
#define SIMULATION_DURATION 30  // minutes
#define STEP_INTERVAL 1          // seconds

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
}

static void set_all_relays(int duty_cycle) {
    int pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(pins[i], duty_cycle);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event("Smart lighting sunrise simulation started");

    int total_steps = SIMULATION_DURATION * STEP_INTERVAL;
    int duty_cycle = 0;
    int elapsed_steps = 0;

    while (running && elapsed_steps < total_steps) {
        set_all_relays(duty_cycle);
        log_event("Simulating sunrise: duty cycle set to 0");
        gpioDelay(STEP_INTERVAL * 1000000);

        duty_cycle = (duty_cycle + 1) % 256;
        elapsed_steps++;

        if (running) {
            log_event("Simulating sunrise: duty cycle set to 1");
            gpioDelay(STEP_INTERVAL * 1000000);
        }
    }

    set_all_relays(0);
    log_event("Smart lighting sunrise simulation complete");
    cleanup_gpio();
    return 0;
}

