#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 250.0f
#define SAMPLE_PERIOD_US 50000

typedef struct {
    time_t timestamp;
    float gyro_x, gyro_y, gyro_z;
} gyro_data_t;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static gyro_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpu6050_init(void) {
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to wake MPU-6050 (PWR_MGMT_1)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error: failed to set sample rate divider\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to set gyro config\n");
        return -1;
    }
    return 0;
}

static int mpu6050_read_gyro(float *gx, float *gy, float *gz) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (float)raw_x / 131.0f;
    *gy = (float)raw_y / 131.0f;
    *gz = (float)raw_z / 131.0f;
    return 0;
}

static void add_to_buffer(float gx, float gy, float gz) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].gyro_x = gx;
    circular_buffer[buffer_index].gyro_y = gy;
    circular_buffer[buffer_index].gyro_z = gz;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int check_threshold(float gx, float gy, float gz) {
    if (fabsf(gx) > THRESHOLD || fabsf(gy) > THRESHOLD || fabsf(gz) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        return 1;
    } else {
        gpioWrite(LED_GPIO, 0);
        return 0;
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return 1;
    }

    if (mpu6050_init() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float gx, gy, gz;
    int read_attempts = 0;

    while (running) {
        if (mpu6050_read_gyro(&gx, &gy, &gz) == 0) {
            read_attempts = 0;
            add_to_buffer(gx, gy, gz);
            check_threshold(gx, gy, gz);
        } else {
            read_attempts++;
            fprintf(stderr, "Warning: read failed (attempt %d)\n", read_attempts);
            if (read_attempts >= 3) {
                fprintf(stderr, "Error: I2C read failed after 3 attempts, exiting\n");
                break;
            }
            gpioDelay(100000);
            if (mpu6050_init() < 0) {
                fprintf(stderr, "Error: re-initialisation failed, exiting\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return 0;
}

