#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define GYRO_SCALE      131.0f
#define GYRO_REG_START  0x43
#define GYRO_REG_END    0x48
#define SAMPLE_PERIOD_US 10000
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_cs_line = NULL;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void) {
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; g_cs_line = NULL; return -1;
    }

    return 0;
}

static void spi_close(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static void gpio_close(void) {
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_raw(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[7] = {0};
    uint8_t rx[7] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (gpiod_line_set_value(g_cs_line, 0) < 0) {
            fprintf(stderr, "CS low: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }

        if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
            gpiod_line_set_value(g_cs_line, 1);
            usleep(1000);
            continue;
        }

        if (gpiod_line_set_value(g_cs_line, 1) < 0) {
            fprintf(stderr, "CS high: %s\n", strerror(errno));
            usleep(1000);
            continue;
        }

        *x = (int16_t)((rx[0] << 8) | rx[1]);
        *y = (int16_t)((rx[2] << 8) | rx[3]);
        *z = (int16_t)((rx[4] << 8) | rx[5]);
        return 0;
    }
    return -1;
}

static void log_data(float x, float y, float z) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) return 1;
    if (gpio_init() < 0) {
        spi_close();
        return 1;
    }

    g_log_fp = fopen("gyro_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(gyro_log.txt): %s\n", strerror(errno));
        gpio_close();
        spi_close();
        return 1;
    }

    fprintf(g_log_fp, "# timestamp,x_rate_dps,y_rate_dps,z_rate_dps\n");
    fflush(g_log_fp);

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_gyro_raw(&raw_x, &raw_y, &raw_z) == 0) {
            float x = (float)raw_x / GYRO_SCALE;
            float y = (float)raw_y / GYRO_SCALE;
            float z = (float)raw_z / GYRO_SCALE;
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Gyro read failed after %d retries\n", MAX_RETRIES);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    fprintf(g_log_fp, "# program terminated\n");
    fclose(g_log_fp);
    g_log_fp = NULL;
    spi_close();
    gpio_close();
    return 0;
}

