#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and open the I2C bus                          */
/* ------------------------------------------------------------------ */
static int initialize_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(g_i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write PWR_MGMT_1.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Set accelerometer full-scale range to +/- 2g (AFS_SEL = 0) */
    if (i2cWriteByteData(g_i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write ACCEL_CONFIG.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data and convert to degrees        */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    /* Read 6 bytes starting at ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(g_i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed.\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw accelerometer data to degrees                            */
/* ------------------------------------------------------------------ */
static void convert_to_degrees(int16_t x, int16_t y, int16_t z,
                                double *roll, double *pitch)
{
    /* Roll = atan2(y, z) * 180/pi */
    *roll = atan2((double)y, (double)z) * 180.0 / M_PI;

    /* Pitch = -atan2(x, sqrt(y^2 + z^2)) * 180/pi */
    *pitch = -atan2((double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
}

/* ------------------------------------------------------------------ */
/* Log data to CSV file with timestamp                                 */
/* ------------------------------------------------------------------ */
static void log_data(double roll, double pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for appending.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Control LED based on tilt thresholds                                */
/* ------------------------------------------------------------------ */
static void control_led(double roll, double pitch)
{
    if (fabs(roll) > TILT_THRESHOLD || fabs(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup resources — safe to call multiple times                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (initialize_i2c() != 0) {
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    int16_t x, y, z;
    double roll, pitch;

    while (g_running) {
        if (read_accelerometer(&x, &y, &z) == 0) {
            convert_to_degrees(x, y, z, &roll, &pitch);
            log_data(roll, pitch);
            control_led(roll, pitch);
            printf("Roll: %.2f deg, Pitch: %.2f deg\n", roll, pitch);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

