#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define REG_ALS_VIS_DATA0 0x20
#define REG_PS1_DATA0 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t reg_buf[1] = {reg};
    uint8_t data[2];
    for (int i = 0; i < I2C_RETRIES; i++) {
        if (write(fd, reg_buf, 1) != 1) { usleep(I2C_RETRY_DELAY_MS * 1000); continue; }
        if (read(fd, data, 2) == 2) {
            *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
            return 0;
        }
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    if (i2c_read_reg16(fd, REG_ALS_VIS_DATA0, ambient_light) != 0) return -1;
    if (i2c_read_reg16(fd, REG_PS1_DATA0, proximity) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c bus"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) { perror("ioctl I2C_SLAVE"); close(i2c_fd); return 1; }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open"); close(i2c_fd); return 1; }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); close(i2c_fd); return 1; }
    if (gpiod_line_request_output(led_line, "si1145-led", 0) < 0) {
        perror("gpiod_line_request_output"); gpiod_line_release(led_line); gpiod_chip_close(chip); close(i2c_fd); return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen log"); gpiod_line_release(led_line); gpiod_chip_close(chip); close(i2c_fd); return 1; }

    while (keep_running) {
        uint16_t ambient_light, proximity;
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            if (proximity > PROXIMITY_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

