#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define GYRO_SENSITIVITY 200.0f
#define SAMPLE_DELAY_US 10000
#define MAX_REINIT_ATTEMPTS 3

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, int16_t *out) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X (ret=%d)\n", reg, ret);
        return -1;
    }
    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_gyro_data(int16_t *x_rate, int16_t *y_rate) {
    if (spi_read_register(0x02, x_rate) != 0) return -1;
    if (spi_read_register(0x04, y_rate) != 0) return -1;
    return 0;
}

static void log_data(double timestamp, int16_t x_rate, int16_t y_rate) {
    if (fprintf(log_file, "%.6f,%d,%d\n", timestamp, x_rate, y_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("gyro_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_rate,Y_rate\n");
        fflush(log_file);
    }

    int16_t x_rate = 0, y_rate = 0;
    int init_attempts = 0;

    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            double timestamp = time_time() * 1000000.0 + (double)clock() * 1000.0 / (double)CLOCKS_PER_SEC;
            log_data(timestamp, x_rate, y_rate);
            init_attempts = 0;
        } else {
            fprintf(stderr, "Gyro read error, reinitializing SPI...\n");
            if (spi_handle >= 0) spiClose(spi_handle);
            spi_handle = -1;
            init_attempts++;
            if (init_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinit attempts reached, exiting\n");
                break;
            }
            sleep(1);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI reinit failed: %d\n", spi_handle);
                break;
            }
            init_attempts = 0;
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

