#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define LOG_FILE     "seismic_events.txt"
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == SENSOR_1_PIN) {
        if (level == 1) {
            log_event("Sensor 1: Tilt detected (rising edge)");
        } else if (level == 0) {
            log_event("Sensor 1: Tilt released (falling edge)");
        }
    } else if (gpio == SENSOR_2_PIN) {
        if (level == 1) {
            log_event("Sensor 2: Tilt detected (rising edge)");
        } else if (level == 0) {
            log_event("Sensor 2: Tilt released (falling edge)");
        }
    }
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        log_event("ERROR: Failed to set alert pin HIGH");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        log_event("ERROR: Failed to set alert pin LOW");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_1_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_2_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to register callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Seismic monitoring started");

    uint32_t start_tick = 0;
    int alert_active = 0;

    while (running) {
        uint32_t now_tick = gpioTick();
        if (start_tick == 0) {
            start_tick = now_tick;
        }

        if (gpioRead(SENSOR_1_PIN) == 1 && gpioRead(SENSOR_2_PIN) == 1) {
            uint32_t elapsed = now_tick - start_tick;
            if (elapsed >= SEISMIC_THRESHOLD_MS * 1000) {
                if (!alert_active) {
                    trigger_alert();
                    alert_active = 1;
                }
            }
        } else {
            alert_active = 0;
        }

        gpioDelay(10000);
    }

    log_event("Seismic monitoring stopped");
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

