#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define ANGULAR_RATE_THRESHOLD 20.0
#define GYRO_SENSITIVITY 200.0
#define GYRO_REG_XL 0x02
#define GYRO_REG_XH 0x03

typedef struct {
    struct timespec timestamp;
    double angular_rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        fprintf(stderr, "Error: Failed to initialize mutex\n");
        return -1;
    }
    return 0;
}

static void add_to_circular_buffer(circular_buffer_t *cb, gyro_data_t data) {
    pthread_mutex_lock(&cb->mutex);
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

static double read_gyro_rate(int handle) {
    char tx_buf[3];
    char rx_buf[3];
    int ret;

    tx_buf[0] = (GYRO_REG_XL | 0x80) << 1;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;

    ret = spiXfer(handle, tx_buf, rx_buf, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return 0.0;
    }

    int16_t raw_rate = (int16_t)(((uint16_t)(uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[2]);
    return (double)raw_rate / GYRO_SENSITIVITY;
}

static void check_threshold(double angular_rate) {
    if (fabs(angular_rate) > ANGULAR_RATE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set LED GPIO mode\n");
        cleanup();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_circular_buffer(&gyro_buffer) != 0) {
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return 1;
    }

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        double angular_rate = read_gyro_rate(spi_handle);
        if (angular_rate > -100.0 && angular_rate < 100.0) {
            struct timespec ts;
            clock_gettime(CLOCK_MONOTONIC, &ts);
            gyro_data_t data = { .timestamp = ts, .angular_rate = angular_rate };
            add_to_circular_buffer(&gyro_buffer, data);
            check_threshold(angular_rate);
        } else {
            fprintf(stderr, "Warning: Invalid gyro reading, skipping\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

