#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define FADE_DURATION 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_lamp_brightness(int pin, int brightness) {
    if (gpioPWM(pin, brightness) != 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int duration) {
    int brightness = 0;
    for (int i = 0; i < duration && running; i++) {
        if (set_lamp_brightness(pin, brightness) != 0) {
            return -1;
        }
        brightness += 3;
        if (brightness > PWM_RANGE) {
            brightness = PWM_RANGE;
        }
        gpioDelay(10000); /* 10 ms */
    }
    if (set_lamp_brightness(pin, 0) != 0) {
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(LAMP1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", LAMP1_PIN);
        return -1;
    }
    if (gpioSetMode(LAMP2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", LAMP2_PIN);
        return -1;
    }
    if (gpioSetMode(LAMP3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", LAMP3_PIN);
        return -1;
    }

    if (gpioSetPWMrange(LAMP1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", LAMP1_PIN);
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", LAMP2_PIN);
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", LAMP3_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", LAMP1_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", LAMP2_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", LAMP3_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Turn off all lamps before releasing */
    gpioPWM(LAMP1_PIN, 0);
    gpioPWM(LAMP2_PIN, 0);
    gpioPWM(LAMP3_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int fade_duration = atoi(argv[1]);
    if (fade_duration <= 0 || fade_duration > 3600) {
        fprintf(stderr, "Error: fade duration must be between 1 and 3600 seconds\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %d seconds\n", fade_duration);
    printf("Lamps on GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("Press Ctrl+C to exit.\n");

    if (fade_lamp(LAMP1_PIN, fade_duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (fade_lamp(LAMP2_PIN, fade_duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }
    if (fade_lamp(LAMP3_PIN, fade_duration) != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Fade complete. All lamps turned off.\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

