#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE0 0x5D
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGETIME 0x5C
#define MPR121_RESET 0x80
#define MPR121_RUN 0x5E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int mpr121_write_byte(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(msg);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write_byte(MPR121_RESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_byte(MPR121_ELECTRODE0, 0x01) < 0) return -1;
    if (mpr121_write_byte(MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write_byte(MPR121_RELEASETH_0, 0x08) < 0) return -1;
    if (mpr121_write_byte(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write_byte(MPR121_CHARGETIME, 0x0D) < 0) return -1;
    if (mpr121_write_byte(MPR121_RUN, 0x0D) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lsb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (lsb < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: reg=0x%02X, rc=%d", MPR121_TOUCHSTATUS_L, lsb);
        log_message(msg);
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (msb < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C read failed: reg=0x%02X, rc=%d", MPR121_TOUCHSTATUS_H, msb);
        log_message(msg);
        return -1;
    }
    *status = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_message("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C open failed: rc=%d", i2c_handle);
        log_message(msg);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "MPR121 init failed");
        log_message(msg);
        cleanup();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t prev_touch = 0;
    int relay_state = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) == 0) {
            uint16_t new_touches = touch_status & ~prev_touch;
            if (new_touches) {
                gpioDelay(100000);
                uint16_t confirmed = touch_status;
                if (confirmed & ~prev_touch) {
                    if (confirmed & (1 << 0)) {
                        relay_state = !relay_state;
                        gpioWrite(RELAY_GPIO, relay_state);
                        char msg[128];
                        snprintf(msg, sizeof(msg), "Relay toggled to %d", relay_state);
                        log_message(msg);
                    }
                }
                prev_touch = confirmed;
            }
        } else {
            log_message("Failed to read touch status");
        }
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

