#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define LOOP_INTERVAL_S 5
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Solenoid 1 (GPIO%d): %d ms, Solenoid 2 (GPIO%d): %d ms\n",
                timestamp, solenoid1_pin, duration_ms / 2,
                solenoid2_pin, (DISPENSE_DURATION_MS - duration_ms) / 2) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int dispense_cycle(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    if (gpioWrite(solenoid1_pin, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d high\n", solenoid1_pin);
        return -1;
    }
    if (gpioWrite(solenoid2_pin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO%d low\n", solenoid2_pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(solenoid1_pin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO%d low\n", solenoid1_pin);
        return -1;
    }
    if (gpioWrite(solenoid2_pin, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d high\n", solenoid2_pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) < 0 || gpioWrite(SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise solenoid pins low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int dispense_ms = DISPENSE_DURATION_MS / 2;

        if (dispense_cycle(SOLENOID_1_PIN, SOLENOID_2_PIN, dispense_ms) < 0) {
            fprintf(stderr, "Dispense cycle failed\n");
        }

        if (!program_running) break;

        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, dispense_ms) < 0) {
            fprintf(stderr, "Logging failed\n");
        }

        for (int i = 0; i < LOOP_INTERVAL_S && program_running; i++) {
            gpioDelay(1000000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

