        return;
    }
}

static void motor_stop(int motor) {
    if (motor == MOTOR_A_FORWARD) {
        gpioPWM(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
    } else if (motor == MOTOR_B_FORWARD) {
        gpioPWM(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
    } else {
        fprintf(stderr, "Invalid motor: %d\n", motor);
        return;
    }
}

/* PID control loop */
static double pid_control(double tilt_error) {
    double error = tilt_error;
    double output = KP * error;

    integral += error;
    if (integral > 255.0) integral = 255.0;
    if (integral < -255.0) integral = -255.0;

    double derivative = error - previous_error;
    output += KD * derivative;

    previous_error = error;

    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    return output;
}

/* Simulate distance reading from ultrasonic sensor */
static double simulate_distance(void) {
    return (double)rand() / (double)RAND_MAX * 398.0;
}

/* Log data to file */
static void log_data(double tilt_error, double distance,
                      int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Initialize pigpio and GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Motor pins as outputs */
    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return -1;
    }

    /* Enable pins as outputs (HIGH = enable) */
    if (gpioSetMode(ENA, PI_OUTPUT) != 0 ||
        gpioSetMode(ENB, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set enable pin modes\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure motors are stopped initially */
    motor_stop(MOTOR_A_FORWARD);
    motor_stop(MOTOR_A_BACKWARD);
    motor_stop(MOTOR_B_FORWARD);
    motor_stop(MOTOR_B_BACKWARD);

    /* Enable L298N */
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    return 0;
}

/* Cleanup GPIO and log file */
static void cleanup(void) {
    /* Stop motors */
    motor_stop(MOTOR_A_FORWARD);
    motor_stop(MOTOR_A_BACKWARD);
    motor_stop(MOTOR_B_FORWARD);
    motor_stop(MOTOR_B_BACKWARD);

    /* Disable L298N */
    gpioWrite(ENA, 0);
    gpioWrite(ENB, 0);

    /* Terminate pigpio */
    gpioTerminate();

    /* Close log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    /* Seed random number generator */
    srand((unsigned int)time(NULL));

    /* Open log file */
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        fclose(log_file);
        log_file = NULL;
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    printf("Self-balancing robot started. Press Ctrl+C to stop.\n");

    /* Main control loop */
    while (running) {
        double tilt_error = (double)rand() / (double)RAND_MAX * 20.0 - 10.0;
        double distance = simulate_distance();

        /* Obstacle avoidance */
        if (distance < OBSTACLE_THRESHOLD) {
            motor_backward(MOTOR_A_FORWARD);
            motor_backward(MOTOR_B_FORWARD);
            motor_forward(MOTOR_A_BACKWARD);
            motor_forward(MOTOR_B_BACKWARD);
            log_data(tilt_error, distance, -50, -50);
        } else {
            /* PID control */
            int motor_a_speed = (int)pid_control(tilt_error);
            int motor_b_speed = (int)pid_control(tilt_error);

            /* Clamp speeds to valid range */
            if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
            if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
            if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
            if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

            motor_forward(MOTOR_A_FORWARD);
            motor_forward(MOTOR_B_FORWARD);
            motor_backward(MOTOR_A_BACKWARD);
            motor_backward(MOTOR_B_BACKWARD);

            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        }

        gpioDelay(LOOP_PERIOD_US);
    }

    /* Graceful shutdown */
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

