static void cleanup_pigpio(void)
{
    set_led_color(0, 0, 0);
    gpioTerminate();
}

static int init_alsa(void)
{
    struct snd_pcm *pcm;
    int err;

    snd_pcm_open(&pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (!pcm) {
        fprintf(stderr, "Error: snd_pcm_open failed: %s\n", strerror(errno));
        return -1;
    }

    snd_pcm_set_params(pcm, SND_PCM_FORMAT_S16_LE,
                       SND_PCM_ACCESS_RW_INTERLEAVED,
                       SAMPLE_RATE, BUFFER_SIZE, 1, 0);

    err = snd_pcm_prepare(pcm);
    if (err < 0) {
        fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n", snd_strerror(err));
        snd_pcm_close(pcm);
        return -1;
    }

    return 0;
}

static void cleanup_alsa(struct snd_pcm *pcm)
{
    if (pcm) {
        snd_pcm_drain(pcm);
        snd_pcm_close(pcm);
    }
}

static int read_audio_sample(struct snd_pcm *pcm, short *sample)
{
