#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_IT_154MS 0xD5
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C read block failed (reg=0x%02X, expected=%u, got=%d): %s\n",
                reg, len, rc, strerror(errno));
    }
    return rc;
}

static int initialize_sensor(int handle) {
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_PON) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) return -1;
    gpioDelay(3000);
    if (i2c_write_byte(handle, TCS34725_ATIME, TCS34725_IT_154MS) < 0) return -1;
    return 0;
}

static int read_sensor_data(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    if (i2c_read_block(handle, TCS34725_CDATA, buf, 8) < 0) return -1;
    *clear = (uint16_t)(buf[1] << 8 | buf[0]);
    *red   = (uint16_t)(buf[3] << 8 | buf[2]);
    *green = (uint16_t)(buf[5] << 8 | buf[4]);
    *blue  = (uint16_t)(buf[7] << 8 | buf[6]);
    return 0;
}

static void log_data(FILE *fp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fp = fopen("color_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open color_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t clear, red, green, blue;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &clear, &red, &green, &blue) == 0) {
            log_data(fp, clear, red, green, blue);
        } else {
            fprintf(stderr, "Sensor read error; setting values to 0\n");
            clear = red = green = blue = 0;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

