#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define RELAY1_PIN 11
#define RELAY2_PIN 13
#define RELAY3_PIN 15
#define RELAY4_PIN 17

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1 = NULL;
static struct gpiod_line *relay2 = NULL;
static struct gpiod_line *relay3 = NULL;
static struct gpiod_line *relay4 = NULL;

static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    if (relay1) gpiod_line_set_value(relay1, 1);
    if (relay2) gpiod_line_set_value(relay2, 1);
    if (relay3) gpiod_line_set_value(relay3, 1);
    if (relay4) gpiod_line_set_value(relay4, 1);
    if (relay1) gpiod_line_release(relay1);
    if (relay2) gpiod_line_release(relay2);
    if (relay3) gpiod_line_release(relay3);
    if (relay4) gpiod_line_release(relay4);
    if (chip) gpiod_chip_close(chip);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int pin, int value) {
    if (!line) return -1;
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void simulate_sunrise(void) {
    for (int i = 0; i <= 100 && running; i++) {
        if (set_relay(relay1, RELAY1_PIN, 0) < 0) return;
        if (set_relay(relay2, RELAY2_PIN, 0) < 0) return;
        if (set_relay(relay3, RELAY3_PIN, 0) < 0) return;
        if (set_relay(relay4, RELAY4_PIN, 0) < 0) return;
        usleep(10000);
    }
}

static void simulate_daytime(void) {
    for (int i = 0; i < 100 && running; i++) {
        if (set_relay(relay1, RELAY1_PIN, 0) < 0) return;
        if (set_relay(relay2, RELAY2_PIN, 0) < 0) return;
        if (set_relay(relay3, RELAY3_PIN, 0) < 0) return;
        if (set_relay(relay4, RELAY4_PIN, 0) < 0) return;
        usleep(10000);
    }
}

static void simulate_sunset(void) {
    for (int i = 100; i >= 0 && running; i--) {
        if (set_relay(relay1, RELAY1_PIN, 0) < 0) return;
        if (set_relay(relay2, RELAY2_PIN, 0) < 0) return;
        if (set_relay(relay3, RELAY3_PIN, 0) < 0) return;
        if (set_relay(relay4, RELAY4_PIN, 0) < 0) return;
        usleep(10000);
    }
}

static void simulate_nighttime(void) {
    for (int i = 0; i < 100 && running; i++) {
        if (set_relay(relay1, RELAY1_PIN, 1) < 0) return;
        if (set_relay(relay2, RELAY2_PIN, 1) < 0) return;
        if (set_relay(relay3, RELAY3_PIN, 1) < 0) return;
        if (set_relay(relay4, RELAY4_PIN, 1) < 0) return;
        usleep(10000);
    }
