#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define VIDEO_DIR "/home/pi/videos"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_MS 200
#define VIDEO_DURATION 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) return -1;
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) return -1;
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (!log_file) return -1;
    if (fprintf(log_file, "%s: Motion detected\n", timestamp) < 0) return -1;
    if (fflush(log_file) != 0) return -1;
    return 0;
}

static int record_video(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "raspivid -o %s -t %d -w 640 -h 480 -fps 30 2>/dev/null",
             filename, VIDEO_DURATION);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(log_file)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;
    int consecutive_errors = 0;

    while (running) {
        int sensor_value = gpioRead(SENSOR_GPIO);
        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", SENSOR_GPIO);
            consecutive_errors++;
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive read errors, aborting.\n");
                break;
            }
            gpioDelay(100000);
            continue;
        }

        if (sensor_value == 0) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick >= DEBOUNCE_MS * 1000) {
                char timestamp[32];
                if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                    if (record_video(timestamp) == 0) {
                        if (log_motion_event(timestamp) != 0) {
                            fprintf(stderr, "Failed to log motion event\n");
                        }
                    } else {
                        fprintf(stderr, "Failed to record video\n");
                    }
                } else {
                    fprintf(stderr, "Failed to get timestamp\n");
                }
                last_trigger_tick = now;
                consecutive_errors = 0;
            }
        } else {
            consecutive_errors = 0;
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

