#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48
#define GYRO_SENSITIVITY 131.0f
#define SAMPLE_RATE_HZ 100
#define LOG_FILE "gyro_log.csv"
#define MAX_REINIT_ATTEMPTS 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

static int mpu6050_init(int handle) {
    if (mpu6050_write_reg(handle, PWR_MGMT_1, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (mpu6050_write_reg(handle, SMPLRT_DIV, 0x07) < 0) return -1;
    if (mpu6050_write_reg(handle, GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read failed: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%03ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpu6050_init(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d/%d)\n", consecutive_errors, MAX_REINIT_ATTEMPTS);
            if (consecutive_errors >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            if (mpu6050_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialization failed. Retrying...\n");
            }
        }
        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

