        return EXIT_FAILURE;
    }

    if (mpu6050_init(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    int consecutive_errors = 0;

    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d/%d)\n", consecutive_errors, MAX_REINIT_ATTEMPTS);
            if (consecutive_errors >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
            if (mpu6050_init(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialization failed. Retrying...\n");
            }
        }
        gpioDelay(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

