#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define DATA_FORMAT     0x31
#define POWER_CTL       0x2D
#define DATAX0          0x32
#define GPIO_ALARM      27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define ALARM_DURATION_MS 5000
#define SCALE_FACTOR 256.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, pigpio_error(i2cWriteByteData(handle, reg, value)));
        return -1;
    }
    return 0;
}

static int adxl345_read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, pigpio_error(result));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int adxl345_read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    if (fabsf(x) < FREEFALL_THRESHOLD && fabsf(y) < FREEFALL_THRESHOLD && fabsf(z) < FREEFALL_THRESHOLD) {
        return 1;
    }
    return 0;
}

static void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening freefall.log\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

static void trigger_alarm(void) {
    gpioWrite(GPIO_ALARM, 1);
    printf("Freefall detected! Triggering alarm.\n");
    gpioDelay(ALARM_DURATION_MS * 1000);
    gpioWrite(GPIO_ALARM, 0);
    printf("Alarm stopped.\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (adxl345_write_register(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (adxl345_write_register(i2c_handle, POWER_CTL, 0x08) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0);

    signal(SIGINT, signal_handler);

    float x, y, z;
    int freefall_count = 0;
    int consecutive_failures = 0;

    while (!terminate) {
        if (adxl345_read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= 2) {
                    log_freefall(x, y, z);
                    trigger_alarm();
                    consecutive_failures = 0;
                    freefall_count = 0;
                }
            } else {
                consecutive_failures++;
                if (consecutive_failures >= 10) {
                    fprintf(stderr, "Too many consecutive failures, aborting.\n");
                    break;
                }
            }
        } else {
            consecutive_failures++;
            if (consecutive_failures >= 10) {
                fprintf(stderr, "Too many consecutive I2C failures, aborting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_ALARM, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

