#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define TRIGGER_INTERVAL_US 200000
#define ECHO_TIMEOUT_US 100000
#define ECHO_THRESHOLD_US 23200
#define MAX_DISTANCE_CM 4.0
#define TIMEOUT_THRESHOLD_MS 100

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int valid_reading = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static double tick_to_us(uint32_t tick) {
    return (double)(tick - gpioTick) / 1000.0;
}

static double pulse_width_us(uint32_t start, uint32_t end) {
    if (end < start) {
        return (double)(0xFFFFFFFF - end + start + 1);
    }
    return (double)(end - start);
}

static double distance_cm(uint32_t pulse_us) {
    if (pulse_us <= 0) {
        return -1.0;
    }
    double speed = 34300.0;
    double time = pulse_us / 1e6;
    return speed * time / 2.0;
}

static void log_distance(FILE *fp, double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long ns = (long)(ts.tv_sec * 1000000000L + ts.tv_nsec);
    if (fprintf(fp, "%ld.%09ld,%.2f\n", ts.tv_sec, ts.tv_nsec, distance_cm) < 0) {
        perror("fprintf");
    }
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize TRIGGER_PIN low\n");
        gpioTerminate();
        return 1;
