#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define BUZZER_GPIO 17
#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 1.5f
#define SAMPLE_DELAY_US 10000
#define I2C_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_lis3dh(int handle) {
    if (i2cWriteByteData(handle, 0x20, 0x77) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x23, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int retries = I2C_RETRIES;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(handle, 0x28, buffer, 6);
        if (bytes_read == 6) {
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
            *x = (float)x_raw / 16384.0f;
            *y = (float)y_raw / 16384.0f;
            *z = (float)z_raw / 16384.0f;
            return 0;
        }
        fprintf(stderr, "Warning: I2C read failed (returned %d), retries left: %d\n", bytes_read, retries - 1);
        retries--;
        gpioDelay(1000);
    }
    fprintf(stderr, "Error: Failed to read acceleration data after %d retries\n", I2C_RETRIES);
    return -1;
}

static void detect_fall(float x, float y, float z, float *freefall) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude < FREEFALL_THRESHOLD) {
        *freefall = 1.0f;
    } else {
        *freefall = 0.0f;
    }
}

static void detect_impact(float x, float y, float z, float *impact) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        *impact = 1.0f;
    } else {
        *impact = 0.0f;
    }
}

static void activate_buzzer(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(1000000);
    gpioWrite(gpio_pin, 0);
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", LIS3DH_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Error: LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Fall detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float x, y, z;
        float freefall = 0.0f;
        float impact = 0.0f;

        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            detect_fall(x, y, z, &freefall);
            detect_impact(x, y, z, &impact);

            if (freefall && impact) {
                printf("Impact detected! Activating buzzer.\n");
                activate_buzzer(BUZZER_GPIO);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

