    if (gpioWrite(pins[0], wave_seq[step][0]) < 0) return -1;
    if (gpioWrite(pins[1], wave_seq[step][1]) < 0) return -1;
    if (gpioWrite(pins[2], wave_seq[step][2]) < 0) return -1;
    if (gpioWrite(pins[3], wave_seq[step][3]) < 0) return -1;
    return 0;
}

static int move_motor(int motor, int steps) {
    for (int i = 0; i < steps && running; i++) {
        if (set_motor_pins(motor, i % 4) < 0) {
            fprintf(stderr, "Error: gpioWrite failed for motor %d step %d\n", motor, i);
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return 0;
}

static int draw_square(int motor1_steps, int motor2_steps) {
    int x_steps = (int)(SQUARE_SIZE_MM * STEPS_PER_MM);
    int y_steps = (int)(SQUARE_SIZE_MM * STEPS_PER_MM);

    if (move_motor(1, x_steps) < 0) return -1;
    if (move_motor(2, y_steps) < 0) return -1;

    /* Move back to starting position */
    if (move_motor(1, -x_steps) < 0) return -1;
    if (move_motor(2, -y_steps) < 0) return -1;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Set all motor GPIO pins as outputs */
    int motor_pins[8] = {
        MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4,
        MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4
    };
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", motor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Drawing square on Raspberry Pi 3 Model B+\n");
    printf("Motor 1 (X-axis): IN1=GPIO4, IN2=GPIO17, IN3=GPIO27, IN4=GPIO22\n");
    printf("Motor 2 (Y-axis): IN1=GPIO5, IN2=GPIO6, IN3=GPIO13, IN4=GPIO19\n");
    printf("Square size: %.1f mm x %.1f mm\n", SQUARE_SIZE_MM, SQUARE_SIZE_MM);
    printf("Steps per mm: %.0f\n", (int)STEPS_PER_MM);
    printf("Step delay: %d us\n", STEP_DELAY_US);
    printf("Press Ctrl+C to stop.\n\n");

    if (draw_square(0, 0) < 0) {
        fprintf(stderr, "Error: motor movement failed\n");
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR1_IN3, 0);
        gpioWrite(MOTOR1_IN4, 0);
        gpioWrite(MOTOR2_IN1, 0);
        gpioWrite(MOTOR2_IN2, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Stop motors and release GPIO resources */
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
    gpioTerminate();

    printf("\nSquare drawing complete.\n");
    return EXIT_SUCCESS;
}

