#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR_MIN 0x08
#define I2C_ADDR_MAX 0x77
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LOG_FILE "/var/log/high_acceleration.log"
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X, rc=%d)\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg=0x%02X, len=%u, rc=%d)\n", reg, len, rc);
    }
    return rc;
}

static int configure_lis3dh(int handle) {
    if (i2c_write_byte(handle, CTRL_REG1, 0x57) < 0) return -1;
    if (i2c_write_byte(handle, CTRL_REG4, 0x88) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];
    int rc = i2c_read_block(handle, OUT_X_L | 0x80, buf, 6);
    if (rc < 0) return -1;
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 2048.0f * 0.0009765625f;
    *y = (float)raw_y / 2048.0f * 0.0009765625f;
    *z = (float)raw_z / 2048.0f * 0.0009765625f;
    return 0;
}

static void log_event(float x, float y, float z, float threshold) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - High acceleration: X=%.3f g, Y=%.3f g, Z=%.3f g (threshold %.3f g)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z, threshold);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("High acceleration detected! Shutting down system...\n");
    fflush(stdout);
    int rc = system("sudo shutdown -h now");
    if (rc != 0) {
        fprintf(stderr, "shutdown command failed with status %d\n", rc);
    }
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    int i2c_address = 0x18;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            int addr = (int)strtol(argv[i + 1], NULL, 16);
            if (addr < I2C_ADDR_MIN || addr > I2C_ADDR_MAX) {
                fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x08-0x77)\n", addr);
                return 1;
            }
            i2c_address = addr;
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[i + 1], NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Threshold must be greater than 0\n");
                return 1;
            }
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-t threshold_g]\n", argv[0]);
            return 1;
        }
    }

    if (i2c_address == 0x18 && threshold == DEFAULT_THRESHOLD) {
        fprintf(stderr, "Using default threshold %.2f g\n", DEFAULT_THRESHOLD);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed (non-hardware environment?)\n");
        return 0;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X (rc=%d)\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (configure_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration (threshold %.2f g, address 0x%02X)...\n", threshold, i2c_address);
    fflush(stdout);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z, threshold);
                shutdown_system();
                break;
            }
        } else {
            fprintf(stderr, "Sensor read error, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

