#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

#define BUFFER_SIZE 5
#define ALERT_DURATION_MS 2000
#define POLL_INTERVAL_US 10000

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *left_line = NULL;
static struct gpiod_line *center_line = NULL;
static struct gpiod_line *right_line = NULL;
static struct gpiod_line *alert_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, SensorData data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void cb_print(const CircularBuffer *cb) {
    printf("\n--- Circular Buffer ---\n");
    int start = (cb->count == BUFFER_SIZE) ? cb->head : 0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%d] L=%d C=%d R=%d\n", i, cb->data[idx].left, cb->data[idx].center, cb->data[idx].right);
    }
    printf("--- End ---\n");
}

static void cleanup(void) {
    if (alert_line) {
        gpiod_line_set_value(alert_line, 0);
        gpiod_line_release(alert_line);
        alert_line = NULL;
    }
    if (right_line) { gpiod_line_release(right_line); right_line = NULL; }
    if (center_line) { gpiod_line_release(center_line); center_line = NULL; }
    if (left_line) { gpiod_line_release(left_line); left_line = NULL; }
    if (chip) { gpiod_chip_close(chip); chip = NULL; }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return -1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(left_line, "line-follower") < 0) {
        fprintf(stderr, "Failed to request LEFT line: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(center_line, "line-follower") < 0) {
        fprintf(stderr, "Failed to request CENTER line: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(right_line, "line-follower") < 0) {
        fprintf(stderr, "Failed to request RIGHT line: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(alert_line, "line-follower", 0) < 0) {
        fprintf(stderr, "Failed to request ALERT line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static void motor_forward(void) {
    printf("Moving forward...\n");
}

static void motor_backward(void) {
    printf("Moving backward...\n");
}

static void motor_left(void) {
    printf("Turning left...\n");
}

static void motor_right(void) {
    printf("Turning right...\n");
}

static void motor_stop(void) {
    printf("Stopping...\n");
}

static void check_line_following(void) {
    SensorData current;
    int left = read_sensor(left_line);
    int center = read_sensor(center_line);
    int right = read_sensor(right_line);

    if (left < 0 || center < 0 || right < 0) {
        fprintf(stderr, "Sensor read error, stopping.\n");
        motor_stop();
        return;
    }

    current.left = left;
    current.center = center;
    current.right = right;

    cb_add(&buffer, current);

    if (center == 0) {
        motor_forward();
    } else if (left == 0) {
        motor_left();
    } else if (right == 0) {
        motor_right();
    } else {
        motor_stop();
    }

    if (center == 1 && buffer.count >= 5) {
        printf("No line detected for 5 consecutive readings. Triggering alert.\n");
        gpiod_line_set_value(alert_line, 1);
        usleep(ALERT_DURATION_MS * 1000);
        gpiod_line_set_value(alert_line, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    cb_init(&buffer);

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        check_line_following();
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

