#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0f
#define SAMPLE_INTERVAL_US 100000
#define MEAS_TIMEOUT_ATTEMPTS 50
#define MEAS_TIMEOUT_DELAY_US 1000
#define FIELD_MT_PER_X100 0.01f
#define FIELD_X100_TO_MT 1000.0f

#define SI7210_REG_MEAS 0xC1
#define SI7210_REG_DATA 0xC0
#define SI7210_CMD_MEAS 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) {
        perror("fopen magnetic_events.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fclose(fp);
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

static int read_field_raw(int16_t *out) {
    int rc;
    for (int i = 0; i < MEAS_TIMEOUT_ATTEMPTS; i++) {
        rc = i2cWriteByteData(i2c_handle, SI7210_REG_MEAS, SI7210_CMD_MEAS);
        if (rc < 0) {
            fprintf(stderr, "i2cWriteByteData (cmd) failed: %d\n", rc);
            return -1;
        }
        gpioDelay(MEAS_TIMEOUT_DELAY_US);
        rc = i2cReadByteData(i2c_handle, SI7210_REG_MEAS);
        if (rc < 0) {
            fprintf(stderr, "i2cReadByteData (poll) failed: %d\n", rc);
            return -1;
        }
        if (rc == 0x00) {
            uint8_t data[2];
            rc = i2cReadI2CBlockData(i2c_handle, SI7210_REG_DATA, (char *)data, 2);
            if (rc != 2) {
                fprintf(stderr, "i2cReadI2CBlockData failed: %d\n", rc);
                return -1;
            }
            *out = (int16_t)((data[1] << 8) | data[0]);
            return 0;
        }
        gpioDelay(MEAS_TIMEOUT_DELAY_US);
    }
    fprintf(stderr, "Si7210 measurement timeout\n");
    return -1;
}

static float raw_to_mt(int16_t raw) {
    return (float)raw * FIELD_MT_PER_X100;
}

static void control_relay(int on) {
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite failed\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_relay(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    int relay_state = 0;
    int consecutive_errors = 0;

    while (running) {
        int16_t raw;
        if (read_field_raw(&raw) == 0) {
            float field_mt = raw_to_mt(raw);
            consecutive_errors = 0;
            if (field_mt > (THRESHOLD_MT * FIELD_X100_TO_MT)) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                log_event("Too many consecutive read errors, deactivating relay");
                control_relay(0);
                consecutive_errors = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

