#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    return 0;
}

static int initialize_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket creation failed");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }
    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }
    return fd;
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    while (running) {
        bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            buffer[strcspn(buffer, "\r\n")] = '\0';
            char command[16];
            strncpy(command, buffer, sizeof(command) - 1);
            command[sizeof(command) - 1] = '\0';
            command[strcspn(command, " \t")] = '\0';
            command[0] = toupper(command[0]);
            if (strcmp(command, "ON") == 0) {
                gpioWrite(GPIO_PIN, 1);
                log_event("Relay turned ON");
            } else if (strcmp(command, "OFF") == 0) {
                gpioWrite(GPIO_PIN, 0);
                log_event("Relay turned OFF");
            } else {
                log_event("Invalid command received");
            }
            send(client_fd, "OK\n", 3, 0);
        } else if (bytes_received == 0) {
            break;
        } else {
            if (errno != EINTR) {
                perror("recv failed");
            }
            break;
        }
    }
    close(client_fd);
    client_fd = -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }
    if (initialize_gpio() != 0) {
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file failed");
        gpioTerminate();
        return 1;
    }
    server_fd = initialize_socket();
    if (server_fd < 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    printf("Server listening on port %d\n", PORT);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept failed");
            break;
        }
        handle_client(client_fd);
    }
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    if (log_file) fclose(log_file);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    printf("Server shut down cleanly\n");
    return 0;
}

