#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SENSOR1_ADDR   0x08
#define SENSOR2_ADDR   0x09
#define RELAY_GPIO     18
#define FLOW_THRESHOLD 5.0f
#define POLL_DELAY_US  100000
#define LOG_FILE       "flow_log.txt"

/* SLF3S-1300F start-measurement command (no averaging, no clock stretching) */
static const uint8_t START_CMD[2] = {0x36, 0x08};

static volatile sig_atomic_t g_running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)                */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Open an I2C handle to the given address                             */
/* ------------------------------------------------------------------ */
static int open_i2c_sensor(uint8_t addr)
{
    int h = i2cOpen(I2C_BUS, addr, 0);
    if (h < 0) {
        fprintf(stderr, "i2cOpen failed for 0x%02X (pigpio error %d)\n",
                addr, h);
        return -1;
    }
    return h;
}

/* ------------------------------------------------------------------ */
/* Start continuous measurement on the sensor                          */
/* ------------------------------------------------------------------ */
static int start_measurement(int handle)
{
    uint8_t cmd[2] = START_CMD;
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (start) failed on handle %d (pigpio %d)\n",
                handle, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 3 bytes (2 data + 1 CRC) from the sensor                         */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch           */
/* ------------------------------------------------------------------ */
static int read_sensor(int handle, float *flow_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "i2cReadDevice failed on handle %d (rc=%d)\n", handle, rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on handle %d (calc=0x%02X recv=0x%02X)\n",
                handle, crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 1500.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one successful cycle to the log file                             */
/* ------------------------------------------------------------------ */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- relay GPIO setup ---- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open I2C sensors ---- */
    i2c_handle1 = open_i2c_sensor(SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    i2c_handle2 = open_i2c_sensor(SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start measurements ---- */
    if (start_measurement(i2c_handle1) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (start_measurement(i2c_handle2) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow monitoring started.  Threshold=%.1f ml/min.  Ctrl-C to exit.\n",
           FLOW_THRESHOLD);

    /* ---- main loop ---- */
    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_sensor(i2c_handle1, &f1) == 0);
        int ok2 = (read_sensor(i2c_handle2, &f2) == 0);

        if (ok1 && ok2) {
            printf("Sensor1: %.2f ml/min  Sensor2: %.2f ml/min\n", f1, f2);
            if (f1 < FLOW_THRESHOLD && f2 < FLOW_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
                printf("  -> Relay energized\n");
            } else {
                gpioWrite(RELAY_GPIO, 0);
                printf("  -> Relay de-energized\n");
            }
            log_flow_data(f1, f2);
        } else {
            fprintf(stderr, "Read error — skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    cleanup();
    printf("Flow monitoring stopped.\n");
    return EXIT_SUCCESS;
}

