#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_THRESHOLD_US  600000   /* 3 polls * 200 ms = 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned gpio, unsigned level)
{
    if (gpioWrite(gpio, level) != 0) {
        syslog(LOG_WARNING, "gpioWrite(%u, %u) failed", gpio, level);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    if (safe_write(MOTOR_ENA_PIN, 0) != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 0) != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0)
        return -1;
    return 0;
}

static int motor_close_window(void)
{
    if (safe_write(MOTOR_ENA_PIN, 1) != 0)
        return -1;
    if (safe_write(MOTOR_IN1_PIN, 1) != 0)
        return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) != 0)
        return -1;
    return 0;
}

static int rain_detected(void)
{
    int v = gpioRead(RAIN_SENSOR_PIN);
    if (v < 0) {
        syslog(LOG_WARNING, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
        return 0;
    }
    return (v == 0);  /* LOW = rain detected */
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_INPUT) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) != 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(%d, PI_PUD_UP) failed", RAIN_SENSOR_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode motor pins failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started (GPIO %d=rain, %d=ENA,%d=IN1,%d=IN2)",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int dry_count = 0;

    while (g_running) {
        if (rain_detected()) {
            syslog(LOG_INFO, "Rain detected - closing window");
            if (motor_close_window() != 0) {
                syslog(LOG_ERR, "Motor close-window sequence failed");
            } else {
                syslog(LOG_INFO, "Window closed");
            }
            dry_count = 0;
        } else {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD_US / POLL_INTERVAL_US) {
                syslog(LOG_INFO, "Dry for %d polls - suppressing triggers",
                       dry_count);
                dry_count = 0;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down - stopping motor");
    motor_stop();
    gpioTerminate();
    syslog(LOG_INFO, "Rain window controller stopped");
    closelog();
    return EXIT_SUCCESS;
}

