#include <pigpio.h>

#define SERVO_PIN      18
#define BUTTON1_PIN    21
#define BUTTON2_PIN    22

#define LOCK_PULSE_US  2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US    200000   /* 200 ms */
#define POLL_DELAY_US   10000    /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", SERVO_PIN);
        return -1;
    }

    if (gpioSetMode(BUTTON1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", BUTTON1_PIN);
        return -1;
    }
    if (gpioSetMode(BUTTON2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", BUTTON2_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", BUTTON1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(BUTTON2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", BUTTON2_PIN);
        return -1;
    }

    return 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) != 0) {
        fprintf(stderr, "Error: gpioServo(%d) failed.\n", pulse_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release pigpio resources. */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
