        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door-lock control started. Press Ctrl+C to exit.\n");

    int last_button1 = 1;   /* pulled high when not pressed */
    int last_button2 = 1;
    int locked = 0;
    int last_state1 = 0;
    int last_state2 = 0;
    uint32_t last_press1_tick = 0;
    uint32_t last_release1_tick = 0;
    uint32_t last_press2_tick = 0;
    uint32_t last_release2_tick = 0;

