        int b1 = gpioRead(BUTTON1_PIN);
        int b2 = gpioRead(BUTTON2_PIN);

        if (b1 < 0 || b2 < 0) {
            fprintf(stderr, "Error: gpioRead failed on button pin.\n");
            break;
        }

        /* Button 1: pressed = 0 (ground), released = 1 (pull-up high) */
        if (b1 == 0 && last_button1 == 1) {
            uint32_t now = gpioTick();
            if (now - last_press1_tick > DEBOUNCE_US) {
                last_press1_tick = now;
                if (last_state1 == 0) {
                    locked = !locked;
                    if (set_servo(locked ? LOCK_PULSE_US : UNLOCK_PULSE_US) == 0) {
                        last_state1 = 1;
                    }
                }
            }
        }
        last_button1 = b1;

        /* Button 2: pressed = 0, released = 1 */
        if (b2 == 0 && last_button2 == 1) {
            uint32_t now = gpioTick();
            if (now - last_press2_tick > DEBOUNCE_US) {
                last_press2_tick = now;
                if (last_state2 == 0) {
                    locked = !locked;
                    if (set_servo(locked ? LOCK_PULSE_US : UNLOCK_PULSE_US) == 0) {
                        last_state2 = 1;
                    }
                }
            }
        }
        last_button2 = b2;

        /* Track release events for debouncing */
        if (b1 == 1 && last_state1 == 0) {
            last_release1_tick = gpioTick();
        }
        if (b2 == 1 && last_state2 == 0) {
            last_release2_tick = gpioTick();
        }

        /* Re-assert servo when button released to avoid stale pulse */
        if (locked && last_state1 == 1) {
            set_servo(0);
        }
        if (!locked && last_state2 == 1) {
            set_servo(0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

