#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN      4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_DURATION 60
#define POLL_INTERVAL_US 100000
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, int duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s (duration: %d seconds)\n", timestamp, event_type, duration) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set floodlight ON (GPIO %d)\n", FLOODLIGHT_PIN);
        return -1;
    }
    return 0;
}

static int deactivate_floodlight(void) {
    if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set floodlight OFF (GPIO %d)\n", FLOODLIGHT_PIN);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set floodlight pin %d as output\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize floodlight pin %d to LOW\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    deactivate_floodlight();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() < 0) {
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    int floodlight_active = 0;
    uint32_t start_tick = 0;
    int last_pir_state = 0;

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR pin %d\n", PIR_PIN);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected on GPIO %d\n", PIR_PIN);

            if (activate_floodlight() < 0) {
                break;
            }

            floodlight_active = 1;
            start_tick = gpioTick();
            last_pir_state = 1;
        }

        if (floodlight_active) {
            uint32_t elapsed = gpioTick() - start_tick;
            if (elapsed >= (uint32_t)(FLOODLIGHT_DURATION * 1000000)) {
                printf("Floodlight activation complete. Deactivating.\n");
                if (deactivate_floodlight() < 0) {
                    break;
                }
                floodlight_active = 0;
                if (log_event("FLOODLIGHT_DEACTIVATED", (int)FLOODLIGHT_DURATION) < 0) {
                    fprintf(stderr, "Warning: failed to log floodlight deactivation\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Smart Security Light System stopped.\n");
    return 0;
}

