#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_PERIOD_US 20000  /* 50 Hz */
#define PULSE_MIN_US 1000    /* 0 degrees */
#define PULSE_MAX_US 2000    /* 180 degrees */
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    closelog();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        syslog(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }

    if (gpiod_line_request_output(servo_line, "servo-pwm", 0) < 0) {
        syslog(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }

    return 0;
}

static void *servo_thread(void *arg) {
    (void)arg;
    int angle = 0;
    int direction = 1;

    while (running) {
        angle += direction;
        if (angle > 180) angle = 180;
        if (angle < 0) angle = 0;

        int pulse_width = PULSE_MIN_US + (angle * (PULSE_MAX_US - PULSE_MIN_US) / 180);
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_event("Error: Failed to set servo high");
            usleep(10000);
            continue;
        }
        usleep(pulse_width);
        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_event("Error: Failed to set servo low");
            usleep(10000);
            continue;
        }
        usleep(PWM_PERIOD_US - pulse_width);
        direction *= -1;
    }
    return NULL;
}

static void handle_command(int client_socket, const char *command) {
    char response[256];
    int ret;

    if (strncmp(command, "SERVO", 5) == 0) {
        int angle = atoi(command + 5);
        if (angle < 0 || angle > 180) {
            snprintf(response, sizeof(response), "Invalid angle: %s", command);
        } else {
            snprintf(response, sizeof(response), "Servo set to %d degrees", angle);
        }
    } else if (strcmp(command, "PIR") == 0) {
        int pir_value = gpiod_line_get_value(pir_line);
        snprintf(response, sizeof(response), "PIR: %d", pir_value);
    } else {
        snprintf(response, sizeof(response), "Unknown command: %s", command);
    }

    ret = send(client_socket, response, strlen(response), 0);
    if (ret < 0) {
        log_event("Error: Failed to send response");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_event("Error: Failed to create socket");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("Error: Failed to set SO_REUSEADDR");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Error: Failed to bind socket");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_event("Error: Failed to listen on socket");
        cleanup();
        return 1;
    }

    log_event("Security system started");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_event("Error: Failed to accept connection");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        char client_port[16];
        snprintf(client_port, sizeof(client_port), "%d", ntohs(client_addr.sin_port));

        char buffer[1024];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_event(buffer);
            handle_command(client_socket, buffer);
        } else if (bytes_received == 0) {
            log_event("Client disconnected");
        } else {
            log_event("Error: Failed to receive data");
        }

        close(client_socket);
    }

    log_event("Shutting down security system");
    cleanup();
    return 0;
}

