#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT_LINE  23
#define HX711_SCK_LINE   24
#define SOLENOID_LINE    25

#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define DOUT_TIMEOUT_MS   1000
#define POLL_INTERVAL_MS  500

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_dout_low(struct gpiod_line *dout, int timeout_ms) {
    int elapsed = 0;
    while (gpiod_line_get_value(dout) == 1) {
        if (elapsed >= timeout_ms) {
            syslog(LOG_ERR, "Timeout waiting for HX711 DOUT to go LOW");
            return -1;
        }
        usleep(1000);
        elapsed++;
    }
    return 0;
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, int *out_raw) {
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
        return -1;
    }
    if (wait_for_dout_low(dout, DOUT_TIMEOUT_MS) < 0) {
        return -1;
    }
    int raw = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "Failed to set SCK high: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        raw = (raw << 1) | (gpiod_line_get_value(dout) & 1);
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "Failed to set SCK low: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "Failed to set SCK high (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "Failed to set SCK low (25th pulse): %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (out_raw) *out_raw = raw;
    return 0;
}

static double calculate_weight(int raw, double scale, double tare_offset) {
    return (raw - tare_offset) / scale;
}

static void control_solenoid(struct gpiod_line *sol, int duration_ms) {
    if (gpiod_line_set_value(sol, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

int main(int argc, char *argv[]) {
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    const char *threshold_str = "--threshold";
    const char *scale_str = "--scale";
    const char *duration_str = "--duration";
    if (argc > 1) threshold_str = argv[1];
    if (argc > 2) scale_str = argv[2];
    if (argc > 3) duration_str = argv[3];

    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    if (threshold_str && threshold_str[0] != '\0') {
        threshold = atof(threshold_str);
        if (threshold <= 0) threshold = DEFAULT_THRESHOLD;
    }
    if (scale_str && scale_str[0] != '\0') {
        scale = atof(scale_str);
        if (scale <= 0) scale = DEFAULT_SCALE;
    }
    if (duration_str && duration_str[0] != '\0') {
        duration = atoi(duration_str);
        if (duration <= 0) duration = DEFAULT_DURATION;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_LINE);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_LINE);
    struct gpiod_line *sol = gpiod_chip_get_line(chip, SOLENOID_LINE);
    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s", strerror(errno));
        goto cleanup;
    }

    syslog(LOG_INFO, "Weight monitor started (threshold=%.0f, scale=%.6f, duration=%dms)",
           threshold, scale, duration);

    double tare_offset = 0.0;
    int tare_ok = 0;
    for (int i = 0; i < TARE_READINGS && running; i++) {
        int raw;
        if (read_hx711(dout, sck, &raw) == 0) {
            tare_offset += raw;
            tare_ok++;
        } else {
            syslog(LOG_ERR, "Tare read %d failed", i + 1);
        }
        usleep(100000);
    }
    if (tare_ok < TARE_READINGS) {
        syslog(LOG_ERR, "Tare failed: %d valid readings", tare_ok);
        goto cleanup;
    }
    tare_offset /= tare_ok;
    syslog(LOG_INFO, "Tare offset: %.0f", tare_offset);

    while (running) {
        int sum = 0;
        int ok = 0;
        for (int i = 0; i < NUM_READINGS && running; i++) {
            int raw;
            if (read_hx711(dout, sck, &raw) == 0) {
                sum += raw;
                ok++;
            } else {
                syslog(LOG_ERR, "Read %d failed", i + 1);
            }
            usleep(100000);
        }
        if (!ok) {
            syslog(LOG_ERR, "All %d readings failed, exiting", NUM_READINGS);
            break;
        }
        double avg = (double)sum / ok;
        double weight = calculate_weight((int)avg, scale, tare_offset);
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            control_solenoid(sol, duration);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down");
    if (gpiod_line_set_value(sol, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW on exit: %s", strerror(errno));
    }
    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

