/*
 * relay_controller.c — MQTT relay controller for Raspberry Pi 4 Model B
 *
 * Subscribes to home/lights/control and drives GPIO17 (BCM 17, physical pin 11)
 * using pigpio.  On a successful connect, keeps the relay in the last
 * received state; on any error, keeps the relay OFF and retries after a
 * 5-second backoff.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *         -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER      "localhost"
#define MQTT_PORT         1883
#define MQTT_TOPIC        "home/lights/control"
#define MQTT_CLIENT_ID    "relay_controller_1"
#define MQTT_KEEPALIVE    60
#define MQTT_CLEANSESS    1
#define MQTT_QOS         0

#define GPIO_PIN          17          /* BCM 17, physical pin 11 */
#define GPIO_INIT_STATE   0           /* relay OFF at startup */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed for pin %d", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN, GPIO_INIT_STATE) < 0) {
        syslog(LOG_ERR, "gpioWrite failed for pin %d", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO %d initialised to %d", GPIO_PIN, GPIO_INIT_STATE);
    return 0;
}

static void gpio_set_state(int state)
{
    if (gpioWrite(GPIO_PIN, state) < 0) {
        syslog(LOG_ERR, "gpioWrite failed for pin %d", GPIO_PIN);
    } else {
        syslog(LOG_INFO, "GPIO %d set to %d", GPIO_PIN, state);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                       */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, MQTT_CLEANSESS, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed (client ID %s)", MQTT_CLIENT_ID);
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(g_mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(g_mosq, mqtt_message_callback);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "MQTT client connected to %s:%d", MQTT_BROKER, MQTT_PORT);
    return 0;
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    (void)mosq; (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to broker");
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq; (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT disconnected cleanly");
    } else {
        syslog(LOG_WARNING, "MQTT unexpected disconnect: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata,
                                  const struct mosquitto_message *message)
{
    (void)mosq; (void)userdata;

    if (message->payloadlen <= 0) {
        syslog(LOG_WARNING, "Empty MQTT message on topic %s", message->topic);
        return;
    }

    const char *payload = (const char *)message->payload;
    syslog(LOG_INFO, "Received MQTT message on %s: '%s'", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        gpio_set_state(1);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set_state(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on topic %s", payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("relay_controller", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int rc = mosquitto_loop_start(g_mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller running; press Ctrl+C to exit");

    while (g_running) {
        sleep(1);
    }

    syslog(LOG_INFO, "Shutting down");

    /* Graceful cleanup */
    gpio_set_state(GPIO_INIT_STATE);
    mosquitto_loop_stop(g_mosq, true);
    mosquitto_disconnect(g_mosq);
    mosquitto_destroy(g_mosq);
    mosquitto_lib_cleanup();

    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

