#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

#define SERVO1_POS 1000
#define SERVO2_POS 1500
#define SERVO3_POS 2000
#define SERVO4_POS 500
#define SERVO5_POS 2500

#define PWM_FREQ 50
#define PWM_RANGE 20000
#define HOLD_MS 3000

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1, SERVO2, SERVO3, SERVO4, SERVO5};
    int positions[] = {SERVO1_POS, SERVO2_POS, SERVO3_POS, SERVO4_POS, SERVO5_POS};
    int num_servos = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_servos; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != PWM_FREQ) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_servos; i++) {
        int pulsewidth = gpioPWM(pins[i], positions[i]);
        if (pulsewidth < 0) {
            fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    sleep(HOLD_MS);

    for (int i = 0; i < num_servos; i++) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

