#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

#define TARGET_SPEED_RPM 50
#define PWM_FREQUENCY 10000
#define PWM_RANGE 255
#define PI_KP 0.5
#define PI_KI 0.05
#define CONTROL_PERIOD_MS 100
#define STALL_TIMEOUT_SEC 2

static volatile int32_t encoder_a_ticks = 0;
static volatile int32_t encoder_b_ticks = 0;
static volatile bool encoder_a_stalled = false;
static volatile bool encoder_b_stalled = false;
static volatile bool running = true;

static void signal_handler(int sig) {
    (void)sig;
    running = false;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        encoder_a_ticks++;
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (level == 1) {
        encoder_b_ticks++;
    }
}

static void set_motor_direction(int motor, int dir) {
    if (motor == 1) {
        gpioWrite(MOTOR_A_DIR_PIN, dir);
    } else if (motor == 2) {
        gpioWrite(MOTOR_B_DIR_PIN, dir);
    }
}

static void set_motor_pwm(int motor, int duty) {
    if (motor == 1) {
        gpioPWM(MOTOR_A_PWM_PIN, duty);
    } else if (motor == 2) {
        gpioPWM(MOTOR_B_PWM_PIN, duty);
    }
}

static double calculate_rpm(int32_t ticks, double dt) {
    if (dt <= 0.0) return 0.0;
    return (double)(ticks / 64.0) * 60.0 / dt;
}

static void control_speed(int32_t current_ticks, double dt) {
    double error = TARGET_SPEED_RPM - calculate_rpm(current_ticks, dt);
    double pwm = PI_KP * error + PI_KI * (error * (PI_KI * dt));
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    set_motor_pwm(1, (int)pwm);
    set_motor_direction(1, (pwm > 0) ? 1 : 0);
    set_motor_pwm(2, (int)pwm);
    set_motor_direction(2, (pwm > 0) ? 1 : 0);
}

static void stall_detection(int32_t ticks, double dt) {
    if (dt > 0.0) {
        if (encoder_a_stalled && ticks != 0) {
            encoder_a_stalled = false;
        } else if (ticks == 0) {
            encoder_a_stalled = true;
        }
        if (encoder_b_stalled && ticks != 0) {
            encoder_b_stalled = false;
        } else if (ticks == 0) {
            encoder_b_stalled = true;
        }
    }
}

static void cleanup(void) {
    set_motor_pwm(1, 0);
    set_motor_pwm(2, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B_PIN, RISING_EDGE, 0, NULL, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B_PIN, RISING_EDGE, 0, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set encoder ISR functions\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct timespec last_tick, now;
    clock_gettime(CLOCK_MONOTONIC, &last_tick);
    double dt = 0.0;

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_tick.tv_sec) +
                         (now.tv_nsec - last_tick.tv_nsec) / 1e9;
        dt = elapsed;
        last_tick = now;

        if (dt > 0.0) {
            int32_t current_a = encoder_a_ticks;
            int32_t current_b = encoder_b_ticks;

            control_speed(current_a, dt);
            stall_detection(current_a, dt);

            int32_t target_a = (TARGET_SPEED_RPM / 60.0) * 64.0;
            int32_t target_b = (TARGET_SPEED_RPM / 60.0) * 64.0;

            if (current_a < target_a) {
                set_motor_pwm(1, (int)(PI_KP * (target_a - current_a) * dt));
            } else if (current_a > target_a) {
                set_motor_pwm(1, (int)(PI_KP * (current_a - target_a) * dt));
            }

            if (current_b < target_b) {
                set_motor_pwm(2, (int)(PI_KP * (target_b - current_b) * dt));
            } else if (current_b > target_b) {
                set_motor_pwm(2, (int)(PI_KP * (current_b - target_b) * dt));
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

