        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set encoder pin modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_B_PIN, RISING_EDGE, 0, NULL, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_B_PIN, RISING_EDGE, 0, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set encoder ISR functions\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct timespec last_tick, now;
    clock_gettime(CLOCK_MONOTONIC, &last_tick);
    double dt = 0.0;

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - last_tick.tv_sec) +
                         (now.tv_nsec - last_tick.tv_nsec) / 1e9;
        dt = elapsed;
        last_tick = now;

        if (dt > 0.0) {
            int32_t current_a = encoder_a_ticks;
            int32_t current_b = encoder_b_ticks;

            control_speed(current_a, dt);
            stall_detection(current_a, dt);

            int32_t target_a = (TARGET_SPEED_RPM / 60.0) * 64.0;
            int32_t target_b = (TARGET_SPEED_RPM / 60.0) * 64.0;

            if (current_a < target_a) {
                set_motor_pwm(1, (int)(PI_KP * (target_a - current_a) * dt));
            } else if (current_a > target_a) {
                set_motor_pwm(1, (int)(PI_KP * (current_a - target_a) * dt));
            }

            if (current_b < target_b) {
                set_motor_pwm(2, (int)(PI_KP * (target_b - current_b) * dt));
            } else if (current_b > target_b) {
                set_motor_pwm(2, (int)(PI_KP * (current_b - target_b) * dt));
            }
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

