#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define RELAY_GPIO 17
#define LUX_LOW 50
#define LUX_HIGH 200
#define POLL_INTERVAL_SEC 5
#define LOG_FILE "chicken_coop_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static int relay_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BH1750_ADDR);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux) {
    if (i2cWriteByte(i2c_handle, BH1750_CMD_OT_HRES2) < 0) {
        fprintf(stderr, "BH1750 write command failed\n");
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "BH1750 read failed\n");
        return -1;
    }
    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_relay(float lux) {
    if (lux < LUX_LOW && relay_state == 0) {
        gpioWrite(RELAY_GPIO, 1);
        relay_state = 1;
        log_event("Relay ON (dusk)");
    } else if (lux > LUX_HIGH && relay_state == 1) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
        log_event("Relay OFF (dawn)");
    }
}

static void cleanup(void) {
    if (relay_state == 1) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        log_event("Program exiting");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_pigpio() != 0) return 1;
    if (init_i2c() != 0) { gpioTerminate(); return 1; }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    log_event("Program started");

    while (running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux = %.2f", lux);
            log_event(msg);
            control_relay(lux);
        } else {
            log_event("Sensor read error, turning off relay");
            gpioWrite(RELAY_GPIO, 0);
            relay_state = 0;
        }
        sleep(POLL_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

