#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000       /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_state(int state) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] Relay state: %s\n", ts, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch = 0;
    int first_touch = 1;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO %d to toggle relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);

        if (touch < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (first_touch) {
            /* First touch: record initial state */
            last_touch = touch;
            first_touch = 0;
        } else {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int debounced = gpioRead(TOUCH_SENSOR_PIN);

            if (debounced < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce.\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (debounced == touch) {
                /* Valid touch detected (both HIGH) */
                if (last_touch == touch) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                        fprintf(stderr, "Error: failed to write GPIO %d.\n", RELAY_PIN);
                        break;
                    }
                    log_state(relay_state);
                }
                last_touch = debounced;
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

