#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define FLOW_THRESHOLD 5.0
#define FLOW_OPEN_THRESHOLD 4.5
#define FLOW_CLOSE_THRESHOLD 4.5
#define HYSTERESIS 0.5
#define SAMPLE_INTERVAL_SEC 1
#define DEBOUNCE_TIMEOUT_US 1000000

static volatile int pulse_count = 0;
static volatile int solenoid_state = 1; /* 1 = open, 0 = closed */
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

static void control_solenoid(double flow_rate) {
    if (flow_rate > FLOW_THRESHOLD && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_GPIO, 0) == 0) {
            solenoid_state = 0;
            log_message("Solenoid closed (flow rate exceeded threshold)");
        } else {
            log_message("ERROR: Failed to close solenoid");
        }
    } else if (flow_rate < FLOW_CLOSE_THRESHOLD && solenoid_state == 0) {
        if (gpioWrite(SOLENOID_GPIO, 1) == 0) {
            solenoid_state = 1;
            log_message("Solenoid opened (flow rate below threshold)");
        } else {
            log_message("ERROR: Failed to open solenoid");
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Failed to open water_flow.log");
        gpioTerminate();
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Mutex init failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        log_message("ERROR: Failed to set flow sensor GPIO mode");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        log_message("ERROR: Failed to set solenoid GPIO mode");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) != 0) {
        log_message("ERROR: Failed to initialize solenoid to open state");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        log_message("ERROR: Failed to set ISR function");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message("ERROR: Failed to set signal handlers");
        pthread_mutex_destroy(&pulse_mutex);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_message("System started");

    while (running) {
        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double flow_rate = calculate_flow_rate(pulses);
        control_solenoid(flow_rate);

        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf), "Flow rate: %.2f L/min", flow_rate);
        log_message(log_buf);

        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    log_message("Shutting down");
    gpioWrite(SOLENOID_GPIO, 1);
    pthread_mutex_destroy(&pulse_mutex);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

