#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <getopt.h>
#include <errno.h>
#include <stdbool.h>

#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVO_PIN 18
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_SETTLE_TIME_US 1000000
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_US 1000
#define DISPENSE_DELAY_US 1000000
#define READ_DELAY_US 100000

typedef struct {
    float calibration_factor;
    char server_ip[64];
    int server_port;
    int servo_pin;
} Config;

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int sock_fd = -1;
static Config config = {DEFAULT_CALIBRATION_FACTOR, DEFAULT_SERVER_IP, DEFAULT_SERVER_PORT, DEFAULT_SERVO_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, Config *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) {
            cfg->calibration_factor = atof(value);
        } else if (strcmp(key, "server_ip") == 0) {
            strncpy(cfg->server_ip, value, sizeof(cfg->server_ip) - 1);
            cfg->server_ip[sizeof(cfg->server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) {
            cfg->server_port = atoi(value);
        } else if (strcmp(key, "servo_pin") == 0) {
            cfg->servo_pin = atoi(value);
        }
    }
    fclose(fp);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioSetMode(config.servo_pin, PI_OUTPUT);
    gpioSetPWMfrequency(config.servo_pin, 50);
    gpioSetPWMrange(config.servo_pin, 1000000);
    return 0;
}

static int read_hx711(int *raw_value) {
    int data = 0;
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < HX711_TIMEOUT_ATTEMPTS) {
        gpioDelay(1);
        timeout++;
    }
    if (timeout >= HX711_TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "Error: HX711 DATA pin stuck HIGH (sensor absent or not ready).\n");
        return -1;
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data = (data << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    *raw_value = data;
    return 0;
}

static float calibrate_hx711(int raw_value) {
    return (float)raw_value / config.calibration_factor;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    gpioServo(config.servo_pin, pulse_width);
    return 0;
}

static void log_event(float target_weight, float actual_weight, const char *error_msg) {
    FILE *fp = fopen(LOG_FILE, "r+");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
            return;
        }
        fprintf(fp, "{}\n", "{\"timestamp\":\"1970-01-01T00:00:00\"}");
    }
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size < 1) {
        fclose(fp);
        return;
    }
    fseek(fp, -1, SEEK_END);
    char *ptr = fread(buffer, 1, 1024 - (int)file_size, fp);
    if (ptr) {
        fprintf(fp, "\n");
        for (int i = 0; ptr[i] != '\0'; i++) {
            buffer[i] = ptr[i];
        }
    }
    fclose(fp);
    if (error_msg) {
        fprintf(buffer, ",\"error\":\"%s\"}", error_msg);
    } else {
        fprintf(buffer, ",\"actual_weight\":%.2f}", actual_weight);
    }
    FILE *log_fp = fopen(LOG_FILE, "w");
    if (log_fp) {
        fprintf(log_fp, "%s", buffer);
        fclose(log_fp);
    }
}

static void send_data(int sock_fd, float target_weight, float actual_weight) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "{\"target_weight\":%.2f,\"actual_weight\":%.2f}", target_weight, actual_weight);
    if (send(sock_fd, buffer, strlen(buffer), 0) < 0) {
        perror("send");
    }
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (sock_fd >= 0) {
        close(sock_fd);
        sock_fd = -1;
    }
    gpioServo(config.servo_pin, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:s:p:h")) != -1) {
        switch (opt) {
            case 'c':
                config.calibration_factor = atof(optarg);
                break;
            case 's':
                strncpy(config.server_ip, optarg, sizeof(config.server_ip) - 1);
                config.server_ip[sizeof(config.server_ip) - 1] = '\0';
                break;
            case 'p':
                config.server_port = atoi(optarg);
                break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c calibration_factor] [-s server_ip] [-p server_port]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (config.calibration_factor <= 0) {
        fprintf(stderr, "Error: Calibration factor must be positive.\n");
        return EXIT_FAILURE;
    }
    if (read_config(CONFIG_FILE, &config) != 0) {
        fprintf(stderr, "Error: Could not read config file. Using defaults.\n");
    }
    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return EXIT_FAILURE;
    }
    int opt_server = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt_server, sizeof(opt_server)) < 0) {
        perror("setsockopt");
        cleanup();
        return EXIT_FAILURE;
    }
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);
    server_addr.sin_port = htons(config.server_port);
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        cleanup();
        return EXIT_FAILURE;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Server listening on %s:%d\n", config.server_ip, config.server_port);
    while (running) {
        sock_fd = accept(server_fd, NULL, NULL);
        if (sock_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }
        char client_ip[64];
        getpeername(sock_fd, (struct sockaddr *)&client_ip, sizeof(client_ip));
        printf("Connection from %s\n", client_ip);
        char buffer[256];
        while (running) {
            memset(buffer, 0, sizeof(buffer));
            ssize_t bytes = recv(sock_fd, buffer, sizeof(buffer) - 1, 0);
            if (bytes > 0) {
                buffer[strcspn(buffer, "\r\n")] = '\0';
                if (strcmp(buffer, "target_weight") == 0) {
                    float target_weight;
                    if (sscanf(buffer + 15, "%f", &target_weight) == 1) {
                        printf("Target weight: %.2f g\n", target_weight);
                        if (set_servo_pulse_width(0) != 0) {
                            fprintf(stderr, "Error: Failed to set servo to dispense position.\n");
                            log_event(target_weight, 0.0, "servo_set failed");
                        } else {
                            gpioDelay(DISPENSE_DELAY_US);
                            int raw_value;
                            if (read_hx711(&raw_value) == 0) {
                                float actual_weight = calibrate_hx711(raw_value);
                                printf("Actual weight: %.2f g\n", actual_weight);
                                send_data(sock_fd, target_weight, actual_weight);
                                log_event(target_weight, actual_weight, NULL);
                            } else {
                                log_event(target_weight, 0.0, "hx711_read failed");
                            }
                        }
                    } else {
                        fprintf(stderr, "Error: Invalid target weight format.\n");
                        log_event(target_weight, 0.0, "invalid_target");
                    }
                } else {
                    fprintf(stderr, "Error: Invalid request format.\n");
                    log_event(0.0, 0.0, "invalid_request");
                }
            } else if (bytes == 0) {
                printf("Client disconnected.\n");
                break;
            } else {
                perror("recv");
                break;
            }
        }
        close(sock_fd);
        sock_fd = -1;
    }
    cleanup();
    return EXIT_SUCCESS;
}

