#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_ANGLE 90
#define ANGLE_STEP 10
#define PWM_FREQ 50
#define PWM_RANGE 20000

static volatile sig_atomic_t g_angle = DEFAULT_ANGLE;
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_terminal_mode(void) {
    struct termios old, newterm;
    memset(&old, 0, sizeof(old));
    memset(&newterm, 0, sizeof(newterm));

    if (tcgetattr(STDIN_FILENO, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }

    newterm.c_lflag &= ~(ICANON | ECHO);
    newterm.c_cc[VMIN] = 0;
    newterm.c_cc[VTIME] = 1; /* 100 ms inter-character timeout */

    if (tcsetattr(STDIN_FILENO, TCSANOW, &newterm) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int restore_terminal_mode(void) {
    struct termios old, newterm;
    memset(&old, 0, sizeof(old));
    memset(&newterm, 0, sizeof(newterm));

    if (tcgetattr(STDIN_FILENO, &old) != 0) {
        perror("tcgetattr");
        return -1;
    }

    newterm.c_lflag = old.c_lflag;
    newterm.c_cc[VMIN] = 1;
    newterm.c_cc[VTIME] = 5;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &newterm) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int read_input(void) {
    char buf[1];
    ssize_t n = read(STDIN_FILENO, buf, sizeof(buf) - 1);
    if (n < 0) {
        perror("read");
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    buf[n] = '\0';
    return (buf[0] == 'q' || buf[0] == 'Q') ? 1 : 0;
}

static int map_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    return angle;
}

static int set_servo_angle(int angle) {
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
    if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
    if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    g_angle = map_angle(angle);
    printf("Angle: %d degrees (pulse: %d us)\n", g_angle, pulse_width);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_terminal_mode() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SERVO_PIN);
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "gpioSetPWMfrequency failed for pin %d\n", SERVO_PIN);
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "gpioSetPWMrange failed for pin %d\n", SERVO_PIN);
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(g_angle) != 0) {
        restore_terminal_mode();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int c = read_input();
        if (c == 1) {
            break;
        }
        if (c < 0) {
            continue;
        }
        if (c == '+') {
            g_angle += ANGLE_STEP;
        } else if (c == '-') {
            g_angle -= ANGLE_STEP;
        }
        if (set_servo_angle(g_angle) != 0) {
            break;
        }
    }

    if (g_running) {
        gpioServo(SERVO_PIN, 0);
        restore_terminal_mode();
        gpioTerminate();
    }
    return EXIT_SUCCESS;
}

