#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_read(int pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (returned PI_BAD_GPIO)\n", pin);
        return -1;
    }
    return v;
}

static int safe_write(int pin, int level)
{
    int rc = gpioWrite(pin, level);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d (returned %d)\n", pin, rc);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure relay starts OFF (active-HIGH module) --- */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-activated relay control started.\n");
    printf("  Touch sensor : GPIO%d (3.3V HIGH on touch)\n", TOUCH_SENSOR_PIN);
    printf("  Relay        : GPIO%d (active-HIGH, OFF by default)\n", RELAY_PIN);
    printf("  Fail-safe    : if sensor stays HIGH for > %d s, relay is forced OFF\n",
           FAILSAFE_TIMEOUT);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    time_t last_touch_time = 0;
    int failsafe_active = 0;

    while (running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            /* Sensor read error — exit cleanly */
            break;
        }

        if (touch) {
            time_t now = time(NULL);
            if (!failsafe_active) {
                /* Rising edge: toggle relay */
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    break;
                }
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            } else {
                /* Sensor still HIGH — failsafe: force relay OFF */
                if (safe_write(RELAY_PIN, 0) != 0) {
                    break;
                }
                relay_state = 0;
                printf("Failsafe: relay forced OFF (sensor stuck HIGH)\n");
            }

            /* Update last-touch time */
            last_touch_time = now;

            /* Check failsafe timeout */
            if (difftime(now, last_touch_time) > (double)FAILSAFE_TIMEOUT) {
                failsafe_active = 1;
            }
        }

        /* Sleep 50 ms; gpioDelay is interruptible by signals */
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    if (safe_write(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to release relay during cleanup\n");
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

