#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define PULSES_PER_LITER   450.0
#define SAMPLE_INTERVAL_US 100000
#define TARGET_FLOW_RATE   5.0
#define KP                 1.0

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    g_pulse_count++;
}

static double calculate_flow_rate(uint32_t pulses, double interval_sec) {
    return (double)pulses / PULSES_PER_LITER * 60.0 / interval_sec;
}

static int set_valve_position(int duty_cycle) {
    if (gpioPWM(VALVE_PWM_PIN, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, duty_cycle > 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", VALVE_ENABLE_PIN);
        return -1;
    }
    return 0;
}

static int log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long ms = (long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
    if (fprintf(g_log_file, "%ld,%.2f,%d\n", ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t target_flow_rate_L_min\n", argv[0]);
        return EXIT_FAILURE;
    }

    double target_flow_rate = strtod(argv[1], NULL);
    if (target_flow_rate <= 0.0 || target_flow_rate > 100.0) {
        fprintf(stderr, "Error: target flow rate must be between 0 and 100 L/min\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for PWM pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for enable pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for flow sensor pin %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pin %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to enable valve pin %d\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (!g_log_file) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for pin %d\n", FLOW_SENSOR_PIN);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min. Press Ctrl+C to exit.\n", target_flow_rate);

    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        uint32_t pulses = g_pulse_count;
        g_pulse_count = 0;

        double interval_sec = (double)SAMPLE_INTERVAL_US / 1000000.0;
        double flow_rate = calculate_flow_rate(pulses, interval_sec);

        int valve_position = (int)(KP * (target_flow_rate - flow_rate));
        if (valve_position < 0) valve_position = 0;
        if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;

        if (set_valve_position(valve_position) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        if (log_data(flow_rate, valve_position) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

