#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define SPI_FLAGS 0
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_MS 50
#define DISENGAGE_MS 5000
#define POLL_MS 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static int read_rfid_tag(int handle, unsigned char *buf, int len) {
    char tx[32] = {0};
    char rx[32] = {0};
    int ret = spiXfer(handle, tx, rx, len);
    if (ret != len) {
        log_event("SPI transfer failed");
        return -1;
    }
    if (len == 10 && memcmp(rx, buf, len) == 0) {
        return 0;
    }
    if (len == 10 && memcmp(rx, buf, 10) == 0x00) {
        return 1; /* no tag present */
    }
    log_event("Invalid RFID tag read");
    return -1;
}

static int read_button(int pin) {
    int level = gpioRead(pin);
    if (level < 0) return -1;
    if (level == 0) {
        gpioDelay(DEBOUNCE_MS * 1000);
        level = gpioRead(pin);
        if (level < 0) return -1;
        if (level == 0) {
            gpioDelay(DEBOUNCE_MS * 1000);
            level = gpioRead(pin);
            if (level < 0) return -1;
            if (level == 0) {
                gpioDelay(DEBOUNCE_MS * 1000);
                level = gpioRead(pin);
                if (level < 0) return -1;
                if (level == 0) {
                    return 1;
                }
            }
        }
    }
    return 0;
}

static void engage_lock(int pin) {
    if (gpioWrite(pin, 0) < 0) {
        log_event("Failed to disengage lock");
        return;
    }
    log_event("Lock disengaged");
    gpioDelay(DEBOUNCE_MS * 1000);
    if (gpioWrite(pin, 1) < 0) {
        log_event("Failed to re-engage lock");
        return;
    }
    log_event("Lock re-engaged");
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    if (log_fp) {
        log_event("System shutting down");
        fclose(log_fp);
        log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LOCK1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        unsigned char tag[10] = {0};
        int tag_ok = read_rfid_tag(spi_handle, tag, sizeof(tag));
        if (tag_ok == 0) {
            if (read_button(BUTTON_PIN) == 1) {
                log_event("Two-factor authentication successful");
                engage_lock(LOCK1_PIN);
                engage_lock(LOCK2_PIN);
            } else {
                log_event("Button pressed without valid tag");
            }
        } else if (tag_ok < 0) {
            log_event("RFID read failed");
        }
        gpioDelay(POLL_MS * 1000);
    }

    cleanup();
    return 0;
}

