static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[4];
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void cleanup(void) {
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_set_value(motor_lines[i], 0);
            gpiod_line_release(motor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_motor_speed(int motor, int speed) {
    if (speed < -PULSES_PER_REV) speed = -PULSES_PER_REV;
    if (speed > PULSES_PER_REV) speed = PULSES_PER_REV;
    int duty = (int)((float)speed * PWM_DUTY_MAX / PULSES_PER_REV);
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;
    int on_us = (duty * PWM_PERIOD_US) / 1000000;
    int off_us = PWM_PERIOD_US - on_us;
    if (motor == 1) {
        gpiod_line_set_value(motor_lines[0], 1);
        gpiod_line_set_value(motor_lines[1], 0);
        gpiod_line_set_value(motor_lines[2], 0);
        usleep(on_us);
        gpiod_line_set_value(motor_lines[0], 0);
        gpiod_line_set_value(motor_lines[1], 1);
        gpiod_line_set_value(motor_lines[2], 0);
        usleep(off_us);
    } else {
        gpiod_line_set_value(motor_lines[3], 1);
        gpiod_line_set_value(motor_lines[4], 0);
        gpiod_line_set_value(motor_lines[5], 0);
        usleep(on_us);
        gpiod_line_set_value(motor_lines[3], 0);
        gpiod_line_set_value(motor_lines[4], 1);
        gpiod_line_set_value(motor_lines[5], 0);
        usleep(off_us);
    }
}

static void *encoder_thread(void *arg) {
    (void)arg;
    struct gpiod_line *a, *b;
    int id;
    if (encoder1_count > encoder2_count) {
        a = encoder_lines[0]; b = encoder_lines[1];
        id = 1;
    } else {
        a = encoder_lines[2]; b = encoder_lines[3];
        id = 0;
    }
    while (running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(a, NULL);
        if (ret < 0) continue;
        if (ret == 0) continue;
        if (gpiod_line_event_read(a, &event) < 0) continue;
        if (gpiod_line_get_value(b) == 0) {
            encoder1_count++;
        } else {
            encoder1_count--;
        }
        pthread_mutex_lock(&encoder_mutex);
        if (id == 0) encoder2_count++;
        else encoder2_count--;
        pthread_mutex_unlock(&encoder_mutex);
    }
    return NULL;
}

static double pid_calculate(int current_speed, double target_speed, double *integral, double *previous_error) {
    double error = target_speed - current_speed;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

static void log_data(double motor1_speed, double motor2_speed, double pid_p, double pid_i, double pid_d, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_speed, motor2_speed, pid_p, pid_i, pid_d, pid_output);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", motor_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %d\n", motor_pins[i]);
            cleanup();
            return 1;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder GPIO line %d\n", encoder_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request both-edge events for encoder GPIO %d\n", encoder_pins[i]);
            cleanup();
            return 1;
        }
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1 Speed (RPM),Motor2 Speed (RPM),PID P,I,D,Output\n");
    fflush(log_file);

    double integral = 0.0, previous_error = 0.0;
    pthread_t encoder_threads[2];
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&encoder_threads[i], NULL, encoder_thread, NULL) != 0) {
            perror("pthread_create");
            cleanup();
            return 1;
        }
    }

    while (running) {
        double motor1_speed = 0.0, motor2_speed = 0.0;
        double pid_p = 0.0, pid_i = 0.0, pid_d = 0.0, pid_output = 0.0;

        pthread_mutex_lock(&encoder_mutex);
        int count1 = encoder1_count;
        int count2 = encoder2_count;
        pthread_mutex_unlock(&encoder_mutex);

        double target_speed1 = TARGET_RPM;
        double target_speed2 = TARGET_RPM;

        double error1 = target_speed1 - count1;
        double error2 = target_speed2 - count2;
        pid_p = KP * error1 + KI * integral + KD * previous_error;
        pid_i += error1;
        pid_d = error1 - previous_error;
        previous_error = error1;
        pid_output = KP * error1 + KI * pid_i + KD * pid_d;

        motor1_speed = (int)(pid_output * (PULSES_PER_REV / 1000.0));
        motor2_speed = (int)(pid_output * (PULSES_PER_REV / 1000.0));

        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);

        log_data(motor1_speed, motor2_speed, pid_p, pid_i, pid_d, pid_output);

        usleep(SAMPLE_MS * 1000);
    }

    pthread_join(encoder_threads[0], NULL);
    pthread_join(encoder_threads[1], NULL);
    cleanup();
    return 0;
}

