#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_SOFTRESET 0x80

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (rc=%d)\n", value, reg, rc);
    }
    return rc;
}

static int mpr121_init(int handle) {
    /* Soft reset */
    if (mpr121_write_reg(handle, MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Filtering configuration (rising) */
    if (mpr121_write_reg(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCLT, 0x0E) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(handle, MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1; /* touch */
        if (mpr121_write_reg(handle, MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; /* release */
    }

    /* Enable run mode (filtering + electrodes) */
    if (mpr121_write_reg(handle, MPR121_ELECONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int handle, uint16_t *status) {
    int lo = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) {
        fprintf(stderr, "Error reading touch status low byte (rc=%d)\n", lo);
        return -1;
    }
    int hi = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) {
        fprintf(stderr, "Error reading touch status high byte (rc=%d)\n", hi);
        return -1;
    }
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s Relay state: %s\n", ts, state ? "ON" : "OFF");
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t touch_status = 0;
    int relay_state = 0;

    while (running) {
        if (read_touch_status(i2c_handle, &touch_status) == 0) {
            int any_touched = (touch_status & 0x0FFF) != 0;
            if (any_touched != relay_state) {
                relay_state = any_touched;
                gpioWrite(RELAY_GPIO, relay_state);
                log_relay_state(relay_state);
            }
        } else {
            fprintf(stderr, "I2C read error; retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

