#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X: %s\n", reg, pigpio_error(rc));
    }
    return rc;
}

static int mpr121_init(int handle) {
    if (mpr121_write(handle, MPR121_ECR, 0x00) < 0) return -1;  // stop mode
    if (mpr121_write(handle, MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_NHDT, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_NCLT, 0x01) < 0) return -1;
    if (mpr121_write(handle, MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + 2 * i, 0x0A) < 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + 2 * i, 0x05) < 0) return -1;
    }

    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (mpr121_write(handle, MPR121_ECR, 0x8F) < 0) return -1;  // enable 12 electrodes, run mode
    return 0;
}

static int read_touch_status(int handle) {
    int low = i2cReadByteData(handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "I2C read failed for touch status low: %s\n", pigpio_error(low));
        return -1;
    }
    int high = i2cReadByteData(handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "I2C read failed for touch status high: %s\n", pigpio_error(high));
        return -1;
    }
    return (high << 8) | low;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, MPR121_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 touch relay control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int status = read_touch_status(i2c_handle);
        if (status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (status > 0) {
            gpioWrite(RELAY_PIN, 1);
            printf("Relay ON\n");
        } else {
            gpioWrite(RELAY_PIN, 0);
            printf("Relay OFF\n");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

