#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000
#define LOG_FILE "door_events.log"

static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fprintf(log_file, "%s.%03ld: %s\n", timestamp, ms, event_type);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

static void unlock_door(void) {
    if (gpioWrite(RELAY_PIN, 1) < 0) {
        log_event("ERROR: Failed to activate relay");
        return;
    }
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        log_event("ERROR: Failed to deactivate relay");
    }
}

static void *motion_detection(void *arg) {
    (void)arg;
    int last_state = 0;
    uint32_t last_event_tick = 0;
    uint32_t last_unlock_tick = 0;

    while (running) {
        int current_state = gpioRead(PIR_PIN);
        uint32_t now = gpioTick();

        if (current_state == 1 && last_state == 0) {
            if (now - last_event_tick > RATE_LIMIT_MS * 1000) {
                if (now - last_unlock_tick > UNLOCK_DURATION_MS * 1000) {
                    unlock_door();
                    last_unlock_tick = now;
                }
            }
        }
        last_state = current_state;
        last_event_tick = now;
        gpioDelay(POLL_INTERVAL_US);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set PIR pull-down\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay to off\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    pthread_t motion_thread;
    if (pthread_create(&motion_thread, NULL, motion_detection, NULL) != 0) {
        perror("pthread_create failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running) {
        gpioDelay(100000);
    }

    pthread_join(motion_thread, NULL);
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return 0;
}

