        int motor2_duty = (rand() % (PWM_RANGE + 1));
        pattern[i * 2] = motor1_duty;
        pattern[i * 2 + 1] = motor2_duty;
    }
    return 0;
}

void play_pattern(int *pattern, int steps, int duration_ms) {
