    printf("Playing pattern with %d steps, %d ms duration...\n", steps, duration_ms);
    play_pattern(pattern, steps, duration_ms);
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    free(pattern);
    gpioTerminate();
    return 0;
}

