#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *calibration_fp = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int load_calibration(void) {
    calibration_fp = fopen(CALIBRATION_FILE, "r");
    if (!calibration_fp) {
        fprintf(stderr, "Warning: cannot open %s, using defaults\n", CALIBRATION_FILE);
        return -1;
    }
    if (fscanf(calibration_fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: invalid calibration data, using defaults\n");
        scale_factor = 1.0;
        offset = 0.0;
        fclose(calibration_fp);
        calibration_fp = NULL;
        return -1;
    }
    fclose(calibration_fp);
    calibration_fp = NULL;
    printf("Calibration loaded: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int save_calibration(void) {
    calibration_fp = fopen(CALIBRATION_FILE, "w");
    if (!calibration_fp) {
        fprintf(stderr, "Error: cannot open %s for writing\n", CALIBRATION_FILE);
        return -1;
    }
    fprintf(calibration_fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(calibration_fp);
    calibration_fp = NULL;
    printf("Calibration saved: scale=%.2f, offset=%.2f\n", scale_factor, offset);
    return 0;
}

static int read_hx711(int *raw_value) {
    if (!raw_value) return -1;
    *raw_value = 0;
    uint32_t start_tick = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 0) {
        if (gpioTick() - start_tick > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout waiting for data\n");
            return -1;
        }
    }
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        *raw_value = (*raw_value << 1) | gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);
    return 0;
}

static double convert_to_weight(int raw_value) {
    return ((double)raw_value - offset) / scale_factor;
}

static void control_solenoid(int lock) {
    gpioWrite(SOLENOID_PIN, lock ? 1 : 0);
}

static void log_weight(double weight) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_fp, "%s, %.2f\n", ts, weight);
    fflush(log_fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (load_calibration() != 0) {
        scale_factor = 1.0;
        offset = 0.0;
    }

    log_fp = fopen("weight_log.txt", "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening weight_log.txt\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(HX711_DATA_PIN, NULL) != 0) {
        fprintf(stderr, "Failed to set alert on HX711 data pin\n");
        fclose(log_fp);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Starting weight monitoring (threshold=%.1f kg)...\n", WEIGHT_THRESHOLD);

    while (running) {
        int raw;
        if (read_hx711(&raw) != 0) {
            gpioDelay(500000);
            continue;
        }
        double weight = convert_to_weight(raw);
        printf("Raw=%d, Weight=%.2f kg\n", raw, weight);
        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            control_solenoid(1);
            printf("Lock engaged\n");
        } else {
            control_solenoid(0);
            printf("Lock released\n");
        }

        gpioDelay(500000);
    }

    printf("\nShutting down...\n");
    control_solenoid(0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

