#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL_US 50000
#define RAIN_THRESHOLD 3
#define MOTOR_RUN_TIME_SEC 5
#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_DUTY 150
#define LOG_FILE "/var/log/window_control.log"
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, message);
    fclose(fp);
    syslog(LOG_INFO, "%s: %s", ts, message);
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL_US);
    }
    return (low_count >= RAIN_THRESHOLD) ? 1 : 0;
}

static int close_window(void) {
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTY) < 0) {
        syslog(LOG_ERR, "Failed to start PWM");
        return -1;
    }
    log_event("Closing window...");
    for (int i = 0; i < MOTOR_RUN_TIME_SEC && running; i++) {
        gpioDelay(1000000);
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return -1;
    }
    log_event("Window closed.");
    return 0;
}

static void cleanup(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        closelog();
        return 1;
    }
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        cleanup();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        cleanup();
        return 1;
    }
    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        cleanup();
        return 1;
    }
    log_event("Window control system started.");
    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected. Closing window...");
            if (close_window() != 0) {
                syslog(LOG_ERR, "Window close failed");
            }
        }
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            gpioDelay(1000000);
        }
    }
    log_event("Shutting down...");
    cleanup();
    return 0;
}

