#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOG_FILE "stock_events.txt"
#define SCK_PULSE_US 1000
#define READ_TIMEOUT_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
    return 0;
}

static int read_hx711(int *out_value) {
    int timeout = 0;
    while (gpioRead(HX711_DT) == 1) {
        if (++timeout > READ_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout)\n");
            return -1;
        }
        gpioDelay(100);
    }
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(SCK_PULSE_US);
        value <<= 1;
        if (gpioRead(HX711_DT)) {
            value |= 1;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(SCK_PULSE_US);
    }
    gpioWrite(HX711_SCK, 1);
    gpioDelay(SCK_PULSE_US);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(SCK_PULSE_US);
    if (value & 0x800000) {
        value |= 0xFF000000;
    }
    *out_value = value;
    return 0;
}

static double calculate_weight(int32_t raw_value) {
    return (double)raw_value / 1000.0;
}

static int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid\n");
        return -1;
    }
    log_event("Solenoid activated");
    gpioDelay(5000000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid\n");
        return -1;
    }
    log_event("Solenoid deactivated");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(HX711_DT, PI_INPUT) != 0 ||
        gpioSetMode(HX711_SCK, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(HX711_SCK, 0);
    gpioDelay(100000);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        gpioTerminate();
        return 1;
    }

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = 0;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "Error: HX711 read failed\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f g\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold (%.2f g). Activating solenoid.\n", weight);
            if (activate_solenoid(SOLENOID_PIN) != 0) {
                fprintf(stderr, "Error: Solenoid activation failed\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Stock monitoring stopped.\n");
    return 0;
}

