#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_THRESHOLD 5.0
#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define LOCK_DURATION_US 5000000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711_raw(int *raw_value) {
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (++timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
        gpioDelay(1);
    }
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN)) {
            value |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }
    if (gpioRead(HX711_DATA_PIN)) {
        value |= 0x800000;
    }
    *raw_value = value;
    return 0;
}

static double read_weight_kg(int *raw_value) {
    if (read_hx711_raw(raw_value) != 0) {
        return -1.0;
    }
    return (double)raw_value / calibration_factor;
}

static int calibrate_hx711(void) {
    printf("Place a known weight on the load cell and press Enter.\n");
    getchar();
    int raw = 0;
    if (read_hx711_raw(&raw) != 0) {
        fprintf(stderr, "Calibration read failed\n");
        return -1;
    }
    double known_weight = 0.0;
    printf("Enter the weight in kg: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid weight entered\n");
        return -1;
    }
    if (known_weight == 0.0) {
        fprintf(stderr, "Calibration factor cannot be zero\n");
        return -1;
    }
    calibration_factor = (double)raw / known_weight;
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file\n");
        return -1;
    }
    if (fprintf(fp, "%.6f\n", calibration_factor) < 0) {
        fprintf(stderr, "Error writing calibration factor\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration factor: %.6f\n", calibration_factor);
    return 0;
}

static void log_event(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }
    if (fprintf(fp, "%s - Weight: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fclose(fp);
}

static void unlock_solenoid(void) {
    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Error setting solenoid high\n");
        return;
    }
    gpioDelay(LOCK_DURATION_US);
    if (gpioWrite(SOLENOID_PIN, 0) != 0) {
        fprintf(stderr, "Error setting solenoid low\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }
    if (calibrate_hx711() != 0) {
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return 1;
    }
    printf("Weight monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        int raw = 0;
        if (read_hx711_raw(&raw) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        double weight = read_weight_kg(&raw);
        if (weight < 0.0) {
            fprintf(stderr, "Weight read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        printf("Weight: %.2f kg\n", weight);
        if (weight > WEIGHT_THRESHOLD) {
            log_event(weight);
            printf("Threshold exceeded, unlocking solenoid...\n");
            unlock_solenoid();
        }
        gpioDelay(100000);
    }
    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    return 0;
}

