#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int read_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;

    while (fgets(line, sizeof(line), fp)) {
        /* Strip trailing newline */
        line[strcspn(line, "\n")] = '\0';

        if (strncmp(line, "duration=", 9) == 0) {
            char *endptr = NULL;
            long val = strtol(line + 9, &endptr, 10);
            if (endptr == line + 9 || *endptr != '\0' ||
                val <= 0 || val > MAX_DURATION) {
                fprintf(stderr, "Invalid duration in config: '%s'\n", line);
                fclose(fp);
                return -1;
            }
            *duration = (int)val;
            found = 1;
            break;
        }
    }

    if (!found) {
        fprintf(stderr, "Config file missing or invalid 'duration=' line.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int set_valve(struct gpiod_line *line, int on)
{
    int ret = gpiod_line_set_value(line, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting valve %s: %s\n",
                on ? "ON" : "OFF", strerror(errno));
        return -1;
    }
    return 0;
}

static void sleep_interruptible(unsigned int seconds)
{
    struct timespec req = { .tv_sec = seconds, .tv_nsec = 0 };
    struct timespec rem;

    while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
        if (!program_running)
            break;
        req = rem;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration = 0;
    int ret = EXIT_FAILURE;

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request line as output, default low (valve off) */
    if (gpiod_line_request_output(line, "watering-valve", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Read configuration */
    if (read_config(CONFIG_FILE, &duration) != 0) {
        goto cleanup;
    }

    printf("Configured watering duration: %d seconds\n", duration);
    fflush(stdout);

    /* Activate valve */
    if (set_valve(line, 1) != 0) {
        goto cleanup;
    }
    printf("Valve ON\n");
    fflush(stdout);

    /* Sleep in 1-second increments so signals can interrupt */
    unsigned int remaining = duration;
    while (remaining > 0 && program_running) {
        unsigned int chunk = remaining > 60 ? 60 : remaining;
        sleep_interruptible(chunk);
        remaining -= chunk;
    }

    /* Deactivate valve */
    if (set_valve(line, 0) != 0) {
        goto cleanup;
    }
    printf("Valve OFF\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure valve is off on every exit path */
    if (line)
        gpiod_line_set_value(line, 0);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

