#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define MOTOR1_PIN 22
#define MOTOR2_PIN 23
#define MOTOR3_PIN 24
#define MOTOR4_PIN 25

#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define LOG_FILE "trace_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return -1;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, MOTOR1_PIN, MOTOR2_PIN, MOTOR3_PIN, MOTOR4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Failed to set pull-up on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR3_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR4_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(MOTOR1_PIN, 0) < 0 ||
        gpioPWM(MOTOR2_PIN, 0) < 0 ||
        gpioPWM(MOTOR3_PIN, 0) < 0 ||
        gpioPWM(MOTOR4_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", pin);
        return -1;
    }
    return val;
}

static void set_motor_speed(int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;
    if (gpioPWM(MOTOR1_PIN, speed) < 0 ||
        gpioPWM(MOTOR2_PIN, speed) < 0 ||
        gpioPWM(MOTOR3_PIN, speed) < 0 ||
        gpioPWM(MOTOR4_PIN, speed) < 0) {
        fprintf(stderr, "Failed to set PWM\n");
    }
}

static void log_data(int s1, int s2, int s3, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s,%d,%d,%d,%d,%d\n",
                timestamp, s1, s2, s3, left_speed, right_speed) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
    }
}

static void cleanup(void) {
    set_motor_speed(0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error, stopping\n");
            break;
        }

        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (s2 == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (s1 == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (s3 == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed);
        set_motor_speed(right_speed);

        log_data(s1, s2, s3, left_speed, right_speed);

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return 0;
}

