#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_MS1 200
#define PULSE_MS2 300

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Register signal handlers for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines for motor 1 and motor 2 */
    line1 = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line1, "haptic-motor1", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, "haptic-motor2", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Main pulsing loop */
    while (running) {
        /* Turn motor 1 on */
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1, 1)");
            break;
        }
        usleep(PULSE_MS1 * 1000);
        if (!running) break;

        /* Turn motor 1 off */
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line1, 0)");
            break;
        }
        usleep(PULSE_MS2 * 1000);
        if (!running) break;

        /* Turn motor 2 on */
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2, 1)");
            break;
        }
        usleep(PULSE_MS2 * 1000);
        if (!running) break;

        /* Turn motor 2 off */
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(line2, 0)");
            break;
        }
        usleep(PULSE_MS1 * 1000);
    }

cleanup:
    /* Ensure motors are off before releasing resources */
    if (line1) {
        gpiod_line_set_value(line1, 0);
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

