#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ADDRESS "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void log_msg(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", buf, msg);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    const char *mode = (argc > 1) ? argv[1] : "sound_sensor";
    char *zmq_address = strdup(ZMQ_ADDRESS);
    if (!zmq_address) {
        perror("strdup");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        free(zmq_address);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        free(zmq_address);
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_GPIO);
    if (!sound_line) {
        perror("gpiod_chip_get_line(sound)");
        gpiod_chip_close(chip);
        free(zmq_address);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_GPIO);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        free(zmq_address);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        perror("gpiod_line_request_input(sound)");
        gpiod_chip_close(chip);
        free(zmq_address);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "alarm_node", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        free(zmq_address);
        return EXIT_FAILURE;
    }

    if (mode == "sound_sensor") {
        int ret = 0;
        while (running) {
            int val = gpiod_line_get_value(sound_line);
            if (val < 0) {
                perror("gpiod_line_get_value(sound)");
                ret = EXIT_FAILURE;
                break;
            }
            if (val == 0) {
                char msg[128];
                snprintf(msg, sizeof(msg), "Sound detected on GPIO%d", SOUND_SENSOR_GPIO);
                if (zmq_send(msg, strlen(msg), ZMQ_TOPIC, 0) < 0) {
                    perror("zmq_send");
                    ret = EXIT_FAILURE;
                    break;
                }
            }
            sleep_ms(POLL_INTERVAL_MS);
        }
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        free(zmq_address);
        return ret;
    } else if (mode == "alarm_node") {
        void *context = zmq_ctx_new();
        if (!context) {
            perror("zmq_ctx_new");
            return EXIT_FAILURE;
        }

        void *socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            perror("zmq_socket");
            zmq_ctx_destroy(context);
            return EXIT_FAILURE;
        }

        if (zmq_bind(socket, zmq_address) < 0) {
            perror("zmq_bind");
            zmq_close(socket);
            zmq_ctx_destroy(context);
            return EXIT_FAILURE;
        }

        int rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, "", 0);
        if (rc < 0) {
            perror("zmq_setsockopt");
            zmq_close(socket);
            zmq_ctx_destroy(context);
            return EXIT_FAILURE;
        }

        while (running) {
            char *message = (char *)zmq_recv(socket, NULL, 0, ZMQ_NOBLOCK);
            if (!message) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    sleep_ms(100);
                    continue;
                }
                perror("zmq_recv");
                break;
            }

            if (strcmp(message, "SOUND_ALERTS") == 0) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    perror("gpiod_line_set_value(led)");
                    break;
                }
                sleep_ms(ALARM_DURATION_MS);
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    perror("gpiod_line_set_value(led)");
                    break;
                }
            }
        }

        zmq_close(socket);
        zmq_ctx_destroy(context);
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(sound_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        free(zmq_address);
        return EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }
}

