#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 180
#define SAMPLE_INTERVAL_MS 1000

static const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int bh1750_read(int fd, int addr, float *lux_out) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE set failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    uint8_t cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "BH1750 write failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "BH1750 read failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(float lux[NUM_SENSORS]) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char line[256];
    int n = snprintf(line, sizeof(line), "%d,%.2f;%d,%.2f;%d,%.2f;%d,%.2f\n",
                     1, lux[0], 2, lux[1], 3, lux[2], 4, lux[3]);
    if (n < 0 || (size_t)n >= sizeof(line)) {
        fprintf(stderr, "Line formatting failed\n");
        close(sock);
        return -1;
    }

    if (sendto(sock, line, (size_t)n, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    float lux[NUM_SENSORS];
    int fd[NUM_SENSORS];
    int i2c_fds[NUM_SENSORS];
    int i2c_ok[NUM_SENSORS];
    int exit_code = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        fd[i] = -1;
        i2c_fds[i] = -1;
        i2c_ok[i] = 0;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        fd[i] = open(I2C_BUS, O_RDWR);
        if (fd[i] < 0) {
            fprintf(stderr, "open(%s) failed for sensor %d: %s\n", I2C_BUS, i+1, strerror(errno));
            exit_code = 1;
            goto cleanup;
        }
        i2c_fds[i] = fd[i];
        i2c_ok[i] = 1;
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!i2c_ok[i]) continue;
            if (bh1750_read(i2c_fds[i], sensor_addresses[i], &lux[i]) < 0) {
                lux[i] = NAN;
            }
        }

        if (send_multicast(lux) < 0) {
            fprintf(stderr, "send_multicast failed\n");
        }

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!i2c_ok[i]) continue;
            if (close(i2c_fds[i]) < 0) {
                fprintf(stderr, "close(i2c_fds[%d]) failed: %s\n", i, strerror(errno));
            }
            i2c_fds[i] = -1;
            i2c_ok[i] = 0;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fd[i] >= 0) {
            close(fd[i]);
            fd[i] = -1;
        }
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
            i2c_fds[i] = -1;
        }
    }
    return exit_code;
}

