        perror("sigaction");
        return 1;
    }

    float lux[NUM_SENSORS];
    int fd[NUM_SENSORS];
    int i2c_fds[NUM_SENSORS];
    int i2c_ok[NUM_SENSORS];
    int exit_code = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        fd[i] = -1;
        i2c_fds[i] = -1;
        i2c_ok[i] = 0;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        fd[i] = open(I2C_BUS, O_RDWR);
        if (fd[i] < 0) {
            fprintf(stderr, "open(%s) failed for sensor %d: %s\n", I2C_BUS, i+1, strerror(errno));
            exit_code = 1;
            goto cleanup;
        }
        i2c_fds[i] = fd[i];
        i2c_ok[i] = 1;
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!i2c_ok[i]) continue;
            if (bh1750_read(i2c_fds[i], sensor_addresses[i], &lux[i]) < 0) {
                lux[i] = NAN;
            }
        }

        if (send_multicast(lux) < 0) {
            fprintf(stderr, "send_multicast failed\n");
        }

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (!i2c_ok[i]) continue;
            if (close(i2c_fds[i]) < 0) {
                fprintf(stderr, "close(i2c_fds[%d]) failed: %s\n", i, strerror(errno));
            }
            i2c_fds[i] = -1;
            i2c_ok[i] = 0;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (fd[i] >= 0) {
            close(fd[i]);
            fd[i] = -1;
        }
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
            i2c_fds[i] = -1;
        }
    }
    return exit_code;
}

