static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_zero_len(int fd)
{
    if (write(fd, NULL, 0) < 0)
        return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == ENXIO)
            return -2;          /* sensor absent */
        if (errno == EIO)
            return -1;          /* bus error */
        return -2;
    }
    if ((size_t)n != len)
        return -1;
    return 0;
}

static int read_airflow(int fd, float *flow_out)
{
    uint8_t buf[2];
    int rc = -1;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_zero_len(fd) < 0) {
            fprintf(stderr, "I2C write zero-length failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n",
                    attempt + 1, strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int16_t raw = ((int16_t)buf[0] << 8) | buf[1];
        raw >>= 2;
        *flow_out = (float)raw * 0.1f - 32.5f;
        return 0;
    }

    fprintf(stderr, "Failed to read airflow after %d attempts.\n", MAX_RETRIES);
    return -1;
}

