#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDR 0x39

#define AS7341_REG_ENABLE 0x80
#define AS7341_REG_ID     0x24
#define AS7341_REG_CFG6   0xAF
#define AS7341_REG_DATA   0x60

#define AS7341_WHO_AM_I   0x19
#define AS7341_PON        0x01
#define AS7341_SP_EN      0x20
#define AS7341_SMUX      0x0F
#define AS7341_SMUX_F1    0x00
#define AS7341_SMUX_F8    0x0F

#define NUM_CHANNELS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_REG_ID, &id) < 0) {
        return -1;
    }
    if (id != AS7341_WHO_AM_I) {
        fprintf(stderr, "Sensor ID mismatch: got 0x%02X, expected 0x%02X\n", id, AS7341_WHO_AM_I);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_PON) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_SMUX_F1) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_SMUX_F8) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_REG_CFG6, AS7341_SP_EN) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_PON | AS7341_SP_EN) < 0) return -1;
    usleep(10000);

    return 0;
}

static int read_spectral_data(int fd, uint16_t *data) {
    uint8_t buf[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (i2c_read_reg8(fd, AS7341_REG_DATA + i, &buf[i]) < 0) {
            return -1;
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        data[i] = (buf[i] << 8) | buf[i + 1];
    }
    return 0;
}

static float calculate_lux(uint16_t *data) {
    float lux = 0.0f;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lux += (float)data[i] * 0.1f;
    }
    return lux;
}

static void log_data(FILE *fp, uint16_t *data, float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7], data[8], data[9]);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", AS7341_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("spectral_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open spectral_log.csv: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8,CH9,CH10\n");
    }

    printf("AS7341 spectral logging started. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t data[NUM_CHANNELS];
        if (read_spectral_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Failed to read spectral data.\n");
            sleep(5);
            continue;
        }

        float lux = calculate_lux(data);
        log_data(log_file, data, lux);
        printf("Lux: %.2f\n", lux);

        sleep(5);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

