#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SCALE_FACTOR 0.000244f

#define REG_X_L 0x28
#define REG_X_H 0x29
#define REG_Y_L 0x2A
#define REG_Y_H 0x2B
#define REG_Z_L 0x2C
#define REG_Z_H 0x2D

static int i2c_fd = -1;
static FILE *output_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_error(const char *message) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s (errno: %d - %s)\n", timestamp, message, errno, strerror(errno));
    fflush(error_file);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        log_error("I2C write failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) != 1) {
            log_error("I2C write register address failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (read(fd, buf, len) == len) return 0;
        log_error("I2C read failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_sensor_data(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_X_L, buf, 6) != 0) return -1;
    int16_t x_raw = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y_raw = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z_raw = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(output_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(output_file);
}

