    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char output_filename[256] = DEFAULT_OUTPUT_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': strncpy(output_filename, optarg, sizeof(output_filename) - 1); output_filename[sizeof(output_filename) - 1] = '\0'; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval_seconds] [-f output_filename]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        fprintf(stderr, "Error opening error log: %s\n", strerror(errno));
        return 1;
    }

    output_file = fopen(output_filename, "a");
    if (!output_file) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        fclose(error_file);
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        fclose(output_file);
        fclose(error_file);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(output_file);
        fclose(error_file);
        return 1;
    }

    printf("Seismic data logging started. Press Ctrl+C to stop.\n");

    while (program_running) {
        float x, y, z;
        if (read_sensor_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            log_error("Failed to read sensor data");
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (output_file) fflush(output_file) && fclose(output_file);
    if (error_file) fflush(error_file) && fclose(error_file);
    return 0;
}

