#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONT_HIGH_RES 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL 1
#define READ_INTERVAL_SEC 1

static int i2c_fd = -1;
static int udp_fd = -1;
static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, BH1750_POWER_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONT_HIGH_RES) < 0) return -1;
    usleep(180000); // Wait for first measurement
    return 0;
}

static int init_udp_socket(void) {
    int fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int ttl = MULTICAST_TTL;
    if (setsockopt(fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(fd);
        return -1;
    }
    return fd;
}

static int send_lux(int fd, float lux) {
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(buffer)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }
    if (sendto(fd, buffer, (size_t)len, 0, NULL, 0) < 0) {
        perror("sendto");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return 1;
    }

    udp_fd = init_udp_socket();
    if (udp_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        uint16_t raw;
        if (i2c_read_word(i2c_fd, &raw) < 0) {
            fprintf(stderr, "Read error, retrying in %d s\n", READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }
        float lux = (float)raw / 1.2f;
        if (send_lux(udp_fd, lux) < 0) {
            fprintf(stderr, "Send error, retrying in %d s\n", READ_INTERVAL_SEC);
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) close(i2c_fd);
    if (udp_fd >= 0) close(udp_fd);
    printf("Exiting cleanly.\n");
    return 0;
}

