#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_LEFT  4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT 27
#define SERIAL_PORT  "/dev/ttyAMA0"
#define BAUD_RATE    115200
#define LOOP_DELAY_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single GPIO pin; returns 0 or 1, or -1 on error.             */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d\n", gpio);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Log a timestamped line to stdout.                                  */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Send an emergency stop message over the serial port.                */
/* ------------------------------------------------------------------ */
static void emergency_stop(void)
{
    char msg[] = "EMERGENCY STOP!\n";
    ssize_t n = write(g_serial_fd, msg, sizeof(msg) - 1);
    if (n < 0) {
        perror("write() failed");
    } else {
        printf("Sent emergency stop message.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_serial_fd >= 0) {
        close(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(SENSOR_LEFT, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_MIDDLE, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_RIGHT, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_LEFT, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_MIDDLE, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_RIGHT, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Serial port ---- */
    g_serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (g_serial_fd < 0) {
        perror("open() failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Clear O_NDELAY so writes block; use raw mode for 8N1. */
    if (fcntl(g_serial_fd, F_SETFL, 0) < 0) {
        perror("fcntl() failed");
        close(g_serial_fd);
        g_serial_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* 8N1, no flow control */
    if (cfsetispeed(&g_serial_fd, B115200) < 0 ||
        cfsetospeed(&g_serial_fd, B115200) < 0) {
        perror("cfsetispeed/cfsetospeed failed");
        close(g_serial_fd);
        g_serial_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Flush any stale data */
    if (tcdrain(g_serial_fd) < 0) {
        perror("tcdrain failed");
        close(g_serial_fd);
        g_serial_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction failed");
        close(g_serial_fd);
        g_serial_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("KY-033 tracking sensor running. Ctrl+C to exit.\n");
    log_line("Program started.");

    /* ---- Main loop ---- */
    while (g_running) {
        int left  = read_sensor(SENSOR_LEFT);
        int middle = read_sensor(SENSOR_MIDDLE);
        int right  = read_sensor(SENSOR_RIGHT);

        if (left < 0 || middle < 0 || right < 0) {
            log_line("Sensor read error — continuing.");
        } else {
            int obstacle = (left  == 0) ? 0 : 1;
            int middle_obstacle = (middle == 0) ? 0 : 1;
            int right_obstacle = (right == 0) ? 0 : 1;

            if (obstacle == 1 && middle_obstacle == 1 && right_obstacle == 1) {
                log_line("EMERGENCY STOP!");
                emergency_stop();
            } else {
                log_line(
                    "Left: " (left  == 0 ? "OBSTACLE" : "CLEAR")
                    "  Middle: " (middle == 0 ? "OBSTACLE" : "CLEAR")
                    "  Right: " (right == 0 ? "OBSTACLE" : "CLEAR")
                );
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    log_line("Shutting down.");
    cleanup();
    return EXIT_SUCCESS;
}

